\subsection{Proof of Theorem~\ref{thm:M-OGP-generic-tensor-correlated}}\label{sec:proof-MOGP}
In this section, we provide a proof of Theorem~\ref{thm:M-OGP-generic-tensor-correlated}.
The proof relies on the first moment method. We first define a set to count the tuples $\mathcal{I}_{i}$ of multi-indices that satisfy conditions $\mathrm{(a)}$ and $\mathrm{(b)}$  of Definition~\ref{Def:Overlap-Set-correlated-generic-subtensor}.
\begin{align}
    F(m,\nu_1,\nu_2) := 
    \left\{ \left(\mathcal{I}_{1},\ldots, \mathcal{I}_{m}\right):
    \frac{\left|I_{n,i_1} \cap I_{n,i_2} \right|}{k} \in \left[\nu_1,\nu_2\right],\,
    \forall n\in[p],1\le i_1<i_2\le m
    \right\}
    \,.
\end{align}
We now observe that
\begin{align}
    \bigl|S_{\gamma}\left(m, \nu_1, \nu_2, \mathcal{J} \right) \bigr|
    &=
    \sum_{\left(\mathcal{I}_{1},\ldots, \mathcal{I}_{m}\right)
    \in 
    F(m,\nu_1,\nu_2)}
    \mathbbm{1}
    \bigg\{
    \exists
    \tau_{1},\ldots,\tau_m \in \mathcal{J}
    :
    \\
    &
    \min_{1 \leq \ell \leq m}
    \frac{1}{k^{p/2}} \sum_{i_1\in I_{i,\ell},\dots,i_p\in I_{p,\ell}} \hat{A}^{(\ell)}_{i_1,\dots,i_p} (\tau_\ell)\ge \gamma k^{p/2} E_{\mathrm{max}}
    \bigg\}
    \,.
\end{align}
In order to apply the first moment method, we need to bound $\mathbb{E}\bigl[\bigl|S_{\gamma}\left(m, \nu_1, \nu_2, \mathcal{J} \right) \bigr| \bigr]$. We have:
\begin{align}\label{eq:upper-bound-size-of-S}
    &\mathbb{E}\left[\left|S_{\gamma}\left(m, \nu_1, \nu_2, \mathcal{J} \right) \right| \right]
    \nonumber
    \\ &=
    \sum_{\left(\mathcal{I}_{1},\ldots, \mathcal{I}_{m}\right)
    \in 
    F(m,\nu_1,\nu_2)}
    \mathbb{P}
    \bigg[\exists
    \tau_{1},\ldots,\tau_m \in \mathcal{J}
    :
    \min_{1 \leq \ell \leq m}
    \frac{1}{k^{p/2}} \sum_{i_1\in I_{i,\ell},\dots,i_p\in I_{p,\ell}} \hat{A}^{(\ell)}_{i_1,\dots,i_p} (\tau_\ell)\ge \gamma k^{p/2} E_{\mathrm{max}} \bigg]
    \nonumber
    \\
    &\leq
    \left|F(m,\nu_1,\nu_2)\right| \sup_{(\mathcal{I}_1,\dots,\mathcal{I}_m)\in F(m,\nu_1,\nu_2)}
    \mathbb{P}
    \bigg[\exists
    \tau_{1},\ldots,\tau_m \in \mathcal{J}
    : \nonumber \\
    &\hspace{5cm}
    \min_{1 \leq \ell \leq m}
    \frac{1}{k^{p/2}} \sum_{i_1\in I_{i,\ell},\dots,i_p\in I_{p,\ell}} \hat{A}^{(\ell)}_{i_1,\dots,i_p} (\tau_\ell)\ge \gamma k^{p/2} E_{\mathrm{max}} \bigg]
    \nonumber
    \\
    &\leq
    \left|F(m,\nu_1,\nu_2)\right| \binom{N}{k}^{cm} \sup_{(\mathcal{I}_1,\dots,\mathcal{I}_m)\in F(m,\nu_1,\nu_2)}
    \sup_{\tau_1,\ldots,\tau_m \in [0,\pi/2]}
    \mathbb{P}\left[\hat{\Phi}_{\mathcal{I}_i} > k^{p/2} \gamma E_{\mathrm{max}},1\le i\le m\right]
\end{align}
where
\begin{equation}\label{hat-PHI}
    \hat{\Phi}_{\mathcal{I}_{\ell}} := \frac{1}{k^{p/2}} \sum_{i_1\in I_{1,\ell},\dots,i_p\in I_{p,\ell}} \hat{A}^{(\ell)}_{i_1,\dots,i_p} (\tau_\ell)
    \,.
\end{equation}
Above,~\eqref{eq:upper-bound-size-of-S} follows by taking a union bound over all $\tau_1,\dots,\tau_m\in\mathcal{J}$, together with the fact that $|\mathcal{J}|\le \binom{N}{k}^{c}$.  Note that the bound in~\eqref{eq:upper-bound-size-of-S} is valid for all $c,\nu_1,\nu_2$ and $\gamma$.

We next bound the quantities
\begin{align*}
    C_0 := \left|F(m,\nu_1,\nu_2)\right|,\quad\text{and}\quad 
    C_1 := \sup_{\substack{(\mathcal{I}_1,\dots,\mathcal{I}_m)\in F(m,\nu_1,\nu_2)\\\tau_1,\ldots,\tau_m \in [0,\pi/2]}}
    \mathbb{P}\left[\hat{\Phi}_{\mathcal{I}_i} > k^{p/2} \gamma E_{\mathrm{max}},1\le i\le m\right] \,.
\end{align*}
\begin{proposition}\label{proposition:C0-C1-bounds}
    For sufficiently small $\eta := \nu_2 - \nu_1$, the following bounds hold
    \begin{align}
        C_0 &\leq \exp_2\left( p\log_2 \binom{N}{k} + m p\log_2 k + mp\left(kh(\nu_1) + k(1-\nu_1) \log_2\frac{eN}{k(1-\nu_1)}\right)\right) \,,\\
%--------------------------------------
        C_1 &\leq \exp_2\left[ 
    -\gamma^2 p \log_2 \binom{N}{k} \frac{m}{1+ 2 m p \nu_2^p}
    \left(1
    +
    o_N(1)\right)
    \right]\,.
    \end{align}
\end{proposition}
We prove Proposition~\ref{proposition:C0-C1-bounds} in Sections~\ref{sec:bound-C0} and \ref{sec:bound-C1}.
Assuming the validity of Proposition~\ref{proposition:C0-C1-bounds}, we establish using~\eqref{eq:upper-bound-size-of-S}
\begin{align}
    \mathbb{E}\left[\left|S_{\gamma}\left(m, \nu_1, \nu_2, \mathcal{J} \right) \right| \right]
    \leq
    \exp_2 \left[ p \log_2 \binom{N}{k} \Psi(c,m,\nu_1,\nu_2) + O
    \left(
    \log \log \binom{N}{k}
    \right)\right]
\end{align}
where
\begin{align}
    \Psi
    =
    1  + m\bigg[c - \frac{ \gamma^2 }{1+ 2 m p \nu_2^p}
    + \frac{k}{\log_2 \binom{N}{k}}h(\nu_1) + \frac{k}{\log_2 \binom{N}{k}}(1-\nu_1) \log_2\frac{eN}{k(1-\nu_1)}
    \bigg].
\end{align}
We now show that $\Psi$ is negative, allowing us to establish:
\begin{align*}
    \mathbb{E}\left[\left|S_{\gamma}\left(m, \nu_1, \nu_2, \mathcal{J} \right) \right| \right]
    \leq
    \exp\left[ - \Theta\left(p \log_2 \binom{N}{k}\right) \right] \,.
\end{align*}
Define $\delta := m \gamma^2 - 1 >0$. We split the analysis into two cases:
\subsubsection*{Case 1: $k = o(N)$}
We have
\begin{align}
    \Psi
    &=
    1  + m\bigg(c  - \frac{ \gamma^2 }{1+ 2 m p \nu_2^p}
    \bigg)
    +
    o\left(1\right)
    \,.
\end{align}
Choose $P^*$ such that for all $p \geq P^*$,
\begin{align}
    1 - \frac{ m\gamma^2 }{1+ 2 m p \nu_2^p} \leq -\frac{\delta}{2}.
\end{align}
Finally, we choose $c \leq \frac{\delta}{4m}$.
These choices collectively lead to
\begin{align*}
    \Psi
    &\leq 
    -\frac{\delta}{4} + o\left(1\right) <0 \,, 
\end{align*}
for sufficiently large $k$ and $N$.
\subsubsection*{Case 2: $k = \alpha N, \alpha >0$}
In this case, we have
\begin{align}
    \Psi
    &=
    1 + 
    cm - \frac{\gamma^2 m}{1 + 2m p \nu_2^p}
    +
    \frac{\alpha}{h(\alpha)} h(\nu_1) + \frac{\alpha}{h(\alpha)}(1 - \nu_1) \log_2 \frac{e }{\alpha (1- \nu_1)}
    +
    o(1)\,.
\end{align}
Let us first choose $\nu_1$ sufficiently close to 1, so that
\begin{align}
    \alpha h(\nu_1) + \alpha(1 - \nu_1) \log_2 \frac{e }{\alpha (1- \nu_1)}
    \leq \frac{\delta h(\alpha)}{8 }.
\end{align}
Notice that such a choice indeed exists since $\alpha$ is fixed, whereas
\[
  \alpha h(\nu_1) + \alpha(1 - \nu_1) \log_2 \frac{e }{\alpha (1- \nu_1)}\to 0,\quad\text{as}\quad \nu_1\to 1.
\]
Choose $P^*$ such that for all $p \geq P^*$, 
\begin{align}
    1 - \frac{m\gamma^2}{1+ 2 m p \nu_2^p} \leq -\frac{\delta}{2}.
\end{align}
Finally, we choose $c \leq \frac{\delta}{8m}$. 
These choices collectively lead to
\begin{align*}
    \Psi
    &\leq -\frac{\delta}{4} + o(1) <0 \,, 
\end{align*}
for sufficiently large $k$ and $N$. We thus conclude that
\begin{align*}
    \mathbb{E}\left[\left|S_{\gamma}\left(m, \nu_1, \nu_2, \mathcal{J} \right) \right| \right]
    \leq
    \exp\left[ - \Theta\left(p \log_2 \binom{N}{k}\right) \right]\,.
\end{align*}
Using Markov's inequality we obtain
\begin{align*}
    \mathbb{P} \left[S_{\gamma}\left(m, \nu_1, \nu_2, \mathcal{J} \right) = \varnothing \right]
    \geq 
    1 - \mathbb{E}\left[\left|S_{\gamma}\left(m, \nu_1, \nu_2, \mathcal{J} \right) \right| \right]
    \geq
    1 - \exp\left[ - \Theta\left(p \log \binom{N}{k}\right) \right]
    \,.
\end{align*}
This yields Theorem~\ref{thm:M-OGP-generic-tensor-correlated}. It thus suffices to prove Proposition~\ref{proposition:C0-C1-bounds}.
