\subsection*{Controlling $C_0$ }\label{sec:bound-C0}
In this section, we prove the first part of Proposition~\ref{proposition:C0-C1-bounds}. Let us first observe a simple combinatorial bound:
\begin{equation}\label{eq:F_COUNT}
        C_0 \le \binom{N}{k}^p\left(\sum_{\nu_1\le \alpha_i\le \nu_2 , \alpha_i k\in\mathbb{N}} \prod_{1 \leq i \leq p}\binom{k}{\alpha_i k}\binom{N-k}{k-\alpha_i k}\right)^{m-1}
\end{equation}
We choose $\nu_1 = \frac{R-1}{R}\nu_2$ for a sufficiently large integer $R$ and $\nu_2$ close to 1 to ensure the binomial coefficients are not vacuous. In particular, the assumption $\nu_1>\frac12$ holds.

We recall the standard estimates
\[
\max_{\nu_1\le \alpha\le \nu_2}\binom{k}{\alpha k}\le \exp_2\bigl(kh(\nu_1)\bigr)
\]
and 
\[
\max_{\nu_1\le \alpha\le \nu_2}\binom{N-k}{k-\alpha k} \le \left(\frac{e(N-k)}{k(1-\nu_1)}\right)^{k(1-\nu_1)} \le \exp_2\left(k(1-\nu_1)\log_2\frac{eN}{k(1-\nu_1)}\right).
\]
Combining the last two displays, we bound~\eqref{eq:F_COUNT} by 
\begin{align}\label{eq:counting-m-ogp}
    &C_0 \le \binom{N}{k}^p\left(\sum_{\nu_1\le \alpha_i\le \nu_2 , \alpha_i k\in\mathbb{N}}\exp_2\left(pkh(\nu_1) + pk(1-\nu_1) \log_2\frac{eN}{k(1-\nu_1)}\right)\right)^{m-1} \nonumber\\ 
    &
    \hspace{2cm}
    \le \exp_2\left( p\log_2 \binom{N}{k} + m p\log_2 k + mp\left(kh(\nu_1) + k(1-\nu_1) \log_2\frac{eN}{k(1-\nu_1)}\right)\right),
\end{align}
where the last step uses the fact 
\[
|\alpha:\nu_1\le \alpha\le \nu_2,k\alpha\in\mathbb{N}|\le k.
\]
This proves part $\mathrm{(a)}$ of Proposition~\ref{proposition:C0-C1-bounds}.
