\subsection*{Controlling $C_1$}\label{sec:bound-C1}
In this section, we prove the second part of Proposition~\ref{proposition:C0-C1-bounds}.
\subsubsection*{Auxiliary Results from linear algebra and probability theory}\label{sec:Auxiliary-results}
We begin by recording auxiliary results from linear algebra and probability, including the Sherman-Morrison formula matrix inversion formula~\cite{sherman1950adjustment} and Wielandt-Hoffman inequality~\cite{hoffman1953variation}; multivariate normal tail bounds~\cite{savage1962mills,hashorva2003multivariate,hashorva2005asymptotics}, and Slepian's Gaussian comparison lemma~\cite{slepian1962one}.
\begin{theorem}[Sherman-Morrison formula]\label{thm:sm}
Let $A\in\R^{n\times n}$ be an invertible matrix and $u,v\in\R^n$ be column vectors. Then, $(A+uv^T)^{-1}$ exists iff $1+v^T A^{-1}u\ne 0$ and the inverse is given by the formula
\[
\bigl(A+uv^T\bigr)^{-1} = A^{-1} - \frac{A^{-1}uv^T A^{-1}}{1+v^T A^{-1}u}.
\]
\end{theorem}
\begin{theorem}[Wielandt-Hoffman inequality]\label{thm:hw}
Let $A,A+E\in\R^{n\times n}$  be two symmetric matrices with respective eigenvalues
\[
\lambda_1(A)\ge \lambda_2(A)\ge\cdots\ge\lambda_n(A)\quad\text{and}\quad \lambda_1(A+E)\ge \lambda_2(A+E)\ge\cdots\ge \lambda_n(A+E).
\]
Then
\[
\sum_{1\le i\le n}\left(\lambda_i(A+E)-\lambda_i(A)\right)^2\le \|E\|_F^2.
\]
\end{theorem}
\begin{theorem}[Multivariate Gaussian tail bound] \label{thm:multiv-tail}
Let $\boldsymbol{X}\in\R^d$ be a centered multivariate normal random vector with non-singular covariance matrix $\Sigma\in\R^{d\times d}$ and $\boldsymbol{t}\in\R^d$ be a fixed threshold. Suppose that $\Sigma^{-1}\boldsymbol{t}>\boldsymbol{0}$ entrywise. Then,
\[
1-\ip{1/(\Sigma^{-1}\boldsymbol{t})}{\Sigma^{-1}(1/(\Sigma^{-1}\boldsymbol{t})} \le \frac{\mathbb{P}[\boldsymbol{X}\ge \boldsymbol{t}]}{\varphi_{\boldsymbol{X}}(\boldsymbol{t})\prod_{i\le d}\ip{e_i}{\Sigma^{-1}\boldsymbol{t}}}\le 1,
\]
where $e_i\in\R^d$ is the $i{\mathrm{th}}$ unit vector and $\varphi_{\boldsymbol{X}}(\boldsymbol{t})$ is the multivariate normal density evaluated at $\boldsymbol{t}$:
\[
\varphi_{\boldsymbol{X}}(\boldsymbol{t}) = (2\pi)^{-d/2}|\Sigma|^{-1/2}\exp\left(-\frac{\boldsymbol{t}^T\Sigma^{-1}\boldsymbol{t}}{2}\right)\in\R^+.
\]
\end{theorem}
\begin{theorem}[Slepian's lemma]\label{lemma:Slepian}
Let $X = (X_1, \ldots , X_n)$and $Y = (Y_1,\ldots, Y_n)$ be multivariate normal random vectors such that $\mathbb{E}[X_i] = \mathbb{E}[Y_i] = 0, \forall i$, $\mathbb{E}[X_i^2] = \mathbb{E}[Y_i^2], \forall i$, and
\begin{align*}
    \mathbb{E}\left[X_{i} X_{j}\right]
    \leq \mathbb{E}\left[Y_{i} Y_{j}\right],
    \quad 1\leq i< j \leq n.
\end{align*}
Fix any $c_{1},\ldots, c_{n} \in \mathbb{R}$.
Then,
\begin{align*}
    \mathbb{P}\left[ X_i \leq c_i,\, \forall \, i \right]
    \leq 
    \mathbb{P}\left[ Y_i \leq c_i, \,\forall \, i \right] ,
    \quad 
    \mathbb{P}\left[ X_i \geq c_i, \, \forall \, i \right]
    \leq 
    \mathbb{P}\left[ Y_i \geq c_i, \, \forall \, i \right]
    .
\end{align*}
\end{theorem}
%---------------------------------------------
\subsection*{Proof of the Second Part of Proposition~\ref{proposition:C0-C1-bounds}}\label{sec:proof-part-b-proposition}
We now bound $C_1$. Fix $(\mathcal{I}_1,\dots,\mathcal{I}_m)\in F(m,\nu_1,\nu_2)$ and $\tau_1,\dots,\tau_m \in \mathcal{J}$. Furthermore, define $ \eta(i,j,q)$ such that
\begin{equation}\label{eq:INTERSECT_PATTERN}
   \frac{|I_{q,i}\cap I_{q,j}|}{k} = \nu_2 - \eta(i,j,q) \ge \nu_1,
\end{equation}
for every $1\le i<j\le m$ and $1\le q\le p$. 
For fixed $\tau_{1},\ldots,\tau_{m}$,
we observe that for $1\leq i <j \leq m$
\begin{align*}
\mathbb{E}\left[\hat{\Phi}_{\mathcal{I}_{i}} \hat{\Phi}_{\mathcal{I}_{j}}\right]
    &=
    \frac{1}{k^p}
    \sum_{i_1\in I_{1,i},\dots,i_p\in I_{p,i}}
    \sum_{j_1\in I_{1,j},\dots,j_p\in I_{p,j}}
    \mathbb{E}
    \left[ 
    A^{(i)}_{i_1,\dots,i_p}(\tau_i)
    A^{(j)}_{j_1,\dots,j_p}(\tau_j)
    \right] \\
    &=
    \frac{1}{k^p}
    \sum_{i_1\in I_{1,i},\dots,i_p\in I_{p,i}}
    \sum_{j_1\in I_{1,j},\dots,j_p\in I_{p,j}}
    \mathbb{E}\bigg[\left( \cos(\tau_i)
            A^{(0)}_{i_1,\dots,i_p}
            +
            \sin(\tau_i)
            A^{(i)}_{i_1,\dots,i_p}\right)
            \\
            &
            \hspace{6cm}
            \times\left(\cos(\tau_j)
            A^{(0)}_{j_1,\dots,j_p}
            +
            \sin(\tau_j)
            A^{(j)}_{j_1,\dots,j_p} \right) \bigg]
    \\
    &=
    \frac{\cos(\tau_i) \cos(\tau_j)}{k^p}
    \sum_{i_1\in I_{1,i}\cap I_{1,j},\dots,i_p\in I_{p,i}\cap I_{p,j}} 1
    \\
    &
    =
    {\cos(\tau_i) \cos(\tau_j)} \prod_{q=1}^{p}\left(\nu_2 - \eta(i,j,q) \right).
\end{align*}
For $\Phi_{\mathcal{I}}$ defined in~\eqref{eq:INFORMAL}, we thus obtain that
\begin{align}
    \mathbb{E}\left[\hat{\Phi}_{\mathcal{I}_i} \hat{\Phi}_{\mathcal{I}_j} \right]
    \leq 
    \mathbb{E}\left[{\Phi}_{\mathcal{I}_i} {\Phi}_{\mathcal{I}_j} \right]
    \,,
\end{align}
Applying now Slepian's lemma, Theorem~\ref{lemma:Slepian}, we arrive at the bound
\begin{align}\label{eq:sup-bound-slepian}
    \sup_{\tau_1,\ldots,\tau_m \in [0,\pi/2]}
    \mathbb{P}\left[\hat{\Phi}_{\mathcal{I}_i} > k^{p/2} \gamma E_{\mathrm{max}},\, 
 \forall\, i\right]
    \leq 
    \mathbb{P}\left[\Phi_{\mathcal{I}_i} > k^{p/2} \gamma E_{\mathrm{max}},\, 
 \forall\, i\right]
    \,.
\end{align}
That is,  to control $C_1$, we restrict our attention to analyzing the tails of $\Phi_{\mathcal{I}_i}$, i.e., the case $\tau_1 = \ldots = \tau_m = 0$.
We note that $\left(\Phi_{\mathcal{I}_1},\ldots,\Phi_{\mathcal{I}_m}\right)$ is a multivariate Gaussian with
\begin{align}\label{eq:momnets-prop-Phi-I-i}
&\mathbb{E}\left[\Phi_{\mathcal{I}_i}\right] = 0 \,, 
    \mathbb{E}\left[\Phi_{\mathcal{I}_i}^2\right] = 1\,,
    \, 
     \nonumber\\ &\mathbb{E}\left[\Phi_{\mathcal{I}_i} \Phi_{\mathcal{I}_j}\right] = \prod_{q=1}^{p}\left(\nu_2 - \eta(i,j,q) \right),
\end{align}
where 
\[
\eta(i,j,q) \in \left[0, \nu_2 - \nu_1 \right],\quad\text{for}\quad  
    1\leq i <j \leq m \quad \text{and}\quad 1\le q\le p.
\]
We now use Theorem~\ref{thm:multiv-tail} to bound $\mathbb{P}\left[\Phi_{\mathcal{I}_i} > k^{p/2} \gamma E_{\mathrm{max}},\, \forall\, i\right]$. 
Define
\begin{align*}
    \boldsymbol{X} = \left(\Phi_{\mathcal{I}_1},\ldots,\Phi_{\mathcal{I}_m}\right) \,, \quad
    \boldsymbol{t} = k^{p/2} \gamma E_{\mathrm{max}} \boldsymbol{\mathbbm{1}}\,.
\end{align*}
\paragraph{Covariance of $\boldsymbol{X}$} Let $\Sigma\in\R^{m\times m}$ be the covariance matrix of $\boldsymbol{X}$. Notice that $\Sigma_{ii}=1$ for all $1\le i\le m$ and for all $1\le i<j\le m$,
\begin{equation}\label{eq:covariance-matrix-def}
    \Sigma_{ij} = \Sigma_{ji} = \prod_{q=1}^p\bigl(\nu_2 - \eta(i,j,q)\bigr)\,.
\end{equation}
Define auxiliary matrices $\Sigma_0,E\in\R^{m\times m}$ as follows.
\begin{equation}\label{eq:Sigma0ij-def} 
   \Sigma_{0} = \left(1-\nu_2^p\right) I_{m} + \nu_2^p \boldsymbol{1} \boldsymbol{1}^T, 
\end{equation}
where $I_m$ is the $m\times m$ identity matrix and $\boldsymbol{1}\in \R^m$ is the all-ones vector. As for the $E$, we set
\begin{align}
    E_{ii} &= 0,\quad \forall 1 \leq i \leq m \nonumber \\ 
    \label{eq:Eij-def}
    E_{ij} &= E_{ji} = \nu_2^p - \prod_{q=1}^{p} \left( \nu_2 - \eta(i,j,q)\right),\quad 1\le i<j\le m.
\end{align}
Notice that
\begin{align*}
    \Sigma = \Sigma_{0} - E \,.
\end{align*}
We now establish some technical results regarding $\Sigma, \Sigma_{0}$ and $E$ that will let us apply Theorem~\ref{thm:multiv-tail}.
These results are closely related to Lemma 3.13 of~\cite{gamarnik2023shatteringisingpurepspin}.
\begin{lemma}\label{lemma:auxilary-results}
    Let $\eta = \nu_2 - \nu_1$ and consider the matrices $\Sigma,\Sigma_{0}$ and $E$ defined in \eqref{eq:covariance-matrix-def}, \eqref{eq:Sigma0ij-def} and \eqref{eq:Eij-def}.
    \begin{itemize}
        \item [(a)] The matrix elements $E_{k \ell}$ are bounded by
        \begin{align*}
            0 \leq E_{k \ell} \leq p \eta \nu_2^{p-1}, \quad 1 \leq k \leq \ell \leq m\,.
        \end{align*}
        \item [(b)] The eigenvalues of the matrix $\Sigma_{0}$ are $1-\nu_2^p$ with multiplicity $m-1$ and $1 + (m-1) \nu_2^p$.
        \item [(c)] The determinant and inverse of $\Sigma_{0}$ are given by
        \begin{align*}
            \left| \Sigma_{0} \right| &= \left(1-\nu_2^p\right)^{m-1} \left(1+ (m-1) \nu_2^p\right)\,\\
            \Sigma_{0}^{-1} &= \frac{1}{1-\nu_2^p} I - \frac{\nu_2^p}{(1-\nu_2^p)(1+(m-1) \nu_2^p)} \boldsymbol{1} \boldsymbol{1}^T \,.
        \end{align*}
        \item [(d)] The covariance matrix $\Sigma$ is positive definite if 
        \begin{align}\label{eq:eta-cond}
            \eta <\frac{1-\nu_2^p}{m p \nu_2^{p-1}}\,.
        \end{align}
        \item [(e)] For sufficiently small $\eta$, the vector $\Sigma^{-1} \boldsymbol{1}$ is entry-wise positive. 
        \item [(f)] We have the following bounds for the determinant and inner product of the covariance matrix with a unit vector $e_i$
        \begin{align*}
            &\left|\Sigma\right|^{-1/2} \leq \left(1- 2 m p \nu_2^p\right)^{-m/2} = O_N(1)\,,\\
            &\prod_{i\leq m } \left<e_i, \Sigma^{-1} \boldsymbol{1} \right>
            \leq m^{m/2} \left(1- 2 m p \nu_2^p\right)^{-m} = O_{N}(1) \,.
        \end{align*}
        \item [(g)] The product $\boldsymbol{1}^T \Sigma^{-1} \boldsymbol{1}$ satisfies the inequality
        \begin{align*}
            \boldsymbol{1}^T \Sigma^{-1} \boldsymbol{1} \geq \frac{m}{1+ 2 m p \nu_2^p} \,.
        \end{align*}
    \end{itemize}
\end{lemma}
\begin{proof}
Before we proceed with the proof, let us setup some notation. We use $\Lambda_{1} \leq \ldots \leq \Lambda_{m} $ to denote the eigenvalues of $\Sigma$ and $\lambda_{1} \leq \ldots \leq \lambda_{m} $ to denote the eigenvalues of $\Sigma_{0}$.
    \begin{itemize}
        \item [(a)]
        From the definition of $E_{ij}$~\eqref{eq:Eij-def}, we see that $E_{ii} = 0$. We recall that $\eta(i,j,q) \in [0,\eta ]$.
        We bound $E_{ij}$ as follows. 
        \begin{align*}
            &0 \leq E_{ij} = \nu_2^p - \prod_{q=1}^{p} \left(\nu_2 - \eta(i,j,q)\right)
            \leq 
            \nu_2^p - \left(\nu_2 - \eta\right)^p
            \\
            &
            = \eta \sum_{0\leq q \leq p-1} \nu_2^{p-1-q} \left(\nu_2 -\eta \right)^{q} \leq \nu_2^{p-1}p \eta \,, \quad i\neq j \,.
        \end{align*}
%----------------------------------------------------------
        \item [(b)]
        One can easily check that $\boldsymbol{1}$ is an eigenvector of $\Sigma_{0}$ with eigenvalue $1 + (m-1) \nu_2^p$.
        Likewise, there are $m-1$ eigenvectors perpendicular to $\boldsymbol{1}$, corresponding to eigenvalue $1 - \nu_2^p$.
%----------------------------------------------------------
        \item  [(c)]
        The formula for the determinant directly follows from part (b).
        To obtain the inverse, we use the Sherman-Morrison formula (Theorem~\ref{thm:sm}) with 
        \begin{align*}
            A = \left(1-\nu_2^p\right) I_{m}\,,
            \quad
            u = v = \nu_2^{p/2}\boldsymbol{1}\,.
        \end{align*}
        \item [(d)] From part (b), we know that the smallest eigenvalue of $\Sigma_{0}$ is $\lambda_{1} = 1 - \nu_2^p$.
        If we can show that the smallest eigenvalue of $\Sigma$ is positive, we have the result. We first note that part (a) implies that
        \begin{align*}
            \left\Vert E \right\Vert_{2}
            \leq 
            \left\Vert E \right\Vert_{F}
            \leq m \eta p \nu_2^{p-1}\,.
        \end{align*}
        We now use the Wielandt-Hoffman inequality (Theorem~\ref{thm:hw})
        \begin{align}\label{eq:wh-on-Lambda-1}
            \bigl| \Lambda_{1} - (1 - \nu_2^p) \bigr| \leq \left\Vert E \right\Vert_{F}
            \leq m \eta p \nu_2^{p-1}
            \implies  
            \Lambda_{1} \geq (1 - \nu_2^p) - m \eta p \nu_2^{p-1}\,.
        \end{align}
        We easily see that
        \begin{align}\label{eq:Lambda_1_ineq}
           \eta <\frac{1-\nu_2^p}{m p \nu_2^{p-1}} \implies  \Lambda_{1} \geq (1 - \nu_2^p) - m \eta p \nu_2^{p-1} > 0.
        \end{align}
        \item [(e)] Define
        \begin{align}
            \boldsymbol{\eta} = \left\{\eta(i,j,q), 1 \le q \le p, 1\le i <j \le m \right\}\,.
        \end{align}
       Note that the map $f_i:\boldsymbol{\eta} \to \left( \Sigma^{-1} \boldsymbol{t} \right)_i$, where $\left( \Sigma^{-1} \boldsymbol{t} \right)_i$ is the $i{\mathrm{th}}$ entry of $\Sigma^{-1} \boldsymbol{t}$, is continuous and that \[
       \boldsymbol{\eta} \in \left[0, \nu_2 -\nu_1\right]^{pm(m-1)/2}
       \]
       which is a compact domain.
        Therefore, if we verify that $f_i(\boldsymbol{0}) = \left(\Sigma_{0}^{-1} \boldsymbol{1}\right)_i >0$, then the proof follows by uniform continuity. Using part (c),
        \begin{align*}
            \Sigma_{0}^{-1} \boldsymbol{1} = \frac{1}{1-\nu_2^p + m \nu_2^p} \boldsymbol{1}
        \end{align*}
        which is indeed entry-wise positive.
        \item [(f)] From~\eqref{eq:Lambda_1_ineq}, we see that
        \begin{align*}
            \Lambda_{1} \geq (1 - \nu_2^p) - m \eta p \nu_2^{p-1} > 1 - (mp + 1) \nu_2^p > 1- 2 m p \nu_2^p \,.
        \end{align*}
        Therefore, we see that
        \begin{align*}
            \left|\Sigma\right|^{-1/2}
            =
            \prod_{1\le i \le m} \Lambda_{i}^{-1/2}
            \leq \Lambda_{1}^{-m/2} 
            \leq \left(1- 2 m p \nu_2^p\right)^{-m/2}\,.
        \end{align*}
        Next, using Cauchy-Schwarz inequality, we obtain
        \begin{align*}
            \left<e_{i}, \Sigma^{-1} \boldsymbol{1} \right>
            \leq 
            \left\Vert e_{i} \right\Vert_{2}
            \left\Vert \Sigma^{-1} \boldsymbol{1} \right\Vert_{2}
            \leq 
            \left\Vert \Sigma^{-1}  \right\Vert_{2}
            \left\Vert \boldsymbol{1}  \right\Vert_{2}
            \leq 
            \frac{\sqrt{m}}{1 - 2mp \nu_2^p}\,.
        \end{align*}
        Thus,
        \begin{align*}
            \prod_{i\leq m } \left<e_i, \Sigma^{-1} \boldsymbol{1} \right>
            \leq m^{m/2} \left(1- 2 m p \nu_2^p\right)^{-m} \,.
        \end{align*}
        \item [(g)]
        We diagonalize $\Sigma^{-1}$ as
        \begin{align*}
            \Sigma^{-1} &= Q^T \Lambda Q \,,
        \end{align*}
        where $Q$ is an orthogonal matrix.
        We let $v := Q \boldsymbol{1}$ and note that
        \begin{align}\label{eq:1T-Sigma-1-bound}
            \boldsymbol{1}^T \Sigma^{-1} \boldsymbol{1}
            =
            \sum_{1 \leq i \leq m} 
            \Lambda_{i}^{-1} v_{i}^2
            \geq 
            \frac{1}{\Lambda_{m}}
            \sum_{1 \leq i \leq m} v_{i}^2
            =
            \frac{1}{\Lambda_{m}} \left\Vert Q \boldsymbol{1} \right\Vert_{2}^2
            =
            \frac{m}{\Lambda_{m}}
            \,.
        \end{align}
        We now apply Wielandt-Hoffman inequality to conclude that
        \begin{align}\label{eq:Lambda_m_bound}
            \left| \Lambda_{m} - \left(1 + (m-1) \nu_2^p \right) \right|
            \leq
            \left\Vert E \right\Vert_{F}
            \leq m p \eta \nu_2^{p-1} \implies \Lambda_{m} \leq 1 + 2 m p \nu_2^p \,.
        \end{align}
        Using~\eqref{eq:Lambda_m_bound} in \eqref{eq:1T-Sigma-1-bound}, we complete the proof of Lemma~\ref{lemma:auxilary-results}.
    \end{itemize}
\end{proof}
We can now apply Theorem~\ref{thm:multiv-tail}.
We use Lemma~\ref{lemma:auxilary-results} to conclude that
\begin{align*}
    &\boldsymbol{t}^T \Sigma^{-1} \boldsymbol{t}
    \geq
    \frac{2 \gamma^2 p m}{1 + 2 m p \nu_2^p} \log \binom{N}{k}\,,\\
    &\left|\Sigma\right|^{-1/2}
    = O_{N}(1) \,,
    \quad 
    \prod_{i\leq m} \left<e_i, \Sigma^{-1} \boldsymbol{t} \right>
    = O_{N}(1) \,.
\end{align*}
Let us combine these estimates and use Theorem~\ref{thm:multiv-tail} to get
\begin{align}\label{eq:prob-estimate-m-ogp}
    \mathbb{P}\left[\Phi_{\mathcal{I}_i} > k^{p/2} \gamma E_{\mathrm{max}}, \forall \,i \right]
    &\leq 
    \varphi_{\boldsymbol{X}}(\boldsymbol{t}) 
    \prod_{i\leq m} \left<e_i, \Sigma^{-1}\boldsymbol{t} \right>
    \,,\nonumber\\
    &\leq
    \exp_2\left[ 
    -\gamma^2 \log_2 \binom{N}{k} \frac{pm}{1+ 2 m p \nu_2^p} \left(1 + o_N(1)\right)
    \right]
    \,.
\end{align}
Combining this bound with~\eqref{eq:sup-bound-slepian} and recalling that $(\mathcal{I}_1,\dots,\mathcal{I}_m)\in F(m,\nu_1,\nu_2)$ is arbitrary, we complete the proof.
%-----------------------------------------------
