\subsection{Proof of Theorem~\ref{thm:IGPT}}\label{IGPT-Proof}
We record a classical fact, reproduced from~\cite[Lemma~3.1]{gamarnik2018finding}.
\begin{lemma}\label{Lemma:Gauss-Max}
    Let $Z_1,\dots,Z_n\sim \cN(0,1)$ be i.i.d.\,random variables. There exists an $N\in\mathbb{N}$ and a constant $c>0$ such that for all $n>N$,
    \[
    \mathbb{P}\left[\sqrt{2\log n}\left(\max_{1\le i\le n}Z_i -b_n\right)\le \frac32\log\log n\right]\ge 1-\frac{c}{\log^{1.5}n},
    \]
    where
    \[
    b_n :=\sqrt{2\log n} - \frac{\log (4\pi \log n)}{2\sqrt{2\log n}}.
    \]
\end{lemma}
In what follows, we use $N/k$ in place of $\lfloor N/k\rfloor$ for simplicity. Let $\mathcal{I}\mathcal{G}\mathcal{P}\text{-T}(\boldsymbol{A}) = (I_1,\dots,I_p)$ where $I_j = \{i_1^{(j)},\dots,i_k^{(j)}\}\subset [N]$ for $1\le j\le p$. Define the sets
\[
I_{u,t}:=\left\{i_1^{(u)},\dots,i_t^{(u)}\right\},\quad 1\le u\le p,\,\,1\le t\le k.
\]
By convention, $I_u = I_{u,k}$ for $1\le u\le p$. 
\paragraph{Initializaition} Note that $A_{i_1^{(1)},\dots,i_p^{(1)}} = \max_{j\in P_1} A_{i_1^{(1)},\dots,i_{p-1}^{(1)},j}$, where $|P_1|=N/k$. Using Lemma~\ref{Lemma:Gauss-Max}, we obtain that
\begin{align}\label{eq:Initialize}
&\mathbb{P}\Bigl[E_{\mathrm{Initial}}\Bigr]\ge 1-\frac{c}{\log^{1.5}(N/k)},\quad\text{where}\\
&E_{\mathrm{Initial}}:=\left\{\left|\sqrt{2\log(N/k)}\left(A_{i_1^{(1)},\dots,i_p^{(1)}} - b_{N/k}\right)\right|\le \frac32\log\log \frac{N}{k}\right\}.  \nonumber  
\end{align}
\paragraph{Loops of \IGPT} We formalize ``Loop-2" of Algorithm~\ref{IGPT}. Set
\[
M_{j,t}:=\max_{i_j\in P_t} \sum_{\substack{\displaystyle  i_1\in I_{1,t},\dots,i_{j-1}\in I_{j-1,t} \\ \displaystyle i_{j+1}\in I_{j+1,t-1},\dots,i_p\in I_{p,t-1}}}A_{\displaystyle i_1,\dots,i_{j-1},i_j,i_{j+1},\dots,i_p}
\]
for $1\le j\le p$ and $2\le t\le k$. Using Lemma~\ref{Lemma:Gauss-Max}, we conclude
\begin{align}\label{eq:E-j-t}
    &\mathbb{P}\bigl[E_{j,t}\bigr]\ge 1-\frac{c}{\log^{1.5}(N/k)},\quad\text{where}\\
   & E_{j,t}:=\left\{\left|\sqrt{2\log(N/k)}\left(\frac{M_{j,t}}{\sqrt{\Pi_{j,t}}} - b_{N/k}\right)\right|\le \frac32\log\log \frac{N}{k}\right\} \quad\text{and}\nonumber\\
   &\Pi_{j,t}=\prod_{1\le u\le j-1}|I_{u,t}|\cdot \prod_{j+1\le u\le p}|I_{u,t-1}|= t^{j-1}(t-1)^{p-j}\nonumber.
\end{align}
Note that the events $E_{\mathrm{Initial}}$ and $E_{j,t}$, $1\le j\le p$, $2\le t\le k$ are mutually independent. Thus,
\begin{align}
  \mathbb{P}\left[E_{\mathrm{Initial}}\cap \bigcap_{\substack{1\le j\le p \\ 2\le t\le k}}E_{j,t}\right]   &= \mathbb{P}[E_{\mathrm{Initial}}] \cdot \prod_{\substack{1\le j\le p \\ 2\le t\le k}} \mathbb{P}[E_{j,t}] \nonumber \\
  &=\left(1-\frac{c}{\log^{1.5}(N/k)}\right)^{1+p(k-1)}\label{eq:Prob-ALG} \\
  &\ge 1-\frac{c(1+p(k-1))}{\log^{1.5}(N/k)}\ge 1-\frac{2cpk}{\log^{1.5} N},\label{eq:BERN-INEQ}
\end{align}
for all large enough $N$ and all $k\le f(N)$,
where~\eqref{eq:Prob-ALG} uses~\eqref{eq:Initialize} and~\eqref{eq:E-j-t}, and~\eqref{eq:BERN-INEQ} uses Bernoulli inequality together with $k=o(\log^{1.5}N)$ so that $\log^{1.5}(N/k) =(1+o(1))\log^{1.5} N$.

For $k=o(\log^{1.5} N)$, the probability guarantee in~\eqref{eq:BERN-INEQ} is $1-o_N(1)$ since $p,c$ are constants. Observing that
\begin{equation}\label{MU}
 \boldsymbol{\mu}:=\frac{1}{k^p}\sum_{i_1\in I_1,\dots,i_p\in I_p}A_{i_1,\dots,i_p} = \frac{1}{k^p}\left(A_{i_1^{(1)},\dots,i_p^{(1)}} + \sum_{1\le j\le p}\sum_{2\le t\le k}M_{j,t}\right),
\end{equation}
 we bound $\boldsymbol{\mu}$ on the event $E_{\mathrm{Initial}}\cap \bigcap_{j,t}E_{j,t}$ which holds w.h.p. To set the stage, notice that for $N$ sufficiently large, we have $2\log(N/k) = 2\log N - 2\log k \ge \log N$ as $k=o(\log^{1.5}N)$,  $b_{N/k}<\sqrt{2\log N}$ and $\log\log(N/k)<\log\log N$. Moreover,~\eqref{eq:E-j-t} yields
\begin{equation}\label{eq:Pi-j}
    (t-1)^{p-1}\le \Pi_{j,t}\le t^{p-1}.
\end{equation}
We are ready to bound $\boldsymbol{\mu}$. We have
\begin{align}
    \boldsymbol{\mu}&\le \frac{1}{k^p}\left(\sqrt{2\log N} +\frac{\frac32\log\log N}{\sqrt{\log N}}\right)\left(1+\sum_{\substack{1\le j\le p\\ 2\le t\le k}}\sqrt{\Pi_{j,t}}\right)\label{use:eq:E-j-t} \\
    &\le \frac{1}{k^p}\left(\sqrt{2\log N} +\frac{\frac32\log\log N}{\sqrt{\log N}}\right)\left(1+p\sum_{2\le t\le k}t^{\frac{p-1}{2}}\right)\label{eq:Crudely}\\
    &\le \frac{1}{k^p}\left(\sqrt{2\log N} +\frac{\frac32\log\log N}{\sqrt{\log N}}\right)\left(1+pk^{\frac{p-1}{2}} + \frac{2p}{p+1}\left(k^{\frac{p+1}{2}} - 2^{\frac{p+1}{2}}\right)\right)\label{eq:INT-ESTIMATE} \\
    &=\frac{2\sqrt{p}}{p+1}\sqrt{\frac{2p\log N}{k^{p-1}}}\left(1+o_{k,N}(1)\right) = \frac{2\sqrt{p}}{p+1}E_{\mathrm{max}}\left(1+o_{k,N}(1)\right).\label{eq:LAST}
\end{align}
We now justify the lines~\eqref{use:eq:E-j-t}-\eqref{eq:LAST}. Line~\eqref{use:eq:E-j-t} uses~\eqref{eq:Initialize},~\eqref{eq:E-j-t}, and~\eqref{MU}; and line~\eqref{eq:Crudely} uses~\eqref{eq:Pi-j}. 
As for the line~\eqref{eq:INT-ESTIMATE}, notice the integral estimate
\[
\sum_{2\le t\le k}t^{\frac{p-1}{2}} \le k^{\frac{p-1}{2}} + \int_2^k t^{\frac{p-1}{2}}\;dt = k^{\frac{p-1}{2}}+\frac{2}{p+1}\left(k^{\frac{p+1}{2}}-2^{\frac{p+1}{2}}\right).
\]
Lastly, for~\eqref{eq:LAST} recall the facts $p=O(1)$, $k,N=\omega(1)$, as well as the fact that for $k=o(\log^{1.5}N)$, under which
\[
\log\binom{N}{k} = k\log \frac{N}{k}(1+o_{N,k}(1)) = k\log N \left(1+o_{N,k}(1)\right),
\]
so that~\eqref{eq:E-star} becomes
\[
E_{\mathrm{max}} = \sqrt{\frac{2p}{k^p}\log\binom{N}{k}} = \sqrt{\frac{2p \log N}{k^{p-1}}}\left(1+o_{k,N}(1)\right).
\]
The lower bound for $\boldsymbol{\mu}$ is similar and omitted. This completes the proof of Theorem~\ref{thm:IGPT}.
