\section{Basic Definitions}
% subgraph
% induced subgraph
% isomorphism
% clique
% inclusion maximal
% uv path
A \emph{subgraph} of a graph $G = (V, E)$ is a graph $H = (V_H, E_H)$ satisfying $V_H \subseteq V$ and $E_H \subseteq E$, with the additional requirement that every edge in $E_H$ has both endpoints in $V_H$.

An important special case is the \emph{induced subgraph}. For any subset $S \subseteq V$, the induced subgraph of $G$ on $S$, denoted by $G[S]$, is defined by setting $V_{G[S]} = S$ and $E_{G[S]} = \big\{ \{u,v\} \in E \mid u \in S, v \in S \big\}.$
In essence, $G[S]$ contains all vertices in $S$ and every edge of $G$ whose endpoints are both contained in $S$.

Let $G = (V, E)$ and $H = (W, F)$ be two graphs. An \emph{isomorphism} between $G$ and $H$ is a bijection $\varphi: V \to W$ that preserves adjacency; that is, for all $u,v \in V$,
$\{u,v\} \in E$ if and only if $\{\varphi(u), \varphi(v)\} \in F$.
When such a bijection exists, we say that $G$ and $H$ are \emph{isomorphic} and write $G \cong H$.

We also recall the definition of a \emph{clique} in a graph $G$. A clique is a subset of vertices $C \subseteq V$ with the property that for every two distinct vertices $u,v \in C$, the edge $\{u,v\}$ is present in $E$. A clique $C$ is termed \emph{inclusion-maximal} if no vertex $w \in V \setminus C$ can be added to $C$ while preserving the clique property; that is, there exists no $w$ for which $C \cup \{w\}$ is also a clique.

Finally, a \emph{$uv$-path} in $G$ is defined as a sequence of vertices $u = v_0, v_1, \ldots, v_k = v$,
such that for every index $0 \leq i < k$, the edge $\{v_i, v_{i+1}\}$ belongs to $E$.

\section{Proof of Lemma~\ref{lem:common-1}  and Proposition~\ref{prop:main}}
In the following sections, we use the definitions above to prove Lemma~\ref{lem:common-1} and Proposition~\ref{prop:main}.

% Note the we distinguish between the terms \emph{maximal} which refers to inclusion 
% while \emph{maximum} to size.  

\xlemma*
\begin{proof}
    Let $G_1,\dots, G_n$, be graphs. Put $G\coloneqq \star_{i=1}^n G_i$. Suppose first that $H$
    be a maximal common induced subgraph of $G_1,\dots,G_n$. By Definition, for
    every $ i$, there is an isomorphism $f_i$ from $H$ to $H_i\subseteq G_i$. 
    Note that $H\simeq H_i$ for all $i\in \{1,\dots,n\}$ implies that
    $H_i\simeq H_j$ for all $i,j\in \{1,\dots,n\}$. Now consider the map $\varphi_{i}\colon
    V(H_1)\to V(H_i)$ defined by $\varphi_i\coloneqq f_i \circ f_{1}^{-1}$ for all $i\in
    \{1,\dots,n\}$. It is easy to verify that $\varphi_{i}$ is a subgraph isomorphism between
    $H_1\subseteq G_1$ and $H_i\subseteq G_i$
    for all $i\in \{1,\dots,n\}$. Note that $\varphi_{1}$ is the identity map on $V(H_1)$, i.e.,
    $\varphi_{1}(w)=w$ for all $w\in V(H_1)$. Consider now the subgraph $K$ of $G$ that is induced
    by $\{(u, \varphi_{2}(u), \dots, \varphi_{n}(u)) \mid u\in V(H_1) \}$.  In particular,
    $|V(K)| = |V(H_1)| = |V(H)|$. Note that the projection $p_1$ satisfies 
    $p_i(u, \varphi_{2}(u), \dots, \varphi_{n}(u))$ for all $ u\in V(H_1)$
    and thus, $p_1(K) = H_1\simeq H$. Note that the choice of $H_1$ as ``basis''
    is arbitrary, i.e., we could have started with every subgraph $H_j\subseteq G_j$
    with $H_j\simeq H$ to establish such a map $\varphi_i$ via $f_i\circ f_{j}^{-1}$
    which implies that $p_j(K) = H_j\simeq H$. 

    We show now that $K$ is a clique in $G$. Assume, for
    contradiction, that $K$ is not complete. Hence, there are vertices $a = (a_1,\dots,a_n), b=(b_1,
    \dots, b_n)\in V(K)$ such that $\{a, b\}\notin E(K)\subseteq E(G)$. By definition, there are
    distinct indices $i,j \in \{1,\dots,n\}$ such that $\{a_i,b_i\}\in E(G_i)$ but
    $\{a_j,b_j\}\notin E(G_j)$. Note that $\{\varphi_i(a_1),\varphi_i(b_1)\} = \{a_i,b_i\}$ and
    $\{\varphi_j(a_1),\varphi_j(b_1)\} = \{a_j,b_j\}$. Hence, $\{\varphi_i(a_1),\varphi_i(b_1)\}\in
    E(G_i)$ implies $\{a_1,b_1\}\in E(G_1)$ while $\{\varphi_j(a_1),\varphi_j(b_1)\}\notin E(G_j)$
    implies $\{a_1,b_1\}\notin E(G_1)$; a contradiction. Thus, $K$ is a complete subgraph in $G$.
    Assume now, for contradiction, that $K$ is not a maximal clique. Hence, there is a complete
    subgraph $\tilde K$ in $G$ such that $K\subsetneq \tilde K$. Let $x\in V(\tilde K)\setminus
    V(K)$ and consider the graph $K'$ that is induced by the vertices in $V(K)\cup \{x\}]$. By definition, $x$ is adjacent to
    each vertex $w$ in $K$. Hence, either $p_i(x)$ is adjacent to $p_i(w)$ for all $i\in
    \{1,\dots,n\}$ or $p_i(x)$ is not adjacent to $p_i(w)$ for all $i\in \{1,\dots,n\}$. It is now a
    straightforward task to verify that $V(H_i)\cup \{p_i(x)\}$ induces a subgraph
    $H'_i$ in $G_i$ such that $H_i\subsetneq H'_i$ and such that $H'_i\simeq H'_j$; a contradiction
    to the maximality of $H$. Consequently, $K$ must be a maximal clique in $G$. 
\end{proof}

To establish Proposition~\ref{prop:main} we need the following result. 
\begin{lemma}
\label{lem:common-2}
    If $K$ is a clique  in $\star_{i=1}^n G_i$,
	then the graph $H$ induced by the vertex set $\{p_i(w)\mid w\in V(K)\}$ in $G_i$  
 	is a common induced subgraph of $G_1,\dots,G_n$ of size $|V(H)|=|V(K)|$ for every $i\in\{1,\dots,n\}$.
\end{lemma}
\begin{proof}
	Suppose  that there is a clique $K$ in $G\coloneqq \star_{i=1}^n G_i$. Since $K$ is a
	complete graph, definition of the $\star$-product implies that distinct vertices $\tilde u =
	(\tilde u_1,\dots, \tilde u_n)$ and $\tilde w = (\tilde w_1,\dots, \tilde w_n)$ in $K$ differ in
	each of their $i$-th coordinates, i.e., $\tilde w_i\neq \tilde u_i$ for all $i\in \{1,\dots,n\}$. Thus,
	we may assume w.l.o.g.\ that each vertex $\tilde v\in V(K)$ has coordinates $\tilde v = (v,\dots,)$; just
	relabel the vertices in $V(G_i)$, $1\leq i\leq n$, if needed. Hence, $\{\tilde
	w,\tilde u\}\in E(K)$ implies that either $\{w,u\} \in E(G_i)$ for all $i\in \{1,\dots,n\}$ or
	$\{w,u\} \notin E(G_i)$ for all $i\in \{1,\dots,n\}$. Thus, the subgraph $H_i$ incuded by
	$\{w\mid \tilde w\in V(K)\}$ in each $G_i$ satisfy $H_i\simeq H_j$ for all $i,j\in
	\{1,\dots,n\}$. Thus, $H\coloneqq H_1$ is a common subgraph of $G_1,\dots,G_n$. Since distinct
	vertices $\tilde u$ and $\tilde w$ in $K$ differ in their $i$-th coordinates, we have $|V(K)| =
	|V(H)|$. The latter arguments, in particular, imply that a common subgraph $H$ of $G_1,\dots,G_n$
	is isomorphic to the graph induced by the vertex set $\{p_i(w)\mid w\in V(K)\}$ in $G_i$ for
	every $i\in\{1,\dots,n\}$. 
\end{proof}


We may note that maximal cliques in $\star_{i=1}^n G_i$ may not ``correspond'' to maximal common
induced subgraphs of $G_1,\dots,G_n$ (see Fig.~\ref{fig:enter-label}). Nevertheless,
the result holds for maximum common induced subgraphs. 
