\section{Replica Analysis}

In this section, we provide the full derivation of the free-energy density in eq.~\eqref{Eq. Variational free entropy} in the main. The starting point of the derivation is the Gibbs formulation of the optimization problem in eq.~\eqref{Eq. Free entropy definition} in the main. The resulting calculation is performed using the replica theory toolbox from the statistical physics of disordered systems.

\subsection{Recap of the learning setting} \label{sec:recap_learning_setting}

\paragraph{\textbf{Data Model.}} We consider a dataset $ \mathcal{D} = \{\bx^{\mu}, y^{\mu}\}_{\mu=1}^P$, consisting of $P$ examples. Each data point $\bx^{\mu} \in \mathbb{R}^N$ is i.i.d. random Gaussian $x_{i}^{\mu}\sim \mathcal{N}(0,1)$ and the labels $y^\mu$ are generated by a two-layer \emph{teacher} neural network:
\begin{equation}
	y^{\mu} = \varphi_{\mathbf{A}^\star}^\star(\bW ^\star\bx^\mu, z^\mu\sqrt{\Delta^\star}):=f^{\star} \left[ \frac{1}{\sqrt{K}}\sum_{k=1}^K \, A^{\star}_{k} \sigma \left( \frac{1}{\sqrt{N}} \bw^{\star}_{k} \cdot \bx^{\mu} \right) - \sqrt{K} B^\star + z^\mu\sqrt{\Delta^\star} \right] 
	\label{eq: teacher_label}
\end{equation}
where the first and second-layer teacher weights are denoted by $\bW^\star=(\bw_k^\star\in \mathbb{R}^N)_{k=1}^K\in \mathbb{R}^{K\times N}$ and $\mathbf{A}^{\star} \in \mathbb{R}^K$ respectively, while $\sigma(\cdot)$ and $f^{\star}(\cdot)$ are generic point-wise activation functions and $B^{\star}$ is a bias term.  The i.i.d. $z^\mu\sim \mathcal{N}(0,1)$ are label noise whose standard deviation is controlled by $\Delta^\star$. We will assume the first-layer weights of the teacher to be extracted from a generic prior $P_{\bW^\star}(\bW)$ which is factorized over the $N$ inputs
\begin{equation}
	P_{\bW^\star}(\bW) = \prod_{i = 1}^N P_{\bw^\star}(\bw_i).
\end{equation}
The second layer weights are extracted from a generic prior 
\begin{equation}
	P_{\mathbf{A}}(\mathbf{A}^\star) = \prod_{i=1}^K P_{A}(A^\star_i)    .
\end{equation}

The bias $B^\star$ is fixed to remove the mean of the second layer pre-activation. Therefore, given the input data and weight's distribution:
\begin{equation}
	B^\star = \frac{1}{K}\sum_{k=1}^K\mathbb{E}_{\bx^\mu,A_k^\star,\bw^\star}\left[a_k^\star\sigma\left(\frac{\bw ^\star_k \cdot \bx^\mu}{\sqrt{N}}\right)\right] =  \frac{\mu_A}{K}\sum_{k=1}^K\mathbb{E}_{x,\bw^\star}\left[\sigma\left(x\sqrt{\frac{\bw^\star_k \cdot \bw^\star_k}{
			N}}\right)\right] \overset{N\to\infty}{=} \mu_A \mathbb{E}_x\left[\sigma\left(x\sqrt{\frac{\mathbb{E}[\bw_k^2]}{N}}\right)\right]\label{eq:bias}.
\end{equation}
In the last equality, we use the assumption that each weight vector $\bw_k^\star$ is drawn independently and identically distributed (i.i.d.), and that the $\bw_{ki}$ are independently sampled. We denote by $\mu_{A}$ the mean of $P_A$.\\

\paragraph{\textbf{Learning Model.}} We want to fit the dataset $\mathcal{D}$ with a two-layer \emph{student} network:
\begin{equation}
	\hat{y}^{\mu} = \varphi_{\mathbf{A}}(\bW\bx^\mu,0) = f \left[ \frac{1}{\sqrt{K}}\sum_{k=1}^K \, A_{k} \sigma_k \left(\frac{1}{\sqrt{N}} \bw_{k} \cdot \bx^{\mu} \right) - \sqrt{K}B \right]\label{eq:predictions}
\end{equation}
whose second-layer weights $\mathbf{A} \in \mathbb{R}^K$ are generic but fixed and only the first layer $\bW \in \mathbb{R}^{K \times N}$ is learned through the training set. This learning model is also known as committee machine. The activation functions $f(\cdot)$ is not necessarily the same as the ones of the teacher network; and the bias term $B$ depends on the weights $\bW$. In practice, $B$ is updated separately during learning once per epoch, based on the current state of the weights (sec. \ref{sec:appendix_numerics}).\\ 

\paragraph{\textbf{The task.}} We are interested in analytically characterize the generalization performances of the Empirical Risk Minimization estimator:
\begin{equation}
	\hat{\bW} = \underset{\bW}{\mbox{argmin}} \left[ \sum_{\mu = 1}^P \ell \left( y^{\mu}, \hat{y}^{\mu} \left(\bx^{\mu}; \bW, \boldsymbol{A}  \right) \right) + \lambda r( \bW )\right] \label{eq: non-convex_opt_problem}
\end{equation}
for generic loss functions $\ell \left( \cdot, \cdot \right)$ and regularization $r(\cdot)$, with weight decay $\lambda\geq0$.  We focus on the case where the trainable model is already
set with the correct readout weights (which are few compared to the inner ones) and we thus 
the dependency on those weights to lighten notations, i.e. $\boldsymbol{A}^\star=\boldsymbol{A}$. 

\subsection{Gibbs formulation}

Given the learning setting defined in sec. \ref{sec:recap_learning_setting}, we define the following Gibbs measure over the student first-layer weights $\bW \in \mathbb{R}^{N \times K}$:
\begin{equation}
	\pi_{\beta} \left( \bW |  \mathcal{D}; \mathbf{A} \right) = \frac{1}{Z_{\beta}} e^{-\beta \sum_{\mu = 1}^P \ell \left( y^{\mu}, \ \hat{y}^{\mu}\left( \bx^{\mu}; \bW, \mathbf{A}\right) \right) - r\left( \bW \right)} %= \frac{e^{-\beta r\left( \bw \right)}}{Z_{\beta}}\prod_{\mu = 1}^P e^{-\beta \ell \left( y^{\mu}, \ \hat{y}^{\mu}\left( \bx^{\mu}; \bw, \boldsymbol{a}\right) \right)} 
	= \frac{1}{Z_{\beta}} P_{\bW}(\bW) \prod_{\mu = 1}^P P_y \left( y^{\mu} \Big\vert  \frac{\bW\bx^{\mu}}{\sqrt{N}}; \boldsymbol{A} \right) \label{eq:posterior}  
\end{equation}
with $\beta >0$ being the inverse temperature. In the low-temperature limit (e.g. $\beta \rightarrow \infty$), $\pi_{\beta}$ peaks in the solutions of the non-convex optimization problem in eq.~\eqref{eq: non-convex_opt_problem}. Note that, the second equality suggests that $\pi_{\beta}$ can be interpreted as a posterior distribution over the first layer $\bW$, with $P_\bW$ and $P_y$ being the prior and the likelihood respectively. We take $r$ to be a component-wise regularizer, which implies that the prior factorizes as:
\begin{equation}
	P_{\bW}(\bW) = \prod_{i=1}^N P_{\bw}(\bw_i) .
\end{equation}

Obtaining an exact analytical expression for $\pi_{\beta}$ when $N$, $P$ and $K$ are large is unpracticable. However, in this high-dimensional limit, it can be shown that the free-entropy density averaged over the training set distribution:
\begin{equation}
	\langle \Phi_{\beta} \rangle  =  \underset{N \rightarrow \infty}{\lim} \frac{1}{N K} \mathbb{E}_{\mathcal{D}}\left[\mbox{log}Z_{\beta}\right]  
\end{equation}
can be explicitly computed by means of the replica method. Here $\mathbb{E}_\mathcal{D}$ denotes the expectation over the data $\mathcal{D}$, which implicitly includes averaging over the weights $\bw^\star$ and the label noise $\mathbf{z}=(z^1,\hdots,z^P)$. This quantity is central because key observables characterizing the learning problem in sec. \ref{sec:recap_learning_setting} -- such as training loss or generalization error-- can be obtained from partial derivatives of the free-energy density. We will perform this computation in the thermodynamic limit $N, P, K \to \infty$, but in a regime where the number of hidden neurons is small compared to the input dimension and sample dimensions: $\frac{K}{N} \to 0$ and $\frac{K}{P} \to 0$. Moreover, we  distinguish between two scaling data regimes:\begin{itemize}
	\item A \textit{small-sample} regime, where the number of samples scales linearly with the input dimension: $P = \alpha N$, with $\alpha$ being the constraint density also known as the sample complexity.
	\item A \textit{large-sample} regime, where the sample complexity is controlled by $\Tilde{\alpha} \equiv \frac{P}{NK } = O (1) $
\end{itemize}

\subsection{Replica computation of the free-energy density} 

The free-entropy density $\Phi_{\beta}(\mathcal{D}) =  \mbox{log}\left( Z_{\beta}(\mathcal{D}) \right)$ is a random variable over different realizations of the training set $ \mathcal{D} = \{\bx^{\mu}, y^{\mu}\}_{\mu=1}^P$. We assume that its associated distribution $P(\Phi)$ satisfies a large deviation principle:
\begin{equation}
	P(\Phi) \simeq e^{-NK\Phi}.
\end{equation}
%where $\Phi(\cdot)$ is a concave function whose maximum is reached at $f = f_{\beta}$.
In the high-dimensional limit $N \rightarrow \infty$, this hypothesis implies that $P(\Phi)$ is peaked on $\langle \Phi_{\beta}\rangle$ and the fluctuations around this mean go to zero, a property known as \emph{self-averaging}. 

To compute $\langle \Phi_{\beta} \rangle$ we need to take the expectation of a logarithm. To overcome this difficulty, we can use replica theory and therefore write the mean free-entropy density in terms of $n>0$ different copies of the same learning system:
\begin{equation}
	K \langle \Phi_{\beta} \rangle =  \underset{N \rightarrow \infty}{\lim} \frac{1}{N} \underset{n \rightarrow 0^{+}}{\lim} \frac{ \mathbb{E}_{\mathcal{D}}\left[Z^n_{\beta}\right]-1}{n}
\end{equation}
where the replicated partition function  is:
\begin{equation}
	Z^n_{\beta} = \prod_{a=1}^n \int_{\mathbb{R}^{K\times N}} d\bw^a P_w\left( \bw^a \right) \prod_{\mu = 1}^P P_y \left( y^{\mu} \vert \left\{ \frac{\bw_k^a \cdot \bx^{\mu}}{\sqrt{N}} \right\}_{k=1}^K, \mathbf{A} \right).
\end{equation}

\paragraph{Average over the training set.} To average the replicated partition function over the training set, we can first write the expectation over the labels explicitly, using the generative model in eq.\eqref{eq: teacher_label}, and then introduce the hidden layer pre-activations for both the teacher and student network:
\begin{equation}
	\nu_{\mu k} = \frac{\bw_k^{\star} \cdot \bx^{\mu}}{\sqrt{N}} ,\hspace{10mm} \lambda^a_{\mu k} = \frac{\bw_k^{a} \cdot \bx^{\mu}}{\sqrt{N}} 
\end{equation}
by means of Dirac $\delta$-functions. This allows to simplify the expectation over the input data $\bx^{\mu}$:
\begin{equation}
	\begin{split}
		\mathbb{E}_{\mathcal{D}} \left[Z_{\beta}^n \right] &= \int \prod_{\mu = 1}^P dy^{\mu} \int d\bW^\star P_{w^\star}(\bW^\star) \prod_{\mu = 1}^P \int \prod_{k=1}^K \frac{d\nu_{\mu k}}{\sqrt{2\pi}} P^{\star}_y \left( y^{\mu} \vert \{ \nu_{\mu k}\}_{k=1}^K ,\,\mathbf{A} \right)\\ 
		&\times\int \prod_{a=1}^n d\bW^a P_w(\bW^a) \prod_{a=1}^n\prod_{\mu = 1}^P \prod_{k=1}^K \frac{d\lambda^a_{\mu k}}{\sqrt{2\pi}} P_y \left( y^{\mu} \vert \{ \lambda^a_{\mu k}\}_{k=1}^K,\,\mathbf{A}  \right) \\
		&\times \prod_{\mu = 1}^n \mathbb{E}_{\bx^{\mu}} \left[ \prod_{k=1}^K \delta\left( \nu_{\mu k} - \frac{\bw_k^{\star} \cdot \bx^{\mu}}{\sqrt{N}} \right) \prod_{a=1}^n \delta \left( \lambda^a_{\mu k} - \frac{\bw_k^{a} \cdot \bx^{\mu}}{\sqrt{N}} \right)\right].
	\end{split}
\end{equation}
By introducing the integral representation of the Dirac $\delta$-functions:
\begin{equation}
	\begin{split}
		\delta\left( \nu_{\mu k} - \frac{\bw_k^{\star} \cdot \bx^{\mu}}{\sqrt{N}} \right) &= \int \frac{d\hat{\nu}_{\mu k}}{\sqrt{2\pi}} \mbox{exp}\left( -i\hat{\nu}_{\mu k} \left( \nu_{\mu k} - \frac{\bw_k^{\star} \cdot \bx^{\mu}}{\sqrt{N}} \right) \right),\\
		\delta \left( \lambda^a_{\mu k} - \frac{\bw_k^{a} \cdot \bx^{\mu}}{\sqrt{N}} \right) &= \int \frac{d\hat{\lambda}^a_{\mu k}}{\sqrt{2\pi}} \mbox{exp}\left( -i\hat{\lambda}_{\mu k} \left( \lambda^a_{\mu k} - \frac{\bw_k^{a} \cdot \bx^{\mu}}{\sqrt{N}} \right) \right), 
	\end{split}
\end{equation}
we can finally perform the expectation over $\bx^{\mu}$, which is now reduced to a simple Gaussian integral:
\begin{equation}
	\begin{split}
		\mathbb{E}_{\mathcal{D}} \left[Z_{\beta}^n \right] &= \int d\bW^\star P_{w^\star}(\bW^\star) \prod_{\mu = 1}^P \int dy^{\mu} \int \prod_{k=1}^K \frac{d\nu_{\mu k} d\hat{\nu}_{\mu k}}{2\pi} e^{i \sum_{k=1}^K \hat{\nu}_{\mu k} \nu_{\mu k}} P^{\star}_y \left( y^{\mu} \vert \{ \nu_{\mu k}\}_{k=1}^K,\,\mathbf{A}  \right) \\ 
		&\times \int \prod_{a=1}^n d\bW^a P_w(\bW^a) \prod_{a=1}^n\prod_{\mu = 1}^P \int \prod_{k=1}^K \frac{d\lambda^a_{\mu k} d\hat{\lambda}^a_{\mu k}}{2\pi} e^{i \sum_{k=1}^K \hat{\lambda}^a_{\mu k} \lambda^a_{\mu k}}  P_y \left( y^{\mu} \vert \{ \lambda^a_{\mu k}\}_{k=1}^K,\,\mathbf{A}  \right) \\
		& \times \mbox{exp}\left(-\frac{1}{2} \sum_{k, k^\prime=1}^K \hat{\nu}_{\mu k} \hat{\nu}_{\mu k^\prime} \frac{\bw^\star_{k} \cdot \bw^\star_{k^{\prime}}}{N} - \frac{1}{2} \sum_{a,b = 1}^n \sum_{k, k^\prime=1}^K \hat{\lambda}^a_{\mu k} \hat{\lambda}^b_{\mu k^\prime} \frac{\bw^a_{k} \cdot \bw^b_{k^{\prime}}}{N} - \sum_{a=1}^n \sum_{k, k^\prime=1}^K \hat{\lambda}^a_{\mu k} \hat{\nu}_{\mu k^\prime} \frac{\bw^a_{k} \cdot \bw^\star_{k^\prime}}{N} \right).
	\end{split} \label{eq: replicated_pf_after_data_average}
\end{equation}

\paragraph{Order parameters.} After averaging over the training set, we note that the integrals in eq.~\eqref{eq: replicated_pf_after_data_average} get coupled via the following set of overlap parameters:
\begin{equation}
	\rho_{k k^\prime} \defeq \frac{\bw^\star_{k} \cdot \bw^\star_{k^{\prime}}}{N} ,\hspace{10mm} q^{ab}_{k k^\prime} \defeq \frac{\bw^a_{k} \cdot \bw^b_{k^{\prime}}}{N} ,\hspace{10mm} m^a_{k k^\prime} \defeq \frac{\bw^a_{k} \cdot \bw^\star_{k^\prime}}{N}.
\end{equation}
To decouple the integrals, it is useful to introduce the overlap definition by means of Dirac $\delta$-functions and their integral representations:
\begin{equation}
	\begin{split}
		1 &\propto \int \prod_{kk^\prime = 1}^K \frac{d\rho_{kk^\prime} d\hat{\rho}_{kk^\prime}}{2\pi} \mbox{exp}\left( -i \sum_{k k^\prime = 1}^K\hat{\rho}_{kk^\prime}\left(\rho_{kk^\prime} - \frac{\bw^\star_{k} \cdot \bw^\star_{k^{\prime}}}{N} \right) \right) \\
		& \times\int \prod_{kk^\prime = 1}^K  \prod_{a=1}^n \frac{dm^a_{kk^\prime} d\hat{m}^a_{kk^\prime}}{2\pi} \mbox{exp}\left( -i \sum_{k k^\prime = 1}^K\sum_{a=1}^n\hat{m}^a_{kk^\prime}\left(m^a_{kk^\prime} - \frac{\bw^a_{k} \cdot \bw^\star_{k^{\prime}}}{N} \right) \right)\\
		&\times \int \prod_{kk^\prime = 1}^K  \prod_{a \leq b=1}^n \frac{dq^{ab}_{kk^\prime} d\hat{q}^{ab}_{kk^\prime}}{2\pi} \mbox{exp}\left( -i \sum_{k k^\prime = 1}^K\sum_{a\leq b = 1}^n\hat{q}^{ab}_{kk^\prime}\left(q^{ab}_{kk^\prime} - \frac{\bw^a_{k} \cdot \bw^b_{k^{\prime}}}{N} \right) \right). 
	\end{split}
\end{equation}
Introducing the above in eq.~\eqref{eq: replicated_pf_after_data_average}, we notice that the integrals factorize over the index $i = 1,..., N$ and $\mu = 1, ..., P = \alpha N$. With the change of variables $i\hat{\rho}_{kk^\prime} \rightarrow  \hat{\rho}_{kk^\prime} $, $i\hat{m}^a_{kk^\prime} \rightarrow  \hat{m}^a_{kk^\prime}$ and $i\hat{q}^{ab}_{kk^\prime} \rightarrow  \hat{q}^{ab}_{kk^\prime}$, we can then express the replicated partition function in terms of saddle-point integrals:
\begin{equation}
	\mathbb{E}_{\mathcal{D}} \left[Z_{\beta}^n \right] = \int \prod_{kk^\prime = 1}^K \frac{d\rho_{kk^\prime} d\hat{\rho}_{kk^\prime}}{2\pi} \int \prod_{kk^\prime = 1}^K  \prod_{a=1}^n \frac{dm^a_{kk^\prime} d\hat{m}^a_{kk^\prime}}{2\pi} \int \prod_{kk^\prime = 1}^K  \prod_{a,b=1}^n \frac{dq^{ab}_{kk^\prime} d\hat{q}^{ab}_{kk^\prime}}{2\pi} \mbox{exp}\left( N \phi \right)
\end{equation}
where the potential $\phi$ is given by the sum of three distinct terms:
\begin{equation}
	\phi = G_I \left( \rho_{kk^\prime}, m^a_{kk^\prime}, q^{ab}_{kk^\prime}, \hat{\rho}_{kk^\prime}, \hat{m}^a_{kk^\prime}, \hat{q}^{ab}_{kk^\prime} \right) + G_S \left( \hat{\rho}_{kk^\prime}, \hat{m}^a_{kk^\prime}, \hat{q}^{ab}_{kk^\prime} \right) + \alpha G_E \left( \rho_{kk^\prime}, m^a_{kk^\prime}, q^{ab}_{kk^\prime} \right),
	\label{eq:action}
\end{equation}
with the ``interaction'', ``entropic'' and ``energetic'' potentials being respectively:
\begin{equation}
	\begin{split}
		&G_I = - \sum_{k k^\prime} \hat{\rho}_{kk^\prime} \rho_{kk^\prime} - \sum_{k k^\prime} \sum_{a=1}^n \hat{m}^a_{k k^\prime} m^a_{k k^\prime} - \sum_{k k^\prime}\sum_{a \leq b=1}^n \hat{q}^{ab}_{k k^\prime}q^{ab}_{k k^\prime},\\
		&G_S = \mbox{log} \int_{\mathbb{R}^K} d\bw^\star P_{w^\star}(\bw^\star) \prod_{a=1}^n \int_{\mathbb{R}^K} d\bw^a P_w(\bw^a) \ \mbox{exp}\left( \sum_{kk^\prime} \hat{\rho}_{kk^\prime} w_k^\star w^\star_{k^{\prime}} + \sum_{a=1}^n \sum_{k k^\prime} \hat{m}_{kk^\prime}^a w^a_k w^\star_{k^\prime} + \sum_{a \leq b = 1}^n \hat{q}^{ab}_{kk^\prime} w_k^a w^b_{k^\prime} \right),\\
		&G_E = \mbox{log}\int dy \int \prod_{k=1}^K \frac{d\nu_k d\hat{\nu}_k}{2\pi} P^{\star}_y \left( y \vert \{ \nu_{k}\}_{k=1}^K,\,\mathbf{A}  \right) \ \mbox{exp}\left(-\frac{1}{2} \sum_{k k^\prime = 1}^K \rho_{kk^\prime} \hat{\nu}_k \hat{\nu}_k^\prime + i \sum_{k=1}^K \hat{\nu}_k \nu_k \right) \times\\
		&\times \int \prod_{k=1}^K \prod_{a=1}^n \frac{d\lambda_k^a d\hat{\lambda}^a_k}{2\pi}  \, P_y \left( y \vert \{ \lambda^a_{ k}\}_{k=1}^K,\,\mathbf{A}  \right) \ \mbox{exp}\left( -\frac{1}{2} \sum_{ab=1}^n \sum_{kk^\prime = 1}^K q_{kk^\prime}^{ab} \hat{\lambda}_k^a \hat{\lambda}^b_{k^\prime} - \sum_{a=1}^n \sum_{kk^\prime = 1}^K m_{k k^\prime}^a \hat{\lambda}_k^a \hat{\nu}_{k^\prime} + i \sum_{a=1}^n \sum_{k=1}^K \hat{\lambda}^a_k \lambda_k^a\right).
	\end{split}
\end{equation}
In the high-dimensional limit, the integrals over the overlap parameters and their conjugates can be solved by saddle-point, so that the mean free-entropy density can be determined through the following optimization problem:
\begin{equation}
	\langle \Phi_{\beta} \rangle = \underset{N \rightarrow \infty}{\lim} \frac{1}{N} \underset{n \rightarrow 0^{+}}{\lim} \frac{\mathbb{E}_{\mathcal{D}}\left[Z^n_{\beta}\right] - 1}{n} = \underset{\rho_{kk^\prime}, m^a_{kk^\prime}, q^{ab}_{kk^\prime}, \hat{\rho}_{kk^\prime}, \hat{m}^a_{kk^\prime}, \hat{q}^{ab}_{kk^\prime}}{\mbox{extr}} \left[\underset{n \rightarrow 0^{+}}{\lim} \frac{1}{n} \phi \left( \rho_{kk^\prime}, m^a_{kk^\prime}, q^{ab}_{kk^\prime}, \hat{\rho}_{kk^\prime}, \hat{m}^a_{kk^\prime}, \hat{q}^{ab}_{kk^\prime} \right)\right].
\end{equation}
This leads to a system of coupled saddle-point equations, whose unknowns are precisely the overlap parameters and their conjugates.\\

\paragraph{Replica-Symmetry assumption.} To proceed further in the calculation, we can assume that all replicas are symmetric with respect to permutations:
\begin{equation}
	\begin{split}
		q_{kk^\prime}^{ab} &= r_{kk^\prime} \delta_{ab} + q_{kk^\prime} (1 - \delta_{ab}) ,\hspace{10mm} m_{kk^\prime}^{a} = m_{kk^\prime}, \\
		\hat{q}_{kk^\prime}^{ab} &= -\frac{1}{2}\hat{r}_{kk^\prime} \delta_{ab} + \hat{q}_{kk^\prime} (1 - \delta_{ab}), \hspace{4.3mm} \hat{m}_{kk^\prime}^{a} = \hat{m}_{kk^\prime}  .     
	\end{split}
\end{equation}
Indeed, since replicas have been introduced as different copies of the same system, we can think that they are all equivalent. Applying this ansatz in eq.\eqref{eq:action}, we can write the replica-symmetric interaction, entropic and energetic potential as:
\begin{equation}
	\begin{split}
		&G_I = - \sum_{k k^\prime} \hat{\rho}_{kk^\prime} \rho_{kk^\prime} - n\sum_{k k^\prime} \hat{m}_{k k^\prime} m_{k k^\prime} + \frac{n}{2} \sum_{k k^\prime} \hat{r}_{k k^\prime}r_{k k^\prime} - \frac{n(n-1)}{2} \sum_{kk^\prime} \hat{q}_{kk^\prime} q_{kk^\prime},\\
		&G_S = \mbox{log} \int_{\mathbb{R}^K} d\bw^\star P_{w^\star}(\bw^\star) e^{(\bw^\star)^t \hat{\rho} \bw^\star} \prod_{a=1}^n \int_{\mathbb{R}^K} d\bw^a P_w(\bw^a) \ \mbox{exp}\left( -\frac{1}{2}\sum_{a=1}^n (\bw^a)^t \hat{v} \bw^a + \frac{1}{2} \sum_{a b = 1}^n (\bw^a)^t \hat{q} \bw^b  + \sum_{a=1}^n (\bw^\star)^t \hat{m} \bw^a \right),\\
		&G_E = \mbox{log} \int dy \int \prod_{k=1}^K \frac{d\nu_k d\hat{\nu}_k}{2\pi} P^{\star}_y \left( y \vert \{ \nu_{k}\}_{k=1}^K,\,\mathbf{A}  \right) \mbox{exp}\left(-\frac{1}{2} \hat{\boldsymbol{\nu}}^t \rho \hat{\boldsymbol{\nu}} + i \hat{\boldsymbol{\nu}}^t \boldsymbol{\nu} \right) \\
		&\times \int \prod_{k=1}^K \prod_{a=1}^n \frac{d\lambda_k^a d\hat{\lambda}^a_k}{2\pi}  P_y \left( y \vert \{ \lambda^a_{ k}\}_{k=1}^K,\,\mathbf{A}  \right) \mbox{exp}\left(- \frac{1}{2} \sum_{a=1}^n (\hat{\boldsymbol{\lambda}}^a)^t v \hat{\boldsymbol{\lambda}}^a -\frac{1}{2} \sum_{ab=1}^n (\hat{\boldsymbol{\lambda}}^a)^t q \hat{\boldsymbol{\lambda}}^b -\sum_{a=1}^n \hat{\boldsymbol{\nu}}^t m \hat{\boldsymbol{\lambda}}^a + i \sum_{a=1}^n (\hat{\boldsymbol{\lambda}}^a)^t \boldsymbol{\lambda}^a  \right).
	\end{split}
\end{equation}
with $\boldsymbol{\nu}, \hat{\boldsymbol{\nu}}, \boldsymbol{\lambda}^a, \hat{\boldsymbol{\lambda}}^a \in \mathbb{R}^K$ and $\rho, \hat{\rho}, q, \hat{q}, r, \hat r, m, \hat{m} \in \mathbb{R}^{K\times K}$. The variables $v$ and $\hat v$ appearing in the energetic and entropic terms are also defined as
\begin{subequations}
	\label{eq::change_of_variables}
	\begin{align}
		v &\equiv r- q, \\
		\hat v &\equiv \hat r + \hat q \,.
	\end{align}
\end{subequations}
We can now notice that, the quadratic sums appearing in both $G_S$ and $G_E$ can be linearized using the following Hubbard-Strat\"{o}novich transformations:
\begin{equation}
	\begin{split}
		&\mbox{exp}\left( \frac{1}{2} \sum_{ab=1}^n (\bw^a)^t \hat{q} \bw^b \right) = \int_{\mathbb{R}^K} D\boldsymbol{\xi}\ \mbox{exp} \left( \boldsymbol{\xi}^t \hat{q}^{1/2} \sum_{a=1}^n \bw^a\right),\\
		& \mbox{exp}\left( -\frac{1}{2} \sum_{ab=1}^n (\hat{\boldsymbol{\lambda}}^a)^t q \hat{\boldsymbol{\lambda}}^b \right)=\int_{\mathbb{R}^K} D\boldsymbol{\xi} \ \mbox{exp}\left( i \boldsymbol{\xi}^t q^{1/2} \sum_{a=1}^n \boldsymbol{\lambda}^a \right),
	\end{split}
\end{equation}
with $\boldsymbol{\xi} \in \mathbb{R}^K$ and $D\boldsymbol{\xi} \defeq{\mathrm{d}\boldsymbol{\xi}\,e^{-\frac{1}{2}\boldsymbol{\xi}^2}/(2\pi)^{K/2}}$. This allows us to factorize both $G_S$ and $G_E$ over the replica index $a=1,...,n$:
\begin{equation}
	\begin{split}
		&G_S = \mbox{log} \int_{\mathbb{R}^K} D\boldsymbol{\xi} \int_{\mathbb{R}^K} d\bw^\star P_{w^\star}(\bw^\star) e^{(\bw^\star)^t \hat{\rho} \bw^\star} \left[ \int_{\mathbb{R}^K} d\bw \, P_w(\bw) \ \mbox{exp}\left( -\frac{1}{2}\bw^t \hat{v} \bw + \mathbf{\xi}^t \hat{q}^{1/2} \bw +( \bw^\star)^t \hat{m} \bw \right)\right]^n,\\
		&G_E = \mbox{log} \int D\boldsymbol{\xi} \int dy \int \prod_{k=1}^K \frac{d\nu_k d\hat{\nu}_k}{2\pi} P^{\star}_y \left( y \vert \{ \nu_{k}\}_{k=1}^K,\,\mathbf{A}  \right) \mbox{exp}\left(-\frac{1}{2} \hat{\boldsymbol{\nu}}^t \rho \hat{\boldsymbol{\nu}} + i \hat{\boldsymbol{\nu}}^t \boldsymbol{\nu} \right) \times\\
		&\times \left[\int \prod_{k=1}^K \frac{d\lambda_k d\hat{\lambda}_k}{2\pi}  P_y \left( y \vert \{ \lambda_{ k}\}_{k=1}^K,\,\mathbf{A}  \right) \mbox{exp}\left(- \frac{1}{2} \hat{\boldsymbol{\lambda}}^t v \hat{\boldsymbol{\lambda}} +i\boldsymbol{\xi}^t q^{1/2} \hat{\boldsymbol{\lambda}} - \hat{\boldsymbol{\nu}}^t m \hat{\boldsymbol{\lambda}} + i \hat{\boldsymbol{\lambda}}^t \boldsymbol{\lambda}  \right)\right]^n.
	\end{split}
\end{equation}
We note that the teacher and the student are coupled in $G_S$ by the term $(\bw^\star)^t \hat{m} \bw$ and in $G_E$ by the term $\hat{\boldsymbol{\nu}}^t m \hat{\boldsymbol{\lambda}}$. To uncouple them and simplify $G_S$ and $G_E$ further, we can perform the change of variables $\boldsymbol{\xi} \rightarrow \boldsymbol{\xi} -  \hat{q}^{-1/2}\hat{m}^t\hat{\bw}^\star$ in $G_S$ and $\boldsymbol{\xi} \rightarrow \boldsymbol{\xi} - i q^{-1/2}m^t\hat{\boldsymbol{\nu}}$ in $G_E$. In this way, we get the following:
\begin{equation}
	\begin{split}
		&G_S = \mbox{log} \int \frac{d\boldsymbol{\xi}}{(2\pi)^{K/2}}  \left[ \int_{\mathbb{R}^K} d\bw^\star P_{w^\star}(\bw^\star) e^{-\frac{1}{2} \left(\boldsymbol{\xi} - q^{-1/2}\hat m^t\hat{\bw}^\star \right)^2 + (\bw^\star)^t \hat{\rho} \bw^\star} \right] \left[ \int_{\mathbb{R}^K} d\bw \, P_w(\bw) \ \mbox{exp}\left( -\frac{1}{2}\bw^t \hat{v} \bw + \boldsymbol{\xi}^t \hat{q}^{1/2} \bw \right)\right]^n ,\\
		&G_E = \mbox{log} \int \frac{d\boldsymbol{\xi}}{(2\pi)^{K/2}} \int dy \int \prod_{k=1}^K \frac{d\nu_k d\hat{\nu}_k}{2\pi} P^{\star}_y \left( y \vert \{ \nu_{k}\}_{k=1}^K,\mathbf{A}  \right) \exp\left(-\frac{1}{2} \left(\boldsymbol{\xi} - iq^{-1/2}m^t\hat{\boldsymbol{\nu}} \right)^2 -\frac{1}{2} \hat{\boldsymbol{\nu}}^t \rho \hat{\boldsymbol{\nu}} + i \hat{\boldsymbol{\nu}}^t \boldsymbol{\nu} \right) \\
		&\hspace{9mm}\times \left[\int \prod_{k=1}^K \frac{d\lambda_k d\hat{\lambda}_k}{2\pi}  P_y \left( y \vert \{ \lambda_{ k}\}_{k=1}^K,\,\mathbf{A}  \right) \exp\left(- \frac{1}{2} \hat{\boldsymbol{\lambda}}^t v \hat{\boldsymbol{\lambda}} +i\boldsymbol{\xi}^t q^{1/2} \hat{\boldsymbol{\lambda}} + i \hat{\boldsymbol{\lambda}}^t \boldsymbol{\lambda}  \right)\right]^n.
	\end{split}
\end{equation}

\paragraph{Limit $n \rightarrow 0$.} Through a series of Taylor's expansions around $n = 0$, we get the following expressions for the interaction, entropic and energetic potentials:
\begin{equation}
	\begin{split}
		&\mathcal{G}_I = \underset{n \rightarrow 0}{\lim} \frac{G_I}{n} = \underset{n \rightarrow 0}{\lim}\left[-\frac{1}{n} \sum_{kk^\prime} \hat{\rho}_{kk^\prime} \rho_{kk^\prime} - \sum_{k k^\prime} \hat{m}_{kk^\prime} m_{kk^\prime} + \frac{1}{2}\sum_{kk^\prime} (\hat{v} - \hat{q})_{kk^\prime} (v + q)_{kk^\prime} + \frac{1}{2} \sum_{k k'} \hat{q}_{kk^\prime} q_{kk^\prime}\right],\\
		&\mathcal{G}_S = \underset{n \rightarrow 0}{\lim} \frac{G_S}{n} = \underset{n \rightarrow 0}{\lim}\left[\frac{1}{n} \log \int_{\mathbb{R}^K} d\bw^\star P_{w^\star}(\bw^\star) e^{(\bw^\star)^t \hat{\rho} \bw^\star} + \frac{1}{n}\mbox{log}\left( 1 + n \mathcal{I}(\hat{\rho}, \hat{v}, \hat{q}, \hat{m})\right)\right],\\
		& \mathcal{G}_E = \underset{n \rightarrow 0}{\lim} \frac{G_E}{n} = \underset{n \rightarrow 0}{\lim}\left[ \int \frac{d\boldsymbol{\xi}}{\sqrt{(2\pi)^K}} \int dy \int \prod_{k=1}^K \frac{d\nu_k d\hat{\nu}_k}{2\pi} P^{\star}_y \left( y \vert \{ \nu_{k}\}_{k=1}^K,\,\mathbf{A}  \right) e^{-\frac{1}{2} \left(\boldsymbol{\xi} - iq^{-1/2}m^t\hat{\boldsymbol{\nu}} \right)^2 -\frac{1}{2} \hat{\boldsymbol{\nu}}^t \rho \hat{\boldsymbol{\nu}} + i \hat{\boldsymbol{\nu}}^t \boldsymbol{\nu}} \right.\\
		&\hspace{21.5mm}\times \left.\left( 1 + n \mbox{log} \left( \int \prod_{k=1}^K \frac{d \lambda_k d\hat{\lambda}_k}{2\pi} P_y \left( y \vert \{ \lambda_{k}\}_{k=1}^K,\mathbf{A}  \right) e^{-\frac{1}{2} \hat{\boldsymbol{\lambda}}^t v \hat{\boldsymbol{\lambda}} + i \boldsymbol{\xi}^t q^{1/2} \hat{\boldsymbol{\lambda}} + i \hat{\boldsymbol{\lambda}}^t \boldsymbol{\lambda} }  \right) \right) \right]
	\end{split}\label{eq:Taylor_potentials}
\end{equation}
where the function $\mathcal{I}(\hat{\rho}, \hat{v}, \hat{q}, \hat{m})$ is given by:
\begin{equation}
	\mathcal{I} = \frac{\int D \boldsymbol{\xi} \int d\bw^\star P_{w^\star}(\bw^\star) e^{(\bw^\star)^t \hat{\rho} \bw^\star} \mbox{log}\left[ \int d\bw P_w(\bw ) \mbox{exp}\left( -\frac{1}{2}\bw^t \hat{v} \bw + \boldsymbol{\xi}^t \hat{q}^{1/2} \bw +( \bw^\star)^t \hat{m} \bw \right)\right]}{\int d\bw^\star P_{w^\star}(\bw^\star) e^{(\bw^\star)^t \hat{\rho} \bw^\star}}.
\end{equation}
We note that there are two terms $\sim \mathcal{O}(n^{-1})$, one in the interaction and another in the entropic potential. To avoid divergent potentials in the limit $n\rightarrow 0$, we need to require both terms to vanish:
\begin{equation}
	-\frac{1}{n} \sum_{kk^\prime} \hat{\rho}_{kk^\prime} \rho_{kk^\prime} + \frac{1}{n} \mbox{log} \int_{\mathbb{R}^K} d\bw^\star P_{w^\star}(\bw^\star) e^{(\bw^\star)^t \hat{\rho} \bw^\star} = 0
\end{equation}
which is true only if $\hat{\rho} = 0$. This then determines the equation for $\rho$ at the saddle-point for $n \rightarrow 0$:
\begin{equation}
	\label{eq::teacher_teacher_overlap}
	\rho_{kk^\prime} = \frac{\partial \mathcal{G}_S}{\partial \hat{\rho}_{kk^\prime}}\biggm\vert_{\hat{\rho} = 0} = \mathbb{E}_{\bw^\star} \left[w_k^\star w^\star_{k^\prime} \right] .
\end{equation}
Thanks to that, we can simplify the expression for the entropic potential in the zero-replica limit:
\begin{equation}
	\mathcal{G}_S =  \int_{\mathbb{R}^K} D\boldsymbol{\xi} \int_{\mathbb{R}^K} d\bw^\star P_{w^\star}(\bw^\star) \, \mbox{log}\int_{\mathbb{R}^K} d\bw \, P_w(\bw) \, e^{-\frac{1}{2} \bw^t \hat{v} \bw + (\mathbf{w^\star})^t \hat{m} \bw + \boldsymbol{\xi}^t \hat{q}^{1/2} \bw}.
\end{equation}
The expression of the energetic potential in eq.~\eqref{eq:Taylor_potentials} can also be further simplified, by computing the $\hat{\boldsymbol{\nu}}, \hat{\boldsymbol{\lambda}}$ - integrals, which, at this stage, are just $K$-dimensional Gaussian integrals. This leads to the following energetic potential:
\begin{equation}
	\begin{split}
		\mathcal{G}_E = \int dy \int D\boldsymbol{\xi} \int D\boldsymbol{\nu} \ P^\star_{y}(y \vert v_\star^{1/2} \boldsymbol{\nu} + m (q^\star)^{-1/2} \boldsymbol{\xi}, \mathbf{A})\label{eq:replica_symmetric_potential} \ \mbox{log} \int D\boldsymbol{\lambda} \ P_{y}(y \vert v^{1/2} \boldsymbol{\lambda} + q^{1/2} \boldsymbol{\xi}, \mathbf{A}) 
	\end{split}
\end{equation}
where we have defined
\begin{equation}
	v^\star = \rho - q^\star \in \mathbb{R}^{K \times K}, \hspace{5em} q^\star = mq^{-1}m^t
	\label{eq:v_star}.
\end{equation}

\paragraph{Summary.} Combining all the expressions above for the interaction, entropic and energetic potential, we get the final form of the mean free-energy density in the replica-symmetry assumption:
\begin{equation}
	\langle f_{\beta} \rangle = \underset{q_{kk^\prime}, v_{kk^\prime}, m_{kk^\prime}, \hat{q}_{kk^\prime}, \hat{v}_{kk^\prime}, \hat{m}_{kk^\prime}}{\mbox{extr}} \left[ \phi^{(n=0)} \left( \rho_{kk^\prime}, q_{kk^\prime}, v_{kk^\prime}, m_{kk^\prime}, \hat{q}_{kk^\prime}, \hat{v}_{kk^\prime}, \hat{m}_{kk^\prime} \right)\right]\label{eq:final_mean_free_energy}
\end{equation}
with the potential $\phi^{(n=0)}$ being the sum of the following three contributions:
\begin{equation}
	\phi^{(n=0)} = \mathcal{G}_I(q_{kk^\prime}, v_{kk^\prime}, m_{kk^\prime}, \hat{q}_{kk^\prime}, \hat{v}_{kk^\prime}, \hat{m}_{kk^\prime}) + \mathcal{G}_S(\hat{q}_{kk^\prime}, \hat{v}_{kk^\prime}, \hat{m}_{kk^\prime}) + \alpha \mathcal{G}_E(\rho_{kk^\prime}, q_{kk^\prime}, v_{kk^\prime}, m_{kk^\prime})
\end{equation}
that is, the interaction, entropic and energetic contribution in the zero-replica limit:
\begin{equation}
	\begin{split}
		&\mathcal{G}_I = - \sum_{k k^\prime} \hat{m}_{kk^\prime} m_{kk^\prime} + \frac{1}{2}\sum_{kk^\prime} (\hat{v} - \hat{q})_{kk^\prime} (v + q)_{kk^\prime} + \frac{1}{2} \sum_{k k^\prime} \hat{q}_{kk^\prime} q_{kk^\prime},\\
		&\mathcal{G}_S = \int_{\mathbb{R}^K} D\boldsymbol{\xi} \int_{\mathbb{R}^K} d\bw^\star \, P_{w^\star}(\bw^\star) \, \mbox{log} \int_{\mathbb{R}^K} d\bw \, P_w(\bw) \, e^{-\frac{1}{2} \bw^t \hat{v} \bw + (\mathbf{w^\star})^t \hat{m} \bw + \boldsymbol{\xi}^t \hat{q}^{1/2} \bw},\\
		&\mathcal{G}_E = \int dy \int D\boldsymbol{\xi} \int D\boldsymbol{\nu} \ P^\star_{y} \left(y \vert v_\star^{1/2} \boldsymbol{\nu} + m q^{-1/2} \boldsymbol{\xi}, \mathbf{A}\right) \ \mbox{log} \int D\boldsymbol{\lambda} \ P_{y}\left(y \vert v^{1/2} \boldsymbol{\lambda} + q^{1/2} \boldsymbol{\xi}, \mathbf{A}\right) . 
	\end{split}    
	\label{eq:replica_symmetric_potential}  
\end{equation}

\subsection{Teacher and student prior}

The entropic potential in eq.~\eqref{eq:replica_symmetric_potential} holds for any prior of the teacher and the student. In the following, we will restrict the discussion to a Gaussian prior over the teacher 
\begin{equation}
	P_{w^\star}(\bw^\star) = \frac{1}{\sqrt{(2\pi)^K}} e^{-\frac{1}{2} (\bw^\star)^t \bw^\star}.
\end{equation}
This will enforce, because of equation~\eqref{eq::teacher_teacher_overlap}
\begin{equation}
	\label{eq::teacher_self_overlap}
	\rho_{k k'} = \delta_{k k'} .
\end{equation}
as expected for large $N$ by the central limit theorem.  In the following, we also consider the specific case of a 
\emph{Gaussian prior} for the student
\begin{equation}
	P_w(\bw) = e^{-\frac{\beta \lambda}{2} \bw^t \bw} .
\end{equation}
%This corresponds to impose an $L_2$ regularization over the weights during learning with regularization strength being $\beta \lambda$.
This corresponds to describing the empirical risk minimization in eq.~\eqref{eq: non-convex_opt_problem} with $L_2$-regularization $r(\bw) = \beta \lambda \vert \vert \bw\vert\vert_2^2$ of intensity controlled by the parameter $\beta \lambda$. 
Note that the prior of the teacher and the student are the same if $\beta \lambda = 1$. Equivalently, remind that in the large $N$ and $P$ limit, for each choice of $\lambda$ one selects a certain value of the (squared) norm of the $K$ set of student weights in the first layer
\begin{equation}
	r_{kk} = \frac{1}{N} \sum_{i=1}^N w_{ik}^2\,, \qquad \forall k = 1, \dots, K.
\end{equation}
Because of equation~\eqref{eq::teacher_self_overlap} tells us that the norm of the teacher weights is always 1, having matching teacher and student prior will also impose $r_{kk} = 1$. Notice that the matrix $r$ corresponds to the self-overlap written as $q_{{\rm self}}$ in the main. 

In the Gaussian prior case, the integrals over $\bw$, $\bw^\star$ and $\boldsymbol{\xi}$ in eq.~\eqref{eq:replica_symmetric_potential} are standard $K$-dimensional Gaussian integrals, that solved give the following expression for the entropic potential:

\begin{equation}
	\mathcal{G}_S = \frac{K}{2} \log(2\pi) - \frac{1}{2} \mbox{log}\left[ \mbox{det}\left( \beta \lambda \mathbb{I}_{K\times K} + \hat{v} \right) \right] + \frac{1}{2}\mbox{tr}\left[ \hat{q} \left(\beta \lambda \mathbb{I}_{K\times K} + \hat{v} \right)^{-1} \right] + \frac{1}{2} \mbox{tr} \left[ \hat{m} \left( \beta \lambda \mathbb{I}_{K\times K} + \hat{v} \right)^{-1} \hat{m}^t \right] \label{eq: replica_symmetric_committee_ansatz}.
\end{equation}

\section{The limit of large number of hidden units}
The replica analysis led to a major simplification: it allowed us to transform the original optimization problem in eq.\eqref{eq: non-convex_opt_problem} spanning over an $N\times K$-dimensional space, into the $K \times K$-dimensional extremization problem in eq.~\eqref{eq:final_mean_free_energy}. Solving this problem analytically for an arbitrary $K$ is generally intractable. In this work, we consider the limit where $K \rightarrow \infty$ but slower than $N$, meaning that $K/N \rightarrow 0$ as in classical and recent works on committee machines~\cite{barkai_broken_1992,engel_storage_1992,baldassi_properties_2019, schwarze_discontinuous_1993,schwarze_learning_1993-1,aubin_committee_2018, nishiyama_solution_2025}. In this limit, as suggested in~\cite{schwarze_learning_1993}, it is reasonable to look for solutions of eq.~\eqref{eq:final_mean_free_energy} of the form:
\begin{equation}
	\begin{split}
		o &= o_d \mathbb{I}_{K \times K} + \frac{o_a}{K} \textbf{1}_K \textbf{1}^t_K  \hspace{10mm} \forall o \in \{ q, v, m \},\\
		\hat{o} &= \hat{o}_d \mathbb{I}_{K \times K} + \frac{\hat{o}_a}{K} \textbf{1}_K \textbf{1}^t_K  \hspace{10mm} \forall \hat{o} \in \{ \hat{q}, \hat{v}, \hat{m} \},
	\end{split}   
	\label{eq:committe-symmetric_ansatz} 
\end{equation}
with the $K$-dimensional all-ones column vector $\textbf{1}_K$. Indeed, when the off-diagonal part of $o$ is nonzero, the ansatz describes solutions that are symmetric under permutations of the hidden units. In contrast, when the off-diagonal part of $o$ is zero, the ansatz captures solutions in which each student hidden unit specializes by correlating with a specific hidden unit of the teacher committee machine. Note that this symmetric-committee ansatz further reduces the dimensionality of the extremization problem in eq.~\eqref{eq:final_mean_free_energy} from $K \times K$ to $2$ for each overlap parameter.

In the following, we show in full detail how to apply this ansatz in the energetic potential. We instead just provide the final expression for the interaction and the entropic potential, since applying the symmetric-committee ansatz in this case is straightforward. 



\subsection{Interaction and entropic potential}

The interaction potential is
\begin{equation}
	\begin{split}
		\mathcal{G}_I =& -K\Big(\hat{m}_d \, m_d - \frac{\hat{v}_d(q_d+v_d)}{2} + \frac{\hat{q}_d \, v_d}{2} \Big)\\
		&- \hat{m}_d \, m_a  + \frac{\hat{v}_d(q_a+v_a)}{2} - \frac{\hat{q}_d \, v_a}{2} - \hat{m}_a(m_d+m_a)  + \frac{\hat{v}_a(q_d+q_a+v_d+v_a)}{2} -\frac{\hat{q}_a(v_d+v_a)}{2}.
	\end{split}
\end{equation}
For the entropic potential, neglecting vanishing terms in $K$, one gets
\begin{equation}
	\begin{split}
		\mathcal{G}_S &= \frac{K}{2}\left[\frac{\hat{m}_d^2 + \hat{q}_d}{\beta\lambda + \hat{v}_d} + \log\left(\frac{2\pi}{\beta\lambda + \hat{v}_d}\right)\right] + \frac{1}{2} \log\left(\frac{\beta\lambda + \hat{v}_d}{\beta\lambda + \hat{v}_d+\hat{v}_a}\right) + \frac{\hat q_d + \hat q_a + (\hat m_d + \hat m_a)^2}{2(\beta \lambda + \hat v_d + \hat v_a )} - \frac{\hat q_d + \hat m_d^2}{2(\beta \lambda + \hat v_d)}. 
	\end{split}
\end{equation}



\subsubsection{Integrating the conjugated order parameters}

The interaction and entropic can be directly extremized with respect to the conjugated order parameters contained in the matrices $\hat{m}$, $\hat{q}$, and $\hat{v}$, as they do not appear in the energetic term that still needs to be analyzed. The corresponding extremization is sufficiently easy that can be solved analytically. One gets
\begin{equation}
	\begin{split}
		\mathcal{G}_{SI} &:= \max_{\hat{m},\hat{q},\hat{v}}\Big[\mathcal{G}_I + \mathcal{G}_S\Big]\\
		&= -\frac{K}{2} \left(q_d + v_d + \frac{q_a + v_a}{K}\right) \beta \lambda + \frac{K}{2}\Big[1 + \frac{q_d - m_d^2}{v_d} + \log(2\pi v_d)\Big] - \frac{1}{2} \log\Big(\frac{v_d}{v_d+v_a}\Big)\\
		& + \frac{1}{2(v_d + v_a)}\left[ q_a - 2m_d \, m_a - m_a^2 - \frac{v_a}{v_d}(q_d - m_d^2) \right]. \label{eq:entropic_channel}
	\end{split}
\end{equation}
With a slight abuse of language in the following we will call $\mathcal{G}_{SI}$ simply as the entropic potential. Note that, as expected, the term $q_d + v_d + \frac{q_a + v_a}{K}$ that multiplies the regularization strength $\beta \lambda$ is the squared norm $Q$. 
%We can express it back as a function of $Q$ by using the variables $r_d$, $r_a$ with the change of variables of equation~\eqref{eq::change_of_variables} $v_d = r_d - q_d$, $v_a = r_a - q_a$ and using the relation $r_d = Q - \frac{r_a}{K}$. One finds \emm{to comment once checks over}
%\begin{equation}
%    \begin{split}
	%       \mathcal{G}_{SI} %&:=      
	%%\max_{\hat{m},\hat{q},\hat{v}}\Big[\mathcal{G}_I + \mathcal{G}_S\Big]\\
	%&= -\frac{K}{2} Q \beta \lambda + \frac{K}{2}\left[1 + \log(2\pi) + \frac{q_d - m_d^2}{Q - q_a - \frac{r_a}{K} } + \log\left(Q-q_d - \frac{r_a}{K} \right)\right] - \frac{1}{2} \log\left(\frac{Q-q_d}{Q+r_a-q_d-q_a}\right)\\
	%& + \frac{1}{2(Q+r_a-q_d-q_a)}\left[ q_a - 2m_d \, m_a - m_a^2 - \frac{r_a-q_a}{Q-q_d}(q_d - m_d^2) \right] \\
	%        &= -\frac{K}{2} Q \beta \lambda + \frac{K}{2}\left[1 + \log(2\pi) + \frac{q_d - m_d^2}{Q - q_d} + \log\left(Q-q_d  \right)\right] - \frac{1}{2} \log\left(\frac{Q-q_d}{Q+r_a-q_d-q_a}\right)\\
	%       & - \frac{1}{2} \left[ \frac{Q+r_a-m_d^2}{Q-q_d} - \frac{r_a (q_d - m_d^2)}{(Q-q_d)^2} - \frac{Q + r_a - (m_a + m_d)^2}{Q-q_d + r_a - q_a}\right]
	%    \end{split}
