\subsection{Energetic potential}

We now analyze the large $K$ limit of the energetic potential in eq.\eqref{eq:replica_symmetric_potential}, which, making explicit the expression of the likelihood of the teacher and the student as in eq.\eqref{eq: teacher_label} and \eqref{eq:posterior} respectively, can be written as
\begin{equation}
	\begin{split}
		\mathcal{G}_E &= \int dy \int D\boldsymbol{\xi} \int D\boldsymbol{\nu} \ \int D z \, \delta \left(y - f_\star\left[\frac{1}{\sqrt{K}}\mathbf{A}^\top \sigma(v_\star^{1/2} \boldsymbol{\nu} + m q^{-1/2} \boldsymbol{\xi}) - B_\star\sqrt{K} + \sqrt{\Delta^\star} z \right] \right)  \\
		&\hspace{2em}\times \log \int D\boldsymbol{\lambda}\ \mbox{exp}\left(-\beta \ell\left(y,  f \left[ \frac{1}{\sqrt{K}} \mathbf{A}^\top  \sigma \left(v^{1/2} \boldsymbol{\lambda} + q^{1/2} \boldsymbol{\xi} \right) - B\sqrt{K} \right] \right) \right)  .
	\end{split}\label{eq: Ge_with_explicit_Pout}
\end{equation}
Here, $\sigma(\mathbf{u})$ acts element-wise on each component of $\mathbf{u}$. As a first step, we apply the symmetric-committee ansatz~\eqref{eq: replica_symmetric_committee_ansatz} in the energetic potential. We detail all the steps for the $\boldsymbol{\lambda}$-integral involving the student likelihood. The ansatz can be applied in the same way on the $\boldsymbol{\nu}$-integral involving the different teacher likelihood.   \\    

\paragraph{Student likelihood.} Using the ansatz~\eqref{eq:committe-symmetric_ansatz}, the matrix $v^{1/2}$ can be written as
\begin{equation}
	v^{1/2} = \sqrt{v_d} \mathbb{I}_K + \frac{\sqrt{v_a + v_d} - \sqrt{v_d}}{K} \boldsymbol{1}_K\boldsymbol{1}^t_K.
\end{equation}
The $\boldsymbol{\lambda}$-integral can then be expressed in terms of the diagonal and off-diagonal parts of $v$ as:
\begin{equation}
	I_{\boldsymbol{\lambda}} = \int D\boldsymbol{\lambda} \ \mbox{exp}\left(-\beta \ell\left(y,  f \left[ \frac{1}{\sqrt{K}}\sum_{k=1}^K \, A_{k} \sigma \left( \sqrt{v_d} \lambda_k + \left( \sqrt{v_d + v_a} - \sqrt{v_d} \right) \frac{\boldsymbol{1}^t_K \boldsymbol{\lambda}}{K} + \left(q^{1/2} \boldsymbol{\xi} \right)_k \right) - B\sqrt{K} \right] \right)\right).
\end{equation}
To factorize over the $k$-index, we can introduce the following definitions by means of Dirac $\delta$-functions and their integral representations:
\begin{equation}
	\begin{split}
		1 &\propto \int \frac{d\omega d\hat{\omega}}{2\pi} \mbox{exp}\left( i\hat{\omega} \left( \omega - \frac{\boldsymbol{1}^t_K \boldsymbol{\lambda}}{K} \right) \right) \\
		&\times \int \frac{du d\hat{u}}{2\pi} \mbox{exp}\left( i\hat{u} \left( u - \frac{1}{\sqrt{K}}\sum_{k=1}^K \, A_{k} \sigma \left( \sqrt{v_d} \lambda_k + \left( \sqrt{v_d + v_a} - \sqrt{v_d} \right) \frac{\omega}{\sqrt{K}} + \left(q^{1/2} \boldsymbol{\xi} \right)_k \right) + B\sqrt{K} \right) \right) 
	\end{split}
\end{equation}
leading to the following expression for the $\boldsymbol{\lambda}$-integral:
\begin{equation}
	\begin{split}
		I_{\boldsymbol{\lambda}} &= \int \frac{d\omega d\hat{\omega}}{2\pi} \int \frac{du d\hat{u}}{2\pi} \mbox{exp}\left(-\beta \ell\left(y,  f \left( u \right)\right)+ i\hat{\omega}\omega + i \hat{u}u \right) \\
		&\times\prod_{k=1}^K \int D\lambda_k \ \mbox{exp} \left( -i\hat{\omega} \frac{\lambda_k}{\sqrt{K}} - i \frac{\hat{u}}{\sqrt{K}} \left(A_k \sigma \left(\sqrt{v_d} \lambda_k + \left( \sqrt{v_d + v_a} - \sqrt{v_d} \right) \frac{\omega}{\sqrt{K}} + \left( q^{1/2} \boldsymbol{\xi} \right)_k \right) \right) + i\hat{u}B \sqrt{K} \right) .
	\end{split}\label{eq: lamb_int_v_ansatz}
\end{equation}
Using the ansatz~\eqref{eq: replica_symmetric_committee_ansatz}, the matrix $q^{1/2}$ can be written as
\begin{equation}
	q^{1/2} = \sqrt{q_d} \mathbb{I}_K + \frac{\sqrt{q_a + q_d} - \sqrt{q_d}}{K} \boldsymbol{1}_K\boldsymbol{1}^t_K
\end{equation}
so that each pre-activation $\lambda_k$ is a Gaussian variable of variance $\sqrt{v_d}$ and mean:
\begin{equation}
	\mu_k\left( \omega, \xi \right) = \sqrt{q_d} \xi_k + \frac{1}{\sqrt{K}}\left[ \left( \sqrt{v_d + v_a} - \sqrt{v_d} \right) \omega + \left( \sqrt{q_d + q_a} - \sqrt{q_d} \right) \omega_{\xi} \right] \coloneqq \mu_{k,0} \left( \xi_k\right) + \frac{1}{\sqrt{K}} \mu_1\left( \omega, \omega_{\xi} \right)
	\label{eq: mean_preact}
\end{equation}
where we defined $\omega_{\xi} = \frac{1}{\sqrt{K}} \sum_{k=1}^K \xi_k$. By plugging the definition of $\mu_k$ in eq.~\eqref{eq: lamb_int_v_ansatz} and performing the change of variable $\sqrt{v_d} \lambda_k + \mu_k \rightarrow \sqrt{v_d} \lambda_k$, we then get the following expression for $I_{\boldsymbol{\lambda}}$ under the committee-symmetric ansatz:  
\begin{equation}
	\begin{split}
		I_{\boldsymbol{\lambda}} &= \int \frac{d\omega d\hat{\omega}}{2\pi} \int \frac{du d\hat{u}}{2\pi} \mbox{exp}\left(-\beta \ell\left(y,  f \left( u \right)\right)+ i\hat{\omega}\omega + i \hat{u}u + i\hat{u} B \sqrt{K} \right) \\
		&\times\prod_{k=1}^K \mbox{exp}\left( -\frac{\mu^2_k}{2v_d} + i \frac{\hat{\omega}}{\sqrt{K}}\frac{\mu_k}{\sqrt{v_d}} \right)  \int D\lambda_k \ \mbox{exp} \left( \frac{\mu_k}{\sqrt{v_d}} \lambda_k - i\frac{\hat{\omega}}{\sqrt{K}}\lambda_k - i \frac{\hat{u}}{\sqrt{K}} A_k \sigma \left( \sqrt{v_d} \lambda_k \right) \right). 
	\end{split}\label{eq: lamb_int_q_ansatz}
\end{equation}

To expand $I_{\boldsymbol{\lambda}}$ in the limit of $K \rightarrow \infty$ we can re-write this integral as
\begin{equation}
	\begin{split}
		I_{\boldsymbol{\lambda}} &= \int \frac{d\omega d\hat{\omega}}{2\pi} \int \frac{du d\hat{u}}{2\pi} \mbox{exp}\left(-\beta \ell\left(y,  f \left( u \right)\right)+ i\hat{\omega}\omega + i \hat{u}u + i\hat{u} B \sqrt{K} +\sum_{k=1}^K \mbox{log} J_k\right)
	\end{split}\label{eq: int_lamb_explog_trick}    
\end{equation}
where we have used the standard log-exp trick so that
\begin{equation}
	\begin{split}
		\mbox{log}J_k &= -\frac{\mu_{k,0}^2}{2v_d} - \frac{\mu_{k,0} \mu_1}{v_d\sqrt{K}} + i\frac{\hat{\omega}\mu_{k,0}}{\sqrt{v_dK}} - \frac{\mu_1^2}{2v_dK} + i \frac{\hat{\omega} \mu_1}{\sqrt{v_d}K}+\\
		&+ \mbox{log} \int D\lambda_k \ \mbox{exp}\left( \frac{\mu_{k,0}}{\sqrt{v_d}} \lambda_k + \frac{1}{\sqrt{K}}\left[ \left( \frac{\mu_1}{\sqrt{v_d}} - i\hat{\omega} \right) \lambda_k - i\hat{u} A_k \sigma \left(\sqrt{v_d} \lambda_k \right) \right] \right)
	\end{split}
\end{equation}
and where we have further used the definition of $\mu_k$ in terms of $\mu_{k,0}$ and $\mu_1$ as in eq.~\eqref{eq: mean_preact}. At this point, we can expand $\mbox{log}J_k$ up to order $1/K$. Since the measure of $\lambda_k$ is normalized to $1$ up to order one in $K$, the expansion leads to the following expression:
\begin{equation}
	\mbox{log}J_k \simeq -\frac{\mu_{k,0} \mu_1}{v_d \sqrt{K}} + i \frac{\hat{\omega} \mu_{k,0}}{\sqrt{v_d K}} - \frac{\mu_1^2}{2v_d K} + i \frac{\hat{\omega} \mu_1}{\sqrt{v_d}K} + \frac{t_1}{\sqrt{K}} + \frac{t_2 - t^2_1}{2K}\label{eq: logJk_expansion}
\end{equation}
where we have defined the terms $t_1$ and $t_2$ as:
\begin{equation}
	\begin{split}
		t_1 &= \int D\lambda_k \left[ \left(\frac{\mu_1}{\sqrt{v_d}} - i \hat{\omega} \right)\lambda_k - i \hat{u} \left( A_k \sigma\left( \sqrt{v_d}\lambda_k\right)\right) \right] \mbox{exp} \left( -\frac{\mu_{k,0}^2}{2v_d} + \frac{\mu_{k,0}}{\sqrt{v_d}}\lambda_k\right),\\
		t_2 &= \int D\lambda_k \left[ \left(\frac{\mu_1}{\sqrt{v_d}} - i \hat{\omega} \right)\lambda_k - i \hat{u} \left( A_k \sigma\left( \sqrt{v_d}\lambda_k\right)\right) \right]^2 \mbox{exp} \left( -\frac{\mu_{k,0}^2}{2v_d} + \frac{\mu_{k,0}}{\sqrt{v_d}}\lambda_k\right).
	\end{split}
\end{equation}

We can now perform the integral over $\lambda_k$ in $t_1$ and $t_2$ whose result directly depends on the moments and their first derivative of the activation function with respect to the pre-activations distribution:

\begin{equation}
	\begin{split}
		t_1 &= \left( \frac{\mu_1}{\sqrt{v_d}} - i \hat{\omega} \right) \frac{\mu_{k,0}}{\sqrt{v_d}} - i \hat{u} A_k g_1 \left( \mu_{k,0}, v_d \right),\\
		t_2 &= \left( \frac{\mu_1}{\sqrt{v_d}} - i\hat{\omega} \right)^2 \left( 1 + \frac{\mu_{k,0}^2}{v_d}\right) - \hat{u}^2 A_k^2 g_2 \mu_{k,0}, v_d \\
		&- 2i\hat{u} \left( \frac{\mu_1}{\sqrt{v_d}} - i \hat{\omega}\right) \left( A_k \left( \sqrt{v_d} \Delta_1 \left(\mu_{k,0}, v_d \right) + \frac{\mu_{k,0}}{\sqrt{v_d}}  g_1 \left( \mu_{k,0}, v_d\right)\right) \right) 
	\end{split}
\end{equation}
where the functions $g_1$, $g_2$ and $\Delta_1$ are defined as it follows:
\begin{comment}
	\begin{equation}
		\begin{split}
			g_1\left( \mu_{k,0}, v_d \right) &= \mathbb{E}_{\lambda_k \sim \mathcal{N}\left( \frac{\mu_{k,0}}{\sqrt{v_d}}, 1\right)}\left[ \sigma \left( \sqrt{v_d} \lambda_k\right)\right] = \mathbb{E}_{\lambda_k\sim\mathcal{N}(0,1)} \left[\sigma(\xi_k \sqrt{q_d} + \sqrt{v_d}\lambda_k)\right]\\
			g_2\left( \mu_{k,0}, v_d \right) &= \mathbb{E}_{\lambda_k \sim \mathcal{N}\left( \frac{\mu_{k,0}}{\sqrt{v_d}}, 1\right)}\left[ \sigma^2 \left( \sqrt{v_d} \lambda_k\right)\right]\\
			\Delta_1\left( \mu_{k,0}, v_d \right) &= \mathbb{E}_{\lambda_k \sim \mathcal{N}\left( \frac{\mu_{k,0}}{\sqrt{v_d}}, 1\right)}\left[ \sigma^{\prime} \left( \sqrt{v_d} \lambda_k\right)\right]
		\end{split}
	\end{equation}
\end{comment}
\begin{equation}
	\begin{split}
		g_1\left( \xi_k \sqrt{q_d}, v_d \right) &= \mathbb{E}_{\lambda_k\sim\mathcal{N}(0,1)} \left[\sigma(\xi_k \sqrt{q_d} + \sqrt{v_d}\lambda_k)\right],\\
		g_2\left( \xi_k \sqrt{q_d}, v_d \right) &=\mathbb{E}_{\lambda_k\sim\mathcal{N}(0,1)} \left[\sigma^2(\xi_k \sqrt{q_d} + \sqrt{v_d}\lambda_k)\right],\\
		\Delta_1\left( \xi_k \sqrt{q_d}, v_d \right) &= \mathbb{E}_{\lambda_k\sim\mathcal{N}(0,1)} \left[\sigma'(\xi_k \sqrt{q_d} + \sqrt{v_d}\lambda_k)\right].
	\end{split}
\end{equation}
We can replace these expressions for $t_1$ and $t_2$ back into eq.\eqref{eq: logJk_expansion} and massaging the final result with a bit of algebra and summing over $k=1,...,K$, we finally get: 
\begin{equation}
	\begin{split}
		\sum_{k=1}^K \mbox{log} J_k &\simeq -\frac{\hat{w}^2}{2} - i \hat{u}  \frac{1}{\sqrt{K}} \sum_{k=1}^K A_k g_1 \left( \mu_{k,0}, v_d \right) -\frac{\hat{u}^2}{2}  \frac{1}{K} \sum_{k=1}^K A_k^2 \left( g_2 \left( \mu_{k,0}, v_d\right) - g_1^2\left( \mu_{k,0}, v_d\right)\right)\\ 
		&- i\hat{u} \left( \mu_1 - i \hat{\omega}\sqrt{v_d} \right) \frac{1}{K} \sum_{k=1}^K A_k \Delta_1\left( \mu_{k,0}, v_d\right).
	\end{split}\label{eq: sum_logJk_expansion}
\end{equation}
If we now define the following auxiliary functions:
\begin{equation}
	\begin{split}
		G_1 &= \frac{1}{\sqrt{K}} \sum_{k=1}^K A_k g_1 \left( \mu_{k,0}, v_d \right),\hspace{10mm}
		G_2 = \frac{1}{K} \sum_{k=1}^K A_k^2 g_2 \left( \mu_{k,0}, v_d\right),\\ 
		G_{12} &= \frac{1}{K} \sum_{k=1}^K A_k^2 g_1^2\left( \mu_{k,0}, v_d\right),\hspace{10mm}
		D_1 = \frac{1}{K} \sum_{k=1}^K A_k \Delta_1\left( \mu_{k,0}, v_d\right),
	\end{split}
\end{equation}
we can then write $I_{\boldsymbol{\lambda}}$ as:
\begin{equation}
	\begin{split}
		I_{\boldsymbol{\lambda}} &= \int \frac{d\omega d\hat{\omega}}{2\pi}\int \frac{du d\hat{u}}{2\pi} \mbox{exp}\left(-\beta \ell \left(y, f(u) \right) \right)\\
		&\times \mbox{exp}\left( -\frac{\hat{\omega}^2}{2} + i \hat{\omega}\omega - \frac{\hat{u}^2}{2} \left( G_2 - G_{1,2}\right) + i \hat{u} \left(u - G_1 + \sqrt{K}B \right) - i\hat{u} \left( \mu_1 - i \hat{\omega}\sqrt{v_d} \right)D_1 \right).
	\end{split}
\end{equation}
By replacing the definition of $\mu_1$ as in eq.\eqref{eq: mean_preact} and then integrating over the Gaussian integrals in $\omega$ and $\hat{\omega}$, we get:
\begin{equation}
	I_{\boldsymbol{\lambda}} = \int \frac{du d\hat{u}}{2\pi} \mbox{exp}\left(-\beta \ell \left(y, f(u) \right) - \left( G_2 - G_{12} + v_a D^2_1\right) \frac{\hat{u}^2}{2} + i \left( u - \left( G_1 + \sqrt{K}B\right) - \left(\sqrt{q_a + q_d} - \sqrt{q_d} \right) \omega_{\xi} D_1\right) \hat{u}\right).
\end{equation}
At his point, we realize that the integral over $\hat{u}$ is also Gaussian and can be easily solved, leading to:
\begin{equation}
	I_{\boldsymbol{\lambda}} = \int \frac{du}{\sqrt{2\pi \sigma^2}} \mbox{exp}\left(-\frac{1}{2} \frac{\left(u - \mu\right)^2}{\sigma^2} -\beta \ell \left(y , f(u) \right)\right) \coloneqq \mathcal{G}\left(y, \omega_{\xi}, G_1, G_2, G_{12}, D_1 \right),
\end{equation}
where the mean and the variance of the second-layer pre-activation $u$ are given by:
\begin{equation}
	\begin{split}
		\mu &= G_1 + \sqrt{K}B + \left(\sqrt{q_a + q_d} - \sqrt{q_d} \right) \omega_{\xi} D_1,\\
		\sigma^2 &= G_2 - G_{12} + v_a D_1^2.
	\end{split}
\end{equation}
Depending on the choice of the loss function $\ell$, the integral over $u$ acquires different shapes. For instance, in the case of square loss, it turns into a simple Gaussian integral.\\

\paragraph{Teacher likelihood.} All the steps outlined in the paragraph above can be repeated in the same way for the $\boldsymbol{\nu}$-integral in eq.~\eqref{eq: Ge_with_explicit_Pout}, with the only expectation that the teacher likelihood is now a Dirac-$\delta$ centered on the teacher's labels. With this in mind, we then get:
\begin{equation}
	\begin{split}
		I_{\boldsymbol{\nu}} &= \int D \boldsymbol{\nu} \int D z \, \delta \left(y - f_\star\left[\frac{1}{\sqrt{K}}\sum_{k=1}^K \, A_{k} \sigma(v_\star^{1/2} \boldsymbol{\nu} +  (q^\star)^{-1/2} \boldsymbol{\xi}) - B_\star\sqrt{K} + \sqrt{\Delta^\star} z \right] \right)  \\    
		&= \int \frac{du_\star}{\sqrt{2\pi \sigma_\star}} \delta \left( y - f_\star \left( u_\star\right)\right) \mbox{exp}\left( -\frac{1}{2} \frac{\left( u_\star - \mu_\star\right)^2}{\sigma_\star^2}\right) \coloneqq \mathcal{G}_{\star} \left( y, \omega_\xi, G_1^\star, G_2^\star, G_{12}^\star, D_1^\star\right)
	\end{split}
\end{equation}
where, precisely as in the student case, we have that the mean and the variance of the pre-activations $u_\star$ of the second layer are:
\begin{equation}
	\begin{split}
		\mu_\star &= G^\star_1 + \sqrt{K}B^\star + \left(\sqrt{q^\star_a + q^\star_d} - \sqrt{q^\star_d} \right) \omega_{\xi} D^\star_1,\\
		\sigma^2_\star &= G^\star_2 - G^\star_{12} + v^\star_a (D_1^\star)^2 + \Delta^\star,
	\end{split}
\end{equation}
with the teacher auxiliary functions $G^\star_1$, $G^\star_2$, $G^\star_{12}$ and $\Delta^\star_1$ defined as:
\begin{equation}
	\begin{split}
		G^\star_1 &= \frac{1}{\sqrt{K}} \sum_{k=1}^K A_k g^\star_1 \left( \mu^\star_{k,0}, v^\star_d \right),\hspace{10mm}
		G^\star_2 = \frac{1}{K} \sum_{k=1}^K A^2_k g^\star_2 \left( \mu^\star_{k,0}, v^\star_d\right),\\ 
		G^\star_{12} &= \frac{1}{K} \sum_{k=1}^K A^2_k (g^\star_1\left( \mu^\star_{k,0}, v^\star_d\right))^2,\hspace{10mm}
		D^\star_1 = \frac{1}{K} \sum_{k=1}^K A_k \Delta^\star_1\left( \mu^\star_{k,0}, v^\star_d\right),
	\end{split}
\end{equation}
and the functions $g^\star_1$, $g^\star_2$ and $\Delta^\star_1$ given by: 
\begin{equation}
	\begin{split}
		g^\star_1\left( \sqrt{q^\star_d} \xi_k, v^\star_d \right) &= \mathbb{E}_{\nu_k\sim\mathcal{N}(0,1)} \left[\sigma(\xi_k \sqrt{q_d^\star} + \sqrt{v_d^\star}\nu_k)\right],\\
		g^\star_2\left(\sqrt{q^\star_d} \xi_k, v^\star_d \right) &=\mathbb{E}_{\nu_k\sim\mathcal{N}(0,1)} \left[\sigma^2(\xi_k \sqrt{q_d^\star} + \sqrt{v_d^\star}\nu_k)\right],\\
		\Delta^\star_1\left(\sqrt{q^\star_d} \xi_k, v^\star_d \right) &=\mathbb{E}_{\nu_k\sim\mathcal{N}(0,1)} \left[\sigma'(\xi_k \sqrt{q_d^\star} + \sqrt{v_d^\star}\nu_k)\right],
	\end{split}
\end{equation}
with $\mu^\star_{k,0} = \sqrt{q^\star_d} \xi_k$ and $v^\star_d$ and $q^\star_d$ the diagonal part of the matrices $q_\star^{1/2}$ and $v_\star^{1/2}$:
\begin{equation}
	\begin{split}
		q_\star^{1/2} &= \sqrt{q^\star_d} \mathbb{I}_K + \frac{\sqrt{q^\star_a + q^\star_d} - \sqrt{q^\star_d}}{K} \boldsymbol{1}_K\boldsymbol{1}^t_K,\\
		v_\star^{1/2} &= \sqrt{v^\star_d} \mathbb{I}_K + \frac{\sqrt{v^\star_a + v^\star_d} - \sqrt{v^\star_d}}{K} \boldsymbol{1}_K\boldsymbol{1}^t_K.
	\end{split}
\end{equation}

\paragraph{Integration over $\xi$.}
The integration over $\boldsymbol{\nu}$ and $\boldsymbol{\lambda}$, the pre-activations of the teacher and student network respectively, leads to expressing the energetic potential $\mathcal{G}_E$ in eq.~\eqref{eq: Ge_with_explicit_Pout} as:
\begin{equation}
	\mathcal{G}_E = \int dy \int D\boldsymbol{\xi} \ \mathcal{G}^\star(y, \omega_\xi, G_1^\star, G_2^\star, G^\star_{12}, D_1^\star) \mbox{log} \ \mathcal{G}(y, \omega_{\xi}, G_1, G_2, G_{12}, D_1).
\end{equation}
To integrate over $\xi$ we introduce the definition of $G_1, G_2, G_{12}, D_1$ and $G^\star_1, G^\star_2, G^\star_{12}, D^\star_1$ by means of Dirac-$\delta$s and their integral representations. In this way, the energetic potential $\mathcal{G}_E$ becomes:
\begin{equation}
	\begin{split}
		\mathcal{G}_E &= \int dy \int \frac{d\omega_\xi d\hat{\omega}_\xi}{\sqrt{2\pi}}\int \frac{dG^\star_1 d\hat{G}^\star_1 dG_1 d\hat{G}_1}{\sqrt{2 \pi}} \int \frac{dG^\star_2 d\hat{G}^\star_2 dG_2 d\hat{G}_2}{\sqrt{2 \pi}} \int \frac{dG^\star_{12} d\hat{G}^\star_{12} dG_{12} d\hat{G}_{12}}{\sqrt{2 \pi}} \int \frac{dD^\star_1 d\hat{D}^\star_1 dD_1 d\hat{D}_1}{\sqrt{2 \pi}} \\
		&\times \mathcal{J} \left(y, \omega_\xi, G_1, G_2, G_{12}, D_1, G^\star_1, G^\star_2, G^\star_{12}, D^\star_1 \right) I_{\boldsymbol{\xi}} \left(G_1, G_2, G_{12}, D_1, G^\star_1, G^\star_2, G^\star_{12}, D^\star_1 \right)\label{eq: Ge_before_int_xi}
	\end{split}
\end{equation}
where the functions $\mathcal{J}$ and $I_{\boldsymbol{\xi}}$ are:
\begin{equation}
	\begin{split}
		\mathcal{J} &= e^{i\hat{\omega}_{\xi}\omega_{\xi}+i \hat{G}^\star_1 G^\star_1 + i \hat{G}^\star_2 G^\star_2 + i \hat{G}^\star_{12} G^\star_{12} + i \hat{D}^\star_1 D^\star_1 +i \hat{G}_1 G_1 + i \hat{G}_2 G_2 + i \hat{G}_{12} G_{12} + i \hat{D}_1 D_1}\\
		&\hspace{60mm}\times \mathcal{G}^\star (y, \omega_\xi, G^\star_1, G^\star_2, G^\star_{12}, D^\star_1) \mbox{log} \mathcal{G} (y, \omega_\xi, G_1, G_2, G_{12}, D_1),\\
		I_{\boldsymbol{\xi}} &= \int D\boldsymbol{\xi} \ e^{-i\frac{\hat{\omega}_\xi}{\sqrt{K}}\sum_{k=1}^K \xi_k -i \frac{\hat{G}^\star_1}{\sqrt{K}} \sum_{k=1}^K A_k g^\star_1  - i \frac{\hat{G}^\star_2}{K} \sum_{k=1}^K A_k^2 g^\star_2 - i \frac{\hat{G}^\star_{12}}{K} \sum_{k=1}^K A_k^2 (g^\star_1)^2 - i \frac{\hat{D}^\star_1}{K} \sum_{k=1}^K A_k \Delta^\star_1  }\\
		& \hspace{60mm}\times e^{-i \frac{\hat{G}_1}{\sqrt{K}} \sum_{k=1}^K A_k g_1  - i \frac{\hat{G}_2}{K} \sum_{k=1}^K A_k^2 g_2 - i \frac{\hat{G}_{12}}{K} \sum_{k=1}^K A_k^2 g_1^2 - i \frac{\hat{D}_1}{K} \sum_{k=1}^K A_k \Delta_1  }.
	\end{split} 
\end{equation}

To solve $I_{\xi}$, we first notice that it factorizes over the index $k$. Because of that, we can use the exp-log trick and write it as:
\begin{equation}    I_{\boldsymbol{\xi}} = \mbox{exp} \left( \sum_{k=1}^K \mbox{log}\int D\xi_k \mbox{exp}\left( \frac{t_1}{\sqrt{K}} + \frac{t_2}{K}\right)\right) = \mbox{exp}\left(\sum_{k=1}^K \mbox{log}J_k \right)\label{eq:int_xi}
\end{equation}
where we have isolated the terms of order $K^{-1/2}$ from those of order $K^{-1}$ with:
\begin{equation}
	\begin{split}
		t_1 &= - i \hat{\omega}_\xi \xi_k - i \hat{G}_1^\star A_k g_1^\star - i \hat{G}_1 A_k g_1,\\
		t_2 &= -i\hat{G}_2^\star A_k^2 g_2^\star + i \hat{G}_{12}^\star A_k^2 (g_1^\star)^2 - i \hat{D}_1^\star A_k \Delta_1^\star - i \hat{G}_2 A_k^2g_2 + i \hat{G}_{12} A_k^2 g_1^2 - i \hat{D}_1 A_k \Delta_1.
	\end{split}
\end{equation}
Expanding the logarithm up to order $K^{-1}$ we get:
\begin{equation}
	\mbox{log}J_k \simeq \frac{\langle t_1 \rangle_\xi}{\sqrt{K}} + \frac{\langle t_2 \rangle_\xi}{K} + \frac{\langle t_1^2 \rangle_\xi - \langle t_1 \rangle^2_\xi}{2K} ,
\end{equation}
where $\langle \cdot \rangle_{\xi}$ is the expectation over the Gaussian variable $\xi$. We can then compute the expectation over $\xi$, thus getting:
\begin{equation}
	\begin{split}
		\langle t_1 \rangle_\xi &= -i\hat{G}_1^\star A_k \langle g_1^\star \rangle_\xi -i\hat{G}_1 A_k \langle g_1^\star \rangle_\xi, \\
		\langle t_2 \rangle_\xi &= -i\hat{G}_2^\star A_k^2 \langle g_2^\star \rangle_\xi +i\hat{G}_{12}^\star A_k^2 \langle (g_1^\star)^2  \rangle_{\xi} - i  \hat{D}_1^\star A_k \langle \Delta_1^\star \rangle_\xi - i\hat{G}_2 A_k^2 \langle g_2 \rangle_\xi +i\hat{G}_{12} A_k^2 \langle (g_1)^2  \rangle_\xi - i  \hat{D}_1 A_k \langle \Delta_1 \rangle_\xi,\\
		\langle t_1^2 \rangle_\xi &= - \hat{\omega}_\xi^2 - (\hat{G}_1^\star)^2 A_k^2 \langle (g_1^\star)^2\rangle_\xi - \hat{G}_1^2 A_k^2 \langle g_1^2\rangle_\xi - 2 \hat{G}_1^\star \hat{G}_1 A^2_k \langle g_1^\star g_1\rangle_\xi - 2\hat{\omega}_\xi \hat{G}_1^\star A_k \langle g_1^\star \xi_k\rangle_\xi - 2\hat{\omega}_\xi \hat{G}_1 A_k \langle g_1 \xi_k\rangle_\xi,\\
		\langle t_1\rangle^2_{\xi} &= (\hat{G}_1^\star)^2 A_k^2 \langle g_1^\star \rangle^2_\xi + \hat{G}_1^2 A_k^2 \langle g_1\rangle^2_\xi + 2 \hat{G}_1^\star \hat{G}_1 A_k^2 \langle g_1^\star\rangle_\xi \langle g_1\rangle_\xi.
	\end{split}
\end{equation}

We can now plug the result of this expansion back into eq.~\eqref{eq:int_xi} to get the final expression for $I_{\boldsymbol{\xi}}$ and then plug $I_{\boldsymbol{\xi}}$ back into eq.~\eqref{eq: Ge_before_int_xi}. This gives the final expression for the energetic potential after the integration over $\boldsymbol{\xi}$:
\begin{equation}
	\begin{split}
		\mathcal{G}_E &= \int dy \int Dz \int \frac{d\omega_\xi d\hat{\omega}_\xi}{\sqrt{2\pi}}\int \frac{dG^\star_1 d\hat{G}^\star_1 dG_1 d\hat{G}_1}{\sqrt{2 \pi}} \int \frac{dG^\star_2 d\hat{G}^\star_2 dG_2 d\hat{G}_2}{\sqrt{2 \pi}} \int \frac{dG^\star_{12} d\hat{G}^\star_{12} dG_{12} d\hat{G}_{12}}{\sqrt{2 \pi}} \int \frac{dD^\star_1 d\hat{D}^\star_1 dD_1 d\hat{D}_1}{\sqrt{2 \pi}} \\
