		&\hspace{50mm}\times\mathcal{G}^\star (y, \omega_\xi, G^\star_1, G^\star_2, G^\star_{12}, D^\star_1, z) \mbox{log} \mathcal{G} (y, \omega_\xi, G_1, G_2, G_{12}, D_1)\label{eq: Ge_after_int_xi}
	\end{split}
