		& - \hat{G}_1^\star \mu_A (\hat{\omega}_\xi \sqrt{q_d^\star} \langle \Delta^\star_1 \rangle_\xi + i \sqrt{K} \langle g_1^\star\rangle_\xi)- \hat{G}_1 \mu_A(\hat{\omega}_\xi \sqrt{q_d} \langle \Delta_1 \rangle_\xi + i \sqrt{K} \langle g_1\rangle_\xi)\\
		& -i\hat{G}_2^\star \nu_A \langle g_2^\star\rangle +i\hat{G}_{12}^\star \nu_A\langle (g_1^\star)^2\rangle -i\hat{G}_2 \nu_A \langle g_2^\star\rangle +i\hat{G}_{12}\nu_A\langle g_1^2\rangle  -i\hat{D}_1^\star \mu_A\langle \Delta_1^\star\rangle_\xi  -i\hat{D}_1\mu_A \langle \Delta_1\rangle_\xi\\
		&+i\hat{\omega}_{\xi}\omega_{\xi}+i \hat{G}^\star_1 G^\star_1 + i \hat{G}^\star_2 G^\star_2 + i \hat{G}^\star_{12} G^\star_{12} + i \hat{D}^\star_1 D^\star_1 +i \hat{G}_1 G_1 + i \hat{G}_2 G_2 + i \hat{G}_{12} G_{12} + i \hat{D}_1 D_1
	\end{split}
\end{equation}
with $\mu_A = \langle A_k \rangle_{P_A(\mathbf{A})}$ and $\nu_A = \langle A^2_k \rangle_{P_A(\mathbf{A})}$, since we expect, in the large $K$ limit, that the empirical mean and variance of the second-layer weights, that is $ K^{-1}\sum_{k=1}^K A_k$ and $K^{-1}\sum_{k=1}^K A^2_k$, converge to the first and second moment of the second-layer weights distribution $P_A(\mathbf{A})$. In order to integrate over the hat-variables, we realize that some of these integrals are of the form:
\begin{equation}
	I_{\hat{x}} = \int \frac{d\hat{x}}{\sqrt{2\pi}} \mbox{exp}(i \hat{x} (x - \langle c \rangle_{\xi})) = \delta(x - \langle c \rangle_{\xi}).
\end{equation}
Because of that, these integrals can be directly solved by simply setting $x = \langle c \rangle_{\xi} = \bar{x}$. This is the case for the hat-variables $\hat{D}_1, \ \hat{D}_1^\star, \ \hat{G}_2, \ \hat{G}^\star_2, \ \hat{G}_{12}, \ \hat{G}^\star_{12}$ and, consequently, $D_1 = \mu_A\langle \Delta_1 \rangle_\xi = \mu_A\bar{D}_1, \ D^\star_1 = \mu_A\langle \Delta^\star_1 \rangle_\xi = \mu_A \bar{D}_1^\star, \ G_2 = \nu_A\langle g_2 \rangle_\xi =  \nu_A\bar{G}_2, \ G^\star_2 = \nu_A\langle g^\star_2 \rangle_\xi = \nu_A \bar{G}^\star_2,\ G_{12} =  \nu_A\langle g_1^2\rangle = \nu_A\bar{G}_{12}, \ \hat{G}^\star_{12} = \nu_A\langle (g_1^\star)^2\rangle = \nu_A \bar{G}^\star_{12}$. This means that the fluctuations of these random variables with respect to the randomness induced by $\xi$ can be neglected when we expand the energetic potential up to order $K^{-1}$. In this way, $\mathcal{G}_E$ in eq.~\eqref{eq: Ge_after_int_xi} consistently simplifies as:
\begin{equation}
	\begin{split}
		\mathcal{G}_E &= \int dy \int Dz \int \frac{d\omega_\xi d\hat{\omega}_\xi}{\sqrt{2\pi}}\int \frac{dG^\star_1 d\hat{G}^\star_1}{\sqrt{2 \pi}} \int \frac{dG_1 d\hat{G}_1}{\sqrt{2\pi}} \mbox{exp}\left(\mathcal{W}(G^\star_1, G_1; \bar{G}_{12}^\star, \bar{G}_{12}, \bar{G}_1^\star, \bar{G}_1, \bar{G}_{\star1}\right) \\ 
		&\hspace{70mm}\times \mathcal{G}^\star (y, \omega_\xi, G^\star_1; \bar{G}_2^\star, \bar{G}_{12}^\star, \bar{D}_1^\star) \mbox{log} \mathcal{G} (y, \omega_\xi, G_1; \bar{G}_2, \bar{G}_{12}, \bar{D}_1)   
	\end{split}    
\end{equation}
where the function $\mathcal{W}$ is given by:
\begin{equation}
	\begin{split}
		\mathcal{W} &= -\frac{\hat{\omega}_\xi^2}{2} - \frac{(\hat{G}_1^\star)^2}{2} \nu_A (\bar{G}_{12}^\star - (\bar{G}_1^\star)^2) - \frac{\hat{G}^2_1}{2} \nu_A(\bar{G}_{12} - \bar{G}_1^2) - \hat{G}_1^\star \hat{G}_1 \nu_A (\bar{G}_1^\star - \bar{G}_1^\star \bar{G}_1)-\hat{G}_1^\star \mu_A (\hat{\omega}_{\xi} \sqrt{q_d^\star} \bar{D}_1^\star + i\sqrt{K}\bar{G}_1^\star) \\
		&\hspace{70mm}-\hat{G}_1 \mu_A (\hat{\omega}_{\xi} \sqrt{q_d} \bar{D}_1 + i\sqrt{K}\bar{G}_1) + i\hat{\omega}_\xi \omega_\xi + i\hat{G}_1 G_1 + i\hat{G}_1^\star G_1^\star.
	\end{split}
\end{equation}
We have set $\bar{G}_1^\star =  \langle g_1^\star\rangle_\xi$, $\bar{G}_1 = \langle g_1\rangle_\xi$ and $\bar{G}_{\star1} = \langle g_1^\star g_1\rangle_\xi$. At this point, performing the change of variables $G_1^\star -\mu_A\sqrt{K}\bar{G}_1^\star \rightarrow G_1^\star $ and $G_1 -\mu_A\sqrt{K}\bar{G}_1 \rightarrow G_1$ and exploiting the identity:
\begin{equation}
	\int_{\mathbb{R}^n} \frac{d\bx d\boldsymbol{\hat{x}}}{(2\pi)^d} \mbox{exp}\left( -\frac{1}{2}\hat{\bx}^t \Sigma \hat{\bx} + i \bx^t \hat{\bx} \right) f(\bx) = \langle f(\bx)\rangle_{\bx}
\end{equation}
with $\bx = (\omega_\xi, G_1, G_1^\star)$ and $d=3$, we notice that $\mathcal{G}_E$ can be finally written as an expectation over the jointly Gaussian random variables $\omega_\xi, G_1$ and $G_1^\star$ as:
\begin{equation}
	\mathcal{G}_E = \biggl<  \int dy \int Dz \ \mathcal{G}^\star (y, \omega_\xi, z, G^\star_1 +\mu_A \sqrt{K} \bar{G}_1^\star; \bar{G}_2^\star, \bar{G}_{12}^\star, \bar{D}_1^\star) \ \mbox{log}\ \mathcal{G} (y, \omega_\xi, G_1 + \mu_A\sqrt{K} \bar{G}_1; \bar{G}_2, \bar{G}_{12}, \bar{D}_1) \biggl>_{\omega_\xi, G_1^\star, G_1}\label{eq:final_finally_Ge}
\end{equation}
with zero mean and covariance matrix:
\begin{equation}
	\Sigma := \begin{pmatrix}
		\sigma_{\omega_\xi}^2& \sigma^2_{\omega_\xi G_1} & \sigma^2_{\omega_\xi G^\star_1}\\
		\sigma^2_{ \omega_\xi G_1}  & \sigma_{G_1}^2 & \sigma^2_{G_1^\star G_1 }\\
		\sigma^2_{ \omega_\xi 
			G_1^\star} & \sigma^2_{G_1^\star G_1} &
		\sigma^2_{G_1^\star}
	\end{pmatrix}\label{eq: Sigma_cov}    
\end{equation}
whose elements are: 
\begin{equation}
	\begin{aligned}[c]
		\sigma_{\omega_\xi}^2 &= 1, \\
		\sigma_{\omega_\xi G_1}^2 &= \mu_A\sqrt{q_d}\bar{D}_1,\\
		\sigma_{\omega_\xi G_1^\star }^2 &= \mu_A\sqrt{q_d}\bar{D}^\star_1,\\
	\end{aligned}
	\hspace{5em}
	\begin{aligned}[c]
		\sigma_{G_1}^2 &= \nu_A(\bar{G}_{12} - \bar{G}_1^2),\\
		\sigma_{G_1^\star G_1}^2 &= \nu_A(\bar{G}_{\star1} - \bar{G}_1^\star \bar{G}_1) ,\\
		\sigma_{G_1^\star}^2 &= \nu_A(\bar{G}^\star_{12} - (\bar{G}_1^\star)^2). 
	\end{aligned}
\end{equation}  
Note that, after the change of variables in $G_1^\star$ and $G_1$, the mean and the variance of the teacher and student second-layer pre-activation $u^\star$ and $u$ are given by:
\begin{equation}
	\begin{aligned}
		\mu &= G_1 + \sqrt{K}\mu_A\bar{G}_1 + \sqrt{K}B + \left(\sqrt{q_a + q_d} - \sqrt{q_d} \right) \mu_A \bar{D}_1 \omega_{\xi},\\ 
		\mu_\star &= G^\star_1 + \sqrt{K} \mu_A\bar{G}^\star_1 + \sqrt{K}B^\star + \left(\sqrt{q^\star_a + q^\star_d} - \sqrt{q^\star_d} \right) \mu_A \bar{D}^\star_1 \omega_{\xi},
	\end{aligned}
	\hspace{4em}
	\begin{aligned}
		\sigma^2 &= \nu_A(\bar{G}_2 - \bar{G}_{12}) + v_a \mu_A^2 \bar{D}_1^2 ,\\
		\sigma^2_\star &= \nu_A(\bar{G}^\star_2 - \bar{G}^\star_{12}) + v^\star_a \mu_A^2 (\bar{D}_1^\star)^2 + \Delta^\star .
	\end{aligned}
\end{equation}
The bias terms $B$ and $B^\star$ must then be chosen to cancel the $K \rightarrow \infty$ divergence induced by $\sqrt{K}\bar{G}_1$ and $\sqrt{K}\bar{G}^\star_1$ terms. At the leading order $K$, we should then fix $B^\star \sim \bar{G}^\star_1$ and $B \sim \bar{G}_1$, which is consistent with the definition in \eqref{eq:bias}.\\

\paragraph{Kernel equivalence.} The energetic potential in eq.~\eqref{eq:final_finally_Ge} can be written in terms of the \emph{Kernel} function:
\begin{equation}
	\mathcal{K}(d_1,d_2,a): = \mathbb{E}_{(x_1\; x_2)\sim \mathcal{N}(0,\Omega)} [\sigma(x_1)\sigma(x_2)]  \ \ \text{with} \ \ \Omega = \begin{pmatrix}
		d_1 &   a   \\
		a   &   d_2
	\end{pmatrix},
\end{equation}
which, making the expectation over $x_1$ and $x_2$ explicit, acquires the shape:
\begin{equation*}
	\mathcal{K}(d_1,d_2,a) =\int Dx_1 Dx_2 \, \sigma\left(\sqrt{d_1}x_1\right)\sigma\left(\frac{a}{\sqrt{d_1}}x_1 + \sqrt{\frac{d_1d_2 - a^2}{d_1}}x_2 \right) .
\end{equation*}
This Kernel function is called Neural Network Gaussian Process (NNGP) and describes the covariance of the function implemented by a neural network at initialization (i.e., with random weights) in the infinite-width limit, evaluated at two different inputs~\cite{Neal1996, Williams1996}. 

Indeed, by applying a linear transformation to the Gaussian random variables $\nu_k$, $\lambda_k$ and $\xi_k$, we can rewrite the auxiliary functions as:
\begin{equation}
	\begin{split}
		\Bar{G}_1 &= \int Dx \, \sigma\left(x \sqrt{q_d + v_d } \right) = \sqrt{\mathcal{K}(q_d+v_d,q_d+v_d,0)} ,\\
		\overline{G}_{2} &= \int Dx \, \sigma^2\left( \sqrt{q_d + v_d} x\right) =\mathcal{K}(q_d+v_d,q_d+v_d,q_d+v_d),\\
		\overline{G}_{12} &= \int Dx \left[ \int Dy \, \sigma\left(\sqrt{q_d} x + \sqrt{v_d} y \right) \right]^2 =\mathcal{K}(q_d+v_d,q_d+v_d,q_d),\\
		\overline{D}_1 &= \int Dx \, \sigma' \left(x\sqrt{q_d + v_d}  \right)  = (q_d+v_d)\sqrt{\partial_a\mathcal{K}(q_d+v_d,q_d+v_d,a)\vert_{a=0}}   ,     
	\end{split}
\end{equation}
the same holds for the teacher auxiliary functions by mapping $q\mapsto q^\star$ and $v\mapsto v^\star$. The term corresponding to the correlation between teacher and student neurons is then:
\begin{equation}
	\overline{G}_{^\star1} = \int Dx \sigma(x\sqrt{q_d^\star+ v_d^\star}) \int Dy \, \sigma\left( \sqrt{\frac{q_dq_d^\star}{q_d^\star+v_d^\star}} x + \sqrt{q_d+v_d - \frac{(q_d^\star q_d)^2}{q_d^\star+v_d^\star}} y \right) =\mathcal{K}(q_d^\star+v_d^\star,q_d+v_d,\sqrt{q_dq_d^\star}).
\end{equation}
Taking into account the definition of $q^\star$ and $v^\star$ in eq.~\eqref{eq:v_star}, we have $v_d^\star + q_d^\star = \rho_d = 1$, and similarly $q_d+v_d =r_d$. We can then rewrite the elements of the covariance matrix $\Sigma$ in eq.~\eqref{eq: Sigma_cov} in terms of the Kernel function as:
\begin{equation}
	\begin{aligned}[c]
		\sigma_{\omega_\xi}^2 &= 1,\\
		\sigma_{\omega_\xi G_1}^2 &=  \sqrt{r_d^2\partial_a\mathcal{K}(r_d,r_d,a)\vert_{a=0}},\\
		\sigma_{\omega_\xi G_1^\star}^2 &= \sqrt{\partial_a\mathcal{K}(1,1,a)\vert_{a=0}},\\
	\end{aligned}
	\hspace{5em}
	\begin{aligned}[c]
		\sigma_{G_1}^2 &= \left(\mathcal{K}(r_d,r_d,q_d) -\mathcal{K}(r_d,r_d,0)\right),\\
		\sigma_{G_1^\star G_1}^2 &= \left(\mathcal{K}(1,r_d,m_d) - \mathcal{K}(1,q_d,0)\right),\\
		\sigma^2_{G_1^\star}&= \left(\mathcal{K}(1,1,1)-\mathcal{K}(1,1,0)\right).         
	\end{aligned}
\end{equation}




