\subsubsection{Classification case}
The classification case can be obtained from the previous formulas by setting $f_\star(\cdot) = \text{sign}(\cdot) = f(\cdot)$. We also consider a loss that is only depending on the product of the label and the preactivation of the output i.e. $\ell(y, \hat y) = \ell(y \hat y)$.

After some simplifications the energetic term can be written in terms of two Gaussian integrals only as 
\begin{multline}
	\mathcal{G}_{E}=2\int Dx\,H\left(-\frac{\left(D + m_a V_\star^{2} \right) \sqrt{\eta}}{\sqrt{\gamma \left( \eta (\Sigma - V_\star^2) - (D - m_d V_\star^2)^2 \right) - \left( \eta V_\star - (D - m_d V V_\star) (\Delta V + m_a V) \right)^2 }} x \right) \\
	\times \ln\int Dh \, e^{-\beta\ell\left( \sqrt{\Delta_1 + v_a V_{\star}^{2}}h+\sqrt{ \Delta_0 +q_a V_{\star}^{2}}x \right)}
\end{multline}
where $H(x) \equiv \frac{1}{2} \mathrm{Erfc}\left( \frac{x}{\sqrt{2}} \right) = \int_x^\infty Dy$. We have defined the additional terms as
\begin{subequations}
	\begin{align}
		\eta &\equiv \mathcal{K}(r_d, r_d, q_d) - \mathcal{K}(r_d, r_d, 0)  + \left(q_a - (m_a + m_d)^2 \right) V^2 ,\\
		\gamma &\equiv \mathcal{K}(Q, Q, q_d) - \mathcal{K}(Q, Q, 0)  + q_a V^2 , \\
		\Sigma &=  \mathcal{K}_{1}(1) - \mathcal{K}_1(0) + \Delta^\star ,\\
		V_\star &= \sqrt{\left. \partial_a \mathcal{K}_1(1, 1, a) \right|_{a=0}}, \\
		V &= \sqrt{r_d^2\left. \partial_a \mathcal{K}(r_d, r_d, a) \right|_{a=0}} ,\\
		\Delta_0 &=  \mathcal{K}(Q, Q, q_d) -\mathcal{K}(Q, Q, 0), \\
		\Delta_1 &= \mathcal{K}(Q, Q, Q) -\mathcal{K}(Q, Q, q_d), \\
		D &= \mathcal{K}(1, r_d, m_d) - \mathcal{K}(1, r_d, 0).
	\end{align}
\end{subequations}
\begin{comment}
	\color{magenta}
	\begin{subequations}
		\begin{align}
			\eta &\equiv \mathcal{K}_{Q}(q_d) - \mathcal{K}_Q(0)  + \left(q_a - (m_a + m_d)^2 \right) V^2 \\
			\gamma &\equiv \mathcal{K}_{Q}(q_d) - \mathcal{K}_Q(0)  + q_a V^2  \\
