\section{Generalization error}
We detail here the computation of the Gibbs error, and how this is related to the order parameters in our system. Recall that we wish to estimate $\bw^\star$ from the observations $y^\mu = \varphi^\star_{\boldsymbol{a}^\star}(\bw^\star\bx^\mu,z^\mu\sqrt{\Delta^\star})$ with $\mu\in[P]$. Thus the goal is to characterize the mean-squared generalization error $\epsilon_g$, for a test sample $(\bx^{\rm new},\,y^{\rm new})$. As mentioned in the main, at finite temperature the Gibbs error is the equivalent to the generalization error and it's defined as 
\begin{equation}
	\epsilon_g = \frac{1}{4^\ell} \mathbb{E}\big[\big\langle \big(y^{\rm}  - \hat{y}_{\bw}(\bx^{\rm new}) \big)^2 \big\rangle\big]\label{equ:generalization_error}
\end{equation}
where $\hat{y}_{\bw}(\bx^{\rm new}) = \varphi_{\boldsymbol{a}}(\bw\bx, 0)$ is the prediction label,  with $\ell=0$ for regression and $\ell=1$ for classification.  $\mathbb{E}[\cdot]$ denotes the expectation value over the quenched variables: the outer weights $\boldsymbol{a}^\star$ and $\boldsymbol{a}$; $\bw^\star$ and  $z^{\rm new}$. Wherea $\langle \cdot\rangle$ denotes the Gibbs average. To light the notation we will  assume that there's no Bias term in $\varphi$  and we will refer to $z^{\rm new}$ as simply $z$, which is sampled from a standard gaussian and similar for $\bx^{\rm new}$. We additionally encoded the $1/\sqrt{N}$ of the first layer pre-activation in the gaussian distribution  of $\bx$
Then we have
\begin{align}
	\epsilon_g &\propto \mathbb{E}\big[\big\langle\big(y^{\rm new} - \hat{y}_{\bw }(\bx) \big)^2 \big\rangle\big]\\
	%
	%
	&= \mathbb{E}\Bigg[\Bigg\langle\Bigg(f^\star\Big(\frac{1}{\sqrt{K^\star}}\boldsymbol{a}^\star\cdot\sigma(\bw^\star\bx) + z\sqrt{\Delta^\star}\Big) - f\Big(\frac{1}{\sqrt{K}}\boldsymbol{a}\cdot\sigma(\bw\bx)\Big)\Bigg)^2 \Bigg\rangle\Bigg]\\
	%
	%
	&\overset{(a)}{=} \mathbb{E}\Bigg\langle\Bigg[ \int\frac{\mathrm{d}\mathbf{T}\mathrm{d}\hat{\mathbf{T}}}{(2\pi)^{K^\star}}\frac{\mathrm{d}\mathbf{Z}\mathrm{d}\hat{\mathbf{Z}}}{(2\pi)^K}\exp\left(i\hat{\mathbf{T}}(\mathbf{T}-\bw^\star \bx)^\top + i\hat{\mathbf{Z}}(\mathbf{Z}-\bw \bx)^\top\right)\notag\\
	%
	&\hspace{15em} \cdot\Bigg(f^\star\Big( \frac{1}{\sqrt{K^\star}}\boldsymbol{a}^\star\cdot\sigma(\mathbf{T}) + z\sqrt{\Delta^\star} \Big)  -f\Big(\frac{1}{\sqrt{K}}\boldsymbol{a}\cdot\sigma(\mathbf{Z})\Big) \Bigg)^2\Bigg] \Bigg\rangle\\
	%
	%
	&=  \int\frac{\mathrm{d}\mathbf{T}\mathrm{d}\hat{\mathbf{T}}}{(2\pi)^{K^\star}}\frac{\mathrm{d}\mathbf{Z}\mathrm{d}\hat{\mathbf{Z}}}{(2\pi)^K} \exp\left(i\hat{\bf T}\mathbf{T}^\top + i \hat{\mathbf{Z}}\mathbf{Z}^\top\right)
	\mathbb{E}_{\bw^\star,\,\bx}\Bigg\langle\Bigg[\exp\left(-i\hat{\mathbf{T}}(\bw^\star \bx)^\top - i\hat{\mathbf{Z}}(\bw \bx)^\top\right)\Bigg]\Bigg\rangle\notag\\
	%
	&\hspace{15em}\cdot\mathbb{E}_{\boldsymbol{a}^\star,\boldsymbol{a},z}\Bigg(f^\star\Big( \frac{1}{\sqrt{K^\star}}\boldsymbol{a}^\star\cdot\sigma(\mathbf{T}) + z\sqrt{\Delta^\star}
	\Big)  -f\Big(\frac{1}{\sqrt{K}}\boldsymbol{a}\cdot\sigma(\mathbf{Z})\Big) \Bigg)^2\Bigg] \\
	%
	%
	&\overset{(b)}{=}  \int\frac{\mathrm{d}\mathbf{T}\mathrm{d}\hat{\mathbf{T}}}{(2\pi)^{K^\star}}\frac{\mathrm{d}\mathbf{Z}\mathrm{d}\hat{\mathbf{Z}}}{(2\pi)^K} \exp\left(i\hat{\bf T}\mathbf{T}^\top + i \hat{\mathbf{Z}}\mathbf{Z}^\top\right)
	\mathbb{E}_{\bw^\star}\Bigg\langle\Bigg[\exp\left(-\frac{1}{2}\hat{\mathbf{T}}\frac{\bw^\star(\bw^\star)^\top}{N}\mathbf{T}^\top - \frac{1}{2}\hat{\mathbf{Z}}\frac{\bw\bw^\top}{N}\mathbf{Z}^\top - \hat{\mathbf{T}}\frac{\bw^\star\bw^\top}{N}\hat{\mathbf{Z}} \right)\Bigg]\Bigg\rangle\notag\\
	%
	&\hspace{15em}\cdot\mathbb{E}_{\boldsymbol{a}^\star,\boldsymbol{a},z}\Bigg(f^\star\Big( \frac{1}{\sqrt{K^\star}}\boldsymbol{a}^\star\cdot\sigma(\mathbf{T}) + z\sqrt{\Delta^\star}
	\Big)  -f\Big(\frac{1}{\sqrt{K}}\boldsymbol{a}\cdot\sigma(\mathbf{Z})\Big) \Bigg)^2\Bigg] \\
	%
	%
	&\overset{(c)}{=} \int_{\mathbb{R}^{K^\star}\times \mathbb{R}^K}\mathrm{d}\mathbf{T}\mathrm{d}\mathbf{Z}\,\mathcal{N}\left(\mathbf{T},\,\mathbf{Z}|\mathbf{0}, Q\right)\,\mathbb{E}_{\boldsymbol{a}^\star,\boldsymbol{a},z}\Bigg(f^\star\Big( \frac{1}{\sqrt{K^\star}}\boldsymbol{a}^\star\cdot\sigma(\mathbf{T}) + z\sqrt{\Delta^\star}
	\Big)  -f\Big(\frac{1}{\sqrt{K}}\boldsymbol{a}\cdot\sigma(\mathbf{Z})\Big) \Bigg)^2\Bigg] . 
\end{align}
In (a), we introduce Dirac delta functions to facilitate the computation of the expectation value over the input $\bx$. In (b), by taking the expectation with respect to the Gibbs measure and the teacher weight priors, the overlap matrices concentrate around the stationary points of the replica equations. As previously discussed, the equilibrium solution dominates the Gibbs measure, describing the most probable configurations. In what follows, we keep the overlap matrices generics, but we should evaluate them at their stationary values to obtain the corresponding generalization error. In (c), after integrating with respect to $\hat{\mathbf{T}}$ and $\hat{\mathbf{Z}}$, we obtain the the gaussian p.d.f. $\mathcal{N}(\mathbf{T},\mathbf{Z}|\mathbf{0},Q)$ for the $K^\star-$dimensional vector $\mathbf{T}$ and the $K-$dimensional vector $\mathbf{Z}$, with covariance matrix
\begin{equation}
	Q := \begin{pmatrix}
		\rho & m\\
		m & r
	\end{pmatrix}.
\end{equation}
Here $\rho$ is the $K^\star\times K^\star$ covariance matrix of the teacher weights, $m$ the $K^\star\times K$ matrix teacher-student overlap matrix and $r$ $K\times K$ the self-student overlap. For simplicity, in our setting we set $K^\star=K$, $f^\star=f$ and $\rho=\mathbf{I}_K$; then given the RS ansatz $r$ and $m$ are parametrized as in \eqref{eq: replica_symmetric_committee_ansatz}. 

Now including the Bias terms in our equations we obtain:
\begin{equation}
	\epsilon_g = \frac{1}{4^\ell} \int_{\mathbb{R}^{K}\times \mathbb{R}^K}\mathrm{d}\mathbf{T}\mathrm{d}\mathbf{Z}\,\mathcal{N}\left(\mathbf{0}, Q\right)\,\mathbb{E}_{\boldsymbol{a}^\star,\boldsymbol{a},z}\Bigg[\Bigg(f\Big( \frac{1}{\sqrt{K}}\boldsymbol{a}^\star\cdot\sigma(\mathbf{T})  - \sqrt{K^\star}B^\star+ z\sqrt{\Delta^\star}
	\Big)  - f\Big(\frac{1}{\sqrt{K}}\boldsymbol{a}\cdot\sigma(\mathbf{Z})- \sqrt{K}B \Big)  \Bigg)^2\Bigg].
\end{equation}
We aim to compute expectation value over the preactivatios of the second layer, and again by using Dirac-deltas we obtain:
\begin{equation}
	\begin{split}
		\epsilon_g&\propto\int\frac{\mathrm{d}\lambda\mathrm{d}\hat{\lambda}}{2\pi}\frac{\mathrm{d}\nu\mathrm{d}\hat{\nu}}{2\pi}\exp\left(i\hat{\nu}\nu + i\hat{\lambda}\lambda\right)\left(f^\star(\nu)-f(\lambda)\right)^2\\
		&\hspace{1em}\cdot \mathbb{E}_{\mathbf{T},\mathbf{Z},\boldsymbol{a}^\star,\boldsymbol{a},z}\,\left[\exp\left(-i\hat{\nu}\sum_{k^\star}\frac{(a_{k^\star}^\star\sigma(T_{k^\star})  - B^\star + z\sqrt{\Delta^\star}/\sqrt{K^\star})}{\sqrt{K^\star}} \right)\exp\left( -i\hat{\lambda} \sum_k\frac{(a_k\sigma(Z_k) -  B)}{\sqrt{K}}\right)\right].
	\end{split}
\end{equation}
To compute the expectation of the previous equation and for the last time, we make use of dirac-deltas for each site of the student and teacher neurons, by introducing:
\begin{equation}
	\begin{split}
		\chi_k&= \frac{a_k\sigma(Z_k) - B}{\sqrt{K}},\\
		\chi_{k}^\star&= \frac{a_{k}^\star \sigma(T_{k}) - B^\star + z\sqrt{\Delta^\star}/\sqrt{K}}{\sqrt{K}}.
	\end{split}
\end{equation}
After a lengthy computation involving (i) an expansion in powers of $1/\sqrt{K}$ of the exponential (ii) taking the expectation over the random variables, (iii) performing a ``Taylor contraction", and (iv) integrating over $\hat{\lambda}$ and $\hat{\nu}$, we obtain:
\begin{equation}
	\epsilon_g = \frac{1}{4^\ell} \int\mathrm{d}\lambda\mathrm{d}\nu\mathcal{N} \left(\lambda,\nu|\boldsymbol{\mu},\Omega_{\nu,\lambda}\right)\left(f^\star(\nu )-f(\lambda)\right)^2 \ \ \text{where} \ \ \Omega_{\nu,\lambda} := \begin{pmatrix}
		\varepsilon_T + \Delta^\star& \varepsilon_C\\
		\varepsilon_C &\varepsilon_S
	\end{pmatrix},
\end{equation}
\begin{equation}
	\label{eq:testError_defs}
	\begin{split} 
		\varepsilon_T &:=\nu_A g_1(1) + (K-1)\mu_A^2 \mathcal{K}(1, 1, 0) - K(B^\star)^2  , \\ 
		\varepsilon_S &:= \nu_A g_1(r_0 ) + (K-1)\mu_A^2 \mathcal{K}(r_0,r_0 ,r_1) - KB^2 , \\
		\varepsilon_C &:= \nu_A g_2(1,r_0, m_0) + (K-1)\mu_A^2 \mathcal{K}(1,r_0 ,m_1)  - K B^\star B ,
	\end{split}
\end{equation}
where $\mu_a$ and $\nu_a$ are the first and second moments of $P_a$; and  $m_0 = m_d + m_a/K$, $m_1 = m_a/K$, and the same for $r$ with the respective parameters. Additionally,  we defined the auxiliary Gaussian integrals: 
\begin{equation*}
	g_1(d) := \mathbb{E}_{x\sim \mathcal{N}(0,d)}[\sigma(x)^2]=\mathcal{K}(d,d,d), \ \ g_2(d_1,d_2,a) =: \mathbb{E}_{(x_1\; x_2)\sim \mathcal{N}(0,\Omega)} [\sigma(x_1)\sigma(x_2)] = \mathcal{K}(d_1,d_2,a) \ \ \text{with} \ \ \Omega = \begin{pmatrix}
		d_1 &   a   \\
		a   &   d_2
	\end{pmatrix}.
\end{equation*}
We can further verify that all elements of the covariance matrix $\Omega_{\nu,\lambda}$ are of order $O_K(1)$ by performing a Taylor expansion of the Gaussian probability density function as follows:
\begin{equation*}
	\mathcal{N}\left(x_1,\,x_2 \Big| 0 , \begin{pmatrix}
		d_1 & a/K\\
		a/K & d_2
	\end{pmatrix}\right) =  \mathcal{N}\left(x_1,\,x_2 \Big| 0 , \begin{pmatrix}
		d_1 & 0\\
		0 & d_2
	\end{pmatrix}\right) \left(1 - \frac{1}{K}\frac{ax_1x_2}{d_1d_2}\right) + \mathcal{O}(K^{-2})
\end{equation*}
and by using the definition of the bias:
\begin{equation*}
	\begin{split}
		B &= \mu_A \sqrt{\mathcal{K}\left(r_d + \nicefrac{r_a}{K},r_d + \nicefrac{r_a}{K},  0\right)} = \mu_A \sqrt{\mathcal{K}(r_d,r_d,0)} + O(K^{-1}),\\
		B^\star &= \mu_A \sqrt{\mathcal{K}(1,1,0)}.
	\end{split}
\end{equation*}
We obtain that the elements of the covariance matrix can be all writen in terms of the NNGP kernel $\mathcal{K}$ as:
\begin{equation}
	\label{eq:testError_defs2}
	\begin{split} 
		\varepsilon_T &:=\nu_A\mathcal{K}(1,1,1)  - \mu_A^2 \mathcal{K}(1, 1, 0)  , \\ 
		\varepsilon_S &:= \nu_A\mathcal{K}(r_d, r_d, r_d) - \mu_A^2 \mathcal{K}(r_d, r_d, 0) - r_a\mu_A^2  \partial_a\mathcal{K}(r_d,r_d,a)|_{a=0} , \\
		\varepsilon_C &:= \nu_A\mathcal{K}(1,r_d, m_d) - \mu_A^2 \mathcal{K}(1,r_d ,m_d)  - m_a \mu_A^2 \partial_a\mathcal{K}(1,r_d,a)|_{a=0}.
	\end{split}
\end{equation}




