	\label{fig:geo}
\end{figure}

\begin{definition} \label{dfn:variants}
    Let $ S $ be a set of $ n $ points in a polygon $ P $.
    \begin{itemize}
        \item $ \Pi(n) $ (resp., $ \overline{\Pi}(n) $) is the largest integer such that, for every set (resp., geodesically convex set) $ S $, there exist points $ u, v \in S $ such that every geodesic disk through them contains $ \Pi(n) $ (resp., $\overline{\Pi}(n)$) points of~$ S$.
        \item $ \Pi^{in\mbox{-}out}(n) $ is the largest integer such that, for every set $ S $, there exist points $ u, v \in S $ such that every geodesic disk through them has $ \Pi^{in\mbox{-}out}(n) $ points of $ S $, both inside and outside.
        \item $ \Pi^{diam}(n) $ (resp., $ \overline{\Pi}^{diam}(n) $) is the largest integer such that, for every set (resp., geodesically convex set) $ S $, there exist points $ u, v \in S $ such that $ D\left(c_{uv},\frac{|g(u,v)|}{2}\right) $ contains $ \Pi^{diam}(n) $ (resp., $\overline{\Pi}^{diam}(n)$) points of $ S$.
    \end{itemize}
    Let $ B $ be a set of $ \frac{n}{2} $ blue points, and $ R $ be a set of $ \frac{n}{2} $ red points in a polygon $ P $, and let $ S= B\cup R $.
    \begin{itemize}
        \item $ \Pi^{bichrom}(n) $ (resp., $ \overline{\Pi}^{bichrom}(n) $) is the largest integer such that, for every set (resp., geodesically convex set) $ S $, there exist points $ u\in B, \ v\in R $ such that every geodesic disk through them contains $ \Pi^{bichrom}(n) $ (resp., $ \overline{\Pi}^{bichrom}(n) $) points of $ S $.
        \item $\Pi^{bichrom\mbox{-}in\mbox{-}out}(n)$ is the largest integer such that, for every set $ S $, there exist points $ u\in B, \ v\in R $ such that every geodesic disk through them has $\Pi^{bichrom\mbox{-}in\mbox{-}out}(n)$ points of $ S $, both inside and outside.
    \end{itemize}
\end{definition}

\section{Euclidean and geodesic disks: some similarities and differences}
\label{sec:comparison}

In this section we describe some of the similarities and differences concerning Euclidean and geodesic disks that arise when proving the main results in this paper.

\subsection{Some similarities}

Two bounded curves $ g_1 $ and $ g_2 $ \emph{intersect} if by traversing $ g_1 $ from one of its endpoints to the other endpoint, it crosses $ g_2 $ and switches from one side of $ g_2 $ to the other side~\cite{biniaz2016plane,toussaint1989computing}. We say that $ g_1 $ and $ g_2 $ are \emph{non-intersecting} if they do not intersect. Two non-intersecting curves can share an endpoint or can ``touch'' each other. Note that if $ g_1 $ and $ g_2 $ are geodesics they can intersect at most once~\cite{biniaz2016plane}.

It is well known that given two segments $ {ab} $ and $ {pq} $ that intersect transversely in the plane, any disk through $ a $ and $ b $ contains at least one endpoint of $ {pq} $, or any disk through $p$ and $q$ contains at least one endpoint of $ {ab} $, see, e.g., \cite{neumann1988combinatorial}. This result translates to the geodesic setting as shown below. We begin with a property of geodesic disks.% We first set up the conditions of the following proposition. Let $ p, q, a \in S $ be three points in $ P $ such that $ a $ is in a geodesic disk $ D $ with center $c$ through $ p $ and $ q $. The center $c$ partitions bisector $b(p,q)$ in two parts. Denote by $b_{l}(p,q)$ the portion of the bisector that is to the left of $\ell(p,c)$ and by $b_{r}(b,q)$ the portion that is to the right. 

\begin{lemma} \label{lem:diskcontain}
Let $ p, q$ be two points in $ P $ and $ D, D' $ be two geodesic disks through $ p $ and $ q $, respectively with centers $c$ and $c'$. If $c'$ is left of $ \ell(p,c) $ then $D\cap P^+(p,q)\subset D'$.    
\end{lemma}

\begin{proof}
    Let $a$ be an arbitrary point in $D\cap P^+(p,q)$. By definition of $P^+(p,q)$, we have that $a$ is to the left of $\ell(p,q)$. We consider two cases: $a\in \triangle(c',p,q)$ and $a \not \in \triangle(c',p,q)$. 

    If $ a $ is in $ \triangle (c',p,q) $, see Figure~\ref{fig:geo}, then we use the fact that, for every point $ x \in g(p,q) $, the length of $ g(c', x) $ as $x$ moves from $p$ to $q$ is a convex function with the maximum occurring at $p$ or $q$~\cite{pollack1989computing}. In particular, we have that $ \lvert g(c',x) \rvert \leq \lvert g(c',q) \rvert =  \lvert g(c',p) \rvert $, for $ x \in g(p,q) $. If we move $ x $ from $ p $ to $ q $ along $ g(p,q) $, at some point $ g(c',x) $ will go through the point $a$, so $ \lvert g(c',a) \rvert \leq \lvert g(c',x) \rvert $. Hence, $ \lvert g(c',a) \rvert \leq \lvert g(c',q) \rvert = \lvert g(c',p) \rvert $, which means that $a \in D'$.

    Now consider the case where the point $ a $ is outside $ \triangle (c',p,q) $, like $ a' $ in Figure~\ref{fig:geo}. Without loss of generality, assume $ a $ is to the right of $ g(p,c')$. (Otherwise, we can consider $ a $ and $ q $, and the proof is analogous). In this case, $g(c',p)$ must intersect $g(c,a)$. Let $x$ be a point in this intersection. By definition, we have $ \lvert g(c',x)\rvert + \lvert g(x,p)\rvert = \lvert g(c',p)\rvert$. Since $a \in D$, we have that $\lvert g(c,a)\rvert = \lvert g(c,x) \rvert + \lvert g(x,a) \rvert \le \lvert g(c,p) \rvert $ and by the triangle inequality, we have $\lvert g(c,p) \rvert \le \lvert g(c,x) \rvert + \lvert g(x,p) \rvert $. This means that $\lvert g(x,a) \rvert \le \lvert g(x,p) \rvert $. Therefore, $ \lvert g(c',a) \rvert \leq \lvert g(c',x) \rvert + \lvert g(x,a) \rvert \le \lvert g(c',x) \rvert + \lvert g(x,p) \rvert = \lvert g(c',p) \rvert $, implying $a \in D'$ in this case.
\end{proof}

With this property of geodesic disks in hand, we are now ready to prove the corresponding property of intersecting segments in the geodesic setting.

\begin{lemma}
    \label{lem:quadrilateral}
    Let $a, b, p, q $ be four distinct points in general position in $P$ such that $ g(p,q) $ and $ g(a,b) $ intersect. Then every geodesic disk with $ p $ and $ q $ on its boundary contains at least one endpoint of $ g(a,b) $, or every geodesic disk with $ a, b $ on its boundary contains at least one endpoint of $ g(p,q) $.
\end{lemma}
\begin{proof}
    First, suppose that the bisectors $ b(a,b) $ and $ b(p,q) $ intersect, see Figure~\ref{fig:intersection}, and let $ x $ be a point in their intersection. Then we have that $ |g(x,a)| = |g(x,b)| $ and $ |g(x,p)| = |g(x,q)| $. We can assume, without loss of generality, that $ |g(x,p)| < |g(x,a)| $ since the points in $ S $ are in general position, and $ a,b,p,q $ are not co-circular. The case where $ |g(x,p)| > |g(x,a)| $ is symmetric. 

    When $ |g(x,p)| < |g(x,a)| $, the geodesic disk through $ a $ and $ b $ with center $x$ contains $p$ and~$q$. Since $ g(a,b) $ and $ g(p,q) $ intersect, $ p $ and $ q $ are on different sides of the extension path $ \ell(a,b) $. Hence, by Lemma~\ref{lem:diskcontain}, if we move the center of this disk along the bisector $ b(a,b) $ in one direction while keeping $a,b$ on its boundary, the geodesic disk will always contain $ p $ in its interior, and if we move the center in the other direction, the geodesic disk will always contain $ q $.

    Now, suppose that the bisectors $ b(a,b) $ and $ b(p,q) $ do not intersect, see Figure~\ref{fig:non-intersection}. Hence, all points of the bisector $ b(a,b) $ are closer to one endpoint of $ g(p,q) $ than to the other one. Assume, without loss of generality, that this point is $ p $, i.e., $ |g(x',p)| \leq |g(x',q)|, \ \forall x'\in b(a,b) $. Similarly, all points of the bisector $ b(p,q) $ are closer to one endpoint of $ g(a,b) $ than to the other one. Assume, without loss of generality, that this point is $ b $.

    \begin{figure}[tb]
		\captionsetup[sub]{justification=centering}
		\centering
		    \begin{subfigure}[b]{0.47\textwidth}
				\centering
	    	    \includegraphics{Images/intersection}
	    	    \caption{Bisectors $ b(a,b) $ and $ b(p,q) $ intersect.}
	    	    \label{fig:intersection}
	    	\end{subfigure}
                \qquad
		    \begin{subfigure}[b]{0.47\textwidth}
   			    \centering
	    	    \includegraphics{Images/non-intersection}
	    	    \caption{Bisectors $ b(a,b) $ and $ b(p,q) $ do not intersect.}
	    	    \label{fig:non-intersection}
    	    \end{subfigure}
