\title{Efficacy of Image Similarity as a Metric for Augmenting Small Dataset Retinal Image Segmentation}

\author[1,2]{Thomas Wallace%
  \thanks{Email Adress: \texttt{t.wallace.1@reserach.gla.ac.uk}; Corresponding author}}


