\ns\ds+(\b_1^2-2\b_1\b_2^3-\b_1^2\b_2^2+2\b_1\b_2+\b_2^4\b_3^4+2\b_2^4\b_3^3+ 2\b_1\b_2^3\b_3^3-2\b_2^3\b_3^3-\b_2^4\b_3^2+2\b_1\b_2^3\b_3^2-4\b_2^3\b_3^2\\
%
\ns\ds+\b_1^2\b_2^2\b_3^2-4\b_1\b_2^2\b_3^2+\b_2^2\b_3^2-2\b_2^4\b_3- 2\b_1\b_2^3\b_3 -4\b_1\b_2^2\b_3+2\b_2^2\b_3-2\b_1^2\b_2\b_3+2\b_1\b_2\b_3)\\
%
