\begin{theorem} \label{M(U)}
Let $U=\{0, \frac{\pi}{n}, \frac{2\pi}{n} \dots, \frac{(n-1)\pi}{n}\}$. Then, $M(U)=R+R(\frac{1}{2}+\frac{1}{2}\tan(\frac{\pi}{n})i)$ for some ring $R \subset \R$ where $R$ contains only rational functions of $\cos^2(\frac{\pi}{n})$ with integer coefficients.
\end{theorem}


\begin{proof}
Let $P$ be the set of projections of all initial intersections onto the real axis via angles in $U$, and let $P^{-1}$ be the set of all multiplicative inverses of elements of $P$. Define $R=\Z[P \cup P^{-1}]$. Then using results from \cite{BR}, $M(U)\cap \R=R$. By Lemma \ref{R}, $P$ contains only rational functions of $\cos^2(\frac{\pi}{n})$, and hence so does $R$. Since $R \subseteq M(U)$ and $[\![0,1]\!]_{\frac{\pi}{n}, \frac{(n-1)\pi}{n}}=\frac{1}{2}+\frac{1}{2}i\tan(\frac{\pi}{n})$ by the intersection formula, it follows that $R+R\left(\frac{1}{2}+\frac{1}{2}i\tan(\frac{\pi}{n})\right) \subseteq M(U)$. 

Conversely, to show that $M(U) \subseteq R+R\left(\frac{1}{2}+\frac{1}{2}i\tan(\frac{\pi}{n})\right)$, it suffices to show that for any $p,q \in R+R\left(\frac{1}{2}+\frac{1}{2}i\tan(\frac{\pi}{n})\right)$, and any $\alpha, \beta \in U$, $[\![p,q]\!]_{\alpha, \beta} \in R+R\left(\frac{1}{2}+\frac{1}{2}i\tan(\frac{\pi}{n})\right)$. Without loss of generality, we may shift the points so that $p=0$. Any intersection obtained this way may also be obtained by replacing $q$ with its projection onto the real line using the same angle $\beta$ so we may assume $q \in R$.  Since $\alpha,\beta \in U$, we have $\alpha=\frac{(i+1)\pi}{n}$ and $\beta=\frac{(j+1)\pi}{n}$ for some $i,j \in \{0,1, 2, \dots, n-2\}$. Now, using the fact (twice) that $[\![p,q]\!]_{\alpha,\beta}=[\![0,q-p]\!]_{\alpha,\beta}$ yields 

\begin{align*}
[\![0,q]\!]_{\alpha, \beta}&= q[\![0,1]\!]_{\alpha,\beta}=q[\![x_0',x_{n-2}']\!]_{\frac{\pi}{n},\frac{(n-1)\pi}{n}}\\
&=q\left(x_0'+[\![0,x_{n-2}'-x_0']\!]_{\frac{\pi}{n},\frac{(n-1)\pi}{n}}\right)\\
&=q\left(x_0'+(x_{n-2}'-x_0')[\![0,1]\!]_{\frac{\pi}{n},\frac{(n-1)\pi}{n}}\right)\\
&=q\left(x_0'+(x_{n-2}'-x_0')\left(\frac{1}{2}+\frac{1}{2}\tan(\alpha)i\right)\right)
\end{align*}
where $x_0',x_{n-2}' \in R$ are as defined in Lemma \ref{R}. Finally, letting $a=qx_0'$ and $b=q(x_{n-2}'-x_0')$, we obtain $a+b(\frac{1}{2}+\frac{1}{2}\tan(\frac{\pi}{n})i \in R+R(\frac{1}{2}+\frac{1}{2}i\tan(\frac{\pi}{n})$ since $a,b \in R$. Therefore, $M(U)=R+R\left(\frac{1}{2}+\frac{1}{2}i\tan(\frac{\pi}{n})\right)$.


\end{proof}

Finally, to show that reflections of order $2n$ cannot be obtained if $n$ is even, it suffices to show that $\cos(\frac{\pi}{n})+i\sin(\frac{\pi}{n}) \notin M(U)$ if $n$ is even.


\begin{lemma} \label{inR}
Let $U$ be an angle set containing $\{0, \frac{\pi}{n}, \frac{2\pi}{n}, \dots, \frac{(n-1)\pi}{n}\}$. Then, $\cos(\frac{\pi}{n})+i\sin(\frac{\pi}{n}) \in M(U)$ if and only if $2\cos(\frac{\pi}{n}) \in M(U) \cap \R$.

\end{lemma}

\begin{proof}
First suppose $\cos\left(\frac{\pi}{n}\right)+i\sin\left(\frac{\pi}{n}\right)\}) \in M(U)$. Then $[\![0,\cos\left(\frac{\pi}{n}\right)+i\sin\left(\frac{\pi}{n} \right)]\!]_{0,\frac{2\pi}{n}}=2\cos\left(\frac{\pi}{n}\right)$ by the intersection formula, so $2\cos\left(\frac{\pi}{n}\right) \in M(U) \cap \R$. 

Conversely, if $2\cos\left(\frac{\pi}{n}\right) \in M(U) \cap \R$, then $[\![0,2\cos\left(\frac{\pi}{n}\right)]\!]_{\frac{\pi}{n},\frac{2\pi}{n}}=\cos\left(\frac{\pi}{n}\right)+i\sin\left(\frac{\pi}{n}\right)$ which then must be in $M(U)$.
%By Theorem \ref{M(U)}, it is known that $M(U)=R+R\left(\frac{1}{2}+\frac{1}{2}i\tan(\frac{\pi}{n})\right)$. Suppose $\cos(\frac{\pi}{n})+i\sin(\frac{\pi}{n}) \in M(U)$ such that for some $a, b \in R$, $\cos(\frac{\pi}{n})+i\sin(\frac{\pi}{n}) = a + \frac{b}{2} + \frac{b}{2} \tan \left(\frac{\pi}{n}\right) i$. Separating the complex and real parts of the equation, the equations $\cos(\frac{\pi}{n}) = a + \frac{b}{2}$ and $\sin(\frac{\pi}{n}) = \frac{b}{2} \tan \left(\frac{\pi}{n}\right)$ are left; moreover, it can be seen that through algebraic manipulations, $b = 2\cos\left(\frac{\pi}{n}\right)$ and $a = 0$. Thus, if $\cos(\frac{\pi}{n})+i\sin(\frac{\pi}{n}) \in M(U)$, then $2\cos(\frac{\pi}{n}) \in R$.

%For the converse direction, Theorem $\ref{M(U)}$ is also applied such that it is known that $M(U)=R+R\left(\frac{1}{2}+\frac{1}{2}i\tan(\frac{\pi}{n})\right)$. Then, some point $p \in M(U)$ will be made up with some $a, b \in R$. Let $a = 0$ and $b = 2\cos(\frac{\pi}{n})$ because it is given in this direction that $2\cos(\frac{\pi}{n}) \in R$. So, $p = 0 + 2\cos(\frac{\pi}{n})\left(\frac{1}{2}+\frac{1}{2}i\tan(\frac{\pi}{n})\right)$. Through simplification, $p = \cos(\frac{\pi}{n}) + \cos(\frac{\pi}{n}) \cdot \tan(\frac{\pi}{n}) i$ and when simplified further, $ p = \cos(\frac{\pi}{n})+i\sin(\frac{\pi}{n})$. Thus, if $2\cos(\frac{\pi}{n}) \in R$, then $\cos(\frac{\pi}{n})+i\sin(\frac{\pi}{n}) \in M(U)$. 

%\s{Quinn prove this? Use the fact that $M(U)=R+R\left(\frac{1}{2}+\frac{1}{2}i\tan(\frac{\pi}{n})\right)$. The forward direction may require a little linear algebra separating the real and imaginary parts. The backwards direction is easier, starting with $2\cos(\frac{\pi}{n}) \in R$.}

\end{proof}


\begin{lemma} \label{evenodd}
Let $U=\{0,\frac{\pi}{n}, \frac{2\pi}{n}, \dots, \frac{(n-1)\pi}{n}\}$. Then, $2\cos(\frac{\pi}{n}) \in M(U)$ if and only if $n$ is odd.
\end{lemma}

\begin{proof}
If $n$ is odd, then $\cos(\frac{\pi}{n})+i\sin(\frac{\pi}{n}) \in M(U)$ as shown in Theorem \ref{nodd}. Then, by Lemma \ref{inR}, $2\cos(\frac{\pi}{n}) \in R$. 

Conversely, suppose that $n$ is even. Using results from \cite{WZ}, the minimal polynomial of $\cos(\frac{2\pi}{n})$ over $\mathbb{Q}$ has degree $k=\frac{\phi(n)}{2}$, where $\phi(n)$ is the number of positive integers less than $n$ that are relatively prime to $n$. Similarly, the minimal polynomial of $\cos(\frac{\pi}{n})=\cos(\frac{2\pi}{2n})$ has degree $\frac{\phi(2n)}{2}=\frac{2\phi(n)}{2}=\phi(n)=2k$ is even since $n>2$. Suppose that $f(x)$ is the minimal polynomial of $\cos(\frac{2\pi}{n})$, which has degree $k$ by \cite{WZ}. Then using the fact that $\cos(\frac{2\pi}{n})=2\cos^2(\frac{\pi}{n})-1$, it must be true that $\cos(\frac{\pi}{n})$ satisfies the polynomial $f(2x^2-1)$ which has degree $2k$, and contains only even powers of $x$. Since the minimal polynomial of $\cos\left(\frac{\pi}{n}\right)$ has degree $2k$, it must be true that its minimal polynomial is $f(2x^2-1)$ up to scaling. 

If $2\cos\left(\frac{\pi}{n}\right) \in R$ then we would have $2\cos(\frac{\pi}{n})=\frac{g(\cos(\frac{\pi}{n}))}{h(\frac{\cos(\pi}{n}))}$ where $g(x)$ and $h(x)$ contain only even powers of $x$ and both have degree at most $2k$ by Lemma \ref{M(U)}. We would then have $2\cos(\frac{\pi}{n})h(\cos(\frac{\pi}{n}))-g(\cos(\frac{\pi}{n}))=0$ which would mean there exists another minimal polynomial of $\cos(\frac{\pi}{n})$ containing some odd powers of $\cos(\frac{\pi}{n})$ which is a contradiction. 

%Therefore, since $n$ is even, $2\cos(\frac{\pi}{n}) \notin R$ since it cannot be written as a rational function of even powers of $\cos(\frac{\pi}{n})$ otherwise its minimal polynomial would contain an odd power of $x$, a contradiction.

\end{proof}

\begin{theorem} \label{neven}
    If $n \neq 2$ is even and $U=\{0,\frac{\pi}{n}, \frac{2\pi}{n}, \dots, \frac{(n-1)\pi}{n}\}$, then $P(U)\cong D_{n}$, the dihedral group of a regular $n$-gon.
\end{theorem}

\begin{proof} 
Suppose $n \neq 2$ is even and $U=\{0,\frac{\pi}{n}, \frac{2\pi}{n}, \dots, \frac{(n-1)\pi}{n}\}$. Since $U$ contains $n$ angles, the highest rotation order must be at most $2n$. Let $\theta=\frac{\pi}{n}$. By the intersection formula, $[\![0,1]\!]_{2\theta, \frac{\pi}{n}\left(\frac{n}{2}-2\right)}=\cos\left(\frac{2\pi}{n}\right)+i\sin\left(\frac{2\pi}{n}\right)$. 
Therefore, by Proposition \ref{rot-ref}, Since $U$ contains $\cos(2\theta)+i\sin(2\theta) \in M(U)$, and for every $\alpha \in U$, $\alpha+2\theta \in U$, $P(U)$ contains rotations by $2\theta$ which have order $\frac{2\pi}{\theta}=n$. By Lemma \ref{evenodd}, since $n$ is even, $2\cos\left(\frac{\pi}{n}\right) \notin M(U)$. Then, by Lemma \ref{inR}, $\cos\left(\frac{\pi}{n}\right)+i\sin\left(\frac{\pi}{n}\right) \notin M(U)$, so by Proposition \ref{rot-ref}, $P(U)$ does not contain rotations by $\frac{\pi}{n}$ which would have order $2n$. Therefore, $n$ is the highest rotation order of $P(U)$.

To show that $P(U)$ contains reflections across the angle $\theta$, it has already been noted that $\cos(2\theta)+i\sin(2\theta) \in M(U)$. It is also true by the definition of $U$ that for every $\alpha \in U$, $2\theta-\alpha \in U$ since $U$ consists of all multiples of $\theta$. Therefore, by Proposition \ref{rot-ref}, $P(U)$ contains a reflection across the angle $\frac{\pi}{n}$ and hence contains reflections.

%Since $U$ contains $n$ angles, the highest rotation order must be at most $2n$. There cannot be rotations of order $2n$ since $\cos(\frac{\pi}{n})+i\sin(\frac{\pi}{n}) \notin M(U)$. However, the point $z=\cos(\frac{2\pi}{n})+\sin(\frac{2\pi}{n})=[\![0,1]\!]_{\frac{2\pi}{n}, \frac{\pi(n+2)/2}{n}}\in M(U)$. Repeating the origami construction process using initial points 0 and $z$ instead of 0 and 1 yields the same set, rotated by an angle of $\frac{\pi}{n}$. Moreover, the angle set, when rotated by an angle of $\frac{\pi}{n}$ yields the same angle set as well. Therefore, $P(U)$ contains a rotation by $\frac{\pi}{n}$ and hence all multiples of $\frac{\pi}{n}$. Therefore, the highest rotation order is $n$ because any rotation order is larger than $n$ since any higher rotation order would be a multiple of $n$ which is not possible.

%An angle $\alpha$ reflected across the axis given by the angle $\frac{\pi}{2n}$ will be mapped to the angle $\frac{(n+1)\pi}{n}-\alpha$, so if $\alpha \in U$, then so is its reflection across $\frac{\pi}{2n}$. Let $x$ be an arbitrary point in the origami set $M(U)$. The reflection of any initial intersection of the form $[\![0,1]\!]_{\alpha, \rho}$ across the axis along the angle $\frac{\pi}{2n}$ can be obtained by replacing the point 1 by $\cos(\frac{\pi}{n})+i\sin(\frac{\pi}{n})$. Any point obtained from the initial intersection points can be obtained by replacing those points with their reflections across the angle $\frac{\pi}{2n}$ and the process continues. 

Since $P(U)$ contains a rotation by an angle of $\frac{\pi}{n}$ and a reflections, all other symmetries in $D_n$ can be written as a composition of those so $P(U)$ is isomorphic to $D_n$ by Theorem \ref{mainthm2}.
\end{proof}

\begin{example} \label{p4m}
    Let $U=\{0, \frac{\pi}{4}, \frac{\pi}{2}, \frac{3\pi}{4}\}$. Using techniques from \cite{BR}, the origami set $M(U)$ is given by $M(U)=R+R i$ where $R=\Z[\frac{1}{2}]$. The group $P(U)$ contains rotations of order 4 as well as four reflection axes: $\frac{\alpha}{8}$, $\frac{3\alpha}{8}$, $\frac{5\alpha}{8}$, and $\frac{7\alpha}{8}$. Thus, $P(U)$ contains the following characteristics: rotations of order 4 and reflection axes of $\frac{\pi}{4}$ radians.


\end{example}

It has now been shown that the point group of an origami construction is either isomorphic to $D_n$ or $\Z/n\Z$ for an even integer $n$. In fact, it is true that every such group is the point group of the origami construction for some set of angles. We conclude with a theorem summarizing this.

\begin{theorem} \label{final}
Let $G$ be a finite group. Then, $G\cong P(U)$ for some angle set $U$ containing at least 3 angles if and only if $G$ is isomorphic to one of the following groups:
\begin{enumerate}
    \item $\Z/2\Z \times \Z/2\Z$
    \item $\Z/n\Z$
    \item $D_n$
\end{enumerate}
for an even integer $n$.
\end{theorem}
\begin{proof}
    It has already been shown in Theorems \ref{nodd}  and \ref{neven} that if $U$ contains more than three angles then $P(U)$ is isomorphic to one of $\Z/2\Z \times \Z/2\Z$, $\Z/n\Z$, or $D_n$ for some even integer $n$. It has also already been shown that if $U$ contains exactly three angles then $G(U)$ is isomorphic to the wallpaper group corresponding to either $p2$ so that $P(U)\cong \Z/2\Z$, $cmm$ so that $P(U) \cong \Z/2\Z \times \Z/2\Z$, or $p6m$ so that $P(U) \cong D_6$ by Theorem \ref{mainthm}. It remains to show the converse.

    Case 1: $G \cong \Z/2\Z \times \Z/2\Z$: Let $U=\{0,\frac{\pi}{4}, \frac{\pi}{2}\}$ so $G(U)$ is the wallpaper group $cmm$ whose point group $P(U)$ is isomorphic to $\Z/2\Z \times \Z/2\Z$.

   Case 2: $G\ \cong \Z/n\Z$ for some even integer $n$: Let $\alpha$ be an angle such that $0<\alpha < \frac{\pi}{2n}$. If $U=\{0, \alpha, \frac{\pi}{n}, \frac{2\pi}{n}, \frac{2\pi}{n}+\alpha, \dots, \frac{(n-1)\pi}{n}\}$ (where $\alpha+\frac{k\pi}{n} \in U $ if and only if $k$ is even) then $P(U) \cong \Z/n\Z$. This can be seen as follows: note that for every $\theta \in U$, $\theta+\frac{2\pi}{n} \in U$, $\frac{2\pi}{n}$ is the smallest angle for which this is true. Moreover, since $[\![0,1]\!]_{\frac{2\pi}{n}, \frac{\pi}{n}\left(\frac{n}{2}-2\right)}=\cos(\frac{2\pi}{n})+i\sin(\frac{2\pi}{n})$ so by Theorem \ref{mainthm2}, the highest rotation order is $2\pi/(\frac{2\pi}{n})=n$. 
    Note that $P(U)$ cannot contain reflections since there would have to be a reflection axis $\theta$ such that $0 \leq \theta < \frac{\pi}{n}$ so $0 \leq 2\theta < \frac{2\pi}{n}$. This cannot be true since that would mean that $2\theta \in U$ meaning that $2\theta=0$, $2\theta=\alpha$, or $2\theta=\frac{\pi}{n}$. If $2\theta=0$ then $2\theta-\alpha=-\alpha$ which is not in $U$. If $2\theta=\alpha$ then $2\theta-\frac{\pi}{2}=\alpha-\frac{\pi}{2}$ which again is also not in $U$. If $2\theta=\frac{\pi}{n}$ then $2\theta-\alpha=\frac{\pi}{n}-\alpha$ which is again not in $U$. Therefore, by Proposition \ref{rot-ref}, $P(U)$ does not contain any reflections so we must have $P(U) \cong \Z/n\Z$.

    Case 3: $G \cong D_n$ for some even integer $n$: By Theorem \ref{neven}, if $U=\{0, \frac{\pi}{n}, \frac{2\pi}{n}, \dots, \frac{(n-1)\pi}{n}\}$ then $P(U) \cong D_n$.
\end{proof}

