\title{RCNet: $\Delta\Sigma$ IADCs as Recurrent AutoEncoders}

\author{Arnaud~Verdant, William~Guicquero and Jérôme~Chossat% <-this % stops a space
%\thanks{Manuscript received 16 April 2025.}% <-this % stops a space
