    \end{align*}
in terms of the equilibrium impact process\footnote{By using the form of the constants in Table \ref{tab:constants}, it can be verified that $I_0=0$.}
\begin{equation*}I_t=\frac{-N\lambda\left[\rho_{-}+\frac{1}{z_1+\beta}e^{z_1t} -\frac{\gamma_1}{ \gamma_2}\frac{1}{z_2+\beta}e^{z_2t}\right]\varphi}{\varepsilon(\rho_0+\beta\rho_{-})+\lambda N(\rho_{+}+\rho_{-})+ \left[\beta\rho_{-}T+\frac{e^{z_1 T}-1}{z_1}-\frac{\gamma_1}{\gamma_2}\frac{e^{z_2 T}-1}{z_2}\right]\varphi}\overline{x}, \ \ \ t\in[0,T].
