\end{align*}
and equilibrium terminal penalty
\begin{align*}
\varphi (X_T^{*,i})^2
&=\varphi\left[\frac{\mathfrak{p}^2}{\psi^2}\overline{x}^2+\frac{ z_3^2}{ \xi^2}(x^i-\overline{x})^2+\frac{ 2z_3\mathfrak{p}}{ \xi\psi}(x^i-\overline{x})\overline{x}\right].
\end{align*}
\end{corollary}

\subsection{Liquidation Constraint}\label{sec:N.inst.cost.liq.constr}

To find the unique equilibrium associated with the cost $J_{A'}$ enforcing full liquidation at~$T$, we argue that it coincides with the limit of the equilibrium in Theorem \ref{thm:equil.term.pen} as the penalty on terminal inventory tends to infinity, $\varphi\uparrow\infty$.

\begin{lemma}\label{lem:conv.equilibria}
If the Nash equilibrium $\boldsymbol{X}^*$ from Theorem \ref{thm:equil.term.pen} converges in $H^{1}[0,T]^{\times N}$ as $\varphi\uparrow\infty$, then the limit is a Nash equilibrium for $J_{A'}$ and the equilibrium costs in Corollary~\ref{cor:eq.cost.term.pen} converge to the equilibrium costs for $J_{A'}$.
\end{lemma}

The proof in \cref{se:proof.of.conv.equilibria} is based on the $\Gamma$-convergence of $\mathcal{J}_{A}(\cdot;\boldsymbol{v}^{*,-i}(\varphi))$ to $\mathcal{J}_{A'}(\cdot;\tilde{\boldsymbol{v}}^{-i})$ as $\varphi\uparrow\infty$, where $\boldsymbol{v}^{*}(\varphi)$ denotes the equilibrium for finite $\varphi$ and $\tilde{\boldsymbol{v}}$ its limit. 

Using \cref{lem:conv.equilibria}, we can deduce a characterization of the equilibrium by passing to the limit in Theorem~\ref{thm:equil.term.pen}. As mentioned in the introduction, our result provides a closed-form solution to the game previously studied in \cite{Strehle.17}. See Table \ref{tab:constants} for the definitions of the simplifying constants.

\begin{theorem}\label{thm:equil.liq.constr}
	There is a unique Nash equilibrium for $J_{A'}$. Its equilibrium strategy profile $\boldsymbol{X}^*=(X^{*,1},\dots,X^{*,N})$ is 
	\begin{equation*}
		X^{*,i}_t= \mathfrak{f}_t (x^{i}-\overline{x})+\mathfrak{g}_t \overline{x}, \ \ \ t\in[0,T], \ \ \ i =1,\dots,N,
	\end{equation*}
	where
	\begin{equation*}
		\mathfrak{f}_t =1-\frac{\beta t+\frac{\lambda (e^{z_{3} t}-1)}{\varepsilon z_3 e^{z_3T}}}{\beta T+ \frac{\lambda(e^{z_3 T}-1)}{\varepsilon z_3e^{z_3 T}}} , \ \ \ 
		\mathfrak{g}_t =1-\frac{\beta \rho_{-}t+\frac{e^{z_1 t}-1}{z_1}-\frac{\gamma_1}{\gamma_2}\frac{e^{z_2 t} -1}{ z_2}}{\beta \rho_{-}T+\frac{e^{z_1 T}-1}{z_1} -\frac{\gamma_1}{\gamma_2}\frac{e^{z_2 T}-1}{ z_2}}.\\ 
	\end{equation*}
        Moreover, this is the $H^{1}[0,T]^{\times N}$ limit of the equilibrium strategy profile in Theorem \ref{thm:equil.term.pen} as $\varphi\uparrow\infty$. 
\end{theorem}


