\begin{equation*}
    I_t=\begin{cases}
    \lambda e^{-\beta t}\sum_{j=1}^Na^{j}+\int_0^t \lambda e^{-\beta(t-s)}\sum_{j=1}^Nv^{j}_sds, & t\in[0,T),\\
    I_{T-}+\lambda \sum_{j=1}^Nb^{j}, & t=T
    \end{cases}
\end{equation*}
for $I_{0-}=0$, and the inventories satisfy
\begin{equation*} X^{i}_t=\begin{cases}
    x^{i}+a^{i}+\int_0^tv^{i}_sds, & t\in[0,T),\\
    0, & t=T,
\end{cases}
\end{equation*}
for $X_{0-}^i=x^i$. In particular, this implies that $b^i = -X_{T-}^i$.
%
In view of the liquidation constraint, $b^i$ is entirely determined by the initial jump $a^i$ and the trading speed $v^i$, hence our minimization is over $\mathbb{R}\times L^2[0,T]$. This retains a Hilbert space structure so, as in Section~\ref{sec:N.inst.cost}, we can apply variational arguments to solve the game. The following lemma shows that the deterministic equilibrium (if it exists) is similarly characterized by a $2N+1$ dimensional system of linear homogeneous ordinary differential equations. However, this time the ODE is written in terms of $\boldsymbol{X}$ (rather than $\boldsymbol{v}$) and the imposition of block costs leads to additional free boundary conditions that must also be pinned down as part of the solution.

\begin{lemma}\label{lem:block.cost.ODE}
The strategy profile $\boldsymbol{X}$ defines a Nash equilibrium for $\mathcal{J}_B$ if and only if it forms, along with $I$ and auxiliary processes $Y^{1},\dots, Y^{N}$, a solution\footnote{More precisely (since $\boldsymbol{X}$ and $I$ may have jumps at $0$ and $T$), $\boldsymbol{X}$ and $I$ satisfy the ODE on $[0,T)$.} to the ODE system 
    \begin{align*}
    \dot{I}_t&=\frac{\beta}{N-1}\left[I_t-\sum_{j=1}^NY^{j}_t\right],\\
    \dot{Y}_t^{i}&=-\frac{\beta}{N-1}\left[I_t-\sum_{j=1}^NY^{j}_t\right], \ \ \ i=1,\dots,N,\\
    \dot{X}_t^{i}&=\frac{\beta}{\lambda(N-1)}\left[I_t+(N-1)Y^{i}_t-\sum_{j=1}^NY^{j}_t\right], \ \ \ i=1,\dots,N,
\end{align*}
subject to the initial and terminal conditions
\begin{align*}
    I_0&=\lambda\sum_{i=1}^Na^{i}, \ \ \ X_0^{i}=x^{i}+a^{i}, \ \ \ Y_T^{i}=\lambda b^{i}, \ \ \ i=1,\dots,N,
\end{align*}
where 
\begin{equation*}\theta_a a^{i} =\frac{\lambda}{2}\sum_{j\not=i}a^{j}, \ \ \ \theta_b b^{i}=-\frac{\lambda}{2}\sum_{j\not=i}b^{j}, \ \ \ \text{and} \ \ \  b^{i}=-X^{i}_{T-}, \  \ \ \ i=1,\dots,N.
\end{equation*}

\end{lemma}

It turns out that the existence of an equilibrium depends crucially on the choice of initial and terminal block costs $\theta_a=\vartheta_0$ and $\theta_b=\vartheta_T$. As the next theorem shows,  there is a single choice yielding existence for general initial inventories. Moreover, that choice consists of different values for the initial and terminal costs, except in the case $N=2$ of two traders. 

\begin{theorem}\mbox{}\label{thm:equil.block.cost}
    \begin{enumerate}
        \item[(1)] If $\vartheta_0=\frac{\lambda (N-1)}{2}$ and $\vartheta_T = \frac{\lambda}{2}$ then a Nash equilibrium for $J_B$ exists.
        \item[(2)] If $\vartheta_0\not=\frac{\lambda (N-1)}{2}$ then a Nash equilibrium for $J_B$ exists if and only if $\overline{x}=0$.
        \item[(3)] If $\vartheta_T \not= \frac{\lambda}{2}$ then a Nash equilibrium for $J_B$ exists if and only if $x^i=x^j$ for all $i,j\in\{1,\dots,N\}$.
    \end{enumerate}
    When a Nash equilibrium exists, it is uniquely defined through the strategy profile $\boldsymbol{X}^*=(X^{*,1},\dots,X^{*,N})$ given by
    \begin{equation*}
		X^{*,i}_t= \mathbbm{f}_t (x^{i}-\overline{x})+\mathbbm{g}_t \overline{x}, \ \ \ t\in[0,T], \ \ \  i =1,\dots,N,
	\end{equation*}
	where
	\begin{equation*}
		\mathbbm{f}_t =1-\frac{\beta t}{\beta T+1} , \ \ \ t\in[0,T), \ \ \ \mathbbm{f}_{0-} = 1 \ \ \ \text{and} \ \ \ \mathbbm{f}_T = 0,
        \end{equation*}
        \begin{equation*}
		\mathbbm{g}_t =1-\frac{N(\beta t + 1) (N+1) e^{\beta \frac{N+1}{N-1} T}+2Ne^{\beta \frac{N+1}{N-1} t}-(N-1)}{N((\beta T+1)(N+1)+2)e^{\beta \frac{N+1}{N-1} T}-(N-1)}, \ \ \ t\in[0,T] \ \ \ \text{and} \ \ \ \mathbbm{g}_{0-} = 1. 
        \end{equation*}
\end{theorem}

We observe that the equilibrium has a much simpler expression compared to the one for instantaneous cost in the preceding section.

\begin{remark}
    If $\vartheta_0\not=\frac{\lambda(N-1)}{2}$ \emph{and} $\vartheta_T\not=\frac{\lambda}{2}$, then (2) and (3) together imply that an equilibrium exists if and only if $x^i = 0$ for all $i=1,\dots,N$. In that case, substituting in $x^i=0$ for all $i$ shows $X^{*,i}\equiv0$. In words, the only possible equilibrium is that all agents have zero inventory and do not trade. More generally, when $\vartheta_0\not=\frac{\lambda(N-1)}{2}$ \emph{or} $\vartheta_T\not=\frac{\lambda}{2}$, the equilibrium exists only for initial inventories such that no block trade occurs at $t=0$ or $t=T$, respectively, and in that sense the value of $\vartheta_t$ does not matter.
\end{remark}

\begin{remark}
  In certain games without a (pure) Nash equilibrium, existence is re-established by allowing for randomization, meaning that agents' strategies can depend on privately observed randomization devices. Seminar participants have rightfully asked whether that is the case in the context of \cref{thm:equil.block.cost}. The answer is negative. In a nutshell, randomized strategies can be de-randomized in a way that strictly decreases the objective function, ruling out the existence of randomized equilibria. The mathematical details are somewhat lengthy and will be reported separately.
\end{remark}

The proof of Theorem~\ref{thm:equil.block.cost} in Appendix \ref{app:N.block.cost} has two parts. The first is based  on the ODE system from Lemma~\ref{lem:block.cost.ODE}, providing  the explicit solution for the ``good'' parameter values and proving that there is no solution for the ``bad'' parameter values. On the strength of Lemma~\ref{lem:nash.eq.a.c.}, the former establishes existence and uniqueness of the equilibrium also for general admissible strategies, for those parameter values. Whereas for the bad parameter values, verifying that the non-existence of a deterministic equilibrium extends to the full class of admissible strategies is a major technical hurdle. Achieving this occupies a sizable part of the proof, which combines original arguments with ideas of \cite[Theorem 4.5(b)]{SchiedStrehleZhang.17}. 

%Moreover, it turns out that relaxing the problem formulation to allow for randomized strategies \textit{does not} restore existence in this problem. The proof of this fact for general price impact kernels will be the subject of a follow up work.

The final result of this section provides the equilibrium cost in closed form.

\begin{corollary}\label{cor:eq.cost.block.cost}
    When a Nash equilibrium for $J_B$ exists, the cost for the traders is
    \begin{align*}
        J_{B}(X^{*,i};\boldsymbol{X}^{*,-i})&= \int_0^TI_{t-}dX^{*,i}_t+\frac{1}{2}\left(\Delta I_0\Delta X^{*,i}_0+\Delta I_T \Delta X^{*,i}_T\right)\\
        & \quad \quad \quad \quad  \quad \quad +\frac{1}{2}\left(\vartheta_0(\Delta X^{*,i}_0)^2+\vartheta_T(\Delta X^{*,i}_T)^2\right), \ \ \ i=1,\dots,N,
    \end{align*}
    in terms of the equilibrium impact process
    \[I_t=-\frac{ \lambda  N (N +1)\left(e^{\beta \frac{N +1}{N -1}t}+N e^{\beta \frac{N +1}{N -1}T}\right) }{N \left(( \beta T +1) (N+1) +2\right) e^{\beta \frac{\left(N +1\right) T}{N -1}}-(N -1)}\overline{x}, \ \ \ t\in[0,T], \ \ \ I_{0-}=0.
    \]  
    Stated explicitly, we obtain the equilibrium impact cost
    \begin{align*}
        &\int_0^TI_{t-}dX^{*,i}_t +\frac{1}{2}\left(\Delta I_0\Delta X^{*,i}_0+\Delta I_T \Delta X^{*,i}_T\right) = \frac{\lambda N}{\beta T+1} \overline{x}(x^i-\overline{x})\\
        &\quad \quad \quad + \frac{ \lambda N^3 (N+1)\left( \left(\left(\beta T +\frac{1}{2}\right) (N+1) +3\right) e^{\frac{2 \left(N +1\right) \beta  T}{N -1}}-\frac{2 \left(N -1\right)}{N^2} \left(N e^{\frac{\left(N +1\right) \beta  T}{N -1}}+\frac{1}{4}\right) \right)}{\left(N \left(\left(\beta T +1\right)(N+1) + 2\right) e^{\frac{\left(N +1\right) \beta  T}{N -1}}-(N -1)\right)^{2}}
    \overline{x}^2,
    \end{align*}
    and equilibrium block trade cost
    \begin{multline*}
        \frac{1}{2}\left(\vartheta_0(\Delta X^{*,i}_0)^2+\vartheta_T(\Delta X^{*,i}_T)^2\right)\\= \frac{\vartheta_0 (N+1)^2 (1+ N e^{\beta \frac{N+1}{N-1} T})^2 \overline{x}^2}{2 \left(N((\beta T+1) (N+1) + 2)e^{\beta \frac{N+1}{N-1} T} - (N-1)\right)^2} +\frac{\vartheta_T (x^i-\overline{x})^2}{2 (\beta T+1)^2}.
    \end{multline*}
\end{corollary}

\section{Identifying the Limit of Small Instantaneous Cost}\label{sec:id.limit}

This section connects the equilibrium with instantaneous cost (Theorem~\ref{thm:equil.liq.constr}) and the equilibrium with block cost (Theorem \ref{thm:equil.block.cost}). Namely, we show that the latter is the limit of the former for vanishing instantaneous cost $\eps\to0$. The equilibrium with instantaneous cost is canonical in that it does not require a particular choice of parameters. The limit of vanishing instantaneous cost then gives rise to the seemingly unprincipled pair of ``good'' block cost parameters in a natural way. Indeed, our result implies that any different choice of parameters would lead to a discontinuity in the equilibrium cost. 

\begin{theorem}\label{thm:small.eps.lim}
    As $\varepsilon\downarrow 0$ the equilibrium $\boldsymbol{X}^*=\boldsymbol{X}^{*,\eps}$ in Theorem \ref{thm:equil.liq.constr} converges uniformly on compact subsets of $(0,T)$ to the equilibrium $\boldsymbol{X}^*=\boldsymbol{X}^{*,0}$ Theorem \ref{thm:equil.block.cost}. Furthermore, the equilibrium cost in Corollary \ref{cor:eq.cost.liq.constr} converges to that of Corollary \ref{cor:eq.cost.block.cost} when $\vartheta_0 =\frac{\lambda (N-1)}{2}$ and $\vartheta_T = \frac{\lambda}{2}$. In particular, for any $\delta\in(0,T)$,		\begin{align*}
     \varepsilon \int_0^{\delta}(\dot{X}^{*,\eps,i}_t)^2 dt \to   \vartheta_0(\Delta X^{*,0,i}_0)^2 \quad\mbox{and}\quad \varepsilon \int_{\delta}^{T}(\dot{X}^{*,\eps,i}_t)^2 dt \to   \vartheta_T(\Delta X^{*,0,i}_T)^2.
		\end{align*} 
\end{theorem}
