\section{Notational Remarks}\label{se:notation}


\paragraph{Integration.} We write $\int_a^b fd\mu$ to denote the integral $\int_{[a,b]}fd\mu$ of a function $f$ against a measure $\mu$ on $[a,b]\subset \mathbb{R}$, including any atoms $\mu$ may have at $a$ or $b$. When the left or right endpoint is not included, we write $\int_{a+}^bfd\mu :=\int_{(a,b]}fd\mu$ or $\int_{a}^{b-}fd\mu :=\int_{[a,b)}fd\mu$, respectively.

\paragraph{Spaces.} As usual, $L^2[0,T]$ is the Hilbert space of (equivalence classes of) square integrable functions on $[0,T]$ with inner product
\[\langle v,w\rangle_{L^2} = \int_0^Tv_tw_tdt.\]
Similarly, $H^1[0,T]$ is the Sobolev space of functions $v\in L^2[0,T]$ that admit weak derivatives $\dot{v}\in L^2[0,T]$. It is a Hilbert space with inner product
\[\langle v,w\rangle_{H^1}=\langle v,w\rangle_{L^2} +\langle \dot{v},\dot{w}\rangle_{L^2}.\]
If $\mathbb{H}$ is any Hilbert space we write $\mathbb{H}^{\times N}$ to denote its $N$-fold Cartesian product.

\section{Reminder on Gateaux Derivative and $\Gamma$-Convergence}\label{app:opt.theory}

For ease of reference, this section collects some standard definitions and results to be used in the proofs below. 
Let $\mathbb{H}$ be a real separable Hilbert space with inner product $\langle\cdot,\cdot\rangle_\mathbb{H}$. For a real-valued function $F$ on $\mathbb{H}$ we define the \textit{Gateaux differential} of~$F$ at~$h\in \mathbb{H}$ in the direction $\eta\in \mathbb{H}$ by 
\[\delta_\eta F(h) = \lim_{\epsilon\downarrow0} \frac{F(h+\epsilon\eta) - F(h)}{\epsilon} \]
when the limit exists. If the Gateaux differential exists for all directions $\eta \in\mathbb{H}$ we say that~$F$ is \textit{Gateaux differentiable} at~$h$ and call $\delta_\cdot F(h)$ the \textit{Gateaux derivative} of~$F$ at~$h$. If, further, the mapping $\eta \mapsto \delta_\eta F(h)$ is a continuous linear operator on $\mathbb{H}$, then by Riesz' representation theorem we can identify the derivative with an element $DF(h)\in \mathbb{H}$,
    \[\delta_\eta F(h) = \langle DF(h), \eta \rangle_{\mathbb{H}}, \ \ \ \forall\eta\in\mathbb{H}.\]
The following result is standard (see, e.g., \cite[Theorem 3.24]{Peypouquet.15}).
\begin{proposition}
If $F:\mathbb{H}\mapsto \mathbb{R}\cup \{\infty\}$ is a proper\footnote{We say that $F:\mathbb{H}\to \mathbb{R}\cup \{\infty\}$ is proper if $\{h\in\mathbb{H}: F(h)<\infty\} \not=\emptyset$.} convex function with Gateaux derivative at every $h\in\mathbb{H}$ then $h^*$ is a minimizer of $F$ if and only if $\delta_\eta F(h^*) = 0$ for all $\eta \in \mathbb{H}$.
\end{proposition}
In particular, if $F$ is a proper convex function with a continuous linear Gateaux derivative at every $h\in \mathbb{H}$, then $h^*$ is a minimizer of $F$ if and only if $DF(h^*) =0$. We will use this fact frequently.

Another notion used below is $\Gamma$-convergence, for which \cite{DalMaso.93} is a standard reference.
\begin{definition}\label{def:gamma.conv}
    We say that a sequence $F_n:\mathbb{H}\to\mathbb{R}\cup\{\infty\}$, $n\geq0$, $\Gamma$-converges to a function $F:\mathbb{H}\to\mathbb{R}\cup\{\infty\}$ (and write $F_n\xrightarrow{\Gamma} F$) if:
    \begin{enumerate}
        \item For all $h\in\mathbb{H}$ and all sequences $(h_n)_{n\geq0}$ with $h_n\to h$,
        \[F(h)\leq \liminf_{n\to\infty} F_n(h_n).\]
        \item For all $h\in \mathbb{H}$ there exists a sequence $(h_n)_{n\geq0}$ with $h_n\to h$ and
        \[F(h)\geq \limsup_{n\to\infty} F_n(h_n).\]
    \end{enumerate}
\end{definition}

The following result (see, e.g., \cite[Proposition 7.18]{DalMaso.93}) connects this type of convergence to the consistency of minimizers.

\begin{theorem}[Fundamental Theorem of $\Gamma$-Convergence\footnote{Other common variants of this theorem include an equicoercivity assumption on $(F_n)_{n\geq0}$ to imply the convergence of the minimum values.
}]\label{thm:fund.thm.gamma.conv}
Suppose that $F_n\xrightarrow{\Gamma} F$ and $h^*_n\in\argmin_{h\in\mathbb{H}}F_n(h)$, $n\geq0$. Then every limit point of $(h^*_n)_{n\geq0}$ is a minimizer of $F$. Moreover, if $(h^*_n)_{n\geq0}$ converges, so do the minimum values,
\[\lim_{n\to\infty} \inf_{h\in\mathbb{H}}F_n(h)=\inf_{h\in\mathbb{H}}F(h).\]
\end{theorem}
