\section{Proofs for Section \ref{sec:prob.formulation}}\label{app:proofsProblemformulationAndUniqueness}

\subsection{Proposition \ref{prop:obj.func.rep}}\label{app:pf.obj.func.rep}

We can expand \eqref{eqn:orig.obj} to get
\begin{align*}J_{\cdot}(X^{i};\boldsymbol{X}^{-i})&=\mathbb{E}\bigg[\int_0^T P_{t-} dX_t^{i}+\frac{1}{2}\sum_{t\in[0,T]}  \Delta P_t \Delta X_t^{i} +\int_0^T I_{t-} dX_t^{i} + \frac{1}{2}\sum_{t\in[0,T]} \Delta I_t \Delta X_t ^{i}\\
&\quad \quad \quad \quad +(X_{0-}^iP_{0-}-X^{i}_TP_T)+C_{\cdot}(X^{i})\bigg].
\end{align*}
Using integration by parts,
\begin{align*}
    \int_0^T P_{t-} dX_t^{i}  &= P_TX_T^i-P_{0-}X_{0-}^i-\int_0^T X_{t-}^i dP_t -[X^i,P]_T
    %&=-P_{0-}x^{i}-\int_0^T X_{t-} dP_t -[X^{i},P]_T.
\end{align*}
and thus
\begin{align*}J_{\cdot}(X^{i};\boldsymbol{X}^{-i})&=\mathbb{E}\bigg[-\int_0^T X^{i}_{t-} dP_t - [X^{i},P]_T+\frac{1}{2}\sum_{t\in[0,T]}  \Delta P_t \Delta X_t^{i} \\
&\quad \quad \quad \quad +\int_0^T I_{t-} dX_t^{i} + \frac{1}{2}\sum_{t\in[0,T]} \Delta I_t \Delta X_t^{i}  +C_{\cdot}(X^{i})\bigg].
\end{align*}
The theory of stochastic processes (see  \cite[Proposition I.3.14]{JacodShiryaev.03}) gives that $\int_0^t X_{s-}^i dP_s$ and $[X^i,P]_t$ are local martingales. Using our assumption that the total variation of $X^i$ is $\mathbb{P}$-a.s.\ bounded, we conclude that $X^i$ is bounded and
\[\mathbb{E}\left[\int_0^T X_{t-}^i dP_t\right] =\mathbb{E}\left[[X^i,P]_T\right]=0.\]
Moreover,
\[\frac{1}{2}\sum_{t\in[0,T]} \Delta X_t^{i} \Delta P_t=\frac{1}{2}[X^{i},P]_T,\]
so its expected value is also $0$. Since these arguments hold for arbitrary admissible~$X^{i}$, we obtain the expression in \eqref{eqn:obj.impact.rep}  of Proposition \ref{prop:obj.func.rep}. 
%
To obtain the remaining representation in \eqref{eqn:obj.schied.rep}, we insert the form of $I$ into \eqref{eqn:obj.impact.rep} to get
\begin{align}\label{eqn:obj.intermediate.rep}J_{\cdot}(X^{i};&\boldsymbol{X}^{-i})
= \mathbb{E}\bigg[C_{\cdot}(X^{i})+\lambda \int_0^T\int_0^{t-} e^{-\beta (t-s)} \sum_{j=1}^NdX_s^{j} dX_t^{i} + \frac{\lambda}{2}\sum_{j=1}^N\sum_{t\in[0,T]}  \Delta X_t^{j} \Delta X_t ^{i}\bigg].%\nonumber 
\end{align}
Observe that by splitting and interchanging the order of integration, we can write
\begin{align*}\int_0^T\int_0^{t-} &e^{-\beta (t-s)} dX_s^{i} dX_t^{i}\\
&=\frac{1}{2}\int_0^T\int_0^{t-} e^{-\beta (t-s)} dX_s^{i} dX_t^{i}+\frac{1}{2}\int_0^T\int_0^{t-} e^{-\beta (t-s)} dX_s^{i} dX_t^{i}\\
&=\frac{1}{2}\int_0^T\int_0^{t-} e^{-\beta (t-s)} dX_s^{i} dX_t^{i}+\frac{1}{2}\int_0^T\int_{s}^T e^{-\beta (t-s)} dX_t^{i} dX_s^{i}-\frac{1}{2}\sum_{s\in[0,T]}(\Delta X^i_s)^2\\
&=\frac{1}{2}\int_0^T\int_0^T e^{-\beta |t-s|} dX_s^{i} dX_t^{i}-\frac{1}{2}\sum_{t\in[0,T]}(\Delta X^i_t)^2.
\end{align*}
Substituting this expression into \eqref{eqn:obj.intermediate.rep} completes the proof.
\qed

\subsection{Proposition \ref{prop:nash.eq.unique}}\label{app:pf.nash.eq.unique}

Suppose there are two distinct equilibria $\boldsymbol{X}^0$ and $\boldsymbol{X}^1$.
Define
    \[\boldsymbol{X}^\alpha = \alpha \boldsymbol{X}^1 +(1-\alpha)\boldsymbol{X}^0, \ \ \ \alpha\in(0,1), \]
and
\begin{equation*}V(\alpha) = \sum_{i=1}^N\left(J(X^{\alpha,i};\boldsymbol{X}^{0,-i})+J(X^{1-\alpha,i};\boldsymbol{X}^{1,-i})\right).\end{equation*}
A consequence of Lemma \ref{lem:strict.convex} is that $V$ is strictly convex. Moreover, by the Nash equilibrium definition,
\[V(\alpha)\geq \sum_{i=1}^N \left(J(X^{0,i};\boldsymbol{X}^{0,-i})+J(X^{1,i};\boldsymbol{X}^{1,-i}) \right),\]
and this lower bound is attained by setting $\alpha=0$. Next, we will differentiate $V$ at $0$ to obtain the contradiction $\dot{V}(0)<0$.

To facilitate this we deal with each term in the expression for $J_{\cdot}$ separately. Let 
\begin{align*}\mathfrak{J}_1^i(\alpha) &= \frac{\lambda}{2}\int_0^T\int_0^T e^{-\beta |t-s|} dX_s^{\alpha,i} dX_t^{\alpha, i}+\frac{\lambda}{2}\int_0^T\int_0^T e^{-\beta |t-s|} dX_s^{1-\alpha,i} dX_t^{1-\alpha, i}.
\end{align*}
By differentiating and setting $\alpha=0$ we find
\begin{align*}
    \dot{\mathfrak{J}}^i_1(0) &=-\lambda\int_0^T\int_0^T e^{-\beta |t-s|} d(X_s^{1,i} -X_s^{0, i})d(X_t^{1,i} -X_t^{0, i}).
\end{align*}
Summing over $i$,
\begin{equation} \label{eqn:J1.sum} \sum_{i=1}^N\dot{\mathfrak{J}}^i_1(0)=-\lambda\sum_{i=1}^N\int_0^T\int_0^T e^{-\beta |t-s|} d(X_s^{1,i} -X_s^{0, i})d(X_t^{1,i} -X_t^{0, i}).
\end{equation}
Next, let
\begin{align*}
    \mathfrak{J}_2^i(\alpha) &= \lambda \int_0^T\int_0^{t-} e^{-\beta (t-s)} \sum_{j\not=i}dX_s^{0,j} dX_t^{\alpha, i}+\lambda \int_0^T\int_0^{t-} e^{-\beta (t-s)} \sum_{j\not=i}dX_s^{1,j} dX_t^{1-\alpha, i}.
\end{align*}
Differentiating,
\begin{align*}\dot{\mathfrak{J}}_2^i(\alpha)&=\lambda \int_0^T\int_0^{t-} e^{-\beta (t-s)} \sum_{j\not=i}dX_s^{0,j} d(X^{1,i}-X^{0,i})\\
&\quad -\lambda \int_0^T\int_0^{t-} e^{-\beta (t-s)} \sum_{j\not=i}dX_s^{1,j} d(X^{1,i}- X^{0,i})\\
&=-\lambda \int_0^T\int_0^{t-} e^{-\beta (t-s)} \sum_{j\not=i}d(X_s^{1,j} - X_s^{0,j})d(X^{1,i}_t- X^{0,i}_t),
\end{align*}
which is constant in $\alpha$. If we sum over $i$ and manipulate the terms,

\begin{align*}\sum_{i=1}^N\dot{\mathfrak{J}}_2^i(0)&= -\lambda \sum_{i=1}^N\sum_{j\not=i}\int_0^T\int_0^{t-} e^{-\beta (t-s)} d(X_s^{1,j} - X_s^{0,j}) d(X^{1,i}_t- X^{0,i}_t)\\
&= -\frac{\lambda}{2} \sum_{i=1}^N\sum_{j\not=i}\int_0^T\int_0^{t-} e^{-\beta (t-s)} d(X_s^{1,j} - X_s^{0,j}) d(X^{1,i}_t- X^{0,i}_t)\\
& \quad -\frac{\lambda}{2} \sum_{i=1}^N\sum_{j\not=i}\int_0^T\int_{s+}^T e^{-\beta (t-s)}  d(X^{1,i}_t- X^{0,i}_t) d(X_s^{1,j} - X_s^{0,j})\\
&= -\frac{\lambda}{2} \sum_{i=1}^N\sum_{j\not=i}\int_0^T\int_0^T e^{-\beta |t-s|} d(X_s^{1,j} - X_s^{0,j}) d(X^{1,i}_t- X^{0,i}_t)\\
&\quad +\frac{\lambda}{2}\sum_{i=1}^N\sum_{j\not=i}\sum_{t\in[0,T]}\Delta(X_t^{1,j} - X_t^{0,j})\Delta(X_t^{1,i} - X_t^{0,i}).
\end{align*}
Due to the positive definiteness of the kernel $e^{-\beta |t-s|}$ (in the sense of Bochner) we have %the ``quadratic'' inequality
\[-\sum_{i}\sum_{j\not=i}\int_0^T\int_0^Te^{-\beta|t-s|}dM_s^jdM_t^i\leq \sum_{i}\int_0^T\int_0^Te^{-\beta|t-s|}dM_s^idM_t^i\] for arbitrary Lebesgue--Stieltjes integrators $M^i$. Applying this,
\begin{align}\label{eqn:J2.sum.bd}
\sum_{i=1}^N\dot{\mathfrak{J}}_2^i(0)&\leq  \frac{\lambda}{2} \sum_{i=1}^N\int_0^T\int_0^T e^{-\beta |t-s|} d(X_s^{1,i} - X_s^{0,i}) d(X^{1,i}_t- X^{0,i}_t)\\
&\quad +\frac{\lambda}{2}\sum_{i=1}^N\sum_{j\not=i}\sum_{t\in[0,T]}\Delta(X_t^{1,j} - X_t^{0,j})\Delta(X_t^{1,i} - X_t^{0,i}).\nonumber
\end{align}
Next, we treat the jumps. Let
\begin{align*}\mathfrak{J}_3^i(\alpha)&=\frac{\lambda}{2}\sum_{j\not=i}\sum_{t\in[0,T]} \Delta X_t ^{\alpha, i} \Delta X_t^{0,j}+\frac{\lambda}{2}\sum_{j\not=i}\sum_{t\in[0,T]} \Delta X_t ^{1-\alpha, i} \Delta X_t^{1,j}.
\end{align*}
Differentiating gives
\begin{align*}\dot{\mathfrak{J}}_3^i(\alpha)&=-\frac{\lambda}{2}\sum_{j\not=i}\sum_{t\in[0,T]} \Delta \left( X_t^{0,i}-X_t ^{1, i}\right)\Delta X_t^{0,j}+\frac{\lambda}{2}\sum_{j\not=i}\sum_{t\in[0,T]} \Delta \left(X_t^{0,i}-X_t ^{1, i}\right) \Delta X_t^{1,j}.
\end{align*}
Then, by collecting terms and summing over $i$,
\begin{equation}\label{eqn:J3.sum.bd}\sum_{i=1}^N\dot{\mathfrak{J}}_3^i(0)=-\frac{\lambda}{2}\sum_{i=1}^N\sum_{j\not=i}\sum_{t\in[0,T]} \Delta \left(X_t^{1,i}-X_t^{0, i}\right)\Delta \left(X_t^{1,j}-X_t^{0,j}\right).
%\\
%&=-\frac{\lambda}{2}\sum_{t\in[0,T]}\left(\sum_{j=1}^N \Delta \left(X_t^{0,j}-X_t^{1,j}\right)\right)^2\leq 0.
\end{equation}

It remains is to treat the terms arising from the cost $C_{\cdot}$. Since $\boldsymbol{X}^0$ and $\boldsymbol{X}^1$ are assumed to be Nash equilibria they (and their convex combinations) must have a finite cost (as measured by $C_{\cdot}$) almost surely. Therefore, we may ignore the characteristic function terms. We only consider the case of $C_B(\cdot)$ as the proof with $C_A(\cdot)$ or $C_{A'}(\cdot)$ is similar. Let
\begin{align*}\mathfrak{J}_4^i(\alpha) &=C_B(X^{\alpha,i})+C_B(X^{1-\alpha,i})
=\sum_{t\in[0,T]} \frac{\vartheta_t}{2}(\Delta X_t^{\alpha, i})^2+\sum_{t\in[0,T]} \frac{\vartheta_t}{2}(\Delta X_t^{1-\alpha, i})^2.
\end{align*}
Differentiating and setting $\alpha=0$,
\begin{align*}\dot{\mathfrak{J}}_4^i(0)&=\sum_{t\in[0,T]} \vartheta_t\left(\Delta X_t^{0,i}(\Delta X_t^{1,i}-\Delta X_t^{0,i}) -\Delta X_t^{1,i}(\Delta X_t^{1,i}-\Delta X_t^{0,i})\right)\nonumber\\
&=-\sum_{t\in[0,T]} \vartheta_t(\Delta X_t^{1,i}-\Delta X_t^{0,i})^2.\nonumber
\end{align*}
Summing over $i$, we have
\begin{align}\sum_{i=1}^N\dot{\mathfrak{J}}_4^i(0)=-\sum_{i=1}^N\sum_{t\in[0,T]} \vartheta_t(\Delta X_t^{1,i}-\Delta X_t^{0,i})^2\leq 0. \label{eqn:J4.sum.bd}
\end{align}
Aggregating the above expressions we recover $V(\alpha)$,
\[V(\alpha) = \mathbb{E}\left[\sum_{i=1}^N(\mathfrak{J}_1^i(\alpha)+\mathfrak{J}_2^i(\alpha)+\mathfrak{J}_3^i(\alpha)+\mathfrak{J}_4^i(\alpha))\right].\]
By an application of the dominated convergence theorem (or a direct verification) we may pass the derivative under the expectation to obtain
\begin{align*}\dot{V}(0) &= \mathbb{E}\left[\sum_{i=1}^N(\dot{\mathfrak{J}}_1^i(0)+\dot{\mathfrak{J}}_2^i(0)+\dot{\mathfrak{J}}_3^i(0)+\dot{\mathfrak{J}}_4^i(0))\right]\\
&\leq -\mathbb{E}\left[\frac{\lambda}{2}\sum_{i=1}^N\int_0^T\int_0^T e^{-\beta |t-s|} d(X_s^{1,i} -X_s^{0, i})d(X_t^{1,i} -X_t^{0, i})\right].
\end{align*}
The last inequality follows from \eqref{eqn:J1.sum}, \eqref{eqn:J2.sum.bd}, \eqref{eqn:J3.sum.bd}, and \eqref{eqn:J4.sum.bd}. Finally, since $\boldsymbol{X}^0\not=\boldsymbol{X}^1$ and the kernel $e^{-\beta |t-s|}$ is positive definite, we conclude $\dot{V}(0)<0$. This contradiction completes the proof.
\qed

\section{Proofs for Section \ref{sec:N.inst.cost}}\label{app:N.inst.cost}

\subsection{Equilibrium with Terminal Inventory Penalty}

\subsubsection{Lemma \ref{lem:term.pen.ODE}}
Taking the Gateaux differential of $\cJ_A(\cdot, \boldsymbol{v}^{-i})$ in~\eqref{eqn:cJ.A} in an arbitrary direction $\eta\in L^2[0,T]$,
\begin{align*}
    \delta_\eta \cJ_A(v^{i};\boldsymbol{v}^{-i})&=\int_0^T(\delta_\eta I_tv_t^{i}+\eta_tI_t+\varepsilon v_t^{i}\eta_t)dt+\varphi X_T^{i}\int_0^T\eta_tdt,
\end{align*}
where
\begin{equation*}
    \delta_\eta I_t=\int_0^t e^{-\beta(t-s)}\lambda\eta_sds, \ \ t\in[0,T].
\end{equation*}
By changing the order of integration,
\begin{align*}
    \int_0^T\delta_\eta I_tv_t^{i}dt&=\int_0^T\int_0^t\lambda e^{-\beta(t-s)}v_t^{i}\eta_sdsdt
    =\int_0^T\int_s^T\lambda e^{-\beta(t-s)}v_t^{i}\eta_sdtds.
\end{align*}
Swapping the roles of the integration variables $s$ and $t$, we get the expression
\begin{equation*}
\int_0^T\delta_\eta I_tv_t^{i}dt=\int_0^T\int_t^T\lambda e^{-\beta(s-t)}v_s^{i}ds\eta_tdt,
\end{equation*}
which leads to the representation
\begin{equation*}
    \delta_\eta \mathcal{J}_A (v^{i};\boldsymbol{v}^{-i})=\int_0^T[Y_t^{i}+I_t+\varepsilon v_t^{i}+\varphi X_T^{i}]\eta_tdt
\end{equation*}
for
\begin{equation*}%\label{eqn:def.Y.process}
    Y_t^{i}:=\int_t^T\lambda e^{-\beta (s-t)}v_s^{i} ds, \ \ \ t\in [0,T].
\end{equation*}

From this, we see that $\eta \mapsto \delta_\eta \mathcal{J}_A(v^{i};\boldsymbol{v}^{-i})$ is a well-defined continuous linear operator on $L^2[0,T]$ for every $v^{i}\in L^2[0,T]$. Letting
\begin{equation*}
   D \mathcal{J}_A(v^{i};\boldsymbol{v}^{-i})=\left(Y_t^{i}+I_t+\varepsilon v_t^{i}+\varphi X_T^{i}\right)\in L^2[0,T] 
\end{equation*}
we have the following form of the derivative in terms of the usual $L^2[0,T]$ inner product,
\[\delta_\eta \mathcal{J}_A(v^{i};\boldsymbol{v}^{-i})=\langle D \mathcal{J}_A(v^{i};\boldsymbol{v}^{-i}),\eta\rangle_{L^2[0,T]}.\]
By standard optimality theory in Hilbert spaces (see Appendix \ref{app:opt.theory}), an element $v^{i}\in L^2[0,T]$ is a minimizer of $\cJ_A(\cdot,\boldsymbol{v}^{-i})$ if and only if  \[D \mathcal{J}_A(v^{i};\boldsymbol{v}^{-i}) =0,\]
where the equality is to be understood in the $L^2$ sense. Equivalently, the representative $D \mathcal{J}_A(v^{i};\boldsymbol{v}^{-i})$ of the Gateaux derivative must be $0$ almost everywhere; that is,
\begin{equation}\label{eqn:foc.inst.cost}
    \boxed{Y_t^{i}+I_t+\varepsilon v_t^{i}=-\varphi X_T^{i},  \ \ \ \text{a.e.} \ \ \  t\in[0,T].}
\end{equation}
Since $Y^{i}$ and $I$ are continuous by definition, we have that any $v^{i}$ satisfying \eqref{eqn:foc.inst.cost} is equal almost everywhere to a continuous function. From here on, we identify any such $v^{i}\in L^2[0,T]$ with its continuous version. Then, by observing that $Y^{i}$ and $I$ are differentiable (and that $X_T^{i}$ is a constant), we have that any $v^{i}$ satisfying \eqref{eqn:foc.inst.cost} is also differentiable. The condition \eqref{eqn:foc.inst.cost} then implies that
\begin{equation}\label{eqn:foc.der.inst.cost}
    \boxed{\dot{Y}_t^{i}+\dot{I}_t+\varepsilon \dot{v}_t^{i}=0, \ \ \  t\in[0,T].}
\end{equation}

To form a Nash equilibrium we require the simultaneous optimality of each of the controls in the strategy profile $\boldsymbol{v}$. As a result, \eqref{eqn:foc.inst.cost} and \eqref{eqn:foc.der.inst.cost} must hold for all $i=1,\dots,N$. In this way, we arrive at the following equilibrium system of ODEs,
\begin{align*}
    0&=\dot{Y}^{i}_t+\dot{I}_t+\varepsilon \dot{v}_t^{i}, \ \ \ i=1,\dots,N,\\
    \dot{Y}^{i}_t&=\beta Y^{i}_t-\lambda v^{i}_t, \ \ \ i=1,\dots,N,\\
    \dot{I}_t&=-\beta I_t+\lambda\sum_{i=1}^Nv_t^{i},
\end{align*}
subject to the initial and terminal conditions
\begin{align*}
    I_0&=0,\\
    Y_T^{i}&=0, \ \ \ i=1,\dots, N,\\
    v_T^{i}&= -\varepsilon^{-1}\left[\varphi X_T^{i}+I_T\right],  \ \ \ i=1,\dots, N,
\end{align*}
where the last equation arises by taking $t\uparrow T$ in \eqref{eqn:foc.inst.cost}.

It is easy to check that the satisfaction of this system implies \eqref{eqn:foc.inst.cost} for all $i=1,\dots,N$. Hence, enforcing the ODEs or the concurrent satisfaction of \eqref{eqn:foc.inst.cost} for all $i=1,\dots, N$ is equivalent. To complete the proof, we rearrange the system of ODEs to recover the standard form reported in Lemma~\ref{lem:term.pen.ODE}. \qed

\subsubsection{Theorem \ref{thm:equil.term.pen}}\label{se:proof.of.equil.term.pen}

Let $\boldsymbol{F} = (I, Y^{1},\dots, Y^{N},v^{1},\dots, v^{N})^\top$. The system in Lemma \ref{lem:term.pen.ODE} can be written in matrix form,
\begin{equation}\label{eqn:term.pen.ode.matrix}
\dot{\boldsymbol{F}}_t=\mathsf{A} \boldsymbol{F}_t
\end{equation}
for 
\[\mathsf{A} = \begin{bmatrix}
    -\beta & 0 & 0 & \dots  & 0 & 0 & \lambda & \lambda  & \dots & \lambda & \lambda \\
    0 & \beta & 0 & \dots & 0 & 0 & -\lambda & 0 & \dots & 0 & 0 \\
     0 & 0 & \beta & \dots & 0 & 0 & 0 & -\lambda & \dots & 0 & 0\\
      \vdots & \vdots & \vdots & \ddots & \vdots & \vdots & \vdots & \vdots & \ddots &  \vdots & \vdots \\
     0 & 0 & 0 & \dots  & \beta & 0 & 0 &  0 & \dots & -\lambda & 0\\
     0 & 0 & 0 & \dots & 0 & \beta & 0 &  0 & \dots & 0 & -\lambda\\
     \frac{\beta}{\varepsilon} & -\frac{\beta}{\varepsilon} & 0 & \dots & 0 & 0 & 0 & -\frac{\lambda}{\varepsilon} & \dots  & -\frac{\lambda}{\varepsilon} & -\frac{\lambda}{\varepsilon} \\
     \frac{\beta}{\varepsilon} & 0 & -\frac{\beta}{\varepsilon} & \dots & 0 & 0 & -\frac{\lambda}{\varepsilon} & 0 & \dots  & -\frac{\lambda}{\varepsilon} & -\frac{\lambda}{\varepsilon} \\
    \vdots & \vdots & \vdots & \ddots & \vdots & \vdots & \vdots & \vdots & \ddots &  \vdots & \vdots \\
     \frac{\beta}{\varepsilon} & 0 & 0 & \dots & -\frac{\beta}{\varepsilon} & 0 & -\frac{\lambda}{\varepsilon} & - \frac{\lambda}{\varepsilon} & \dots  & 0 & -\frac{\lambda}{\varepsilon} \\
     \frac{\beta}{\varepsilon} & 0 & 0 & \dots & 0 & -\frac{\beta}{\varepsilon} & -\frac{\lambda}{\varepsilon} & - \frac{\lambda}{\varepsilon} & \dots  & -\frac{\lambda}{\varepsilon} & 0 \\
\end{bmatrix}.\]
It can be directly verified that the matrix $\mathsf{A}$ has eigenvalues
\[z_1 = \frac{-\lambda(N-1)+\sqrt{(N-1)^2\lambda^2+4\beta \varepsilon (N+1) \lambda +4\beta^2\varepsilon^2}}{2\varepsilon},\]
\[z_2 = \frac{-\lambda(N-1)-\sqrt{(N-1)^2\lambda^2+4\beta \varepsilon (N+1) \lambda +4\beta^2\varepsilon^2}}{2\varepsilon},\]
\[z_{2+i} = \beta + \varepsilon^{-1} \lambda, \ \ \ \  i=1,\dots,N-1,\] and $z_{N+1+i}=0$ for $i=1,\dots,N$, with associated eigenvectors
\[\boldsymbol{q}_1=\frac{N\lambda}{z_1+\beta} \boldsymbol{e}_1-\sum_{j=1}^N\frac{\lambda}{z_1-\beta}\boldsymbol{e}_{1+j}+\sum_{j=1}^N\boldsymbol{e}_{N+1+j},\]
\[\boldsymbol{q}_2=\frac{N\lambda}{z_2+\beta} \boldsymbol{e}_1-\sum_{j=1}^N\frac{\lambda}{z_2-\beta}\boldsymbol{e}_{1+j}+\sum_{j=1}^N\boldsymbol{e}_{N+1+j},\]
\[\boldsymbol{q}_{2+i} = \varepsilon \boldsymbol{e}_2-\varepsilon \boldsymbol{e}_{2+i}-\boldsymbol{e}_{N+2}+\boldsymbol{e}_{N+2+i}, \ \ \ i=1,\dots,N-1,\]
\[\boldsymbol{q}_{N+1+i} = \frac{\lambda}{\beta} \boldsymbol{e}_1+\frac{\lambda}{\beta}\boldsymbol{e}_{1+i}+\boldsymbol{e}_{N+1+i}, \ \ \ i=1,\dots,N.\] 
Here, we write $\boldsymbol{e}_i$ for the $i$th Euclidean basis vector. These eigenvalues and eigenvectors define the columns of the fundamental matrix
\[\mathsf{Q}_t=\begin{bmatrix}
    \frac{N\lambda}{z_1+\beta}e^{z_1t} & \frac{N\lambda}{z_2+\beta}e^{z_2t} & 0 & 0 & \dots & 0 & \frac{\lambda}{\beta} & \frac{\lambda}{\beta} & \frac{\lambda}{\beta}  & \dots & \frac{\lambda}{\beta}\\
    -\frac{\lambda}{z_1-\beta}e^{z_1t} & -\frac{\lambda}{z_2-\beta}e^{z_2t} & \varepsilon e^{z_3t} & \varepsilon e^{z_3t} & \dots & \varepsilon e^{z_3t} & \frac{\lambda}{\beta} & 0 & 0 & \dots & 0 \\
    -\frac{\lambda}{z_1-\beta}e^{z_1t} & -\frac{\lambda}{z_2-\beta}e^{z_2t} & -\varepsilon e^{z_3t} & 0 & \dots & 0 & 0 & \frac{\lambda}{\beta} & 0 & \dots & 0\\
    -\frac{\lambda}{z_1-\beta}e^{z_1t} & -\frac{\lambda}{z_2-\beta}e^{z_2t} & 0  & -\varepsilon e^{z_3t} & \dots & 0 & 0 & 0 & \frac{\lambda}{\beta}  & \dots & 0\\
    \vdots & \vdots & \vdots  & \vdots & \ddots & \vdots & \vdots & \vdots  & \vdots  & \ddots & \vdots\\
    -\frac{\lambda}{z_1-\beta}e^{z_1t} & -\frac{\lambda}{z_2-\beta}e^{z_2t} & 0  & 0 & \dots & -\varepsilon e^{z_3t} & 0 & 0 & 0 & \dots  & \frac{\lambda}{\beta} \\
    e^{z_1t} & e^{z_2t} & -e^{z_3t} & -e^{z_3t} & \dots & -e^{z_3t} & 1 & 0 & 0 & \dots & 0\\
    e^{z_1t} & e^{z_2t} & e^{z_3t} & 0 & \dots & 0 & 0 & 1 & 0 & \dots & 0\\
    e^{z_1t} & e^{z_2t} & 0 & e^{z_3t} & \dots & 0 & 0 & 0 & 1 & \dots & 0\\
    \vdots & \vdots & \vdots & \vdots & \ddots & \vdots & \vdots & \vdots & \vdots & \ddots & \vdots\\
    e^{z_1t} & e^{z_2t} & 0 & 0 & \dots & e^{z_3t} & 0 & 0 & 0 & \ddots & 1\\
\end{bmatrix}.\]
Let  $\boldsymbol{c} = (c_1,\dots,c_{2N+1})^\top$ be a vector of constants. The fundamental solution to \eqref{eqn:term.pen.ode.matrix} takes the form
\begin{equation}\label{eqn:fund.sol.inst.cost}
    \boldsymbol{F}_t = \mathsf{Q}_t\boldsymbol{c} =c_1\boldsymbol{q}_1e^{z_1 t}+c_2\boldsymbol{q}_2e^{z_2 t}+\sum_{i=1}^{N-1} c_{2+i}\boldsymbol{q}_{2+i}e^{z_3 t}+\sum_{i=1}^N c_{N+1+i}\boldsymbol{q}_{N+1+i}.
\end{equation}
To solve for $\boldsymbol{c}$ we enforce the boundary conditions from Lemma \ref{lem:term.pen.ODE}. 
To begin, we need an expression for the inventory processes. By integrating the expressions for $v^{i}$ in \eqref{eqn:fund.sol.inst.cost} we have that $X^{1}$ is given by
\begin{equation}\label{eqn:x1}
    X^{1}_t = x^{1}+ \frac{c_1}{z_1}(e^{z_1 t}-1) + \frac{c_2}{z_2}(e^{z_2 t}-1) - (e^{z_{3} t}-1)\sum_{j=2}^{N}\frac{c_{1+j}}{z_3}  + c_{N+2}t,
\end{equation}
and
\begin{equation}\label{eqn:xi}
X^{i}_t = x^{i}+ \frac{c_1}{z_1}(e^{z_1 t}-1) + \frac{c_2}{z_2}(e^{z_2 t} -1)+\frac{c_{1+i}}{z_3}(e^{z_{3} t}-1)+ c_{N+1+i}t, \ \ \ i=2,\dots, N.
\end{equation}
Then, writing the boundary conditions in terms of $\boldsymbol{c}$ we get the system of $2N+1$ equations,

\begin{equation*}
    \begin{cases}
    c_1\frac{N\lambda}{z_1+\beta}+c_2\frac{N\lambda}{z_2+\beta}+\frac{\lambda}{\beta}\sum_{j=1}^Nc_{N+1+j}=0,\\
    \\
    -c_1\frac{\lambda}{z_1-\beta}e^{z_1 T}-c_2\frac{\lambda}{z_2-\beta}e^{z_2 T}+\varepsilon e^{z_3 T}\sum_{j=2}^Nc_{1+j}+\frac{\lambda}{\beta}c_{N+2}=0,\\
    \\
    -c_1\frac{\lambda}{z_1-\beta}e^{z_1 T}-c_2\frac{\lambda}{z_2-\beta}e^{z_2 T}-\varepsilon e^{z_3 T}c_{1+i}+\frac{\lambda}{\beta}c_{N+1+i}=0, & i=2,\dots,N,\\
    \\
    c_1e^{z_1 T} + c_2 e^{z_2 T} - e^{z_{3} T}\sum_{j=2}^{N}c_{1+j} + c_{N+2} \\
    \quad =-\varepsilon^{-1}\varphi\left(x^{1}+ \frac{c_1}{z_1}(e^{z_1 T}-1) + \frac{c_2}{z_2}(e^{z_2 T}-1)\right)\\
    \quad\quad +\varepsilon^{-1}\varphi\left( (e^{z_{3} T}-1)\sum_{j=2}^{N}\frac{c_{1+j}}{z_3}  - c_{N+2}T\right)\\
    \quad \quad - \varepsilon^{-1}\left(c_1 \frac{N\lambda}{z_1+\beta} e^{z_1 T} + c_2 \frac{N\lambda}{z_2+\beta} e^{z_2 T}+\frac{\lambda}{\beta}\sum_{j=1}^Nc_{N+1+j}\right),\\
    \\
     c_1e^{z_1 T} + c_2 e^{z_2 T} +c_{1+i}e^{z_{3} T} + c_{N+1+i}\\
     \quad =-\varepsilon^{-1}\varphi \left(x^{i}+ \frac{c_1}{z_1}(e^{z_1 T}-1) + \frac{c_2}{z_2}(e^{z_2 T} -1)\right)\\
     \quad\quad -\varepsilon^{-1}\varphi\left(\frac{c_{1+i}}{z_3}(e^{z_{3} T}-1)+ c_{N+1+i}T\right)\\
     \quad \quad - \varepsilon^{-1}\left(c_1 \frac{N\lambda}{z_1+\beta} e^{z_1 T} + c_2 \frac{N\lambda}{z_2+\beta} e^{z_2 T}+\frac{\lambda}{\beta}\sum_{j=1}^Nc_{N+1+j}\right), & i = 2,\dots,N.
    \end{cases}
\end{equation*}
We will solve this system in parts. First, we reduce to a tractable three dimensional system. Summing over the last $N$ equations and rearranging yields
\begin{align}
    -\varepsilon^{-1}\varphi\sum_{j=1}^Nx^{j}&=Nc_1\left[e^{z_1 T} +\frac{\varepsilon^{-1}\varphi}{z_1}[e^{z_1 T}-1] +\varepsilon^{-1} \frac{N\lambda}{z_1+\beta} e^{z_1 T}\right]  \nonumber \\
    &\quad+ Nc_2 \left[e^{z_2 T}+\frac{\varepsilon^{-1}\varphi}{z_2}[e^{z_2 T} -1] +\varepsilon^{-1} \frac{N\lambda}{z_2+\beta} e^{z_2 T}\right] \label{eqn:sum.1} \\ 
    &\quad +\left[1+\varepsilon^{-1}\varphi T+N\varepsilon^{-1}\frac{\lambda}{\beta}\right] \sum_{j=1}^Nc_{N+1+j}.\nonumber
\end{align}
At the same time, summing over the $2$nd to $(N+1)$th equations gives
\begin{equation}\label{eqn:sum.2}
    0=-c_1\frac{N\lambda}{z_1-\beta}e^{z_1 T}-c_2\frac{N\lambda}{z_2-\beta}e^{z_2 T}+\frac{\lambda}{\beta}\sum_{i=1}^Nc_{N+1+i}.
\end{equation}
Coupling \eqref{eqn:sum.1} and \eqref{eqn:sum.2} with the first equation we can solve for $c_1$, $c_2$ and $\sum_{i=1}^Nc_{N+1+i}$. Written in terms of the constants in Table \ref{tab:constants}, we get
\begin{equation}\label{eqn:c1.c2.sum}
    c_1 = -\frac{\varphi}{\varepsilon \psi} \overline{x}, \ \ \ c_2 = \frac{\gamma_1\varphi}{\varepsilon \gamma_2\psi} \overline{x}, \ \ \ \sum_{i=1}^Nc_{N+1+i}= -\frac{N\beta \rho_-\varphi}{\varepsilon \psi} \overline{x}.
\end{equation}
We now pare off the $2$nd and the $(N+2)$th equations. After substituting in \eqref{eqn:c1.c2.sum} and rearranging we get (again in term of the constants in Table \ref{tab:constants})
\begin{equation}\label{eqn:simplified.2}
\frac{\lambda}{\beta}c_{N+2}+\varepsilon e^{z_3 T}\sum_{j=2}^Nc_{1+j}=-\frac{\lambda \rho_{-}\varphi}{\varepsilon\psi}\overline{x},
\end{equation}
\begin{align}\label{eqn:simplified.N+2}
    -\left[e^{z_3 T} +\frac{\varphi}{\varepsilon }\frac{e^{z_3 T}-1}{z_3}\right]\sum_{j=2}^Nc_{1+j} + &\left[1+\frac{\varphi}{\varepsilon} T\right] c_{N+2}
    =-\frac{\varphi}{\varepsilon}( x^{1}-\overline{x})-\beta\rho_{-}\left[1+\frac{\varphi}{\varepsilon} T\right]\frac{\varphi}{\varepsilon\psi}\overline{x}. %\nonumber %-\frac{\varphi}{\varepsilon}x^{1}-\frac{\varphi\xi}{\varepsilon \psi}\overline{x}.
\end{align}
Solving \eqref{eqn:simplified.2} and \eqref{eqn:simplified.N+2} yields
\begin{equation}\label{eqn:cN+2}
c_{N+2} = -\frac{\beta \varphi}{\varepsilon\xi}(x^{1}-\overline{x})-\frac{\beta \rho_{-}\varphi}{\varepsilon \psi}\overline{x},
\end{equation}
% \begin{equation}\label{eqn:cN+2}
% c_{N+2} = -\frac{\beta \varphi}{\varepsilon\sigma}(x^{(1)}-\overline{x})-\frac{\beta \pi\varphi}{\varepsilon\sigma \psi}\overline{x},
% \end{equation}
\begin{equation}\label{eqn:sum.c1+i}
    \sum_{j=2}^Nc_{1+j}=\frac{\lambda\varphi}{\varepsilon^2 \xi  e^{z_3T}}(x^{1}-\overline{x}).
\end{equation}
% \begin{equation}\label{eqn:sum.c1+i}
%     \sum_{j=2}^Nc_{1+j}=\frac{\lambda\varphi}{\varepsilon^2 \sigma  e^{z_3T}}(x^{(1)}-\overline{x})+\frac{\lambda\varphi\left( \pi -\sigma \rho_{-}\right)}{\varepsilon^2 \sigma \psi e^{z_3T}}\overline{x}.
% \end{equation}
At last, we turn to the $3$rd to $(N+1)$th equations and the last $N-1$ equations. Substituting in the existing solutions and collecting terms we arrive at the system
\begin{equation*}
    -\varepsilon e^{z_3 T}c_{1+i}+\frac{\lambda}{\beta}c_{N+1+i}=-\frac{\lambda \varphi\rho_{-}}{\varepsilon\psi}\overline{x}, \ \ \ i=2,\dots,N,
\end{equation*}
\begin{align*}
    \left[e^{z_3 T} +\frac{\varphi}{\varepsilon }\frac{e^{z_3 T}-1}{z_3}\right]& c_{1+i} + \left[1+\frac{\varphi}{\varepsilon}T\right]c_{N+1+i}\\
    &=-\frac{\varphi}{\varepsilon}( x^{i}-\overline{x})-\beta\rho_{-}\left[1+\frac{\varphi}{\varepsilon} T\right]\frac{\varphi}{\varepsilon\psi}\overline{x} ,\ \ \ i = 2,\dots,N.\nonumber %-\frac{\varphi}{\varepsilon} x^{i}-\frac{\varphi\xi}{\varepsilon\psi}\overline{x} ,\ \ \ i = 2,\dots,N.
\end{align*}
These equations can be solved in pairs. By doing so, one finds
\begin{equation}\label{eqn:cN+1+i}
c_{N+1+i} = -\frac{\beta\varphi}{\varepsilon\xi}(x^{i}-\overline{x})-\frac{\beta\rho_{-}\varphi}{\varepsilon \psi}\overline{x}, \ \ \ i=2,\dots,N,
\end{equation}
% \begin{equation}\label{eqn:cN+1+i}
% c_{N+1+i} = -\frac{\beta\varphi}{\varepsilon\sigma}(x^{(1)}-\overline{x})-\frac{\beta\pi\varphi}{\varepsilon\sigma \psi}\overline{x}, \ \ \ i=2,\dots,N,
% \end{equation}
\begin{equation}\label{eqn:c1+i}
c_{1+i}=-\frac{\lambda\varphi}{\varepsilon^2 \xi e^{z_3T}}(x^{i}-\overline{x}), \ \ \ i=2,\dots,N.
\end{equation}
% \begin{equation}\label{eqn:c1+i}
% c_{1+i}=-\frac{\lambda\varphi}{\varepsilon^2 \sigma e^{z_3T}}(x^{i}-\overline{x})-\frac{\lambda\varphi\left( \pi -\sigma \rho_{-}\right)}{\varepsilon^2 \sigma \psi e^{z_3T}}\overline{x}, \ \ \ i=2,\dots,N.
% \end{equation}
To complete the proof we substitute \eqref{eqn:c1.c2.sum}, \eqref{eqn:cN+2}, \eqref{eqn:sum.c1+i},  \eqref{eqn:cN+1+i}, and \eqref{eqn:c1+i} into \eqref{eqn:x1} and \eqref{eqn:xi}, and collect terms. \qed

\subsubsection{Corollary \ref{cor:eq.cost.term.pen}}

Using the form of the equilibrium in Theorem \ref{thm:equil.term.pen}, we compute the equilibrium impact
\begin{equation*}I_t=-N\lambda\left[\rho_{-}+\frac{1}{z_1+\beta}e^{z_1t} -\frac{\gamma_1}{ \gamma_2}\frac{1}{z_2+\beta}e^{z_2t}\right]\frac{\varphi}{\varepsilon\psi}\overline{x}.
\end{equation*}
By differentiating we similarly obtain
\[\dot{X}^{*,i}_t= -\left[\beta\rho_{-}+e^{z_1 t}- \frac{\gamma_1}{\gamma_2} e^{z_2 t}\right]\frac{\varphi}{\varepsilon \psi}\overline{x}-\left[\beta+\frac{\lambda e^{z_{3} t}}{\varepsilon e^{z_3T}}\right]\frac{\varphi}{\varepsilon \xi}(x^{i}-\overline{x}), \ \ \ i=2,\dots,N.\]
Here we have used the constants $\psi$ and $\xi$ from Table \ref{tab:constants}.
Defining
\[h^1_t := \left[\beta\rho_{-}+e^{z_1 t}- \frac{\gamma_1}{\gamma_2} e^{z_2 t}\right]\left[\rho_{-}+\frac{1}{z_1+\beta}e^{z_1t} -\frac{\gamma_1}{ \gamma_2}\frac{1}{z_2+\beta}e^{z_2t}\right],\]
\[h^2_t := \left[\beta+\frac{\lambda e^{z_{3} t}}{\varepsilon e^{z_3T}}\right]\left[\rho_{-}+\frac{1}{z_1+\beta}e^{z_1t} -\frac{\gamma_1}{ \gamma_2}\frac{1}{z_2+\beta}e^{z_2t}\right],\]
one can verify that
\[I_t\dot{X}^{*,i}_t = h^1_t\frac{N\lambda\varphi^2}{\varepsilon^2\psi^2}\overline{x}^2+h^2_t\frac{N\lambda\varphi^2}{\varepsilon^2\xi\psi}(x^{i}-\overline{x})\overline{x}.\]
At the same time, defining
\[h^3_t:=\left[\beta\rho_{-}+e^{z_1 t}- \frac{\gamma_1}{\gamma_2} e^{z_2 t}\right]^2, \ \ \ h^4_t:=\left[\beta+\frac{\lambda e^{z_{3} t}}{\varepsilon e^{z_3T}}\right]^2,\]
%and,
\[h^5_t:=\left[\beta\rho_{-}+e^{z_1 t}- \frac{\gamma_1}{\gamma_2} e^{z_2 t}\right]\left[\beta+\frac{\lambda e^{z_{3} t}}{\varepsilon e^{z_3T}}\right],\]
we have
\[(\dot{X}^{*,i}_t)^2=h^3_t\frac{\varphi^2}{\varepsilon^2 \psi^2}\overline{x}^2+h^4_t\frac{\varphi^2}{\varepsilon^2 \xi^2}(x^{i}-\overline{x})^2+h^5_t\frac{2\varphi^2}{\varepsilon^2 \xi\psi}\overline{x}(x^{i}-\overline{x}).\]
By expanding the product form of the functions $h^i_t$, $i=1,\dots,5$ and integrating over $[0,T]$ we obtain the identities
\[\mathfrak{h}_i=\int_0^T h_t^i dt, \ \ \ i=1,\dots, 5,\]
for the constants $\mathfrak{h}_i$ defined in Table \ref{tab:constants}. The form of the integrals
\[ \int_0^T I_t dX_t^{*,i} = \int_0^TI_t\dot{X}^{*,i}_tdt \ \ \ \text{and} \ \ \ \frac{\varepsilon}{2}\int_0^T(\dot{X}_t^{*,i})^2dt\]
in the statement of the corollary follows by substitution. Finally, an algebraic manipulation allows us to write $X_T^{*,i}$ in terms of the constant $\mathfrak{p}$ of Table \ref{tab:constants},
\begin{equation*}
    X_T^{*,i}=\frac{ z_3}{ \xi}(x^i-\overline{x})+\frac{\mathfrak{p}}{\psi}\overline{x}.
\end{equation*}
The reported form of $\varphi(X_T^{*,i})^2$ is then immediate. \qed

\subsection{Equilibrium with Liquidation Constraint}
\subsubsection{Lemma \ref{lem:conv.equilibria}}\label{se:proof.of.conv.equilibria}
To emphasize the dependence of the equilibria in Theorem \ref{thm:equil.term.pen} on $\varphi$ we will write $\boldsymbol{X}^{*}(\varphi)$ and $\dot{\boldsymbol{X}}^*(\varphi)=\boldsymbol{v}^*(\varphi)$. Under our assumptions there is $\tilde{\boldsymbol{X}}\in H^1[0,T]^{\times N}$ such that $\boldsymbol{X}^{*}(\varphi)\xrightarrow[\varphi\to\infty]{H^{1^{\times N}}} \tilde{\boldsymbol{X}}$. As a consequence, there is also $\tilde{\boldsymbol{v}}\in L^2[0,T]^{\times N}$ such that $\dot{\tilde{\boldsymbol{X}}}=\tilde{\boldsymbol{v}}$ and $\boldsymbol{v}^{*}(\varphi)\xrightarrow[\varphi\to\infty]{L^{2^{\times N}}} \tilde{\boldsymbol{v}}$. We begin with a technical result about the $\Gamma$-convergence of the objective functions when indexed by $\varphi$ and $\boldsymbol{v}^{*,-i}(\varphi)$. See Appendix \ref{app:opt.theory} for the definition of $\Gamma$-convergence.

\begin{lemma}\label{lem:gamma.conv.J}
We have $\mathcal{J}_{A}(\cdot;\boldsymbol{v}^{*,-i}(\varphi))\xrightarrow[\varphi\to\infty]{\Gamma} \mathcal{J}_{A'}(\cdot;\tilde{\boldsymbol{v}}^{-i})$ for $i=1,\dots,N$.    
\end{lemma}

\begin{proof}
We begin by considering $I$ as a functional that takes $L^2[0,T]$ to itself. That is, for any $v\in L^2[0,T]$ we write $I[v;\boldsymbol{v}^{*,-i}(\varphi)]$ to denote the function
\[t\mapsto I_t[v;\boldsymbol{v}^{*,-i}(\varphi)]= \lambda\int_0^t e^{-\beta(t-s)}\left(v_t+\sum_{j\not=i} v^{*,j}_s(\varphi)\right)ds.\]
Standard estimates verify that $I[v;\boldsymbol{v}^{*,-i}(\varphi)]\in L^2[0,T]$. We also consider $X_T^i$ as a functional from $L^2[0,T]$ to $\mathbb{R}$,
\[v\mapsto X_T^i[v] = x^i+\int_0^Tv_tdt.\] With this, we can express the objectives $\cJ_A$ and $\cJ_{A'}$ of \eqref{eqn:cJ.A} and \eqref{eqn:cJ.A'} as
\[\mathcal{J}_{A}(v;\boldsymbol{v}^{*,-i}(\varphi))=\left\langle I[v;\boldsymbol{v}^{*,-i}(\varphi)], v\right\rangle_{L^2}+\frac{\varepsilon}{2}\|v\|_{L^2} + \frac{\varphi}{2}\left(X_T^i[v]\right)^2,\]
\[\mathcal{J}_{A'}(v;\tilde{\boldsymbol{v}})=\left\langle I[v;\tilde{\boldsymbol{v}}], v\right\rangle_{L^2}+\frac{\varepsilon}{2}\|v\|_{L^2} + \chi_{\left\{X_T^i[v]\not=0\right\}}.\]

Next, fix a sequence of positive numbers $(\varphi^n)_{n\geq0}$ satisfying $\varphi^n\to\infty$. Let $v\in L^2[0,T]$ be arbitrary and fix any convergent sequence $(v^n)_{n\geq0}$ in $L^2[0,T]$ with limit $v$. It is easy to verify that
$I[v^n;\boldsymbol{v}^{*,-i}(\varphi^n)]\xrightarrow[n\to\infty]{L^2}I[v,\tilde{\boldsymbol{v}}^{-i}]$. Using this and the continuity of the inner product,
\begin{equation}\label{eqn:cont.conv.inner.prod}
    \lim_{n\to\infty}\left(\left\langle I[v^n;\boldsymbol{v}^{*,-i}(\varphi^n)], v^n\right\rangle_{L^2}+\frac{\varepsilon}{2}\|v^n\|_{L^2}\right)=\left\langle I[v;\tilde{\boldsymbol{v}}], v\right\rangle_{L^2}+\frac{\varepsilon}{2}\|v\|_{L^2} .
\end{equation}
It is similarly straightforward to check that
\begin{equation}\label{eqn:gamma.conv.pen}
    \frac{\varphi^n}{2}\left(X_T^i[v]\right)^2\xrightarrow[n\to\infty]{\Gamma} \chi_{\{X_T^i[v]\not=0\}}
\end{equation}
as a functional on $L^2[0,T]$. Combining the conclusions of \eqref{eqn:cont.conv.inner.prod} and \eqref{eqn:gamma.conv.pen} with \cite[Proposition 6.20]{DalMaso.93} gives the $\Gamma$-convergence stated in the lemma. 
\end{proof}

As $v^{*,i}(\varphi)$ minimizes $\mathcal{J}_{A}(\cdot;\boldsymbol{v}^{*,-i}(\varphi))$ and $v^{*,i}(\varphi)\xrightarrow[\varphi\to\infty]{L^2} \tilde{v}^i$, Lemma \ref{lem:gamma.conv.J} and Theorem \ref{thm:fund.thm.gamma.conv} yield that $\tilde{v}^i$ minimizes $\mathcal{J}_{A'}(\cdot,\tilde{\boldsymbol{v}}^{-i})$ and the costs converge. As this holds for all $i$, $\tilde{\boldsymbol{v}}$ is a Nash equilibrium for $\mathcal{J}_{A'}$. By reparametrizing in terms of the original process~$\tilde{\boldsymbol{X}}$, it follows that~$\tilde{\boldsymbol{X}}$ is a Nash equilibrium for $J_{A'}$. \qed

\subsubsection{Theorem \ref{thm:equil.liq.constr}}\label{app:pf.equil.liq.constr}
% We will show the convergence of $f$ and $g$ from \ref{thm:equil.term.pen}. Note that $z_1,z_2,z_3,\gamma_1,\gamma_2,$ and $\rho_{-}$ do not depend on $\varphi$, so we focus on the remaining terms.  The relevant quantities to investigate are $\psi$, $\sigma$, and $\pi$. 

% We begin by investigating the ratio $\psi\varphi^{-1}$. From Table \ref{tab:constants},
% \begin{equation*}
