\section{Proofs for Section \ref{sec:N.block.cost}}\label{app:N.block.cost}

\subsection{Proposition \ref{prop:no.interior.jumps}}

We first show an auxiliary result related to the optimality of jumps; it follows the template of \cite[Proposition 4.11]{SchiedStrehleZhang.17}.

\begin{lemma}\label{lem:gen.foc.jumps}
     Fix a strategy profile $\boldsymbol{X}$. If $X^{i}$ is optimal for $J_B(\cdot,\boldsymbol{X}^{-i})$ then for any $[0,T]$-valued predictable time $\tau$ there exists an $\mathcal{F}_{\tau-}$-measurable random variable $\boldsymbol{\Upsilon}$ satisfying
     \begin{equation*}
         \mathbb{E}\left[\lambda\int_0^Te^{-\beta |\sigma-t|}dX_t^{i}+\lambda\int_0^{\sigma-} e^{-\beta (\sigma-t)}\sum_{j\not=i}dX_t^{j} + \vartheta_\sigma\Delta X_\sigma^{i}+\frac{\lambda}{2}\sum_{j\not=i}\Delta X_\sigma^{j}\bigg|\mathcal{F}_{\tau-}\right]=\boldsymbol{\Upsilon} \ \ \ a.s.
     \end{equation*}
     for all predictable times $\sigma$ satisfying $\tau\leq \sigma \leq T$. In particular, we may take
     \[\boldsymbol{\Upsilon} = \mathbb{E}\left[\lambda\int_0^Te^{-\beta |\tau-t|}dX_t^{i}+\lambda\int_0^{\tau-} e^{-\beta (\tau-t)}\sum_{j\not=i}dX_t^{j} + \vartheta_\tau\Delta X_\tau^{i}+\frac{\lambda}{2}\sum_{j\not=i}\Delta X_\tau^{j}\bigg|\mathcal{F}_{\tau-}\right].\]


\end{lemma}

\begin{proof}
    Let $\tau$ and $\sigma\geq \tau$ be arbitrary $[0,T]$-valued predictable stopping times. Fixing some $A\in\mathcal{F}_{\tau-}$ we can consider the round trip trade $Z$ defined by
    \[Z_t=\mathds{1}_{A}\left(\mathds{1}_{t\geq \tau}-\mathds{1}_{t\geq\sigma}\right). \]
    If we perturb $X^{i}$ by $\alpha Z$ ($\alpha\in\mathbb{R}$) we get from Proposition \ref{prop:obj.func.rep} the cost
    \begin{align*}
    &J_B(X^{i}+\alpha Z;\boldsymbol{X}^{-i})\\
    &\quad =\frac{1}{2}\mathbb{E}\left[\sum_{t\in[0,T]} \vartheta_t(\Delta X_t^{i}+\alpha \Delta Z_t)^2\right] +\lambda\mathbb{E}\bigg[\frac{1}{2}\int_0^T\int_0^T e^{-\beta |t-s|} d(X_s^{i} +\alpha Z_s)d(X_t^{i}+\alpha Z_t)\\
    &\quad \quad \quad  + \int_0^T\int_0^{t-} e^{-\beta (t-s)} \sum_{j\not=i}dX_s^{j} d(X_t^{i}+\alpha Z_t) + \frac{1}{2}\sum_{j\not=i}\sum_{t\in[0,T]} (\Delta X_t ^{i} +\alpha \Delta Z_t)\Delta X_t^{j}\bigg ].
    \end{align*}
    Differentiating this expression with respect to $\alpha$ and setting $\alpha=0$ yields
    \begin{align*}
        \frac{d}{d\alpha}J_B(X^{i}+\alpha Z;\boldsymbol{X}^{-i})|_{\alpha=0}&=\mathbb{E}\left[\sum_{t\in[0,T]} \vartheta_t\Delta X_t^{i}\Delta Z_t\right]+ \lambda\mathbb{E}\bigg[\int_0^T\int_0^T e^{-\beta |t-s|} dX_s^{i}dZ_t\\
        &\quad + \int_0^T\int_0^{t-} e^{-\beta (t-s)} \sum_{j\not=i}dX_s^{j} d Z_t + \frac{1}{2}\sum_{j\not=i}\sum_{t\in[0,T]} \Delta Z_t\Delta X_t^{j}\bigg ].
    \end{align*}
    Therefore, a necessary first-order condition for optimality is
    \begin{align*}0&=\mathbb{E}\left[\sum_{t\in[0,T]} \vartheta_t\Delta X_t^{i}\Delta Z_t\right]+ \lambda\mathbb{E}\bigg[\int_0^T\int_0^T e^{-\beta |t-s|} dX_s^{i}dZ_t\\
        &\quad + \int_0^T\int_0^{t-} e^{-\beta (t-s)} \sum_{j\not=i}dX_s^{j} d Z_t + \frac{1}{2}\sum_{j\not=i}\sum_{t\in[0,T]} \Delta Z_t\Delta X_t^{j}\bigg ].
    \end{align*}
    By substituting in the form of $Z$ we obtain
    \begin{align*}0&=\mathbb{E}\left[\mathds{1}_A \left(\vartheta_\tau\Delta X_\tau^{i}-\vartheta_\sigma\Delta X_\sigma^{i}\right)\right]+ \lambda\mathbb{E}\Bigg[\mathds{1}_A\bigg(\int_0^T(e^{-\beta |\tau-t|} -e^{-\beta |\sigma-t|})dX_t^{i}\\
        &\quad + \int_0^{\tau-} e^{-\beta (\tau-t)}\sum_{j\not=i}dX_t^{j} -\int_0^{\sigma-} e^{-\beta(\sigma-t)}\sum_{j\not=i}dX_t^{j} + \frac{1}{2}\sum_{j\not=i}(\Delta X_\tau^{j}-\Delta X_\sigma^{j})\bigg)\Bigg ],
    \end{align*}
    which becomes, after rearranging, 
\begin{align*}
    \mathbb{E}&\left[\mathds{1}_A \left(\vartheta_\tau\Delta X_\tau^{i}+\lambda\int_0^Te^{-\beta |\tau-t|}dX_t^{i}+\lambda\int_0^{\tau-} e^{-\beta (\tau-t)}\sum_{j\not=i}dX_t^{j}+\frac{\lambda}{2}\sum_{j\not=i}\Delta X_\tau^{j}\right)\right]\\
    &=\mathbb{E}\left[\mathds{1}_A \left(\vartheta_\sigma\Delta X_\sigma^{i}+\lambda\int_0^Te^{-\beta |\sigma-t|}dX_t^{i}+\lambda\int_0^{\sigma-} e^{-\beta (\sigma-t)}\sum_{j\not=i}dX_t^{j}+\frac{\lambda}{2}\sum_{j\not=i}\Delta X_\sigma^{j}\right)\right].
\end{align*}
Iterative conditioning on $\mathcal{F}_{\tau-}$ under the expectation completes the proof after noting that $A\in\mathcal{F}_{\tau-}$ was arbitrary.
\end{proof}

For the proof of Lemma~\ref{lem:main.step.for.no.interior.jumps}  below it will be helpful to approximate predictable times with times where the inventories do not jump. That is feasible according to the next lemma, which is a straightforward generalization of \cite[Lemma B.1]{SchiedStrehleZhang.17}. We omit the proof.

\begin{lemma}\label{lem:no.jump.delay.times}
    Let $\boldsymbol{X}$ be an admissible strategy profile and let $\tau,\sigma$ be predictable stopping times satisfying $\tau\leq \sigma\leq T$. There exists a sequence $(\tau_n)_{n\geq0}$ of predictable times satisfying
    \begin{enumerate}
        \item[(i)] $\tau\leq \tau_n\leq \sigma$ with $\tau_n\downarrow \tau$ a.s.,
        \item[(ii)] $\tau<\tau_n$ on $\{\tau<\sigma\}$,
        \item[(iii)] $\Delta X_{\tau_n}^i=0$ on $\{\tau_n<\sigma\}$ for $i=1,\dots,N$.
        %$\tau_n>\tau$ and for sufficiently large $n$ there are no jumps at $\tau_n$ almost surely. That is, \[\mathbb{P}\left(\exists n_0 \ s.t. \  \forall n\geq n_0 \ \ \ \Delta X^{i}_{\tau_n}=0, \ \ \ i=1,\dots,N \right) =1.\]
    \end{enumerate}
    In particular, $\lim_{n\to\infty} \Delta X_{\tau_n}^i = 0$ on $\{\tau<\sigma\}$ for all $i$.
\end{lemma}

