With this we are ready to prove the following necessary conditions for the jumps of a best response to a strategy profile $\boldsymbol{X}^{-i}$.

\begin{lemma}\label{lem:main.step.for.no.interior.jumps} 
    Fix an admissible strategy profile $\boldsymbol{X}$ and suppose that $X^{i}$ is optimal for $J_B(\cdot,\boldsymbol{X}^{-i})$. If
    $\tau$ is any $[0,T]$-valued predictable stopping time, then
     \begin{equation}\label{eqn:eq.jumps.not.0}
         \left(\vartheta_\tau \Delta X_{\tau}^{i}+\frac{\lambda}{2}\sum_{j\not=i}\Delta X_{\tau}^{j}\right)\mathds{1}_{\{\tau>0\}}=0, \ \ \ a.s.
     \end{equation}
     and
     \begin{equation}\label{eqn:eq.jumps.not.T}
         \left( \vartheta_\tau \Delta X_{\tau}^{i}-\frac{\lambda}{2}\sum_{j\not=i}\Delta X_{\tau}^{j}\right)\mathds{1}_{\{\tau<T\}}=0, \ \ \ a.s.
     \end{equation}
     % In particular, if there exists a $t$ such that $\vartheta_t = 0$ and $\mathbb{P}\left(\sum_{j\not=i} \Delta X_t^j >0\right)>0$ then there is no admissible optimal strategy.
     % Moreover, if $\tau:=\inf\{t\geq 0: \exists i \ s.t. \ \Delta X^{*,i}_t=0\}\wedge T$,
     % \[\left(\vartheta (\tau)\Delta X_{\tau}^{i}+\frac{\lambda}{2}\sum_{j\not=i}\Delta X_{\tau}^{j}\right)\mathds{1}_{\{\tau>0\}}=0, \ \ \ i=1,\dots,N \ \ \ a.s.\]
\end{lemma}

\begin{proof}
    By predictability there exists an announcing sequence of stopping times $\tau_n\uparrow \tau$ with $\tau_n<\tau$ on $\{\tau>0\}$ and $\tau_n= 0$ on $\{\tau=0\}$. Moreover, we can take these times to be predictable (see \cite[Corollary 2.1]{Siorpaes.14}). At the same time, for each $\tau_n$ we can apply Lemma~\ref{lem:no.jump.delay.times} to find a sequence $(\tau_{n,m})_{m\geq0}$ satisfying (i) $\tau_n\leq \tau_{n,m}\leq \tau$ with $\tau_{n,m}\downarrow \tau_n$ as $m\uparrow\infty$, (ii) $\tau_n<\tau_{n,m}$ on $\{\tau_n<\tau\}$, and (iii) $\Delta X_{\tau_{n,m}}^{i} =0$ for all $i$ on $\{\tau_{n,m}<\tau\}$.

    Applying Lemma \ref{lem:gen.foc.jumps} twice and using the absence of jumps at $\tau_{n,m}$ on $\{\tau_{n,m}<\tau\}$,
    \begin{align*}
    \mathbb{E}&\Bigg[\lambda\int_0^Te^{-\beta |\tau_{n,m}-t|}dX_t^{i}+\lambda\int_0^{\tau_{n,m}-} e^{-\beta (\tau_{n,m}-t)}\sum_{j\not=i}dX_t^{j}\\
    &\quad \quad \quad  +\left( \vartheta_{\tau_{n,m}} \Delta X_{\tau_{n,m}}^{i}+\frac{\lambda}{2}\sum_{j\not=i}\Delta X_{\tau_{n,m}}^{j}\right)\mathds{1}_{\{\tau_{n,m}=\tau\}}\bigg|\mathcal{F}_{\tau_n-}\Bigg]\\
    &=\mathbb{E}\left[\lambda\int_0^Te^{-\beta |\tau_n-t|}dX_t^{i}+\lambda\int_0^{\tau_n-} e^{-\beta (\tau_n-t)}\sum_{j\not=i}dX_t^{j} + \vartheta_{\tau_n}\Delta X_{\tau_n}^{i}+\frac{\lambda}{2}\sum_{j\not=i}\Delta X_{\tau_n}^{j}\bigg|\mathcal{F}_{\tau_n-}\right]\\
    &=\mathbb{E}\left[\lambda\int_0^Te^{-\beta |\tau-t|}dX_t^{i}+\lambda\int_0^{\tau-} e^{-\beta (\tau-t)}\sum_{j\not=i}dX_t^{j} + \vartheta_{\tau}\Delta X_{\tau}^{i}+\frac{\lambda}{2}\sum_{j\not=i}\Delta X_{\tau}^{j}\bigg|\mathcal{F}_{\tau_n-}\right].
    \end{align*}
    We focus on the first and last expectation in this chain of equalities. Taking $m\uparrow \infty$ we get, by the dominated convergence theorem,
    \begin{align*}
    \mathbb{E}&\Bigg[\lambda\int_0^Te^{-\beta |\tau_n-t|}dX_t^{i}+\mathds{1}_{\{\tau_n<\tau\}}\lambda\int_0^{\tau_n} e^{-\beta (\tau_n-t)}\sum_{j\not=i}dX_t^{j}+\mathds{1}_{\{\tau_n=\tau\}}\lambda\int_0^{\tau-} e^{-\beta (\tau-t)}\sum_{j\not=i}dX_t^{j}\\
    &\quad \quad \quad  +\left( \vartheta_\tau \Delta X_{\tau}^{i}+\frac{\lambda}{2}\sum_{j\not=i}\Delta X_{\tau}^{j}\right)\mathds{1}_{\{\tau_n=\tau\}}\bigg|\mathcal{F}_{\tau_n-}\Bigg]\\
    &=\mathbb{E}\left[\lambda\int_0^Te^{-\beta |\tau-t|}dX_t^{i}+\lambda\int_0^{\tau-} e^{-\beta (\tau-t)}\sum_{j\not=i}dX_t^{j} + \vartheta_\tau \Delta X_{\tau}^{i}+\frac{\lambda}{2}\sum_{j\not=i}\Delta X_{\tau}^{j}\bigg|\mathcal{F}_{\tau_n-}\right].
    \end{align*}
    Here, we have used that $\lim_{m\to\infty}\Delta X^{i}_{\tau_{n,m}}=0$ on $\{\tau_n<\tau\}$ for all $i$  and $\Delta X^{i}_{\tau_{n,m}}=\Delta X^{i}_{\tau}$ on $\{\tau_n=\tau\}$ for all $i$. By definition of the announcing sequence we have $\{\tau_n=\tau\}=\{\tau=0\}$, so
    \begin{align*}
    \mathbb{E}&\Bigg[\lambda\int_0^Te^{-\beta |\tau_n-t|}dX_t^{i}+\mathds{1}_{\{\tau>0\}}\lambda\int_0^{\tau_n} e^{-\beta (\tau_n-t)}\sum_{j\not=i}dX_t^{j}+\left( \vartheta_0\Delta X_{0}^{i}+\frac{\lambda}{2}\sum_{j\not=i}\Delta X_{0}^{j}\right)\mathds{1}_{\{\tau=0\}}\bigg|\mathcal{F}_{\tau_n-}\Bigg]\\
    &=\mathbb{E}\left[\lambda\int_0^Te^{-\beta |\tau-t|}dX_t^{i}+\lambda\int_0^{\tau-} e^{-\beta (\tau-t)}\sum_{j\not=i}dX_t^{j} + \vartheta_\tau \Delta X_{\tau}^{i}+\frac{\lambda}{2}\sum_{j\not=i}\Delta X_{\tau}^{j}\bigg|\mathcal{F}_{\tau_n-}\right].
    \end{align*}
    Then, taking $n\uparrow \infty$ and applying the dominated convergence theorem for conditional expectations \cite[Theorem 4.6.10]{Durrett.19},
    \begin{align*}
    \mathbb{E}&\Bigg[\lambda\int_0^Te^{-\beta |\tau-t|}dX_t^{i}+\mathds{1}_{\{\tau>0\}}\lambda\int_0^{\tau-} e^{-\beta (\tau-t)}\sum_{j\not=i}dX_t^{j}+\left( \vartheta_0\Delta X_{0}^{i}+\frac{\lambda}{2}\sum_{j\not=i}\Delta X_{0}^{j}\right)\mathds{1}_{\{\tau=0\}}\bigg|\mathcal{F}_{\tau-}\Bigg]\\
    &=\mathbb{E}\left[\lambda\int_0^Te^{-\beta |\tau-t|}dX_t^{i}+\lambda\int_0^{\tau-} e^{-\beta (\tau-t)}\sum_{j\not=i}dX_t^{j} + \vartheta_\tau \Delta X_{\tau}^{i}+\frac{\lambda}{2}\sum_{j\not=i}\Delta X_{\tau}^{j}\bigg|\mathcal{F}_{\tau-}\right].
    \end{align*}
    Rearranging shows that
    \[\mathbb{E}\left[\left(\vartheta_\tau\Delta X_{\tau}^{i}+\frac{\lambda}{2}\sum_{j\not=i}\Delta X_{\tau}^{j}\right)\mathds{1}_{\{\tau>0\}}\bigg|\mathcal{F}_{\tau-}\right]=0.\]
    In view of the predictability of $\boldsymbol{X}$  we recover \eqref{eqn:eq.jumps.not.0}.
    % \[\boxed{\left(\vartheta (\tau)\Delta X_{\tau}^{i}+\frac{\lambda}{2}\sum_{j\not=i}\Delta X_{\tau}^{j}\right)\mathds{1}_{\{\tau>0\}}=0, \ \ \ i=1,\dots,N \ \ \ a.s.}\]

    On the other hand, we can once again choose a sequence of stopping times $\tau_n\downarrow \tau$ satisfying the conditions of Lemma \ref{lem:no.jump.delay.times} with the choice of $\sigma\equiv T$. Applying Lemma \ref{lem:gen.foc.jumps} we have
    \begin{align*}
    \mathbb{E}&\left[\lambda\int_0^Te^{-\beta |\tau_n-t|}dX_t^{i}+\lambda\int_0^{\tau_n-} e^{-\beta (\tau_n-t)}\sum_{j\not=i}dX_t^{j} +\left( \vartheta_T\Delta X_{T}^{i}+\frac{\lambda}{2}\sum_{j\not=i}\Delta X_{T}^{j}\right)\mathds{1}_{\{\tau=T\}}\bigg|\mathcal{F}_{\tau-}\right]\\
    &=\mathbb{E}\left[\lambda\int_0^Te^{-\beta |\tau-t|}dX_t^{i}+\lambda\int_0^{\tau-} e^{-\beta (\tau-t)}\sum_{j\not=i}dX_t^{j} + \vartheta_\tau \Delta X_{\tau}^{i}+\frac{\lambda}{2}\sum_{j\not=i}\Delta X_{\tau}^{j}\bigg|\mathcal{F}_{\tau-}\right].
    \end{align*}
    Passing to the limit, by the dominated convergence theorem,
    \begin{align*}
    \mathbb{E}&\Bigg[\lambda\int_0^Te^{-\beta |\tau-t|}dX_t^{i}+\mathds{1}_{\tau<T}\lambda\int_0^{\tau} e^{-\beta (\tau-t)}\sum_{j\not=i}dX_t^{j} \\
    &\quad \quad +\left( \lambda\int_0^{T-} e^{-\beta (T-t)}\sum_{j\not=i}dX_t^{j} +\vartheta_T\Delta X_{T}^{i}+\frac{\lambda}{2}\sum_{j\not=i}\Delta X_{T}^{j}\right)\mathds{1}_{\{\tau=T\}}\bigg|\mathcal{F}_{\tau-}\Bigg]\\
    &\quad \quad \quad =\mathbb{E}\left[\lambda\int_0^Te^{-\beta |\tau-t|}dX_t^{i}+\lambda\int_0^{\tau-} e^{-\beta (\tau-t)}\sum_{j\not=i}dX_t^{j} + \vartheta_\tau \Delta X_{\tau}^{i}+\frac{\lambda}{2}\sum_{j\not=i}\Delta X_{\tau}^{j}\bigg|\mathcal{F}_{\tau-}\right].
    \end{align*}
    Subtracting the left-hand side from the right we obtain
    \[\mathbb{E}\left[\left( \vartheta_\tau \Delta X_{\tau}^{i}-\frac{\lambda}{2}\sum_{j\not=i}\Delta X_{\tau}^{j}\right)\mathds{1}_{\{\tau<T\}}\bigg|\mathcal{F}_{\tau-}\right]=0.\]
    Using predictability once more yields the condition \eqref{eqn:eq.jumps.not.T}.
    % \[\boxed{\left( \vartheta (\tau)\Delta X_{\tau}^{i}-\frac{\lambda}{2}\sum_{j\not=i}\Delta X_{\tau}^{j}\right)\mathds{1}_{\{\tau<T\}}=0, \ \ \ i=1,\dots, N, \ \ \ a.s.}\]
\end{proof}

%Leveraging Lemma \ref{lem:main.step.for.no.interior.jumps}, the proof of Proposition \ref{prop:no.interior.jumps} is straightforward. As it turns out, our approach allows us to obtain the following stronger, but lengthier, result from which Proposition \ref{prop:no.interior.jumps} follows as an immediate consequence.

Proposition \ref{prop:no.interior.jumps} is a direct consequence of the following, more precise result.

\begin{proposition}\label{prop:admissible.jumps.extended}
    Fix an admissible strategy profile $\boldsymbol{X}$ and suppose $X^i$ is optimal for $J_B(\cdot,\boldsymbol{X}^{-i})$.
    \begin{enumerate}
    \item[(i)] The initial and terminal jumps of $X^i$ satisfy
    \[\vartheta_0\Delta X_{0}^{i}=\frac{\lambda}{2}\sum_{j\not=i}\Delta X_{0}^{j}, \ \ \ \vartheta_T\Delta X_{T}^{i}=-\frac{\lambda}{2}\sum_{j\not=i}\Delta X_{T}^{j}.\]
    \item[(ii)] If $\vartheta_t>0$ at $t\in(0,T)$ then $X^i$ has no interior jump at $t$,
    \[\Delta X_{t}^{i} = 0, \ \ \ a.s.\]
    \item[(iii)] If there exists $t\in[0,T]$ such that $\vartheta_t=0$ and $\mathbb{P}\left(\sum_{j\not=i}\Delta X_t^j \not=0\right)>0$, then no optimal strategy $X^i$ exists.
    \end{enumerate}
    If $\boldsymbol{X}$ is a Nash Equilibrium, then there are no interior jumps, irrespective of~$\vartheta$. Furthermore, if $\vartheta_0=0$ or $\vartheta_T=0$, then there are no jumps at $0$ or $T$ in equilibrium, respectively.
\end{proposition}

\begin{proof}
(i) Taking $\tau\equiv T$ in \eqref{eqn:eq.jumps.not.0} and $\tau\equiv0$ in \eqref{eqn:eq.jumps.not.T} gives the two equations in the proposition. (ii) Let $\vartheta_t>0$ for some $t\in(0,T)$. Then we can take $\tau\equiv t$ and sum across \eqref{eqn:eq.jumps.not.0} and \eqref{eqn:eq.jumps.not.T} to get
\[2\vartheta_t\Delta X_{t}^{*,i}=0, \ \ \ \text{a.s.},\]
which implies the result.
(iii) Fix $t$ such that $\vartheta_t=0$ and $\mathbb{P}\left(\sum_{j\not=i}\Delta X_t^j \not=0\right)>0$. By Lemma~\ref{lem:main.step.for.no.interior.jumps} if $X^{i}$ is admissible and optimal for $\boldsymbol{X}^{-i}$ then one (or both) of \eqref{eqn:eq.jumps.not.0} and \eqref{eqn:eq.jumps.not.T} hold at $t$. In this case these read
    \begin{equation}\label{eqn:eqns.when.theta.is.0} \frac{\lambda}{2}\sum_{j\not=i}\Delta X_{t}^{j}\mathds{1}_{\{t>0\}}=0 \ \ \ \mbox{a.s.} \ \ \ \text{and} \ \ \ -\frac{\lambda}{2}\sum_{j\not=i}\Delta X_{t}^{j}\mathds{1}_{\{t<T\}}=0 \ \ \ \mbox{a.s.}
    \end{equation}
    which, as $\lambda>0$, implies the contradiction that $\sum_{j\not=i}\Delta X_{t}^{j}=0$ a.s. 

To characterize the jumps in equilibrium we leverage the concurrent satisfaction of \eqref{eqn:eq.jumps.not.0} and \eqref{eqn:eq.jumps.not.T} for all $i$. If $\vartheta_t>0$ for $t\in(0,T)$, the absence of interior jumps at $t$ follows from~(ii). If $\vartheta_t=0$ for $t\in[0,T]$ (note the inclusion of $0$ and $T$) then in equilibrium we can sum over $i=1,\dots,N$ in either \eqref{eqn:eq.jumps.not.0} or \eqref{eqn:eq.jumps.not.T} to get
\[\frac{\lambda(N-1)}{2}\sum_{i=1}^N\Delta X_t^{*,i}=0.\]
Again, as $N\geq2$ and $\lambda>0$ this implies $\sum_{i=1}^N\Delta X_i^{*,i}=0$ which, when combined with \eqref{eqn:eq.jumps.not.0} or \eqref{eqn:eq.jumps.not.T} holding at $t$ for all $i$ (see \eqref{eqn:eqns.when.theta.is.0}), implies that $\Delta X_t^{*,i}=0$ for all $i$. This completes the proof. 
\end{proof}


