\subsection{Lemma \ref{lem:nash.eq.a.c.}}
      Let $\boldsymbol{X}^*=(X^{*,1},\dots,X^{*,N})$ be a Nash equilibrium in the class of deterministic strategies that are absolutely continuous on $(0,T)$. 
      By Lemma \ref{lem:nash.eq.det} it suffices to show that $\boldsymbol{X}^*$ is also a  Nash equilibrium in the class of deterministic strategies. Suppose for contradiction that $\boldsymbol{X}^*$ is not a Nash equilibrium in the class of deterministic strategies. Then, there exists a deterministic admissible strategy $Z=(Z_t)_{t\geq0}$ satisfying
     \[J_B(Z;\boldsymbol{X}^{*,-i})<J_B(X^{*,i},\boldsymbol{X}^{*,-i}). \]
     % As a right continuous function of bounded variation on $[0,T]$, it admits the Lebesgue decomposition
     % \[Z_t = x^{i}+Z^{A}_t + Z^{S}_t+Z^J_t, \ \ \ t\in[0,T],\]
     % in terms of some absolutely continuous $Z^A=(Z^{A}_t)_{t\in[0,T]}$, singular continuous $Z^S =( Z^{S}_t)_{t\in[0,T]}$ and pure jump function $Z^J = (Z_t^J)_{t\in[0,T]}$. 
     By definition of $C_B(
    \cdot)$ (see \eqref{eqn:CB}) it is safe to assume that $Z_T=0$. 

    We will approximate $Z$ by a sequence of admissible controls that are absolutely continuous on $(0,T)$.  For concreteness, we will use the Bernstein polynomials $\mathbb{B}_n(f)$ defined for functions $f$ on $[0,1]$ via the Bernstein operator $\mathbb{B}_n$, $n= 1, 2, \ldots$,
    \[
    \mathbb{B}_n(f)(t)=\sum_{k=0}^nf\left(\frac{k}{n}\right)\binom{n}{k}t^k(1-t)^{n-k}, \quad t\in[0,1].
    \]
    We extend the definition to functions on $[0,T]$ via the isomorphism $\iota(t) = t/T$ and abuse notation by still writing $\mathbb{B}_n(f)$ for this approximation. Define an auxiliary process $\tilde{Z}$ by $\tilde{Z}_t=Z_t$ for $t\in[0,T)$ and $\tilde{Z}_{T}=Z_{T-}$. We define our approximating sequence $(Z^n)_{n\geq1}$ by $Z^n_t:=\mathbb{B}_n(\tilde{Z})(t)$ on $[0,T)$ with $Z_{0-}^n=Z_{0-}=x^i$ and $Z_{T}^n=Z_{T}=0$.

    We collect here several critical properties of the approximating sequence.
    \begin{enumerate}
        \item[(a)] (Matching Endpoints) By definition of $\mathbb{B}_n$ and $Z^n$, there is no approximation error at the endpoints $\{0-,0,T-,T\}$.
        \item[(b)] (Smoothing)  Let $TV(\cdot;[a,b])$ denote the total variation of a function on $[a,b]$. The smoothing property (see \cite{lorentz1937theorie} or \cite[Proposition 4.16]{bustamante2017bernstein}) of $\mathbb{B}_n$ gives $TV(Z_n;[0,T))\leq TV(Z;[0,T))$. By additivity of the total variation on intervals and (a), we can extend this to include any jumps at $0$ and $T$. That is, $TV(Z_n;[0-,T])\leq TV(Z;[0-,T])$. 
        \item[(c)] (Uniformly Bounded) As $TV(Z^n;[0-,T])$ is uniformly bounded by (b) and $Z^n_{0-}=x^i$ for all $n$, we have that $\|Z^n\|_\infty$ and $\|Z^n-Z\|_\infty$ are uniformly bounded.
        \item[(d)] (Consistency) Since $Z$ is c\`adl\`ag, it only has discontinuities of the first kind. As a result (see, e.g., %\cite{bustamante2014bernstein,chlodovsky1929representation,herzog1946bernstein}) 
        \cite[Section~4.5.1]{bustamante2017bernstein})
        \[Z^n_t\to \frac{Z_{t-}+Z_{t+}}{2}, \ \ \ \forall t\in(0,T).\]
        Since the discontinuities of $Z$ are at most countable, $Z^n$ converges to $Z$ almost everywhere. Moreover, by (c) and the dominated convergence theorem, $Z^n\to Z$ in~$L^1$.
    \end{enumerate}
    In view of (a), it is clear that $Z^n$ is an admissible deterministic strategy. Moreover, by the definition of $\mathbb{B}_n$ it is absolutely continuous on $(0,T)$. The objective representation in \eqref{eqn:obj.schied.rep} tells us that for $Z$,
    \begin{align*}J_B(Z;\boldsymbol{X}^{*,-i})&=\lambda\Bigg(\frac{1}{2}\int_0^T\int_0^T e^{-\beta |t-s|} dZ_s dZ_t + \int_0^T\int_0^{t-} e^{-\beta (t-s)} \sum_{j\not=i}dX_s^{*,j} dZ_t\\
    &\quad \quad \quad \quad + \frac{1}{2}\sum_{j\not=i}\sum_{t\in\{0,T\}} \Delta X_t^{*,j}\Delta Z_t \Bigg )+\frac{1}{2}\sum_{t\in[0,T]} \vartheta_t(\Delta Z_t)^2.
    \end{align*}
    Note that we have enforced in \eqref{eqn:obj.schied.rep} the assumption that $\Delta X_t^{*,j}=0$ for all $t\in(0,T)$ when $i\not=j$. For $Z^n$ we have
    \begin{align*}J_B(Z^n;\boldsymbol{X}^{*,-i})&=\lambda\Bigg(\frac{1}{2}\int_0^T\int_0^T e^{-\beta |t-s|} dZ^n_s dZ^n_t + \int_0^T\int_0^{t-} e^{-\beta (t-s)} \sum_{j\not=i}dX_s^{*,j} dZ^n_t\\
    &\quad \quad \quad \quad + \frac{1}{2}\sum_{j\not=i}\sum_{t\in\{0,T\}} \Delta X_t^{*,j}\Delta Z^n_t \Bigg )+\frac{1}{2}\sum_{t\in\{0,T\}} \vartheta_t(\Delta Z^n_t)^2\\
    &=\lambda\Bigg(\frac{1}{2}\int_0^T\int_0^T e^{-\beta |t-s|} dZ^n_s dZ^n_t + \int_0^T\int_0^{t-} e^{-\beta (t-s)} \sum_{j\not=i}dX_s^{*,j} dZ^n_t\\
    &\quad \quad \quad \quad + \frac{1}{2}\sum_{j\not=i}\sum_{t\in\{0,T\}} \Delta X_t^{*,j}\Delta Z_t \Bigg )+\frac{1}{2}\sum_{t\in\{0,T\}} \vartheta_t(\Delta Z_t)^2.
    \end{align*}
    In the second equality we have used (a) to identify the jumps at the endpoints with those of~$Z$.

    Next, we claim that
    \begin{align}
    \lim_{n\to\infty}&\left(J_B(Z^n;\boldsymbol{X}^{*,-i})-J_B(Z;\boldsymbol{X}^{*,-i})\right)\label{eqn:limit.obj.approx.seq}\\
    &=\lim_{n\to\infty}\Bigg[\lambda\bigg(\frac{1}{2}\int_0^T\int_0^T e^{-\beta |t-s|} dZ^n_s dZ^n_t -\frac{1}{2}\int_0^T\int_0^T e^{-\beta |t-s|} dZ_s dZ_t\nonumber\\
    &\quad + \int_0^T\int_0^{t-} e^{-\beta (t-s)} \sum_{j\not=i}dX_s^{*,j} dZ^n_t-\int_0^T\int_0^{t-} e^{-\beta (t-s)} \sum_{j\not=i}dX_s^{*,j} dZ_t\bigg)-\frac{1}{2}\sum_{t\in (0,T)} \vartheta_t(\Delta Z_t)^2\Bigg]\nonumber \\
    &=-\frac{1}{2}\sum_{t\in (0,T)} \vartheta_t(\Delta Z_t)^2\leq 0.\nonumber
    \end{align}
    We will prove this by treating each of the integrals in turn. Using Lebesgue--Stieltjes integration by parts and (a),
    \begin{align}
        \int_0^T e^{-\beta|t-s|}dZ^n_s &= e^{-\beta(T-t)} Z_T^n-e^{-\beta t}Z^n_{0-}-\beta \int_0^T \mathrm{sign}(t-s)Z_s^ne^{-\beta|t-s|}ds\nonumber\\
        &=-e^{-\beta t}x^i-\beta \int_0^T \mathrm{sign}(t-s)Z_s^ne^{-\beta|t-s|}ds, \ \ \ t\in[0,T]. \label{eqn:IBP.H}
    \end{align}
    Repeating this for $\int_0^T e^{-\beta|t-s|}dZ_s$ gives, using (d), that
    \begin{align}
        \left|\int_0^T e^{-\beta|t-s|}dZ^n_s-\int_0^T e^{-\beta|t-s|}dZ_s\right| &\leq \beta \int_0^T|Z_s^n-Z_s|e^{-\beta|t-s|}ds\leq \beta \|Z^n-Z\|_{L^1}\to 0. \label{eqn:unif.est.conv.H}
    \end{align}
    To keep notation compact define $H^n_t:=\int_0^T e^{-\beta|t-s|}dZ^n_s$ and $H_t:=\int_0^T e^{-\beta|t-s|}dZ_s$. By \eqref{eqn:IBP.H} and dominated convergence, it is clear that $H^n$ (and $H$) are continuous in $t$. Moreover, the uniform estimate in \eqref{eqn:unif.est.conv.H} shows that $\|H^n-H\|_\infty \to 0$. As a result, by applying (b),
    \begin{align*}
        \left|\int_0^T H^n_tdZ^n_t-\int_0^TH_tdZ^n_t\right|&\leq \|H^n-H\|_\infty TV(Z^n;[0-,T])\leq \|H^n-H\|_\infty TV(Z;[0-,T])\to 0.
    \end{align*}
    At the same time, by Fubini's theorem and the symmetry $|t-s|=|s-t|$,
    \begin{align*}
        \left|\int_0^T H_t dZ^n_t-\int_0^T H_t dZ_t \right|&= \left|\int_0^T \int_0^T e^{-\beta|t-s|} dZ_s dZ^n_t-\int_0^T H_t dZ_t\right|\\
        &=\left|\int_0^T \int_0^T e^{-\beta|t-s|} dZ^n_t dZ_s-\int_0^T H_t dZ_t\right|\\
        &=\left|\int_0^T H^n_s dZ_s-\int_0^T H_t dZ_t\right|\\
        &\leq \|H^n-H\|_\infty TV(Z;[0-,T])\to 0.
    \end{align*}
    Taken together,
    \begin{align}
        &\left|\int_0^T\int_0^T e^{-\beta |t-s|} dZ^n_s dZ^n_t -\int_0^T\int_0^T e^{-\beta |t-s|} dZ_s dZ_t\right|\label{eqn:first.est.obj.approx}\\
        &\quad \quad \quad \quad \quad \quad \quad \quad \quad \quad \quad \quad=\left|\int_0^TH^n_tdZ^n_t-\int_0^TH_tdZ_t\right|\nonumber\\
        &\quad \quad \quad \quad \quad \quad \quad \quad \quad \quad \quad \quad \leq \left|\int_0^TH^n_t dZ^n_t-\int_0^T H_t dZ^n_t\right|+\left|\int_0^TH_t dZ_t^n-\int_0^T H_t dZ_t\right|\to 0.\nonumber
    \end{align}
    We turn to the final set of integrals in \eqref{eqn:limit.obj.approx.seq}. Define the function $I^{-i}$ by
    \[I^{-i}_t:= \int_0^te^{-\beta(t-s)}\sum_{j\not=i}dX^{*,j}, \ \ \ t\in[0,T],\]
    with $I_{0-}^{-i}=I_{0}^{-i}=0$. Notice that this does not depend on $Z^n$ or $Z$, and by our assumption on $\boldsymbol{X}^*$, $I^{-i}$ is absolutely continuous.
    By integration by parts (using $Z^n_T=0$ and $I^{-i}_{0-}=0$),
    \begin{align*}
        \int_0^T\int_0^{t-} e^{-\beta (t-s)} \sum_{j\not=i}dX_s^{*,j} dZ^n_t&=\int_0^TI^{-i}_{t-} dZ^n_t= -\int_0^T Z_{t-}^n dI_t^{-i}.
    \end{align*}
    Repeating this for $Z$, it follows that
    \begin{align}
        &\left|\int_0^T\int_0^{t-} e^{-\beta (t-s)} \sum_{j\not=i}dX_s^{*,j} dZ^n_t-\int_0^T\int_0^{t-} e^{-\beta (t-s)} \sum_{j\not=i}dX_s^{*,j} dZ_t\right|\label{eqn:second.est.obj.approx}\\
        &\quad \quad \quad \quad \quad \quad \quad \quad \quad \quad \quad \quad \quad \quad = \left|\int_0^T Z_{t-}^n -Z_{t-}dI_t^{-i}\right|\leq \int_0^T\left| Z_{t-}^n -Z_{t-}\right||dI_t^{-i}|,\nonumber
    \end{align}
    where $|dI_t^{-i}|$ denotes the total variation measure associated with $I^{-i}$. As, by assumption, $I^{-i}$ is absolutely continuous with finite variation, $|dI_t^{-i}|$ defines a finite positive measure that is absolutely continuous with respect to the Lebesgue measure. Then, since $\|Z^n-Z\|_\infty$ is bounded by (c) and $Z^n\to Z$ Lebesgue-a.e.\ (and hence, also $|dI^{-i}|$-a.e.),
\begin{equation}\label{eqn:third.est.obj.approx} \int_0^T\left| Z_{t-}^n -Z_{t-}\right||dI_t^{-i}|\to 0
    \end{equation}
    by dominated convergence.
    Combining \eqref{eqn:first.est.obj.approx},  \eqref{eqn:second.est.obj.approx}, and \eqref{eqn:third.est.obj.approx} proves \eqref{eqn:limit.obj.approx.seq}.

    We conclude
    \[\lim_{n\to\infty}J_B(Z^n;\boldsymbol{X}^{*,-i})\leq J_B(Z;\boldsymbol{X}^{*,-i})<J_B(X^{*,i};\boldsymbol{X}^{*,-i}).\]
    But then
     $J_B(Z^{n};\boldsymbol{X}^{*,-i})<J_B(X^{*,i};\boldsymbol{X}^{*,-i})$
     for $n$ sufficiently large, contradicting the optimality of $X^{*,i}$ in the class of strategies that are absolutely continuous on $(0,T)$. \qed

\subsection{Lemma \ref{lem:block.cost.ODE}}

To derive the characterization in Lemma \ref{lem:block.cost.ODE} we will make use of the fact that $\mathbb{R}\times L^2[0,T]$ is a Hilbert space when equipped with the inner product
\[\langle (a,v), (a',v') \rangle = a a' + \langle v,v'\rangle_{L^2[0,T]}.\]
As in the proof of Lemma \ref{lem:term.pen.ODE}, we will take the Gateaux differential of $\mathcal{J}_{B}$, but this time in an arbitrary direction $(h,\eta)\in \mathbb{R}\times L^2[0,T]$. We begin by taking the Gateaux differential of the objective $\mathcal{J}_B(\cdot,\cdot;\boldsymbol{v}^{-i})$ in the direction $(0,\eta)$ in steps. Observe
\begin{equation*}
\delta_{(0,\eta)} b^{i}=-\int_0^T\eta_tdt, \ \ \ \text{and} \ \ \ 
    \delta_{(0,\eta)} \left(\frac{\theta_a}{2}(a^{i})^2+\frac{\theta_b}{2}(b^{i})^2\right)=\theta_b b^{i}\delta_{(0,\eta)} b^{i}=-\int_0^T\theta_b b^{i}\eta_tdt.
\end{equation*}
Similarly,
\begin{equation*}
    \delta_{(0,\eta)} I_t=\int_0^t e^{-\beta(t-s)}\lambda\eta_sds, \ \ \  t\in[0,T)
\end{equation*}
and
\begin{align*}
    \delta_{(0,\eta)}\left[\frac{1}{2}(I_{T-}+I_T)b^{i}\right]&=\delta_{(0,\eta)}\left[I_{T-}b^{i}+\frac{\lambda}{2}\left(\sum_{j=1}^Nb^{j}\right)b^{i}\right]\\
    % &=\delta_\eta I_{T-}b^{(i)}+I_{T-}\delta_\eta b^{(i)}+\lambda b^{(i)}\delta_\eta b^{(i)}+\frac{\lambda}{2}\left(\sum_{j\not=i}b^{(j)}\right)\delta_\eta b^{(i)}\\
    &=\delta_{(0,\eta)} I_{T-}b^{i}+I_{T}\delta_{(0,\eta)} b^{i}-\frac{\lambda}{2} \left(\sum_{j\not=i}b^{(j)}\right)\delta_{(0,\eta)} b^{i}.
\end{align*}
Working now directly with $\mathcal{J}_B$ we get
\begin{align*}
    \delta_{(0,\eta)} \cJ(a^{i},v^{i};\boldsymbol{v}^{-i})
    &=\int_0^T[\delta_{(0,\eta)} I_tv_t^{i}+\eta_tI_t]dt+\delta_{(0,\eta)} I_{T-}b^{i}+I_{T}\delta_{(0,\eta)} b^{i} \\
    &\quad \quad -\frac{\lambda}{2} \left(\sum_{j\not=i}b^{j}\right)\delta_{(0,\eta)} b^{i}-\int_0^T\theta_b b^{i}\eta_tdt\\
    &=\int_0^T[\delta_{(0,\eta)} I_tv_t^{i}+\eta_tI_t]dt+b^{i}\int_0^T e^{-\beta(T-t)}\lambda\eta_tdt-\int_0^TI_{T}\eta_tdt\\
    &\quad \quad +\int_0^T\frac{\lambda}{2} \left(\sum_{j\not=i}b^{j}\right)\eta_tdt-\int_0^T\theta_b b^{i}\eta_tdt\\
    &=\int_0^T\delta_{(0,\eta)} I_tv_t^{i}dt+\int_0^T\left[I_t-I_{T}+\lambda b^{i} e^{-\beta(T-t)}+\frac{\lambda}{2}\left(\sum_{j\not=i}b^{j}\right)-\theta_b b^{i}\right]\eta_tdt.
\end{align*}
By changing the order of integration, the first term can be written
\begin{align*}
    \int_0^T\delta_{(0,\eta)} I_tv_t^{i}dt&=\int_0^T\int_0^t\lambda e^{-\beta(t-s)}v_t^{i}\eta_sdsdt=\int_0^T\int_s^T\lambda e^{-\beta(t-s)}v_t^{i}\eta_sdtds.
\end{align*}
If we let
\begin{equation*}
    Y_t^{i}:=\lambda b^{i} e^{-\beta(T-t)}+\int_t^T\lambda e^{-\beta (s-t)}v_s^{i} ds, \ \ \ t\in [0,T],
\end{equation*}
then the Gateaux differential can be written
\begin{equation}\label{eqn:dJ.eta.block}
    \delta_{(0,\eta)} \cJ(a^{i},v^{i};\boldsymbol{v}^{-i})=\int_0^T\left[Y^{i}_t+I_t-I_{T}+\frac{\lambda}{2}\left(\sum_{j\not=i}b^{j}\right)-\theta_b b^{i}\right]\eta_tdt.
\end{equation}


Next, we take the Gateaux differential in the direction $(1,0)\in\mathbb{R}\times L^2[0,T]$. Note that 
\begin{equation*}
    \delta_{(1,0)} I_t=\lambda e^{-\beta t}, \ \ t\in[0,T),
\end{equation*}
\begin{equation*}
    \delta_{(1,0)} \left(\frac{\theta_a}{2}(a^{i})^2+\frac{\theta_b}{2}(b^{i})^2\right)=\theta_a a^{i}+\theta_b b^{i} \delta_{(1,0)} b^{i}=\theta_aa^{i}-\theta_b b^{i},
\end{equation*}
and
\begin{align*}\delta_{(1,0)}\left[\frac{1}{2}I_0a^{i}\right]&=\frac{1}{2}\left[\delta_{(1,0)} I_0 a^{i}+\lambda \left(a^{i}+\sum_{j\not=i}a^{j}\right)\right]=\lambda a^{i}+\frac{\lambda}{2}\sum_{j\not=i}a^{j}.
\end{align*}
Moreover,
\begin{align*}
    \delta_{(1,0)}\left[\frac{1}{2}\left(I_{T-}+I_T\right)b^{i}\right]&=\delta_{(1,0)}\left[I_{T-}b^{i}+\frac{\lambda}{2}\left(b^{i}+\sum_{i\not=j}b^{j}\right)b^{i}\right]\\
    &=\delta_{(1,0)}I_{T-}b^{i}+I_{T-}\delta_{(1,0)} b^{i}+\lambda b^{i}\delta_{(1,0)} b^{i}+\frac{\lambda}{2}\left(\sum_{i\not=j}b^{j}\right)\delta_{(1,0)} b^{i}\\
    &=\delta_{(1,0)} I_{T-}b^{i}-I_{T-}-\lambda b^{i}-\frac{\lambda}{2}\left(\sum_{i\not=j}b^{j}\right)\\
    &=\delta_{(1,0)} I_{T-}b^{i}-I_T+\frac{\lambda}{2}\left(\sum_{i\not=j}b^{j}\right).
\end{align*}
Putting all this together we find
\begin{align*}
\delta_{(1,0)} & \cJ(a^i,v^i;\boldsymbol{v}^{-i}) \\
&=  \lambda a^{i}+\frac{\lambda}{2}\sum_{j\not=i}a^{j}+ \int_0^T\delta_{(1,0)} I_t v_t^{i} dt+\delta_{(1,0)}I_{T-}b^{i} -I_T+\frac{\lambda}{2}\left(\sum_{i\not=j}b^{j}\right)+\theta_a a^{i}-\theta_b b^{i}\\
    &=\lambda a^{i}+\frac{\lambda}{2}\sum_{j\not=i}a^{j}+ \int_0^T\lambda v_t^{i} e^{-\beta t}dt +\lambda e^{-\beta T}b^{i} -I_{T}+\frac{\lambda}{2}\left(\sum_{i\not=j}b^{j}\right)+\theta_a a^{i}-\theta_b b^{i}.
\end{align*}
Rewriting the last equality yields
\begin{equation}\label{eqn:dJ.a.block}
\delta_{(1,0)}\cJ(a^i,v^i;\boldsymbol{v}^{-i})= I_0-I_{T} + Y_0+\theta_a a^{i}-\frac{\lambda}{2}\sum_{j\not=i}a^{j}+\frac{\lambda}{2}\sum_{i\not=j}b^{j}-\theta_b b^{i}.
\end{equation}
Combining \eqref{eqn:dJ.eta.block} and \eqref{eqn:dJ.a.block} we get the Gateaux differential in an arbitrary direction $(h,\eta)$,
\begin{align*}
    \delta_{(h,\eta)}\cJ(a^i,v^i;\boldsymbol{v}^{-i}) &= \left(I_0-I_{T} + Y_0+\theta_a a^{i}-\frac{\lambda}{2}\sum_{j\not=i}a^{j}+\frac{\lambda}{2}\sum_{i\not=j}b^{j}-\theta_b b^{i}\right) h\\
    & \quad \quad + \int_0^T\left[Y^{i}_t+I_t-I_{T}+\frac{\lambda}{2}\left(\sum_{j\not=i}b^{j}\right)-\theta_b b^{i}\right]\eta_tdt.
\end{align*}
Reasoning as in Lemma \ref{lem:term.pen.ODE} (see also Appendix \ref{app:opt.theory}) we have that the necessary and sufficient first-order conditions for optimality are
\begin{equation}\label{eqn:foc.block.tax.eta}    \boxed{I_{T}=Y^{i}_t+I_t+\frac{\lambda}{2}\left(\sum_{j\not=i}b^{j}\right)-\theta_b b^{i}, \ \ \ t\in[0,T)}
\end{equation}
and
\begin{equation}\label{eqn:foc.block.tax.a}    \boxed{I_T=Y_{0}^{i}+I_0+\frac{\lambda}{2}\left(\sum_{j\not=i}b^{j}\right)-\theta_b b^{i}+\theta_a a^{i}-\frac{\lambda}{2}\left(\sum_{j\not=i}a^{j}\right).}
\end{equation}

By symmetry, an equilibrium is achieved if and only if these first-order conditions hold simultaneously for all $i=1,\dots,N$. Differentiating \eqref{eqn:foc.block.tax.eta} (note that $I$ and $Y$ are differentiable almost everywhere by definition) leads to the equilibrium system of ODEs,
\begin{align*}
    0&=\dot{Y}^{i}_t+\dot{I}_t, \ \ \ i=1,\dots,N,\\
    \dot{Y}^{i}_t&=\beta Y^{i}_t-\lambda v^{i}_t, \ \ \ i=1,\dots,N,\\
    \dot{I}_t&=-\beta I_t+\lambda\sum_{i=1}^Nv_t^{i}.
\end{align*}
Writing this in terms of $X_t^{i}$, for almost every $t\in(0,T)$,
\begin{align*}
    0&=\dot{Y}^{i}_t+\dot{I}_t, \ \ \ i=1,\dots,N,\\
    \dot{Y}^{i}_t&=\beta Y^{i}_t-\lambda \dot{X}_t^{i}, \ \ \ i=1,\dots,N,\\
    \dot{I}_t&=-\beta I_t+\lambda\sum_{i=1}^N\dot{X}_t^{i},
\end{align*}
subject to the initial and terminal conditions
\begin{align*}
    I_0&=\lambda\sum_{i=1}^Na^{i}, \ \ \ 
    X_0^{i}=x^{i}+a^{i}, \ \ \ 
    Y_T^{i}=\lambda b^{i}, \ \ \ i=1,\dots,N.
\end{align*}
By rearranging the system we can write it in the standard form reported in Lemma \ref{lem:block.cost.ODE}. Moreover, from that representation we see that any solution to this system must have derivatives that are equal almost everywhere to continuous functions. Thus, without loss of generality, we identify the derivatives of the equilibrium $I$, $Y^i$ and $X^i$ (if an equilibrium exists) with their continuous versions and interpret the ODE in the classical sense.


We now turn to the additional consistency conditions that the initial and terminal block trades must satisfy. Specifically, letting $t\downarrow 0 $ in \eqref{eqn:foc.block.tax.eta} and comparing with \eqref{eqn:foc.block.tax.a} we find that the optimal $a$ must satisfy
\begin{equation}\label{eqn:a.cond}\boxed{\theta_a a^{i} =\frac{\lambda}{2}\sum_{j\not=i}a^{j}.}
\end{equation}
% By symmetry in equilibrium we have the condition
% \begin{equation}\label{eqn:a.cond}\boxed{\theta_a a^{(i)} =\frac{\lambda}{2}\sum_{j\not=i}a^{(j)}, \ \ \ i=1,\dots,N.}
% \end{equation}
Sending $t\uparrow T$ in \eqref{eqn:foc.block.tax.eta} we get
\begin{equation*}
    I_{T}=\lambda b^{i}+I_{T-}+\frac{\lambda}{2}\left(\sum_{j\not=i}b^{j}\right)-\theta_b b^{i}.
\end{equation*}
By rearranging,
\[\lambda\sum_{j=1}^Nb^{j}=\lambda b^{i}+\frac{\lambda}{2}\left(\sum_{j\not=i}b^{j}\right)-\theta_b b^{i},\]
which yields
\begin{equation}\label{eqn:b.cond.1}
\boxed{\theta_b b^{i}=-\frac{\lambda}{2}\sum_{j\not=i}b^{j}.}
\end{equation}
Moreover, since we require liquidation by $T$,
\begin{equation}\label{eqn:b.cond.2}
    \boxed{b^{i}=-X^{i}_{T-}, \ \ \ i=1,\dots,N.}
\end{equation}
Again, by symmetry in equilibrium, we arrive at the conditions reported in the lemma. Note that \eqref{eqn:a.cond} and \eqref{eqn:b.cond.1} are exactly the conditions of Proposition \ref{prop:no.interior.jumps}. In summary, these ODEs and consistency conditions necessarily hold in equilibrium.

% Again by symmetry:
% \begin{equation}\label{eqn:b.cond.1}
% \boxed{\theta_b b^{(i)}=-\frac{\lambda}{2}\sum_{j\not=i}b^{(j)}, \ \ \ i=1,\dots,N.}
% \end{equation}
% Moreover, we will require that:
% \begin{equation}\label{eqn:b.cond.2}
%     \boxed{b^{(i)}=-X^{(i)}_{T-}, \ \ \ i=1,\dots,N.}
% \end{equation}
For sufficiency we use that an equilibrium is attained if and only if \eqref{eqn:foc.block.tax.eta} and \eqref{eqn:foc.block.tax.a}  hold. Enforcing \eqref{eqn:a.cond}, \eqref{eqn:b.cond.1} and \eqref{eqn:b.cond.2} we have that \eqref{eqn:foc.block.tax.eta} and \eqref{eqn:foc.block.tax.a} reduce (after some manipulation) to
\[I_{T-}-I_t=-(Y^{i}_T-Y^{i}_t) \ \ \ \text{and} \ \ \ I_{T-}-I_0=-(Y^{i}_T-Y^{i}_{0}).\]
This must be satisfied if the ODE holds for $I$ on $[0,T)$ and $Y$ on $[0,T]$ since
\[I_{T-}-I_t=\int_t^T\dot{I_t}dt \ \ \ \text{and} \ \ \ -(Y^{i}_T-Y^{i}_t)=-\int_t^T\dot{Y_t}dt.\]
The right-hand side of both these equations must coincide by the ODE for all $t\in[0,T)$.
Thus, to obtain an equilibrium for the game it is sufficient to solve the ODE for fixed boundary conditions and enforce the consistency equations \eqref{eqn:a.cond},  \eqref{eqn:b.cond.1}, and \eqref{eqn:b.cond.2} for the boundaries. \qed

\subsection{Theorem \ref{thm:equil.block.cost}}

We will prove Theorem \ref{thm:equil.block.cost} in stages. First we will fix the boundary conditions and solve the ODE from Lemma \ref{lem:block.cost.ODE}. Then, we will use the consistency conditions to show conclusions (1)--(3) for a deterministic equilibrium and derive the form of the equilibrium (when it exists). Finally, we will show that when a deterministic equilibrium does not exist, neither does an equilibrium in the full class of admissible strategies.

\subsubsection*{Step 1: Solving the ODE for fixed boundary conditions.}
Defining the vector $\boldsymbol{F}=(I,Y^{1},\dots,Y^{N},X^{1},\dots,X^{N})$, we can write the ODE  from Lemma~\ref{lem:block.cost.ODE} in the matrix form
\[\dot{\boldsymbol{F}}_t=A \boldsymbol{F}_t\]
where
\[A=\frac{\beta}{N-1}\begin{bmatrix}
1 & -1 & -1 &  \dots & -1 & -1 & 0 & \dots & 0 \\
-1 & 1 & 1 & \dots & 1 & 1 & 0 & \dots & 0 \\
\vdots & \vdots & \vdots & \vdots & \vdots & \vdots & \vdots & \vdots & \vdots \\
-1 & 1 & 1 & \dots & 1 & 1 & 0 & \dots & 0 \\
\lambda^{-1} & (N-2)\lambda^{-1} & -\lambda^{-1} & \dots & -\lambda^{-1} & -\lambda^{-1} & 0 & \dots & 0 \\
 \lambda^{-1} &  -\lambda^{-1}  & (N-2)\lambda^{-1} & \dots & -\lambda^{-1} & -\lambda^{-1} & 0 & \dots & 0 \\
\vdots &  \vdots  & \vdots & \ddots & \vdots & \vdots  & \vdots & \vdots \\
\lambda^{-1} &  -\lambda^{-1}  &  -\lambda^{-1}  & \dots & (N-2)\lambda^{-1} & -\lambda^{-1} & 0 & \dots & 0 \\
\lambda^{-1} &  -\lambda^{-1}  &  -\lambda^{-1}  & \dots & -\lambda^{-1} & (N-2)\lambda^{-1} & 0 & \dots & 0 \\
\end{bmatrix}.\]
The only non-zero eigenvalue of this matrix is $\mathbbm{z}_1=\frac{N+1}{N-1}\beta$. The associated eigenvector is
\[\boldsymbol{q}_1=\begin{bmatrix}
    \frac{N+1}{2}\lambda \\
    -\frac{N+1}{2}\lambda \\
    \vdots\\
     -\frac{N+1}{2}\lambda \\
    1\\
    \vdots\\
    1
\end{bmatrix}.\]
The remaining (non-zero) eigenvectors are $\boldsymbol{q}_{1+j}=\boldsymbol{e}_{N+1+j}$ for $j=1,\dots,N$ where $\boldsymbol{e}_i$ is the $i$th Euclidean basis vector. This is the exhaustive set of linearly independent eigenvectors corresponding to the eigenvalue $0$ since the dimension of the solution to the eigenvector equation
\[A\boldsymbol{q}=0 \boldsymbol{q}=0\]
is exactly the dimension of the nullspace of $A$. We can see that $A$ is of rank $N+1$ (as the first $N+1$ columns are linearly independent) and thus, by the rank--nullity theorem the nullspace has dimension $N$.

In order to completely characterize the solution to the ODE we must find $N$ additional generalized eigenvectors corresponding to the eigenvalue $0$. These generalized eigenvectors $(\boldsymbol{q}_{N+1+j})_{j=1}^N$ solve
\[A\boldsymbol{q}_{N+1+j}=\boldsymbol{q}_{1+j}, \ \ \ j=1,\dots,N\]
and must be linearly independent of $\boldsymbol{q}_{j}$, $j=1,\dots,N+1$. It is easy to verify that we can take $\boldsymbol{q}_{N+1+j}=\frac{\lambda}{\beta}[\boldsymbol{e}_1+\boldsymbol{e}_{j}]$ for $j=1,\dots,N$.
Therefore, the general solution to the matrix ODE is given by
\[\boldsymbol{F}_t=c_1\boldsymbol{q}_{1}e^{\mathbbm{z}_1t}+\sum_{j=1}^{N}(c_{1+j}\boldsymbol{q}_{1+j}+c_{N+1+j}  (t\boldsymbol{q}_{1+j}+\boldsymbol{q}_{N+1+j})).\]

We now solve for the constants $\boldsymbol{c}:=(c_1,\dots, c_{2N+1})^\top$ by enforcing the boundary conditions.
Reading off of the equation for $\boldsymbol{F}$ we get
\begin{align*}
    I_0 & = c_1 \frac{N+1}{2}\lambda + \frac{\lambda}{\beta}\sum_{i=1}^N c_{N+1+i} = \lambda \sum_{i=1}^N a^{i}, \\
    Y_T^{i} & = -c_1 \frac{N+1}{2}\lambda e^{\mathbbm{z}_1 T}+ \frac{\lambda}{\beta}c_{N+1+i}=\lambda b^{i}, \ \ \ i=1,\dots, N,\\
    X_0^{i}&=c_1+c_{1+i}=x^{i}+a^{i}, \ \ \ i=1,\dots,N.
\end{align*}
Summing the second set of equations over $i$ we find
\[-c_1 \frac{N(N+1)}{2}\lambda e^{\mathbbm{z}_1 T}+\frac{\lambda}{\beta}\sum_{i=1}^N c_{N+1+i}=\lambda \sum_{i=1}^N b^{i}.\]
Subtracting this from the first equation,
\[c_1 \frac{N+1}{2}\lambda+c_1 \frac{N(N+1)}{2}\lambda e^{\mathbbm{z}_1 T}=\lambda \sum_{i=1}^N (a^{i}-b^{i}).\]
Solving for $c_1$ yields
\[c_1 = \frac{2\sum_{i=1}^N (a^{i}-b^{i})}{(N+1) (1+Ne^{\mathbbm{z}_1 T})}.\]
Substituting this back into the initial equations we find
\[c_{1+i} = x^{i}+a^{i}-\frac{2\sum_{j=1}^N (a^{j}-b^{j})}{(N+1) (1+Ne^{\mathbbm{z}_1 T})}, \ \ \ i=1,\dots,N \]
and
\[c_{N+1+i} = \beta b^{i}+\beta e^{\mathbbm{z}_1 T}\frac{\sum_{j=1}^N (a^{j}-b^{j})}{(1+Ne^{\mathbbm{z}_1 T})}, \ \ \ i=1,\dots,N.\]
These define the solution to the ODE uniquely for fixed $x^i,a^i$ and $b^i$, $i=1,\dots,N$.

\subsubsection*{Step 2: Solving for the deterministic equilibrium.}

We now study the conditions that $\boldsymbol{a} = (a^1,\dots,a^N)^\top$ and $\boldsymbol{b}=(b^1,\dots,b^N)^\top$ need to satisfy. Our first result characterizes the solution to the system of equations for $\boldsymbol{a}$ and $\boldsymbol{b}$. 

\begin{lemma}\label{lem:bdy.sys.of.eqns}\mbox{}

\begin{enumerate}
    \item If $\boldsymbol{a}$ satisfies
\[\theta_a a^{i}=\frac{\lambda}{2}\sum_{j\not=i}a^{j}, \ \ \ i=1,\dots,N\]
then $a^i = a^j$ for all $i,j=1,\dots,N$. If, in addition, $\theta_a \not=\frac{\lambda (N-1)}{2}$ then $\boldsymbol{a}=\boldsymbol{0}$.
    \item If $\boldsymbol{b}$ satisfies
\[\theta_b b^{i}=-\frac{\lambda}{2}\sum_{j\not=i}b^{j}, \ \ \ i=1,\dots,N\]
then $\sum_{i=1}^N b^i =0$. If, in addition, $\theta_b \not=\frac{\lambda}{2}$ then $\boldsymbol{b}=\boldsymbol{0}$.
\end{enumerate}
\end{lemma}

\begin{proof}
    Let $\boldsymbol{1}=(1,\dots,1)^\top$ be the vector of ones and $\mathrm{Id}$ be the identity matrix.  The system of equations for $\boldsymbol{a}$ can be written as $M\boldsymbol{a}=\boldsymbol{0}$ where $M=(\theta_a+\frac{\lambda}{2}) \mathrm{Id}-\frac{\lambda}{2}\boldsymbol{1}\boldsymbol{1}^\top$. 
    Similarly, the system of equations for $\boldsymbol{b}$ can be written as $\tilde{M}\boldsymbol{b}=\boldsymbol{0}$
    where $\tilde{M}=(\theta_b-\frac{\lambda}{2}) \mathrm{Id}+\frac{\lambda}{2}\boldsymbol{1}\boldsymbol{1}^\top$. 


If $M$ is invertible then we must have $\boldsymbol{a}=\boldsymbol{0}$.  Similarly, if $\tilde{M}$ is invertible, then $\boldsymbol{b}=\boldsymbol{0}$. By the Matrix Determinant Lemma,
    \[\mathrm{det}(M)=\left(\theta_a+\frac{\lambda}{2}\right)^N-N\frac{\lambda}{2}\left(\theta_a+\frac{\lambda}{2}\right)^{N-1},\]
    \[\mathrm{det}(\tilde{M})=\left(\theta_b-\frac{\lambda}{2}\right)^N+N\frac{\lambda}{2}\left(\theta_b-\frac{\lambda}{2}\right)^{N-1}.\]
    As a function of $\theta_a$, the first equation has a root $\theta_a=-\frac{\lambda}{2}$ of multiplicity $N-1$ and a remaining root of $\theta_a=\frac{\lambda(N-1)}{2}$. As a function of $\theta_b$, the second equation has a root $\theta_b=\frac{\lambda}{2}$ of multiplicity $N-1$ and a remaining root of $\theta_b=-\frac{\lambda(N-1)}{2}$. Since $\lambda,\theta_a,\theta_b>0$, the unique feasible value of $\theta_a$ (resp.\ $\theta_b$) that leads to the non-invertibility of $M$ (resp.\ $\tilde{M}$) is $\theta_a=\frac{\lambda(N-1)}{2}$ (resp. $\theta_b=\frac{\lambda}{2}$). 

    Suppose now that $\theta_a=\frac{\lambda(N-1)}{2}$ and $\theta_b = \frac{\lambda}{2}$. The nullspace of $M$ is characterized by the $1$-dimensional space of vectors $\boldsymbol{a}$ taking the form $\boldsymbol{a}=c\boldsymbol{1}$,
    for some $c>0$. Similarly, the nullspace of $\tilde{M}$ is given by the $N-1$ dimensional space of vectors $\boldsymbol{b}$ satisfying $\boldsymbol{1}^T \boldsymbol{b}=0$.
    This completes the proof.
\end{proof}

% \medskip

% \noindent \textit{\textbf{Case (1):}}

% \medskip 

By Lemma \ref{lem:bdy.sys.of.eqns} we there must be an $\alpha\in \mathbb{R}$ such that
\[a^{i}=\alpha \ \ \ i =1,\dots,N, \ \ \ \text{and} \ \ \  \sum_{i=1}^Nb^{i} = 0.\]
Enforcing the conditions on $\boldsymbol{a}$ and $\boldsymbol{b}$ in the equations for the constants $\boldsymbol{c}$, we get
\[\begin{cases}
    c_1=\frac{2N \alpha}{(N+1)(1+N e^{\mathbbm{z}_1 T})},\\
    c_{1+i} = x^{i}+\alpha -\frac{2N \alpha}{(N+1)(1+Ne^{\mathbbm{z}_1 T})} & i=1,\dots,N,\\
    c_{N+1+i} = \beta b^{i} + \beta \frac{Ne^{\mathbbm{z}_1T}\alpha}{1+Ne^{\mathbbm{z}_1 T}} & i=1,\dots,N.
\end{cases}\]
Let
\[u_N := \frac{2N}{(N+1)(1+Ne^{\mathbbm{z}_1T})}, \ \ \ w_N:= \frac{Ne^{\mathbbm{z}_1 T}}{1+N e^{\mathbbm{z}_1 T}}\]
so that we may write more concisely,
\[\begin{cases}
    c_1=u_N\alpha,\\
    c_{1+i} = x^{i}+(1-u_N)\alpha & i=1,\dots,N,\\
    c_{N+1+i} = \beta b^{i} + \beta w_N\alpha & i=1,\dots,N.
\end{cases}\]
It remains to enforce the terminal conditions \eqref{eqn:b.cond.2}. Thus, we solve the $N+1$ dimensional system
\[\begin{cases}
    b^{i} = -X_{T-}^{i}= -\left[c_1e^{\mathbbm{z}_1 T}+c_{1+i}+c_{N+1+i} T\right],& i=1,\dots,N,\\
    \sum_{i=1}^N b^{i}=0
\end{cases}\]
for the $N+1$ unknowns given by $\alpha$ and $\boldsymbol{b}$. Inserting the form of $\boldsymbol{c}$,
\begin{align*}b^{i} 
%&=-\left[u_Ne^{z_1 T}\alpha+x^{(i)}+(1-u_N)\alpha+\beta b^{(i)}T + \beta w_N\alpha T\right]\\
&=-\left[\left(u_Ne^{\mathbbm{z}_1 T}+(1-u_N)+\beta w_N T\right)\alpha+x^{i}+\beta b^{i}T\right].
\end{align*}
Let
\[r_N:=1+(e^{\mathbbm{z}_1T}-1)u_N+\beta w_N T\]
so that
\[b^{i}=-r_N \alpha - x^{i}-\beta b^{i} T.\]
Summing over $i$ and using that $\sum_{i=1}^Nb^{i}=0$ we have
\[0=-Nr_N\alpha -\sum_{i=1}^N x^{i}.\]
This implies \begin{equation}\label{eqn:alpha.form}
    \boxed{\alpha = -r_N^{-1} \overline{x}.} 
\end{equation}
Substituting this back in, we get $b^{i} = \overline{x}-x^{i}-\beta b^{i} T$
which yields 
\begin{equation}\label{eqn:b.form}
    \boxed{b^{i} = -\frac{x^{i}-\overline{x}}{1+\beta T}.}
\end{equation}
With this the final solution for the constants is
\[\begin{cases}
    c_1=-\frac{u_N}{r_N}\overline{x},\\
    c_{1+i} = x^{i}-\frac{(1-u_N)}{r_N}\overline{x}=(x^{i}-\overline{x})+\frac{r_N-1+u_N}{r_N}\overline{x}& i=1,\dots,N,\\
    c_{N+1+i} = - \frac{\beta}{1+\beta T}(x^{i}-\overline{x})- \frac{\beta w_N}{r_N}\overline{x} & i=1,\dots,N.
\end{cases}\]
Recalling that
\[X_t^i= c_1e^{\mathbbm{z}_1 t}+c_{1+i}+c_{N+1+i}, \ \ \ i=1,\dots,N, \]
we recover (after simplification) the form of $\boldsymbol{X}^{*}$ reported in Theorem \ref{thm:equil.block.cost}.
