% \end{align*}
If $\theta_a = \frac{(N-1)\lambda}{2}$ \textbf{and} $\theta_b = \frac{\lambda}{2}$, then by Proposition \ref{prop:nash.eq.unique} and Lemma \ref{lem:nash.eq.det} this defines the unique equilibrium for all initial inventories. Hence, we have shown case (1) of Theorem \ref{thm:equil.block.cost}. 

Next, we address cases (2)--(3) for deterministic controls. If $\theta_a\not=\frac{\lambda(N-1)}{2}$ then Lemma~\ref{lem:bdy.sys.of.eqns} implies $\alpha =0$. But then \eqref{eqn:alpha.form} can only be true if $\overline{x}=0$. On the other hand, if $\theta_b\not=\frac{\lambda}{2}$ then Lemma \ref{lem:bdy.sys.of.eqns} further requires that $\boldsymbol{b}=\boldsymbol{0}$. In order to have a consistent solution, \eqref{eqn:b.form} mandates that $x^i=\overline{x}=x^j$ for all $i,j=1,\dots,N$. In summary, for cases (2) and (3) we have derived the unique equilibrium (again by Proposition \ref{prop:nash.eq.unique} and Lemma \ref{lem:nash.eq.det}) when the initial inventories satisfy the stated conditions. We also have that a \textbf{deterministic} equilibrium cannot exist otherwise by the aforementioned inconsistencies. It remains to show that this non-existence generalizes to arbitrary equilibria.

\subsubsection*{Step 3: Extending non-existence to the class of admissible strategies.}

We will treat cases (2) and (3) of Theorem \ref{thm:equil.block.cost} separately. 

\paragraph*{Case (2):}
It suffices to show that if $\vartheta_0 \not=\frac{\lambda (N-1)}{2}$ and a Nash equilibrium exists, then $\overline{x}=0$.

Proposition \ref{prop:no.interior.jumps} implies an equilibrium system of equations for $\Delta X_{0}^{*,i}$ and $\Delta X_{T}^{*,i}$ that coincides with the one in Lemma \ref{lem:bdy.sys.of.eqns}. We have assumed $\vartheta_0 \not=\frac{\lambda (N-1)}{2}$, so we can conclude that
$\Delta X_0^{*,i} =0$ for all $i$ and $\sum_{i=1}^N\Delta X_T^{*,i} = 0$. Moreover, again by Proposition \ref{prop:no.interior.jumps}, there are no interior jumps. Then, by Lemma \ref{lem:gen.foc.jumps}, for all predictable $\sigma\geq \tau$,
    \begin{align*}
         &\mathbb{E}\left[\lambda\int_0^Te^{-\beta |\sigma-t|}dX_t^{i}+\lambda\int_0^{\sigma-} e^{-\beta (\sigma-t)}\sum_{j\not=i}dX_t^{j} + \left(\vartheta_T\Delta X_T^{i}+\frac{\lambda}{2}\sum_{j\not=i}\Delta X_T^{j}\right)\mathds{1}_{\{\sigma=T\}}\bigg|\mathcal{F}_{\tau-}\right]\\
         &=\mathbb{E}\left[\lambda\int_0^Te^{-\beta |\tau-t|}dX_t^{i}+\lambda\int_0^{\tau-} e^{-\beta (\tau-t)}\sum_{j\not=i}dX_t^{j} + \left(\vartheta_T\Delta X_T^{i}+\frac{\lambda}{2}\sum_{j\not=i}\Delta X_T^{j}\right)\mathds{1}_{\{\tau=T\}}\bigg|\mathcal{F}_{\tau-}\right].
     \end{align*}
     Recall from Proposition \ref{prop:no.interior.jumps} that
     \[ \vartheta_T\Delta X_{T}^{*,i}=-\frac{\lambda}{2}\sum_{j\not=i}\Delta X_{T}^{*,j}=0, \ \ \ i=1,\dots,N.\]
     Substituting this in, and rearranging terms,
%      \begin{align*}
