% Rearranging terms,
\begin{align*}
         \mathbb{E}&\left[\lambda\int_\sigma ^Te^{-\beta (t-\sigma)}dX_t^{i}+\lambda\int_0^{\sigma-} e^{-\beta (\sigma-t)}\sum_{j=1}^NdX_t^{j}\bigg|\mathcal{F}_{\tau-}\right]\\
         &=\mathbb{E}\left[\lambda\int_\tau^Te^{-\beta (t-\tau)}dX_t^{i}+\lambda\int_0^{\tau-} e^{-\beta (\tau-t)}\sum_{j=1}^NdX_t^{j}\bigg|\mathcal{F}_{\tau-}\right].
\end{align*}
% Using that the sum process has no jumps,
