%          &=\mathbb{E}\left[\lambda\int_\tau^Te^{-\beta (t-\tau)}dX_t^{i}+\lambda\int_0^{\tau} e^{-\beta (\tau-t)}\sum_{j=1}^NdX_t^{j}\bigg|\mathcal{F}_{\tau-}\right]
% \end{align*}
% Averaging over $i$,
By averaging over $i$ and using that the average process, $\overline{X}$, has no jumps,
\begin{align*}
         \mathbb{E}&\left[\lambda\int_\sigma ^Te^{-\beta (t-\sigma)}d\overline{X}_t+N\lambda\int_0^{\sigma} e^{-\beta (\sigma-t)}d\overline{X}_t\bigg|\mathcal{F}_{\tau-}\right]\\
         &=\mathbb{E}\left[\lambda\int_\tau^Te^{-\beta (t-\tau)}d\overline{X}_t+N \lambda\int_0^{\tau} e^{-\beta (\tau-t)}d\overline{X}_t\bigg|\mathcal{F}_{\tau-}\right].
\end{align*}
Setting $\tau\equiv 0$,
\begin{align*}
         \mathbb{E}&\left[\lambda\int_\sigma ^Te^{-\beta (t-\sigma)}d\overline{X}_t+N\lambda\int_0^{\sigma} e^{-\beta (\sigma-t)}d\overline{X}_t\right]=\mathbb{E}\left[\lambda\int_0^Te^{-\beta t}d\overline{X}_t\right].
\end{align*}
Now the right-hand side is just a constant in $\sigma$. Taking $\sigma$ to be any deterministic time in $[0,T]$,  this implies
\begin{align*}
         \mathbb{E}&\left[\lambda e^{\beta t}\int_t ^Te^{-\beta s}d\overline{X}_s+N\lambda e^{-\beta t}\int_0^{t} e^{\beta s}d\overline{X}_s\right]=\mathbb{E}\left[\lambda\int_0^Te^{-\beta t}d\overline{X}_t\right], \ \ \ \forall t\in[0,T].
\end{align*}
Integrating by parts and dividing by $\lambda$,
\begin{multline*}
        \mathbb{E}\bigg[ e^{-\beta (T-t)}\overline{X}_T-\overline{X}_t +  \beta \int_t ^T\overline{X}_s e^{-\beta (s-t)}ds+N \left( \overline{X}_t -e^{-\beta t}\overline{X}_0-\beta \int_0^{t} e^{-\beta (t-s)}\overline{X}_sds \right)\bigg]\\
        =\mathbb{E}\left[e^{-\beta T} \overline{X}_T -\overline{X}_0 +\beta \int_0^Te^{-\beta t}\overline{X}_tdt\right], \ \ \ \forall t\in[0,T].
\end{multline*}
Using that $\overline{X}_T=0$ and $\overline{X}_0=\overline{x}$ we have, after collecting terms,
\begin{multline*}
        \mathbb{E}\bigg[(N-1) \overline{X}_t + \beta \int_t^T e^{-\beta (s-t)}\overline{X}_sds-N e^{-\beta t}\overline{x}-N \beta \int_0^{t} e^{-\beta (t-s)}\overline{X}_sds \bigg]\\
        =\mathbb{E}\left[-\overline{x} +\beta \int_0^Te^{-\beta t}\overline{X}_tdt\right], \ \ \ \forall t\in[0,T].
\end{multline*}
Writing
$m_t := \mathbb{E}[\overline{X}_t]$, Fubini's theorem yields
\begin{multline*}
        (N-1)m_t + \beta \int_t ^Tm_s e^{-\beta (s-t)}ds+(1-N e^{-\beta t})\overline{x}-N \beta \int_0^{t} e^{-\beta (t-s)}m_sds\\
        =\beta \int_0^Te^{-\beta t}m_tdt, \ \ \ \forall t\in[0,T].
\end{multline*}
While we already know that $m$ is continuous (by the continuity of $\overline{X}$ and dominated convergence), this equation further shows that $m_t$ is differentiable. Define
\[y_t:=\int_t ^Te^{-\beta (s-t)}m_s ds \ \ \ \text{and} \ \ \ \ell_t:=\int_0^{t} e^{-\beta (t-s)}m_sds,\]
so that our equation becomes
\begin{align*}
        (N-1)m_t + \beta y_t +(1-N e^{-\beta t})m_0-N \beta \ell_t=\beta y_T, \ \ \ \forall t\in[0,T].
\end{align*}
Differentiating gives a system of ODEs,
\[\begin{cases}
    \dot{m}_t =-\frac{\beta}{N-1} \left(\dot{y}_t +N (e^{-\beta t}\overline{x}- \dot{\ell}_t)\right), & m_0 = \overline{x}, \ \ \ m_T =0,\\
    \dot{y}_t = \beta y_t -m_t, & y_T = 0,\\
    \dot{\ell}_t = -\beta \ell_t +m_t, & \ell_0 = 0.
\end{cases}\]
Ignoring the boundary condition $m_0=\overline{x}$ and solving the system gives the unique solution
\[m_t=\frac{N\left(\left(\beta  \left(T -t \right) N +2+\beta  \left(T -t \right)\right) e^{\frac{\beta  \left(N +1\right) T}{N -1}}-2 e^{\frac{\beta  \left(N +1\right) t}{N -1}}\right)}{\left(\left(\beta  T +1\right) N +\beta  T +3\right) N e^{\frac{\beta  \left(N +1\right) T}{N -1}}-N +1}\overline{x}, \ \ \ t\in[0,T].
\]
If we now enforce that $m_0 = \overline{x}$ we get the necessary condition
\[\frac{\left(\left(N \beta  T +\beta  T +2\right) e^{\frac{\beta  \left(N +1\right) T}{N -1}}-2\right) N}{\left(\left(\beta  T +1\right) N +\beta  T +3\right) N e^{\frac{\beta  \left(N +1\right) T}{N -1}}-N +1}\overline{x}=\overline{x}.\]
If $\overline{x}\not=0$ this can only be true if 
\[\left(\left(N \beta  T +\beta  T +2\right) e^{\frac{\beta  \left(N +1\right) T}{N -1}}-2\right) N=\left(\left(\beta  T +1\right) N +\beta  T +3\right) N e^{\frac{\beta  \left(N +1\right) T}{N -1}}-N +1\]
which, for $N>0$, is equivalent to
\[Ne^{\frac{\beta (N+1)}{N-1} T} = -1.\]
However, the left-hand side is clearly positive, and we conclude that $\overline{x}=0$.





