\paragraph*{Case (3):}
For case (3) it suffices to show that if $\vartheta_T\not=\frac{\lambda}{2}$ and a Nash equilibrium exists, then $x^i=x^j$ for all $i,j$.

Proposition \ref{prop:no.interior.jumps} tells us that there are no interior jumps and provides us a system of equations for $\Delta X_{0}^{*,i}$ and $\Delta X_{T}^{*,i}$.
This is the same system of equations as in Lemma \ref{lem:bdy.sys.of.eqns}. In this case $\vartheta_T \not=\frac{\lambda}{2}$, so we can conclude that
$\Delta X_T^{*,i} =0$ for all $i$ and $\Delta X_0^{*,i} = \Delta X_0^{*,j}$ for all $i,j$. Then, by Lemma \ref{lem:gen.foc.jumps}, we have that for all predictable $\sigma\geq \tau$,
\begin{multline*}
     \mathbb{E}\left[\lambda\int_0^Te^{-\beta |\sigma-t|}dX_t^{*,i}+\lambda\int_0^{\sigma-} e^{-\beta (\sigma-t)}\sum_{j\not=i}dX_t^{*,j} + \left(\vartheta_0\Delta X_0^{*,i}+\frac{\lambda}{2}\sum_{j\not=i}\Delta X_0^{*,j}\right)\mathds{1}_{\{\sigma=0\}}\bigg|\mathcal{F}_{\tau-}\right]\\
     =\mathbb{E}\left[\lambda\int_0^Te^{-\beta |\tau-t|}dX_t^{*,i}+\lambda\int_0^{\tau-} e^{-\beta (\tau-t)}\sum_{j\not=i}dX_t^{*,j} + \left(\vartheta_0\Delta X_0^{*,i}+\frac{\lambda}{2}\sum_{j\not=i}\Delta X_0^{*,j}\right)\mathds{1}_{\{\tau=0\}}\bigg|\mathcal{F}_{\tau-}\right]
 \end{multline*}
 for all $i=1,\dots,N$. 
 Appealing to Proposition \ref{prop:no.interior.jumps} once again, 
 \[ \vartheta_0\Delta X_{0}^{*,i}=\frac{\lambda}{2}\sum_{j\not=i}\Delta X_{0}^{*,j}, \ \ \ i=1,\dots,N.\]
 If we substitute this in and simplify,
 % \begin{align*}
 %     \mathbb{E}&\left[\lambda\int_0^Te^{-\beta |\sigma-t|}dX_t^{i}+\lambda\int_0^{\sigma-} e^{-\beta (\sigma-t)}\sum_{j\not=i}dX_t^{j} + \lambda\mathds{1}_{\{\sigma=0\}}\sum_{j\not=i}\Delta X_0^{j}\bigg|\mathcal{F}_{\tau-}\right]\\
 %     &=\mathbb{E}\left[\lambda\int_0^Te^{-\beta |\tau-t|}dX_t^{i}+\lambda\int_0^{\tau-} e^{-\beta (\tau-t)}\sum_{j\not=i}dX_t^{j} + \lambda\mathds{1}_{\{\tau=0\}}\sum_{j\not=i}\Delta X_0^{j}\bigg|\mathcal{F}_{\tau-}\right]
 % \end{align*}
 % This is exactly,
 \begin{align*}
     \mathbb{E}&\left[\lambda\int_0^Te^{-\beta |\sigma-t|}dX_t^{*,i}+\lambda\int_0^{\sigma} e^{-\beta (\sigma-t)}\sum_{j\not=i}dX_t^{*,j}\bigg|\mathcal{F}_{\tau-}\right]\\
     &\quad \quad =\mathbb{E}\left[\lambda\int_0^Te^{-\beta |\tau-t|}dX_t^{*,i}+\lambda\int_0^{\tau} e^{-\beta (\tau-t)}\sum_{j\not=i}dX_t^{*,j}\bigg|\mathcal{F}_{\tau-}\right], \ \ \ i=1,\dots,N.
 \end{align*}
 Then, by subtracting any two equations when $i\not=k$,
 \begin{align*}
     \mathbb{E}&\left[\lambda\int_0^Te^{-\beta |\sigma-t|}d(X_t^{*,i}-X_t^{*,k})-\lambda\int_0^{\sigma} e^{-\beta (\sigma-t)}d(X_t^{*,i}-X_t^{*,k})\bigg|\mathcal{F}_{\tau-}\right]\\
     &=\mathbb{E}\left[\lambda\int_0^Te^{-\beta |\tau-t|}d(X_t^{*,i}-X_t^{*,k})-\lambda\int_0^{\tau} e^{-\beta (\tau-t)}d(X_t^{*,i}-X_t^{*,k})\bigg|\mathcal{F}_{\tau-}\right].
 \end{align*}
 This implies that
 \begin{align*}
  \mathbb{E}&\left[\lambda\int_{\sigma+}^Te^{-\beta |\sigma-t|}d(X_t^{*,i}-X_t^{*,k})\bigg|\mathcal{F}_{\tau-}\right]=\mathbb{E}\left[\lambda\int_{\tau+}^Te^{-\beta |\tau-t|}d(X_t^{*,i}-X_t^{*,k})\bigg|\mathcal{F}_{\tau-}\right].
 \end{align*}
 Summing over $k\not=i$,
 \begin{align*}
     \mathbb{E}&\left[\lambda\int_{\sigma+}^Te^{-\beta |\sigma-t|}d(N X_t^{*,i}-\sum_{i=1}^NX_t^{*,k})\bigg|\mathcal{F}_{\tau-}\right]=\mathbb{E}\left[\lambda\int_{\tau+}^Te^{-\beta |\tau-t|}d(NX_t^{*,i}-\sum_{k=1}^NX_t^{*,k})\bigg|\mathcal{F}_{\tau-}\right],
 \end{align*}
 which is equivalent to
% \begin{align*}
%      \mathbb{E}&\left[\lambda\int_{\sigma+}^Te^{-\beta |\sigma-t|}d(X_t^{i}-\overline{X}_t)\bigg|\mathcal{F}_{\tau-}\right]=\mathbb{E}\left[\lambda\int_{\tau+}^Te^{-\beta |\tau-t|}d(X_t^{i}-\overline{X}_t)\bigg|\mathcal{F}_{\tau-}\right].
%  \end{align*}
%  which is just,
 \begin{align*}
     \mathbb{E}&\left[\lambda\int_{\sigma+}^Te^{-\beta (t-\sigma)}d(X_t^{*,i}-\overline{X}_t)\bigg|\mathcal{F}_{\tau-}\right]=\mathbb{E}\left[\lambda\int_{\tau+}^Te^{-\beta (t-\tau)}d(X_t^{*,i}-\overline{X}_t)\bigg|\mathcal{F}_{\tau-}\right]
 \end{align*}
 where $\overline{X} = N^{-1}\sum_{i=1}^NX_t^{*,i}$.
 Setting $\sigma\equiv T$ and using predictability we get
 \begin{equation}\label{eqn:block.cost.case.3.v1}
     0=e^{\beta \tau}\mathbb{E}\left[\lambda\int_{\tau+}^Te^{-\beta t}d(X_t^{*,i}-\overline{X}_t)\bigg|\mathcal{F}_{\tau-}\right].
 \end{equation}
 Note that the process $X^{*,i} - \overline{X}$ has no jumps since $\Delta X_0^{*,i} =\Delta \overline{X}_0$ for all $i=1,\dots,N$. Hence, \eqref{eqn:block.cost.case.3.v1} implies that
 \begin{equation}\label{eqn:block.cost.case.3.v2}
     0=\mathbb{E}\left[\lambda\int_{\tau}^Te^{-\beta t}d(X_t^{*,i}-\overline{X}_t)\bigg|\mathcal{F}_{\tau-}\right].
 \end{equation}
 Let us define 
 \[M_t =\mathbb{E}\left[\lambda\int_{0}^Te^{-\beta t}d(X_t^{*,i}-\overline{X}_t)\bigg|\mathcal{F}_{t}\right], \ \ \ t\in[0,T].\]
 By definition, $M$ is a right-continuous martingale with respect to the filtration $\mathbb{F}$. Taking limits from below and applying \cite[Theorem 4.6.10]{Durrett.19},
 \begin{align*}
     M_{t-} &=\mathbb{E}\left[\lambda\int_{0}^Te^{-\beta t}d(X_t^{*,i}-\overline{X}_t)\bigg|\mathcal{F}_{t-}\right], \ \ \ t\in(0,T].
 \end{align*}
Using \eqref{eqn:block.cost.case.3.v2} and the predictability of the inventory processes,
\[M_{t-}=\lambda\int_{0}^te^{-\beta t}d(X_t^{*,i}-\overline{X}_t), \ \ \ t\in(0,T].\]
From this, we can infer that $M$ is continuous on $[0,T)$ and takes the form
\[M_{t}=\lambda\int_{0}^te^{-\beta t}d(X_t^{*,i}-\overline{X}_t).\]
The definition of $M_T$ reveals that the continuity holds on the entire interval $[0,T]$. Thus $M$ is a bounded variation and continuous martingale, implying that it must be constant. Hence,
 \[0=dM_t = e^{-\beta t} d(X_t^{*,i}-\overline{X}_t) \]
 from which we conclude that $dX^{*,i}_t = d\overline{X}_t$.
 Since $X^{*,i}_T=\overline{X}_T=0$ (recall that inventory liquidation is enforced by $T$) we have
 \[0=X_T^{*,i}-\overline{X}_T = x^i-\overline{x} + \int_0^Td(X_t^{*,i}-\overline{X}_t)=x^i-\overline{x}. \]
 From this we conclude that $x^i = \overline{x}$ for all $i$. Hence, $x^i=x^j$ for all $i,j$. This completes the proof of Theorem \ref{thm:equil.block.cost}. \qed



\subsection{Corollary \ref{cor:eq.cost.block.cost}}
From Theorem \ref{thm:equil.block.cost}, we can differentiate $X^{*,i}$ on $(0,T)$ to get
\begin{equation*}
		\dot{X}^{*,i}_t= -\frac{\beta}{\beta T+1} (x^{i}-\overline{x})-\frac{\beta N  (N+1) e^{\beta \frac{N+1}{N-1} T}+ \frac{2\beta N(N+1)}{N-1}e^{\beta \frac{N+1}{N-1} t}}{N((\beta T+1)(N+1)+2)e^{\beta \frac{N+1}{N-1} T}-(N-1)} \overline{x}.
\end{equation*}
Moreover, we have 
\[\Delta X_0^{*,i} = -\frac{(N+1)\left(1+Ne^{\beta \frac{N+1}{N-1}T}\right)}{N((\beta T+1)(N+1)+2)e^{\beta \frac{N+1}{N-1} T}-(N-1)}\overline{x}, \ \ \ \Delta X_T^{*,i} = -\frac{x^i-\overline{x}}{1+\beta T}.\]
From this we can obtain the equilibrium impact process,
\[I_t=-\frac{ \lambda  N (N +1)\left(e^{\beta \frac{N +1}{N -1}t}+N e^{\beta \frac{N +1}{N -1}T}\right) }{N \left(( \beta T +1) (N+1) +2\right) e^{\beta \frac{\left(N +1\right) T}{N -1}}-(N -1)}\overline{x}, \ \ \ t\in[0,T),
\]
where
\[\Delta I_0 =  \lambda \sum_{i=1}^N \Delta X_0^{*,i}=-\frac{\lambda N(N+1)\left(1+Ne^{\beta \frac{N+1}{N-1}T}\right)}{N((\beta T+1)(N+1)+2)e^{\beta \frac{N+1}{N-1} T}-(N-1)}\overline{x}\]
and
\[\Delta I_T=\lambda\sum_{i=1}^N\Delta X_T^{*,i} = 0.\]
Now, a direct computation (omitted for the sake of brevity) gives Corollary \ref{cor:eq.cost.block.cost}. \qed


\section{Proofs for Section \ref{sec:id.limit}}\label{app:proofs.for.sec.id.limit}

\subsection{Theorem \ref{thm:small.eps.lim}}

We divide the proof into two steps, corresponding to the two claims in the theorem.

\subsubsection*{Step 1: Strategy convergence.}

Note that $z_1\to \frac{N+1}{N-1}\beta$ as $\varepsilon\downarrow 0$. Writing $\tau_1=  \frac{N+1}{N-1}\beta$ we conclude
\begin{equation}\label{eqn:small.eps.1}
\frac{e^{z_1 T}-1}{z_1}\to \frac{e^{\tau_1 T}-1}{ \tau_1}.
\end{equation}
On the other hand, we see that $z_2\to -\infty$ as $\varepsilon\downarrow0$. So,
\[\gamma_1=\frac{1}{z_1+\beta}+\frac{1}{z_1-\beta}e^{z_1 T}\to\frac{1}{\tau_1+\beta}+\frac{1}{\tau_1-\beta}e^{\tau_1 T}, \]
\[\gamma_2=\frac{1}{z_2+\beta}+\frac{1}{z_2-\beta}e^{z_2 T}\to 0, \ \ \ \text{and} \ \ \ \frac{e^{z_2 t} -1}{ z_2}\to 0,  \ \ \ t\in(0,T].\]
The limit of 
$\gamma_1(e^{z_2 t} -1)/\gamma_2z_2$
therefore depends on the ratio of these last two terms. We have
\[z_2\gamma_2=\frac{z_2}{z_2+\beta}+\frac{z_2}{z_2-\beta}e^{z_2 T}\to 1, \ \ \ \text{and} \ \ \ e^{z_2 t} -1\to -1, \ \ \ t\in(0,T].\]
So,
\begin{equation*}%\label{eqn:small.eps.2}
\frac{\gamma_1}{\gamma_2}\frac{e^{z_2 t} -1}{ z_2} \to -\left(\frac{1}{\tau_1+\beta}+\frac{1}{\tau_1-\beta}e^{\tau_1 T}\right), \ \ \ t\in(0,T],
\end{equation*}
and the limit is $0$ if $t=0$.
Arguing similarly,
\begin{equation*}%\label{eqn:small.eps.3}
    \rho_{-}=\frac{1}{z_1-\beta}e^{z_1T}-\frac{\gamma_1}{\gamma_2} \frac{1}{z_2-\beta}e^{z_2T}\to \frac{1}{\tau_1-\beta} e^{\tau_1 T}.
\end{equation*}
Finally, we see that $z_3\uparrow \infty$ as $\varepsilon\downarrow 0$.
Moreover,
\[\varepsilon z_3 = \beta\varepsilon+\lambda \to \lambda, \ \ \ \text{and} \ \ \ \frac{e^{z_{3} t}-1}{e^{z_3 T}}=e^{-z_3(T-t)}-e^{-z_3 T}\to 0,\ \ \ t\in[0,T).\]
When $t=T$, the latter converges to $1$. Therefore,
\begin{equation}\label{eqn:small.eps.4}
    \frac{\lambda(e^{z_3 t}-1)}{\varepsilon z_3e^{z_3 T}}\to 0, \ \ \ t\in[0,T), \ \ \ \text{and} \ \ \ \frac{\lambda(e^{z_3 T}-1)}{\varepsilon z_3e^{z_3 T}}\to 1.
\end{equation}
Applying \eqref{eqn:small.eps.1}--\eqref{eqn:small.eps.4} yields that as $\varepsilon\downarrow0$,
\begin{align*}
		\mathfrak{f}_t &\to 1-\frac{\beta t}{1+\beta T} , \ \ \ t\in[0,T),\\
		\mathfrak{f}_T &\to 0,  \\
    \mathfrak{g}_t &\to 1-\frac{\frac{\beta}{\tau_1-\beta} e^{\tau_1 T}t+\frac{e^{\tau_1 t}-1}{\tau_1}+\frac{1}{\tau_1+\beta}+\frac{1}{\tau_1-\beta}e^{\tau_1 T}}{\frac{\beta}{\tau_1-\beta} e^{\tau_1 T}T+\frac{e^{\tau_1 T}-1}{\tau_1} +\frac{1}{\tau_1+\beta}+\frac{1}{\tau_1-\beta}e^{\tau_1 T}}, \ \ \ t\in(0,T],\\
    \mathfrak{g}_0 &\to 1.
\end{align*}
Rearranging these expressions shows agreement with Theorem \ref{thm:equil.block.cost} on $(0,T)$. 

It remains to upgrade the pointwise convergence to locally uniform on $(0,T)$. To this end, we first claim that $\mathfrak{f}$ and $\mathfrak{g}$ are monotone decreasing. As $z_3\geq0$ for all $\varepsilon$ we have
\begin{equation*}
		\dot{\mathfrak{f}}_t=-\frac{\beta+\frac{\lambda e^{z_{3} t}}{\varepsilon e^{z_3T}}}{\beta T+ \frac{\lambda(e^{z_3 T}-1)}{\varepsilon z_3e^{z_3 T}}}\leq 0.
\end{equation*}
Turning to $\dot{\mathfrak{g}}$ we claim that
\begin{equation}\label{eqn:dg.negative}
		\dot{\mathfrak{g}}_t=-\frac{\beta \rho_{-}+e^{z_1 t}-\frac{\gamma_1}{\gamma_2}e^{z_2 t}}{\beta \rho_{-}T+\frac{e^{z_1 T}-1}{z_1} -\frac{\gamma_1}{\gamma_2}\frac{e^{z_2 T}-1}{ z_2}}\leq 0.
\end{equation}
Indeed, from the form of $z_1$ and $z_2$ we can see that $z_1>0$, $z_2<0$, and $z_1$ increases and $z_2$ decreases as $\varepsilon\downarrow0$. Taking $\varepsilon\uparrow\infty$ we deduce
\[z_1 >\lim_{\varepsilon\uparrow\infty} z_1=\beta, \ \ \ z_2< \lim_{\varepsilon\uparrow\infty}z_2=-\beta.\]
These observations allow us to conclude $\gamma_1\geq0$ and $\gamma_2\leq 0$. Rearranging the expression for~$\rho_{-}$, we get
\[\rho_{-}=e^{z_{1} T}\frac{\left(z_{2}+\beta \right) \left(z_{1}-\beta \right) e^{(z_{2}-z_1) T}- \left(z_{2}-\beta \right) \left(z_{1}+\beta \right)}{\left(z_{1}+\beta \right) \left(-\left(z_{2}+\beta \right) e^{z_{2} T}-(z_2-\beta)\right) \left(z_{1}-\beta \right)}.
\]
The denominator is positive by the bounds on $z_1$ and $z_2$. As $(z_2+\beta)(z_1-\beta)\leq 0$ and $z_2-z_1\leq 0$ 
% \[z_2-z_1=-\frac{\sqrt{\left(N -1\right)^{2} \lambda^{2}+4 \beta  \varepsilon  \left(N +1\right) \lambda +4 \beta^{2} \varepsilon^{2}}}{\varepsilon}\leq 0,\] 
we have
\begin{align*}\rho_{-}&\geq e^{z_1 T}\frac{\left(z_{2}+\beta \right) \left(z_{1}-\beta \right)- \left(z_{2}-\beta \right) \left(z_{1}+\beta \right)}{\left(z_{1}+\beta \right) \left(-\left(z_{2}+\beta \right) e^{z_{2} T}-(z_2-\beta)\right) \left(z_{1}-\beta \right)}\\
&=e^{z_1 T}\frac{2 \beta (z_1-z_2)}{\left(z_{1}+\beta \right) \left(-\left(z_{2}+\beta \right) e^{z_{2} T}-(z_2-\beta)\right) \left(z_{1}-\beta \right)}\geq0.
\end{align*}
Taken together we see that each term in the numerator and denominator of $\dot{\mathfrak{g}}$ is positive and so \eqref{eqn:dg.negative} follows.

In summary, the monotone functions $\mathfrak{f}$ and $\mathfrak{g}$ converge pointwise to $\mathbbm{f}$ and $\mathbbm{g}$ which are continuous on $(0,T)$. By Dini's theorem, it follows that the convergence is locally uniform.


