\subsubsection*{Step 2: Cost convergence.}

We first consider the limit of the equilibrium impact cost from Corollary \ref{cor:eq.cost.liq.constr}. Along the lines of Step~1, it can be checked that as $\varepsilon\downarrow 0$,
\begin{equation}\label{eqn:xi.limit}
    \Xi \to 1+\beta T,
\end{equation}
\begin{equation}\label{eqn:psi.limit}
\Psi \to \frac{\beta}{\tau_1-\beta} e^{\tau_1 T}T+\frac{e^{\tau_1 T}-1}{\tau_1} +\frac{1}{\tau_1+\beta}+\frac{1}{\tau_1-\beta}e^{\tau_1 T},
\end{equation}
\begin{align}\mathfrak{h}_1&= \rho_{-}(\Psi+\beta\varrho_1) +\mathfrak{r}_1\label{eqn:h1.limit}\\
&\to \frac{1}{\tau_1-\beta} e^{\tau_1 T}\left(\frac{\beta}{\tau_1-\beta} e^{\tau_1 T}T+\frac{e^{\tau_1 T}-1}{\tau_1} +\frac{1}{\tau_1+\beta}+\frac{1}{\tau_1-\beta}e^{\tau_1 T}+\beta \frac{e^{\tau_1T} -1}{\tau_1(\tau_1 +\beta)}\right)\nonumber\\
&\quad +\frac{e^{2\tau_1 T}-1}{2\tau_1(\tau_1+\beta)}-\frac{1}{2}\left(\frac{1}{\tau_1+\beta}+\frac{1}{\tau_1-\beta}e^{\tau_1 T}\right)^2+\frac{1}{(\tau_1+\beta)^2}+\frac{1}{(\tau_1-\beta)(\tau_1+\beta)}e^{\tau_1 T},\nonumber
\end{align}
and
\begin{equation}\label{eqn:h2.limit}\mathfrak{h}_2=\rho_{-}\Xi+\beta\varrho_1 + \lambda\varepsilon^{-1}\mathfrak{m}_1\to \frac{1}{\tau_1-\beta} e^{\tau_1 T}(1+\beta T)+\beta \frac{e^{\tau_1T} -1}{\tau_1(\tau_1 +\beta)}+\frac{e^{\tau_1 T}}{\tau_1 +\beta}.
\end{equation}
Using \eqref{eqn:psi.limit} and \eqref{eqn:h2.limit}, we get (after simplification) that $\mathfrak{h}_2\Psi^{-1}\to 1$, so
\begin{equation}\label{eqn:h2.ratio.limit}
    \frac{\mathfrak{h}_2}{\Psi\Xi}\to\frac{1}{1+\beta T}.
\end{equation}
A protracted algebraic manipulation of the quantities in \eqref{eqn:psi.limit} and \eqref{eqn:h1.limit} also yields
\begin{equation}\label{eqn:h1.ratio.limit}
    \frac{\mathfrak{h}_1}{\Psi^2}\to \frac{ N^2 (N+1)\left( \left(\left(\beta T +\frac{1}{2}\right) (N+1) +3\right) e^{\frac{2 \left(N +1\right) \beta  T}{N -1}}-\frac{2 \left(N -1\right)}{N^2} \left(N e^{\frac{\left(N +1\right) \beta  T}{N -1}}+\frac{1}{4}\right) \right)}{\left(N \left(\left(\beta T +1\right)(N+1) + 2\right) e^{\frac{\left(N +1\right) \beta  T}{N -1}}-(N -1)\right)^{2}}.
\end{equation}
Passing to the limit in the expression of the impact cost in Corollary \ref{cor:eq.cost.liq.constr} and applying  \eqref{eqn:h2.ratio.limit} and  \eqref{eqn:h1.ratio.limit} gives the desired convergence to the corresponding term in Corollary \ref{cor:eq.cost.block.cost}.

We now turn to the instantaneous cost in Corollary \ref{cor:eq.cost.liq.constr}. Once again, a careful accounting allows us to extract the limits
\begin{equation}\label{eqn:h3.limit}\varepsilon \mathfrak{h}_3=\varepsilon\beta\rho_{-}(\Psi+\varrho_0)+\varepsilon\mathfrak{r}_0\to \frac{\lambda(N-1)}{2} \left(\frac{1}{\tau_1+\beta}+\frac{1}{\tau_1-\beta}e^{\tau_1 T}\right)^2,
\end{equation}
\begin{equation}\label{eqn:h4.limit}
\varepsilon\mathfrak{h}_4=\varepsilon\beta(2\Xi -\beta T)+\lambda^2 \varepsilon^{-1}e^{-z_3 T}\mathfrak{q}_3\to \frac{\lambda}{2},
\end{equation}
and
\begin{equation}\label{eqn:h5.limit}
\varepsilon\mathfrak{h}_5=\varepsilon\beta\rho_{-}\Xi+\varepsilon\beta\varrho_0+\lambda\mathfrak{m}_0\to0.
\end{equation}
Using \eqref{eqn:psi.limit} and \eqref{eqn:h3.limit}, we obtain after simplification,
\begin{equation}\label{eqn:h3.ratio.limit}
    \frac{\varepsilon \mathfrak{h}_3}{2\Psi^2}\to \frac{\lambda(N-1) (N+1)^2 (1+ N e^{\beta \frac{N+1}{N-1} T})^2}{4 \left(N((\beta T+1) (N+1) + 2)e^{\beta \frac{N+1}{N-1} T} - (N-1)\right)^2}.
\end{equation}
Appealing to \eqref{eqn:xi.limit}, \eqref{eqn:psi.limit}, \eqref{eqn:h4.limit}, and \eqref{eqn:h5.limit} we similarly find
\begin{equation}\label{eqn:h4.and.h5.ratio.limit}
    \frac{\varepsilon \mathfrak{h}_4}{2\Xi^2}\to \frac{\lambda}{4 (\beta T+1)^2} \ \ \ \text{and} \ \ \ \frac{\varepsilon\mathfrak{h}_5}{\Xi\Psi}\to 0.
\end{equation}
Applying the limits \eqref{eqn:h3.ratio.limit} and \eqref{eqn:h4.and.h5.ratio.limit} to the instantaneous cost expression in Corollary~\ref{cor:eq.cost.liq.constr} shows that this cost converges to the block cost in Corollary \ref{cor:eq.cost.block.cost} for the specific choice $\vartheta_0 =\frac{\lambda (N-1)}{2}$ and $\vartheta_T = \frac{\lambda}{2}$. 

