\section{Introduction and Preliminaries}
In this paper we will discuss some types of cross-ratio maps sets of points, we discussed about each of the 4-points of cross-ratio and we will examine the algebraic properties for each case.
This paper comes as a result of the influence of the recently achieved results of my research which mainly is focused on Desargues affine planes and his reports on algebraic structures, as is evident from my earlier works, see \cite{ZakaThesisPhd}, \cite{ZakaCollineations},\cite{ZakaVertex},\cite{ZakaDilauto},\cite{ZakaFilipi2016},\cite{ZakaMohammedEndo},\cite{ZakaMohammedSF}, \cite{ZakaPetersIso}, \cite{ZakaPetersOrder}. Also, in our earlier research, we think that we have made a detailed presentation about the ratio of 2 and 3 points, accompanied by the division of transformations related to these ratios, invariant and preserving transforms, we also made a presentation of the Dyck free Group and Dyck Fundamental Group, see \cite{ZakaPeters2022DyckFreeGroup}, \cite{PetersZakaFundamentalGroup2023},\cite{ZakaPeters2022InvariantPreserving}. We have also made a detailed presentation of the cross-ratio and transforms related to it, and we have presented a division of some transformations as invariant and preserving transforms, see \cite{ZakaPeters2025CrosRatio}, \cite{ZakaPeters2024}. In this paper we will discuss in turn, four cross-ratio map sets of points in Desargues affine planes.
The foundations for the study of the connections between axiomatic geometry and algebraic structures were set forth by D. Hilbert \cite{Hilbert1959geometry}. And some classic for this are,  E. Artin \cite{Artin1957GeometricAlgebra}, D.R. Huges and F.C. Piper ~\cite{HugesPiper}, H. S. M Coxeter ~\cite{CoxterIG1969}. 
Marcel Berger in \cite{Berger2009geometry12}, Robin Hartshorne
 in \cite{Hartshorne1967Foundations}, etc. 

In this paper we work in Desargues affine plane, and we study the sets of points in a line of this plane, for this reason, we will follow and remain correct to the well-known definitions and results for Desargues affine planes, presented in our previous papers, and the results for Desargues affine planes, and skew-fields presented in \cite{Pickert1973PlayfairAxiom}, \cite{Kryftis2015thesis}, \cite{Artin1957GeometricAlgebra}, \cite{HugesPiper}, \cite{Hilbert1959geometry}, \cite{Cohn2008sf}, \cite{Herstein1968NR},\cite{Rotman2015AMAlgebra},\cite{Lam2001GTMalgebra}.\\
\textbf{Desargues Affine Plane:} 
Let $\mathcal{P}$ be a nonempty space, $\mathcal{L}$ a nonempty subset of $\mathcal{P}$. The elements $P$ of $\mathcal{P}$ are points and an element $\ell$ of $\mathcal{L}$ is a line. 
\begin{definition}
The incidence structure $\mathcal{A}=(\mathcal{P}, \mathcal{L},\mathcal{I})$, called affine plane, where satisfies the above axioms:
\begin{description}
	\item[1$^o$] For each points $\left\{P,Q\right\}\in \mathcal{P}$, there is exactly one line $\ell\in \mathcal{L}$ such that $\left\{P,Q\right\}\in \ell$.
\item[2$^o$] For each point $P\in \mathcal{P}, \ell\in \mathcal{L}, P \not\in \ell$, there is exactly one line $\ell'\in \mathcal{L}$ such that
$P\in \ell'$ and $\ell\cap \ell' = \emptyset$\ (Playfair Parallel Axiom~\cite{Pickert1973PlayfairAxiom}).   Put another way,
if the point $P\not\in \ell$, then there is a unique line $\ell'$ on $P$ missing $\ell$~\cite{Prazmowska2004DemoMathDesparguesAxiom}.
\item[3$^o$] There is a 3-subset of points $\left\{P,Q,R\right\}\in \mathcal{P}$, which is not a subset of any $\ell$ in the plane.   Put another way, there exist three non-collinear points $\mathcal{P}$~\cite{Prazmowska2004DemoMathDesparguesAxiom}.
\end{description}
\end{definition}

\emph{\bf Desargues' Axiom, circa 1630}~\cite[\S 3.9, pp. 60-61] {Kryftis2015thesis}~\cite{Szmielew1981DesarguesAxiom}.   Let $A,B,C,A',B',C'\in \mathcal{P}$ and let pairwise distinct lines  $\ell^{AA'} , \ell^{BB'}, \ell^{CC'}, \ell^{AC}, \ell^{A'C'}\in \mathcal{L}$ such that
\begin{align*}
\ell^{AA'} \parallel \ell^{BB'} \parallel \ell^{CC'} \ \mbox{(Fig.~\ref{fig:DesarguesAxiom}(a))} &\ \mbox{\textbf{or}}\
\ell^{AA'} \cap \ell^{BB'} \cap \ell^{CC'}=P.
 \mbox{(Fig.~\ref{fig:DesarguesAxiom}(b) )}\\
 \mbox{and}\  \ell^{AB}\parallel \ell^{A'B'}\ &\ \mbox{and}\ \ell^{BC}\parallel \ell^{B'C'}.\\
A,B\in \ell^{AB}, A'B'\in \ell^{A'B'}, A,C\in \ell^{AC}, &\  \mbox{and}\ A'C'\in \ell^{A'C'}, B,C\in \ell^{BC},  B'C'\in \ell^{B'C'}.\\
A\neq C, A'\neq C', &\ \mbox{and}\ \ell^{AB}\neq \ell^{A'B'}, \ell^{BC}\neq \ell^{B'C'}.
\end{align*}
\begin{figure}[htbp]
	\centering
		\includegraphics[width=0.85\textwidth]{Desargues}
	\caption{Desargues Axioms: (a) For parallel lines $\ell^{AA'} \parallel \ell^{BB'} \parallel \ell^{CC'}$; (b) For lines which are cutting in a single point $P$,  $\ell^{AA'} \cap \ell^{BB'} \cap \ell^{CC'}=P$.}
		\label{fig:DesarguesAxiom}
\end{figure}
Then $\boldsymbol{\ell^{AC}\parallel \ell^{A'C'}}$.  

\noindent A {\bf Desargues affine plane} is an affine plane that satisfies Desargues' Axiom. 
\begin{notation}
Three vertexes $ABC$ and $A'B'C'$, which, fulfilling the conditions of the Desargues Axiom, we call \emph{'Desarguesian'}.
\end{notation}

\textbf{Addition and Multiplication of points in a line of Desargues affine plane \cite{ZakaThesisPhd}:}
The process of construct the points $C$ for addition (Figure \ref{fig:FigureAdMult} (a)) and multiplication (Figure \ref{fig:FigureAdMult} (b)) of points in $\ell^{OI}-$line in affine plane, is presented in the tow algorithmic form  
\begin{multicols}{2}
\textsc{Addition Algorithm}
\begin{description}
	\item[Step.1] $B_{1}\notin \ell^{OI}$
	\item[Step.2] $\ell_{OI}^{B_{1}}\cap \ell_{OB_{1}}^{A}=P_{1}$
	\item[Step.3] $\ell_{BB_{1}}^{P_{1}}\cap \ell^{OI}=C(=A+B)$
\end{description}

\textsc{Multiplication Algorithm}
\begin{description}
	\item[Step.1] $B_{1}\notin \ell^{OI}$
	\item[Step.2] $\ell_{IB_{1}}^{A}\cap \ell^{OB_{1}}=P_{1}$
	\item[Step.3] $\ell_{BB_{1}}^{P_{1}}\cap \ell^{OI}=C(=A\cdot B)$
\end{description}
\end{multicols}
\begin{figure}[htbp]
\centering%
\includegraphics[width=0.92\textwidth]{2}
\caption{ (a) Addition of points in a line in affine plane, 
(b) Multiplication of points in a line in affine plane}
\label{fig:FigureAdMult}
\end{figure}
In \cite{ZakaThesisPhd} and \cite{FilipiZakaJusufi}, we have prove that $(\ell^{OI}, +, \cdot)$ is a skew field in Desargues affine plane, and is field (commutative skew field) in the Papus affine plane.
\begin{definition} \label{ratio2points}
\cite{ZakaPeters2022DyckFreeGroup} Lets have two different points $A,B \in \ell^{OI}-$line, and $B\neq O$, in Desargues affine plane. We define as ratio of this tow points, a point $R\in \ell^{OI}$, such that,
\[R=B^{-1}A, \qquad \text{ we mark this, with,} \qquad 
R=r(A:B)=B^{-1}A
\]
\end{definition}
For a 'ratio-point' $R \in \ell^{OI}$, and for point $B\neq O$ in line $\ell^{OI}$, is a unique defined point, $A \in \ell^{OI}$, such that $R=B^{-1}A=r(A:B)$.
\begin{figure}[htbp]
	\centering
		\includegraphics[width=0.75\textwidth]{ratio2point}
	\caption{Ilustrate the Ratio-Point, of 2-Points in a line of Desargues affine plane $R=r(A:B)=B^{-1}A$.}
