\begin{theorem} \label{thm.33}
In the cross-ratio-maps-set $\mathcal{R}^{C}_4=\left\{f_C(X)=c_r(A,B;X,D) | \quad \forall X \in \ell^{OI} \right\}$, for three elements $f_C(X)$, $f_C(Y)$, $f_C(Z)$ of its, have true, that equations
\begin{enumerate}
	\item $f_C(X)\cdot [f_C(Y)+f_C(Z)]=f_C(X)\cdot f_C(Y) +f_C(X)\cdot f_B(Z)$, and,
	\item $[f_C(X)+f_C(Y)]f_C(Z)=f_C(X)\cdot f_C(Z) +f_C(Y)\cdot f_C(Z)$
\end{enumerate}
\end{theorem}
\proof In the same way as Theorem \ref{thm.13}.
\qed


