\begin{theorem}\label{thm.42}
Let's have three different points $A,C,D$ and different for point $O$, in  $\ell^{OI}-$line. The cross-ratio map set with multiplication of points in a line of Desargues affine plane $\left( \mathcal{R}^{B}_4, \cdot \right)$ is  Group.
\end{theorem}
\proof
\textbf{1.} Associative properties prove similar to Theorem \ref{thm.12} 


\textbf{2.} ('unitary') $\exists E \in \ell^{OI}, \forall X \in \ell^{OI}$, we have that:
\[
f_D(X)\cdot f_D(E)=f_D(X)\]
so, 
\[
\{[(A-X)^{-1}(B-X)][(B-C)^{-1}(A-C)] \}
 \cdot \{[(A-E)^{-1}(B-E)][(B-C)^{-1}(A-C)] \}  \]
\[ =[(A-X)^{-1}(B-X)][(B-C)^{-1}(A-C)]\]
Both elements $f_D(X), f_D(E)$ are points in the line $\ell^{OI}$, we also know that the unitary element related to the multiplication of points in $\ell^{OI}-$ line is \emph{unique point} $I$, for this reason we have $f_D(E)=I$. We see that, for $E=C$, we have,
\[
\begin{aligned}
f_D(E)=f_D(C) \\
&=[(A-C)^{-1}(B-C)][(B-C)^{-1}(A-C)]\\
&=(A-C)^{-1}[(B-C)(B-C)^{-1}](A-C)\\
&=(A-C)^{-1}[I](A-C)\\
&=(A-C)^{-1}(A-C)\\
&=I.
\end{aligned}
\]
so unitary-element element is $f_D(C)$.

\textbf{3.} ('inverse') $\forall X \in \ell^{OI}, \exists Y \in \ell^{OI}$, we have that:
\[
f_D(X)\cdot f_D(Y)=I=f_D(C)\]
so,
\[
f_B(X)\cdot f_B(Y)=I\Rightarrow f_B(Y)=\{f_B(X) \}^{-1} \]
\[
\{[(A-X)^{-1}(B-X)][(B-C)^{-1}(A-C)] \}
 \cdot \{[(A-Y)^{-1}(B-Y)][(B-C)^{-1}(A-C)]\}=I, \]
%\[  =[(A-D)^{-1}(A-D)][(A-C)^{-1}(A-C)]=I\]
hence,
\[
[(A-Y)^{-1}(B-Y)][(B-C)^{-1}(A-C)]=\{ [(A-X)^{-1}(B-X)][(B-C)^{-1}(A-C)] \}^{-1} \]
\[
=\{[(B-C)^{-1}(A-C)]\}^{-1}\{[(A-X)^{-1}(B-X)]\}^{-1} \]
\[f_D(Y) =[(A-C)^{-1}(B-C)][(B-X)^{-1}(A-X)] \]
Hence,
\[ \{f_D(X) \}^{-1}=c_r(A, B; X,C) \]
\qed

