\section{Preliminaries}

We work over the field of complex numbers $\mathbb{C}$. All varieties are assumed to be quasi-projective over $\mathbb{C}$. We adopt the standard notations and definitions in birational geometry as in \cite{KM98} and \cite{BCHM10}, and use them freely throughout the paper. The coefficient of a prime divisor $D$ in an $\R$-divisor $M$ is denoted by $\mu_D M$.


\subsection{Basic definitions} We begin by recalling some basic definitions and notations related to foliations and b-divisors, and define generalized foliated quadruples, following \cite{CS21,HL23,CHLX23}.

\begin{definition}[Foliations]

Let $X$ be a normal variety. A \textit{foliation} $\cF$ on $X$ is a coherent subsheaf $\cF\subset T_X$ such that
\begin{enumerate}
    \item $\cF$ is saturated in $T_X$, i.e. $T_X/\cF$ is torsion free, and 
    \item $\cF$ is closed under the Lie bracket.
\end{enumerate}
The \textit{rank} of $\cF$ is the rank of $\cF$ as a coherent sheaf and is denoted by $\rank \cF$. The \textit{canonical divisor} of $\cF$ is a Weil divisor $K_\cF$ such that $\cO_X(-K_\cF)\cong \det(\cF)$. 

Let $X$ be a normal variety and $\cF$ be a foliation of rank $r$ on $X$. We may associate $\cF$ to a morphism:
\[
\phi: \Omega_X^{[r]} \to \cO_X(K_\cF),
\]
defined by taking the double dual of the $r$-wedge product of the map $\Omega_X^1 \to \cF^*$, which is induced by the inclusion $\cF \subset T_X$. This yields a map 
\[
\phi': (\Omega_X^{[r]}\otimes \cO_X(-K_\cF))^{**} \to \cO_X, 
\]
and we define the \textit{singular locus}, denoted by $\Sing \cF$, to be the cosupport of the image of $\phi'$. 

\end{definition}



\begin{definition}[Pullbacks]
    Let $X$ be a normal variety and let $\cF$ be a foliation on $X$. Let $f: Y \bir X$ be a dominant map. We denote $f^{-1}\cF$ to be the \textit{pullback} of $\cF$ as in \cite[3.2]{Dru21}. We also say $f^{-1}\cF$ is the \textit{induced foliation} of $\cF$ on $Y$. If $\cF = 0$, then we say $f^{-1}\cF$ is the foliation induced by $f$.  If a foliation $\cG$ is induced by a dominant map, then we say $\cG$ is \textit{algebraically integrable}. If $g: X \bir X'$ is a birational map, then we define the \textit{pushforward} $g_* \cF$ of $\cF$ on $X'$ to be $(g^{-1})^{-1}(\cF)$.
\end{definition}

\begin{definition}[Invariance]


Let $S$ be a subvariety of $X$. We say $S$ is \textit{$\cF$-invariant} if for any open subset $U\subset X$ and any section $\partial \in H^0(U,\cF)$, we have 
$ \partial(\mathcal{I}_{S \cap U}) \subset \mathcal{I}_{S \cap U}$, where $\mathcal{I}_{S \cap U}$ is the ideal sheaf of $S \cap U$. If $D\subset X$ is a prime divisor, we define $\epsilon(D) = 0$ if $D$ is $\cF$-invariant and $\epsilon(D) = 1$ if $D$ is not $\cF$-invariant. 

\end{definition}


\begin{definition}[b-divisors]

Let $X$ be a normal variety, and let $X \bir X'$ is a birational map.
%A \textit{b-divisor} $\bM$ on $X$ is a collection of $\R$-divisors $\{\bM_Y\}$ on birational models $Y$ over $X$ which is compatible with respect with pushdowns. More specifically, for any birational morphism $Y \to X$, there exists an $\R$-divisor $\bM_Y$ such that if $Y'\to X$ is any birational morphism such that $f: Y' \bir Y $ is a morphism, then $\bM_Y = f_*\bM_{Y'}$. 
For any valuation $\nu$ over $X$, we denote by $\nu_{X'}$ the center of $\nu$ on $X'$. A \emph{b-divisor} $\bM$ is a formal sum $\bM = \sum r_\nu \nu$ where $\nu$ are valuations over $X$ and $r_\nu \in \R$, such that $\nu_X$ is a divisor only for finitely many $\nu$. The trace of $\bM$ on $X'$ is defined as 
\[
\bM_{X'} := \sum_{\nu_{X'} \text{ is a divisor}} r_\nu \nu_{X'},
\]
which is an $\R$-divisor on $X'$. If $\bM_{X'}$ is $\R$-Cartier and $\bM_{Y'} = g^* \bM_{X'}$ for any birational morphism $g: Y' \to X'$, then we say $\bM$ \emph{descends} to $X'$, or say $\bM$ is the \emph{closure} of $\bM_{X'}$, and we write $\bM = \overline{\bM_{X'}}$. 


A b-divisor $\bM$ on $X$ is called \textit{b-$\R$-Cartier} if there exists a birational morphism $f:Y \to X$ such that $\bM = \overline{\bM_Y}$. 
In this case, if $\bM_Y$ is nef on $Y$, then we say that $\bM$ is a \textit{b-nef} b-\R-Cartier divisor. If $\bM_Y$ is a Cartier divisor (resp. a $\Q$-Cartier $\Q$-divisor), then we say that $\bM$ is \emph{b-Cartier} (resp. \emph{b-$\Q$-Cartier}).

\end{definition}

\begin{definition}[Restricted b-divisors]\label{def:Restrictedbdiv}

Let $\bM$ be a b-\R-Cartier divisor on $X$. Let $S$ be a prime divisor on $X$ and $\nu: S^\nu \to S$ be the normalization of $S$. Let $f: Y \to X$ be a log resolution of $(X,S)$ such that $\bM$ descends to $Y$. Let $S_Y = f^{-1}_*S$, then there exists a birational morphism $g: S_Y \to S^\nu$ such that $f|_{S_Y} = \nu \circ g$. We define the \textit{restricted b-divisor} $\bM|_{S^\nu}$ of $\bM$ to $S^\nu$ to be the closure of $ \bM_Y |_{S_Y} $. Note that if $\bM$ is nef b-\R-Cartier, then so is $\bM|_{S^\nu}$. Moreover, if $\bM$ is b-Cartier, then so is $\bM|_{S^\nu}$.

\end{definition}

\begin{definition}
Fix $I\subset \R$. We say a b-$\R$-Cartier b-divisor $\bM$ on $X$ is an \textit{$I$-linear combination} of b-Cartier b-divisors, if $\bM = \sum \mu_i\bM^i$ for some b-Cartier b-divisors $\bM^i$ on $X$ and $\mu_i \in I$. Sometimes for simplicity, we may just say that the coefficients $\mu_i$ of $\bM^i$ belong to $I$, or just $\bM \in I$. We also say $\bM_i$ \textit{appears in} $\bM$ if $\mu_i \neq 0$. Note that if $S$ is a prime divisor on $X$ and  $\bM = \sum \mu_i \bM^i$, then $\bM|_{S^\nu} = \sum \mu_i \bM^i|_{S^\nu}$. Thus $\bM\in I$ implies $\bM|_{S^\nu}\in I$.
\end{definition}



\begin{definition}[Generalized foliated quadruples]\label{def:GFQS}

A \textit{generalized foliated sub-quadruple} $(X,\cF,B,\bM)$ (\textit{sub-gfq} for short) consists of a normal variety $X$, a foliation $\cF$ on $X$, an \R-divisor $B$ on $X$, a b-nef b-\R-Cartier b-divisor $\bM$ on $X$, such that $K_\cF + B + \bM_X$ is $\R$-Cartier. If $B\geq 0$, we say $(X,\cF,B,\bM)$ is a \textit{generalized foliated quadruple} (\textit{gfq} for short). If $\bM = \overline{0}$ (and $B \geq 0)$, we drop $\bM$ and say $(X,\cF,B)$ is a \textit{foliated sub-triple} (\textit{foliated triple}). If $B$ ($\geq 0$) is $\Q$-divisor and $\bM$ is b-$\Q$-Cartier, we say $(X,B,\bM)$ is (sub)-$\Q$-gfq.

\end{definition}


\begin{definition}[Singularities]
Let $(X, \cF,B,\bM)$ be a sub-gfq. For any prime divisor $E$ over $X$, suppose $f: Y\to X$ is a birational morphism such that $E$ is a prime divisor on $Y$, then we may write 
\[
K_{\cF_Y} + B_Y + \bM_Y = f^* (K_\cF + B + \bM_X),
\]
where $\cF_Y = f^{-1}\cF$. We define $a(E,\cF,B,\bM) := -\mu_E B_Y$ to be the \textit{discrepancy} of $E$ with respect to $(X,\cF,B,\bM)$. It is easy to see that the definition of $a(E,\cF,B,\bM)$ is independent of the choice of $Y$. If $\bM = \overline{0}$ (resp. $B = 0$), we will drop $\bM$ (resp. $B$) in the notation of discrepancies. If $\cF = T_X$, the definition of the discrepancies coincides with the classical definition of discrepancies for generalized pairs as in \cite{BZ16}. 

For a (sub)-gfq $(X, \cF, B, \bM)$, we say $(X,\cF,B,\bM)$ is \textit{(sub)-log canonical} (\textit{(sub)-lc} for short) if $a(E,\cF,B,\bM) \geq -\epsilon(E)$ for any prime divisor $E$ over $X$. We say $(X,\cF,B,\bM)$ is \textit{(sub)-canonical} (resp. \textit{(sub)-terminal}) if $a(E,\cF,B,\bM) \geq 0$ (resp. $>0$) for any prime divisor $E$ exceptional over $X$. An \textit{lc place} (resp. \textit{non-lc place}) of $(X,\cF,B,\bM) $ is a prime divisor $E$ over $X$ with $a(E,\cF, B,\bM) = -\epsilon(E)$ (resp. $a(E,\cF, B,\bM) < -\epsilon(E)$) . An \textit{lc center} (resp. \textit{non-lc center}) of $ (X,\cF,B,\bM) $ is the center of an lc place (resp. non-lc place) of $(X,\cF,B,\bM)$ on $X$. 
A \textit{non-canonical center} of $(X,\cF,B,\bM)$ is a center of a prime divisor $E$ exceptional over $X$ such that $a(E,\cF,B,\bM)< 0$.

Let $(X, \cF,B,\bM)$ be a gfq, and $P\in X$ be a not necessarily closed point of $X$. We say that $(X,\cF,B ,\bM)$ is lc (resp. canonical, terminal) at $P$ if for every divisor $E$ over $X$ whose center is the Zariski closure $\overline{P}$ of $P$, the discrepancy of $E$ is $\geq -\epsilon(E)$ (resp. $\geq 0$, $>0$). 

\end{definition}

%\textcolor{magenta}{Follow the version in [CHLX23]. Lc: for every divisor over X, terminal/canonical: for every divisor exceptional over X.}



\begin{definition}[Generalized foliated log canonical thresholds]\label{def:GFLCT}
    Let $(X,\cF,B,\bM)$ be a gfq. Let $D\geq 0$ be an effective divisor on $X$ and $\bN$ be a b-nef b-divisor on $X$ such that $D + \bN_X$ is $\R$-Cartier. We define the \textit{generalized foliated log canonical threshold} of $(D, \bN)$   with respect to $(X, \cF, B ,\bM)$ to be 
    \[
    \lct (X,\cF,B,\bM;D,\bN) := \sup \{ \,s \in \R \mid (X,\cF,B + sD, \bM + s\bN)\, \text{is lc}\, \}.
    \]
    If $\cF = T_X$, we may omit $\cF$, and the definition coincides with the generalized lc thresholds for generalized pairs (\cite[Definition 4.3]{BZ16}).
\end{definition}



\subsection{Finite morphism}


In this subsection we consider the finite pullback of gfqs. First we define the pullbcak of b-$\R$-Cartier b-divisor under finite morphisms.

\begin{definition}[Finite pullback]
Let $\bM$ be a b-$\R$-Cartier b-divisor on $X$ and $\sigma:X' \to X$ be a {finite} morphism between normal varieties. If $Y \to X$ is a birational morphism such that $\bM$ descends to $Y$, then let $Y' $ be the normalization of the main component of $X'\times_X Y$, $\sigma': Y' \to Y$ be the induced morphism, and we define the pullback $\sigma^*\bM$ of $\bM$ under $\sigma$ to be the closure of the $\R$-Cartier divisor $\sigma'^*\bM_Y$ on $Y'$. It is easy to see that the definition is independent of the choice of $Y$.
\end{definition}

\begin{lemma}\label{lemma:GFQfinite}
    Let $(X,\cF,B,\bM)$ be a sub-gfq and $\sigma: X' \to X$ be a finite morphism between normal varieties. Let $Z'$ be an irreducible subvariety of $X'$ and let $Z = \sigma(Z')$. Let $\cF' = \sigma^{-1}\cF$ and $\bM' = \sigma^*\bM$. We may write 
    \[
    K_{\cF'} + B' + \bM'_{X'} := \sigma^*(K_\cF + B + \bM_X),
    \]
    which defines a sub-gfq $(X',\cF',B',\bM')$. Then
    \begin{enumerate}
        \item $(X,\cF,B,\bM)$ is sub-lc at the generic point of $Z$ if and only if $(X',\cF',B',\bM')$ is sub-lc at the generic point of $Z'$.
        \item If $(X,\cF,B,\bM)$ is sub-canonical (resp. sub-terminal) at the generic point of $Z$, then  $(X',\cF',B',\bM')$ is sub-canonical (resp. sub-terminal) at the generic point of $Z'$.
        %\item Suppose that any codimension one component of branch locus of $\sigma$ is $\cF$-invariant. Assume that $K_\cF$ is \Q-Cartier and $B \geq 0$ is \R-Cartier. Then $B' \geq 0$.
    \end{enumerate}
\end{lemma}

\begin{proof}
    Let $f: Y \to X$ be a birational morphism such that $\bM$ descends to $Y$ and $E$ be a prime divisor whose center on $X$ is $Z$. Let $Y'$ be the normalization of the main component of $X' \times_X Y$ and $\sigma': Y' \to Y$ and $g: Y' \to X'$ be induced morphisms. Let $E'$ be a prime divisor on $Y'$ which dominates $E$ and has center $Z'$ on $X'$.

    Let $g: Y' \to X'$ be a birational morphism and $E'$ be a $g$-exceptional divisor on $Y'$ centering on $Z'$. By \cite[Lemma 2.22]{Kol13}, there exist a birational morphism $f: Y \to X$ and a finite morphism $\sigma': Y' \to Y$ such that $E = \sigma'(E')$ is a $f$-exceptional prime divisor on $Y$ and is centered on $Z$. After replacing $Y$, $Y'$ by higher models, we may assume that $\bM$ (resp. $\sigma^*\bM$) descends to $Y$ (resp. $Y'$).

    In both cases above, let $ \cF_Y = f^{-1}\cF $ and $\cF_{Y'} =g^{-1}\cF' $. By \cite[Lemma 3.4]{Dru21} (see also \cite[Proposition 2.2]{CS20}),
    \[
    K_{\cF_{Y'}} = \sigma^*K_{\cF_Y}  + \sum \epsilon(\sigma(D))(r_D-1)D,
    \]
    where the sum runs over all prime divisors on $Y'$ and $r_D$ is the ramification index of $\sigma'$ along $D$. Since $\epsilon(E) = \epsilon(E')$ and $\bM'_{Y'} = \sigma'^*\bM_Y$, following the same computation of \cite[Proposition 5.20]{KM98} (see also \cite[Proposition 3.15]{HJLL24}), we have
    \[
    a(E',\cF',B',\bM') + \epsilon(E') = r_{E'} (a(E,\cF,B,\bM) + \epsilon(E)).
    \]
    Thus $a(E',\cF',B',\bM') \geq -\epsilon(E')$ if and only if $a(E,\cF,B,\bM) \geq -\epsilon(E)$. If $a(E,\cF,B,\bM) \geq 0$ (resp. $>0$), then $a(E',\cF',B',\bM') \geq 0$ (resp. $>0$). Note that $E$ is $f$-exceptional if and only if $E'$ is $g$-exceptional. Therefore (1) and (2) follow.
    %In the case of (3), we have $K_{\cF'} = \sigma^*K_\cF $. Since $K_\cF$ and $B$ are $\R$-Cartier, then $\bM_X$ is also $\R$-Cartier, and we may write $\bM_Y+ \Theta =  f^*\bM_X $ where $\Theta \geq 0 $ is $f$-exceptional. Then $\bM'_{Y'} = \sigma'^* \bM_Y = g^*\sigma^*\bM_X-\sigma'^*\Theta$, where $\sigma'^*\Theta$ is $g$-exceptional. By pushing forward to $X'$ we have $\bM'_{X'} = \sigma^*\bM_X$. Therefore $B' = \sigma^* B \geq 0$.
\end{proof}

\subsection{Divisorial adjunction}

We give the subadjunction formula for gfqs along prime divisors.

\begin{proposition}\label{prop:subadj,primediv}
    Let $X$ be a normal variety, $S$ be an prime divisor on $X$. Let $\nu: S^\nu \to S$ be the normalization of $S$. Let $(X,\cF,B,\bM)$ be a gfq of rank $r$ such that $S$ is not contained in $\Supp B$. Assume that $K_\cF + B$  and $ \epsilon(S)S $ are $\R$-Cartier. Then there exists a restricted foliation $\cF_S$ on $S^\nu$ with  $\rank \cF_S = r - \epsilon(S)$, an \R-divisor $B_S\geq 0$ on $S^\nu$, such that
    \[
    %(K_\cF + B + \epsilon(S) S + \bM_X)|_{S^\nu} \sim_\R K_{\cF_{S}} + B_S + \bM^S_{S^\nu},
    (K_\cF + B + \epsilon(S) S + \bM_X)|_{S^\nu} = K_{\cF_{S}} + B_S + \bM^S_{S^\nu},
    \]
    where $\bM^S = \bM|_{S^\nu}$ is the restricted b-divisor.
\end{proposition}

\begin{proof}

    By \cite[Proposition-Definition 3.7]{CS24}, there exists a restricted foliation $\cF_S$ on $S^\nu$ of rank $r -\epsilon(S)$ and  an \R-divisor $B'_{S}\geq 0$ on $S^\nu$ such that 
    \[
    %(K_\cF + B + \epsilon(S)S)|_{S^\nu} \sim_\R K_{\cF_S} + B'_S.
    (K_\cF + B + \epsilon(S)S)|_{S^\nu} = K_{\cF_S} + B'_S.
    \]
    Note that \cite{CS24} only dealt with the case when $B$ is a $\Q$-divisor, but we may write $B$ as a $\R$-linear combination of $\Q$-divisors $B_i \geq 0$ such that $K_\cF + B_i$ is $\Q$-Cartier, so the same argument holds when $B$ is an $\R$-divisor. Since $\bM_X$ is $\R$-Cartier, it suffices to prove that $\bM_X|_{S^\nu} \geq \bM_{S^\nu}^S$. Let $f:Y\to X$ be a log resolution of $(X,S)$ such that $\bM$ descends to $Y$. By the negativity lemma, we may write $\bM_Y + E = f^*\bM_X$ for an $f$-exceptional $\R$-divisor $E \geq 0$. Let $S_Y $ be the strict transform of $S$ to $Y$ and $g: S_Y \to S^\nu$ be the induced morphism. Therefore,
    \begin{align*}
        \bM_{S^\nu}^S &= g_*\bM_{S_Y}^S =g_*(\bM_Y|_{S_Y}) = g_*((f^*\bM_X -E)|_{S_Y}) \\&= \bM_X|_{S^\nu}- g_*(E|_{S_Y}) \leq \bM_X|_{S^\nu}.\qedhere
    \end{align*}
\end{proof}


\subsection{Sets} Let $I\subset \R$ be a set. We say $I$ satisfies DCC (descending chain condition) if it contains no strictly decreasing infinite sequence of numbers. We say $I$ satisfies ACC (ascending chain condition) if it contains no strictly increasing infinite sequence of numbers. In both cases, we also just say that $I$ is a DCC or an ACC set.

\begin{definition}

Let $I \in [0,+\infty)$ be a set. Define 
\[
I_+ := \{0\}\cup \left\{\, \sum_{k=1}^n i_k \,\Bigg|\, i_k \in I, n \in \Z_{>0} \, \right\},
\]
It is clear that $I \subset I_+$. Note that if $I\subset [0,+\infty)$ is a DCC set, then $I_+$ is also a DCC set.

\end{definition}

\begin{lemma}\label{lemma:finiteset}
Let $I\in [0,+\infty)$ be a DCC set and let $\Omega \subset (0,+\infty)$ be a finite set. Then the set 
\[
J :=\left\{\, i\in I \,\Bigg|\, mi + \sum_{k=0}^n m_ki_k \in \Omega,\, \textrm{for some } i_k\in I,\, m\in \Z_{>0},\, n,m_k \in \Z_{\geq 0}  \,\right\}
\]
is finite.
\end{lemma}
\begin{proof}
    We may assume that $\Omega = \{c\}$ for some fixed $c>0$. For $i\in J$, we may write $mi + \sum_{k=0}^n m_ki_k = c$ for some $i_k\in I$, $ m\in \Z_{>0}$, $n,m_k \in \Z_{\geq 0}$. Then 
    \[
    i = \frac{1}{m} \left(c -\sum_{k=0}^n m_ki_k\right).
    \]
    The LHS belongs to $I$, which is a DCC set. Note that $\sum_{k=0}^n m_ki_k \in I_+$, The RHS belongs to an ACC set only depends on $I$ and $c$. Thus $i$ belongs to a finite set.
\end{proof}

\subsection{Convex geometry} We recall some terminology and theorems from convex geometry that will be used in the following proof of the cone theorems. For more details, see \cite[$\S$18]{Roc70}.

\begin{definition}[Exposed rays]

A convex cone $K \subset \R^n$ is said to be \emph{strongly convex} if $K \cap (-K) = \{0\}$. Let $K\subset \R^n$ be a strongly convex cone containing more than just the origin. A ray $R$ is said to be \textit{exposed} if there exists a hyperplane $H$ that meets $K$ exactly along $R$. The hyperplane $H$ is called a \textit{supporting hyperplane} of $R$. A \textit{supporting function} of $R$ is a linear functional $f\in (\R^n)^*$ such that $f(K) \geq 0$ and for $\xi\in K$, $f(\xi) = 0$ if and only if $\xi\in R$. 

\end{definition}

In particular, any exposed ray is extremal, but not vice versa. Assume that $K$ is a closed strongly convex cone containing more than just origin. Then $K$ is generated by its extremal rays, and it is the closure of the subcone generated by its exposed rays. In particular, every extremal ray of $K$ is the limit of a sequence of exposed rays of $K$ (see \cite[Theorem 18.6]{Roc70}).

%We state a lemma concerning the extremal rays of $\NE(X)$ for a normal proper variety $X$, which will be used frequently in the remainder of the paper.

\begin{lemma}\label{lemma:ExtRayPullback}
    Let $h: V \to W$ be a linear map between finite dimensional $\R$-vector spaces, and let $C \subset V$ and $D \subset W$ be two closed strongly convex cones containing more than just the origin. Assume that $f(C) \subset D$. Let $R$ be an extremal ray of $W$ contained in $h(V)$. Then there exists an extremal ray $R'$ of $V$ such that $R' = h(R)$. Moreover, let $L\in W^*$, then $R$ is $L$-trivial (resp. $L$-negative) if and only if $R'$ is $h^*L$-trivial (resp. $h^*L$-negative), where $h^* : W^* \to V^*$ is the dual map.
\end{lemma}

\begin{proof}
    Since $R$ is contained in $h(V)$, we may assume that $R = h(R'')$ for a ray $R''$ in $V$. Since $V$ is closed and strongly convex, it is generated by extremal rays. We may assume $R''$ is generated by $\sum a_i \xi_i$, where $a_i >0$ and $\xi_i$ generates an extremal ray of $V$ for each $i$. Then $R$ is generated by $\sum a_i h(\xi_i)$. Since $R$ is extremal, we have $R$ is generated by $h(\xi_j)$ for some $j$. Let $\xi' = \xi_j$, and we may take $R'$ to be the extremal ray of $V$ generated by $\xi'$. Note that $\langle h^*L,\xi' \rangle = \langle L,h(\xi') \rangle$ by the definition of $h^*$, the last assertion follows.
\end{proof}

In the remainder of the paper, we use Lemma~\ref{lemma:ExtRayPullback} frequently for $h: N_1(Y/S)_\R \to N_1(X/S)_\R$ and the cones of curves, induced by proper morphisms $f: X \to S$ and $g:Y\to X$. By the projection formula, the dual of $h$ is just the pullback of the divisor class $g^*: N^1(X/S)_\R \to N^1(Y/S)_\R$.

\begin{definition}
    Let $X$ be a normal proper variety, and let $R$ be a ray in the cone of curves $\NE(X)$. We define the \emph{locus} of $R$, denoted by $\loc R$, to be the union of all curves $C$ on $X$ such that $[C]\in R$.
\end{definition}

