\subsection{Bend and break} 

We recall the following foliated bend and break lemma originated from \cite{Miy87}, and stated in \cite{Spi20} as follows. 

\begin{theorem}[{\cite[Corollary 2.28]{Spi20}}]\label{thm:B&B}
    Let $X $ be a normal projective variety of dimension n,  $(X,\cF,B)$ be a foliated triple, and $N, D_1, \dots ,D_n$ be nef $\R$-divisors on $X$. Assume that 
    \begin{enumerate}
        \item $D_1 \cdot D_2 \cdot \cdots \cdot D_n = 0$, and
        \item $-(K_\cF + B) \cdot D_2 \cdot \cdots \cdot D_n >0$.
    \end{enumerate}
    Then through a general closed point $x$ of $X$, there is a rational curve $\xi$ tangent to $\cF$ such that $D_1 \cdot \xi = 0$ and 
    \[
    N\cdot \xi \leq 2n \frac{M\cdot D_2 \cdot \cdots D_n}{-K_\cF \cdot D_2 \cdot \cdots \cdot D_n}.
    \]
\end{theorem}




\subsection{Singularities in the sense of McQuillan}

For foliations of rank $1$, we need a slightly different definition of foliation singularities, originated from \cite{McQ04}, \cite{BM16}. We recall the definitions and notations introduced in \cite{CS24}.

\begin{definition}
    Let $X$ be a normal variety, and let $\cF$ be a foliation of rank 1 on $X$ such that $K_\cF$ is $\Q$-Cartier. Let $x\in X$ be a point. We may take an open neighborhood $U$ of $x$, and an index 1 cover $\sigma:U'\to U$ associate to $K_\cF$ such that $\sigma^{-1}\cF$ is generated by a vector field $\partial$. We say $\cF$ is \textit{singular in the sense of McQuillan} at $x \in X$, if there exists an embedding $\partial: U'\to M$ to a smooth variety $M$, such that there exists a lift $\Tilde{\partial}$ of $\partial$ to a vector field of $M$ such that $\Tilde{\partial}$ vanishes along $\sigma^{-1}(x)$. We denote by $\Sing^+\cF$ the locus of points $x\in X$ such that $\cF$ is singular in the sense of McQuillan.
\end{definition}

For a foliation $\cF$ on a smooth variety, it is clear that $\Sing \cF = \Sing^+\cF$. In general, we have $\Sing \cF \subset \Sing^+\cF$ by \cite[Lemma 4.1]{CS24}, provided $K_\cF$ is $\Q$-Cartier. %We recall a lemma relating singularities in the sense of McQuillan and discrepancies.

\begin{comment}



\begin{lemma}[{\cite[Lemma 2.12]{CS20}}] %new version is Lemma 2.9 
    \label{lemma:singplusterminal}Let $X$ be a normal variety and let $\cF$ be a foliation of rank 1 on $X$. Assume that $K_\cF$ is $\Q$-Cartier. Let $P\in X$ be a closed point. Then the following are equivalent:
    \begin{enumerate}
        \item $(X,\cF)$ is terminal at $P$.
        \item $P$ is not contained in $\Sing^+\cF$.
        \item There exists an analytic open neighborhood $U$ of $P$, a quasi-\'etale morphism $q: V\to U$ and a holomorphic submersion $f:V \to B$, such that $q^{-1}(\cF|_U)$ is the foliation induced by $f$.
    \end{enumerate}
    Additionally, if $K_\cF$ is Cartier, these are equivalent to the following:
    \begin{itemize}
        \item[(4)] $P$ is not $\cF$-invariant.
    \end{itemize}

\end{lemma}

\end{comment}


\subsection{Simple singularities}
We recall the definition of simple singularities for foliation of rank 1 on threefolds following \cite{MP13} and \cite{CS20}, which plays an important role in the foliated minimal model program of rank 1 on threefolds. 

\begin{example}[{\cite[Example III.iii.3]{MP13}}]\label{ex:simple}
    Let $Y$ be the quotient of $\C^3$ by the $\Z/2\Z$-action $(x, y, z)\mapsto (y,x,-z)$. We consider the vector field $\partial$ on $\C^3$ given by 
    \[
    \partial = \left( x \partial_x - y \partial_y\right) + \left(a(xy,z)x\partial_x - a(xy,-z)y\partial_y + c(xy,z)\partial_z  \right),
    \]
    where $a$, $c$ are formal functions in two variables and $c$ is not a unit and
    satisfies $c(xy,z) = c(xy,-z)$. Note that $\partial \mapsto -\partial $ under the group action. Therefore $\partial$ defines a foliation $\cG$ on $Y$ with an isolated singularity. Moreover, $(Y,\cG)$ is canonical. 
\end{example}

\begin{definition}[cf. {\cite[Definition 2.24]{CS20}}]
    Let $X$ be a normal threefold and let $\cF$ be a rank 1 foliation on $X$ with canonical singularities. We say that $\cF$ admits a \textit{simple singularity} at $P\in X$ if either
    \begin{enumerate}
        \item $\cF$ is terminal and no component of $\Sing X$ through $P$ is $\cF$-invariant; or
        \item $(X,\cF)$ is formally isomorphic to $(Y,\cG)$ defined in Example~\ref{ex:simple} at $P$; or
        \item $X$ is smooth at $P$.
    \end{enumerate}
    Moreover, we say that $\cF$ has simple singularities if $\cF$ admits a simple singularities at every $P\in X$. 
\end{definition}

\begin{theorem}\label{thm:simpleprop}
    Let $X$ be a normal threefold and let $\cF$ be a foliation of rank $1$ on $X$. Then the following hold:
    \begin{enumerate}
        \item There exists a sequence of weighted blow-ups in foliation invariant centres $p: X' \to X$ such that $p^{-1}\cF$ has simple singularities.
        \item If $\cF$ has simple singularities, then $X$ has cyclic quotient singularities. In particular, $X$ is $\Q$-factorial klt. 
    \end{enumerate}
\end{theorem}
\begin{proof}
    See \cite[III.iii.4]{MP13} and \cite[Lemma 2.26]{CS20}.
\end{proof}

\subsection{Algebraically integrable foliations} In the end of the section, we recall the theory of ($\ast$)-models for algebraically integrable foliations, following \cite{ACSS22} and \cite{CHLX23}. 

\begin{definition}[Property $(\ast)$ gfq, {\cite[Definition 7.2.2]{CHLX23}}]
    Let $(X,\cF,B,\bM)$ be a sub-gfq and let $G \geq 0$ be a reduced divisor on $X$. Let $f:X \to Z$ be a contraction. We say $(X,\cF,B,\bM;G)/Z$ satisfies \textit{Property $(\ast)$} if 
    \begin{itemize}
        \item $\cF$ is induced by $f$ and $G$ is $\cF$-invariant.
        \item $f(G)$ is pure of codimension $1$, $(Z,f(G))$ is log smooth, and $G = f^{-1}(f(G))$.
        \item For any closed point $z \in Z$ and any reduced divisor $\Sigma \geq f(G)$ on $Z$ such that $(Z,\Sigma)$ is log smooth near $z$, then $(X,B+G + f^*(\Sigma - f(G)),\bM)$ is sub-lc over a neighborhood of $z$.
    \end{itemize}
\end{definition}

\begin{definition}[$(\ast)$-models, {\cite[Definition 7.4.1]{CHLX23}}]
    Let $(X,\cF,B,\bM)$ be an algebraically integrable gfq. A \textit{$(\ast)$-modification} of $(X,\cF,B,\bM)$ is a birational morphism $h: (X',\cF',B',\bM;G)/Z \to X$ such that
    \begin{itemize}
        \item $\cF' = h^{-1}\cF$, $B' = h^{-1}_* (B \wedge \Supp B) + F$, where $F$ is the non-$\cF'$-invariant part of $\Exc (h)$.
        \item $X'$ is klt, and $(X',\cF',B',\bM)$ is lc.
        \item $f:X' \to Z$ is an equidimensional contraction.
        \item $(X',\cF',B',\bM;G)/Z$ satisfies Property $(\ast)$.
        \item For any $h$-exceptional prime divisor $E$, $a(E,\cF,B,\bM)\leq -\epsilon (E)$.
    \end{itemize}
    We say that $(X',\cF',B',\bM;G)/Z$ is a \textit{$(\ast)$-models} of $(X,\cF,B,\bM)$. Moreover, if $X'$ is $\Q$-factorial, we say $(X',\cF',B',\bM;G)/Z$ is a $\Q$-factorial \textit{$(\ast)$-models} of $(X,\cF,B,\bM)$.
\end{definition}

\begin{theorem}[Existence of $(\ast)$-models, {\cite[Theorem 2.5.1]{CHLX23}}]\label{Thm:Exist*models}
    Let $(X,\cF,B,\bM)$ be an lc algebraically integrable gfq. Then $(X,\cF,B,\bM)$ has a $\Q$-factorial $(\ast)$-model.
\end{theorem}

We remark that \cite{CHLX23} defines various type of models for algebraically integrable foliations. They states the existence of ACSS models, which are  stronger than $(\ast)$-models, for algebraically integrable lc gfqs, but $(\ast)$-models is enough for our purpose. One may check \cite[II.7, II.8]{CHLX23} for more details, including definitions and the existence theorem of such type of models.

\section{Normal surfaces}\label{section:normalsurfaces} In this section we recall  Mumford's intersection theory on normal surfaces, introduce the notion of surface numerical generalized foliated quadruple, and prove the cone theorem for surface numerical generalized foliated quadruples. In some of the following proofs, we freely use the MMP for foliated surfaces, following \cite{Bru02,McQ08,Bru15}.


\begin{definition}[{\cite[II.b]{Mum61}, cf. \cite{Sak84}}]

Let $S$ be a normal surface, and $f: S' \to S$ be a birational morphism from a $\Q$-factorial normal surface $S'$. Let $\bigcup E_i$ be the exceptional locus of $f$. For any $\R$-Weil divisor $D$, we define the \emph{pullback} $f^*D$ to be 
\[
f^*D := f^{-1}_* D + \sum \alpha_i E_i,
\]
where $ f^{-1}_* D$ is the strict transform of $D$ along $f$ and $\alpha_i$ are uniquely defined by 
$$\left(f^{-1}_*D + \sum \alpha_j E_j\right)\cdot E_i = 0 \quad \text{for all } i.$$
For $\R$-Weil divisors $D_1$ and $D_2$, we define their intersection number to be 
\[
D_1 \cdot D_2 := (f^* D_1)\cdot(f^*D_2). 
\] 
If $D_1$ is $\R$-Cartier, the definition coincide with the classical case. The definition is independent of the choice of the model $S'$. 
%The Mumford's intersection theory gives a bilinear form on $Z_1(S)_\R$, the real space of $1$-cycles (or Weil divisors). 

\end{definition}

\begin{definition}[Cone of curves]

For $\R$-Weil divisors $D_1$ and $D_2$ on a normal surface $S$, we say that $D_1$ and $D_2$ are \emph{numerically equivalent in the sense of Mumford} if $D_1 \cdot C = D_2 \cdot C$ for every curve $C$ on $S$.  
We denote by $N_1^M(S)_{\mathbb{R}}$ the space of numerical equivalence classes of $\mathbb{R}$-Weil divisors on $S$ in the sense of Mumford.  
If $S$ is $\mathbb{Q}$-factorial, then $N_1^M(S)_{\mathbb{R}}$ coincides with $N_1(S)_{\mathbb{R}}$.  
Note that for any birational morphism $f \colon S' \to S$ from a $\mathbb{Q}$-factorial normal surface $S'$, there is a surjective linear map $N_1(S')_{\mathbb{R}} \to N_1^M(S)_{\mathbb{R}}$ induced by the strict transform.  
In particular, $N_1^M(S)_{\mathbb{R}}$ is a finite-dimensional $\mathbb{R}$-vector space. The Mumford's intersection theory gives a non-degenerate bilinear form on $N_1^M(S)_\R$. 
We denote by $\NE^M(S)$ the closed cone in $N_1^M(S)_{\mathbb{R}}$ generated by effective Weil divisors.


\end{definition}

\begin{definition}

For an $\R$-Weil divisor $D$ and an irreducible curve $C$ on $S$, Let $f: S' \to S$ be a birational morphism with $S'$ to be $\Q$-factorial. Let $C' = f^{-1}_*C$. We may define the restriction of $D|_{C^\nu}$  to be  the Weil divisor $j^*f^*D$, where $C^\nu$ is the smooth model of $C$ and $j: C^\nu \to C'$. If $D$ is $\Q$-Cartier, this definition of $D|_{C^\nu}$ coincides with the classical case.

\end{definition}

\begin{definition}
    For an $\R$-Weil divisor $D$ on $S$, we say $D$ is \textit{nef} (resp. \textit{strictly nef}) if $D \cdot C \geq 0$ (\(D \cdot C > 0\)) for any irreducible curve $C$ on $S$, and we say $D$ is \textit{numerically ample} if it is strictly nef and $D^2 >0$.
\end{definition}

\begin{lemma}\label{lemma:bnefonsurface}
    Let $S$ be a normal surface, and let $f:S'\to S$ be a birational morphism of from a normal surface $S'$ to $S$. 
    \begin{enumerate}
        \item Let $\{E_i\}$ be all the irreducible components of the exceptional set of $f$. Then the intersection matrix $(E_i \cdot E_j)$ is negative definite.
        \item If $D'$ is a nef (resp. strictly nef, ample) $\R$-divisor on $S'$, then $D = f_*D'$ is nef (resp. strictly nef, numerically ample). In particular, let $\bM$ be a b-nef b-\R-Cartier divisor on a normal surface $S$, then $\bM_S$ is nef as an $\R$-Weil divisor.
    \end{enumerate}

\end{lemma}

\begin{proof}
    (1) is the normal surface version of Grauert’s contraction criterion theorem \cite[Theorem 1.2]{Sak84}. For (2), assume that $D'$ is nef on $S'$. We may write 
    \[
    D' + E^+ - E^- = f^*D,
    \]
    where $E^+$, $E^- \geq 0$ are $f$-exceptional divisors with no common components. Since $(f^*D)\cdot E_i = 0$ for each $i$ and $D'$ is  nef, $(E^+ -E^-) \cdot E_i \leq 0$ for each $i$. In particular, $(E^+ - E^-) \cdot E^- \leq 0$. On the other hand, by (1) we have 
    \[
    0 \geq (E^+ - E^-) \cdot E^- = E^+ \cdot E^- - (E^-)^2 \geq 0.
    \]
    Hence the equality holds which implies $E^- = 0$. For any irreducible curve $C$ on $S$, let $C' = f^{-1}_*C$. Since $C'$ is not exceptional, $E^+ \cdot C'\geq 0$, then we have
    \begin{align*} 
        D\cdot C =  (f^* D ) \cdot C' = D' \cdot C' + E^+ \cdot C' \geq D' \cdot C' \geq  0.
    \end{align*}
    Therefore $D$ is nef. If $D'$ is strictly nef, then $D\cdot C \geq  D'\cdot C' >0$. If $D'$ is ample, then 
    \begin{align*}
        D^2 = D' \cdot f^*D = D'\cdot (D' + E^+) = D'^2 + D'\cdot E^+ \geq D'^2 >0. 
    \end{align*}
    We may assume that $\bM$ descends to $S'$ and we may conclude.
\end{proof}

\begin{definition}[Surface num-gfqs]\label{def:NumGFQ}
    A \textit{surface numerical generalized foliated sub-quadruple} (\textit{surface sub-num-gfq} for short) $(S,\cF,B,\bM)$ consists of a normal surface $S$, a foliation $\cF$ of rank $1$, an $\R$-divisor $B$, and an b-nef b-divisor $\bM$ on $X$. A surface sub-num-gfq $(S,\cF,B,\bM)$ is called a \textit{surface num-gfq} if $B\geq 0$.

    Let $(S,\cF,B,\bM)$ be an surface num-gfq. For any prime divisor $E$ over $X$, let $f: S'\to S$ be a resolution of $X$ such that $E$ is a divisor on $S'$. Let $\cF_{S'} = f^{-1}\cF$, and we may write
    \[
    K_{\cF_{S'}} + B_{S'} + \bM_{S'} = f^*(K_\cF + B + \bM),
    \]
    where the pullback is defined in the sense of Mumford. We define the discrepancy to be  \[a_{num}(E,\cF,B,\bM) := -\mu_E B_{S'}.\] By \cite[Definition 6.4.9]{CHLX23}, this definition is independent of the choice of the resolution and if $(S,\cF,B,\bM)$ is a sub-gfq, then $a_{num}(E,\cF,B,\bM) = a(E,\cF,B,\bM)$. We say a surface num-gfq $(S,\cF,B,\bM)$ is lc if $a
    _{num}(E,\cF,B,\bM) \geq -\epsilon(E)$ for any prime divisor $E$ over $X$.
\end{definition}

%definition of Z(\cF,C)? 

\begin{lemma}\label{lemma:surfacemodel}
Let $S$ be a normal surface and let $\cF$ be a foliation on $S$. Then there exists a birational morphism $g: S'\to S$ such that we may write 
\[
K_{\cF'}+ \Delta' = g^* K_\cF, 
\]
where the pullback is defined in the sense of Mumford, $\cF'=g^{-1}\cF$ such that $(S',\cF')$ is canonical and $\Delta' \geq 0$ is a $\Q$-divisor exceptional over $S$. Moreover, $S'$ has cyclic quotient singularities.
\end{lemma}

\begin{proof}
    Take a resolution $f: X \to S$ of $S$ such that $\mathcal{G} = f^{-1}\cF$ has reduced singularities. We may write
    $
    K_{\mathcal{G}} + \Delta = f^*K_\cF.
    $
    By \cite[Corollary 2.26]{Spi20}, we may run a $K_{\mathcal{G}}$-MMP over $S$, and assume the MMP terminates on $S'$. Let $g:S' \to S$ be the induced morphism and $\alpha:X\to S'$ be the composition of each step of the MMP. Let $\cF' = g^{-1}\cF$ and  $\Delta' = \alpha_*\Delta$, then we have $K_{\cF'} + \Delta' = g^*K_\cF$. Note that $\Delta' = -K_{\cF'} + g^*K_\cF$ is exceptional over $S$ and anti-nef over $S$, we have $\Delta' \geq 0$ by Lemma~\ref{lemma:bnefonsurface}. Moreover, $(S',\cF')$ is canonical as $(X,\cG)$, with reduced singularities, is canonical.% and $S'$ has cyclic quotient singularities as the output of MMP. 
\end{proof}

\begin{proposition}\label{prop:surfnum}
    Let $S$ be a normal projective surface and $(S,\cF,B,\bM)$ be a surface num-gfq. Let $C \subset S$ be a irreducible curve not contained in $\Supp B$. Then:
    \begin{enumerate}
        \item If $C$ is not $\cF$-invariant, then $(K_\cF + B + C + \bM_S)\cdot C \geq 0 $.
        \item If $C$ is $\cF$-invariant, and $(K_\cF + B + \bM_S) \cdot C <0 $, then $C$ is a rational curve, and $0 <-(K_\cF + B + \bM_S)\cdot C \leq 2$.
    \end{enumerate}
\end{proposition}

\begin{proof}
For (1), by Lemma~\ref{lemma:bnefonsurface}, we have $\bM_S \cdot C \geq 0$. Since $C$ is not contained in $\Supp B$, we also have $B \cdot C \geq 0$.  
Thus, it remains to show that $(K_\cF + C) \cdot C \geq 0$. The proof is similar to \cite[Proposition 3.4]{Spi20}, but we present a complete proof for the reader’s convenience.
Let $\mu:Y \to S$ be a log resolution of $(X,C)$ and let $\cG = \mu^{-1}\cF$. Possibly replacing $\mu$ with a higher resolution we may assume that $\cG$ has reduced singularities. Let $C_Y = \mu^{-1}_* C$. By \cite[Corollary 2.2]{Spi20}, we may run a $(K_\cG + C_Y)$-MMP over $S$, which terminates on $\pi:X \to S$. 

We claim that this MMP only contracts curves $E$ which are disjoint from the strict transform of $C$. We apply induction on the number of steps of this MMP. Let $Y \to Y'$ be an intermediate step of the MMP, let $\cG'$ be the transformed foliation on $Y'$, and let $C_{Y'}$ be the strict transform of $C$ on $Y'$. Note that by induction $Y'$ is smooth in a neighborhood of $C_{Y'}$, then for any curve $E$ intersects $C_{Y'}$ we have $ C_{Y'}\cdot E\geq 1$. On the other hand, the relative MMP only contracted curves $E$ such that $(K_{\cG'} + C_{Y'})\cdot E <0$ and $0>K_{\cG'}\cdot E \geq -1$, then the contracted curve cannot intersect with $C_{Y'}$.

Let $\cF_X = \pi^{-1}\cF$ and $C_X = \pi^{-1}_* C$. Since $K_{\cF_X} + C_X$ is nef over $S$, by Lemma~\ref{lemma:bnefonsurface}, we may write 
\[
K_{\cF_X} + C_X + \Gamma = \pi^*(K_\cF + C),
\] 
where $\Gamma \geq 0$ is exceptional over $S$. Therefore
\[
(K_\cF + C)\cdot C  = \pi^*(K_\cF + C) \cdot C_X = (K_{\cF_X} + C_X + \Gamma) \cdot C_X \geq 0,
\]
where the last inequality holds by \cite[Proposition-Definition 3.7]{CS24} and the fact that $X$ is smooth in a neighborhood of $C_X$.


For (2), since $B \cdot C \geq 0$ and $\bM_S \cdot C \geq 0$, we have $K_\cF \cdot C <0$. By Lemma~\ref{lemma:surfacemodel}, there exists a birational morphism $g:S'\to S$ such that $K_{\cF'} + \Delta' = g^*K_\cF$ where $\Delta' \geq 0$ is exceptional over $S$ and $\cF' = g^{-1}\cF$ has canonical singularities. Let $C'$ be the strict transform of $C$ to $S'$. then $0 > K_{\cF}\cdot C = g^*K_\cF \cdot C' = (K_{\cF'}+ \Delta')\cdot C'\geq K_{\cF'} \cdot C' $. Then $C'$ is $K_{\cF'}$-negative, then we have
\[
0 > K_{\cF'} \cdot C' = 2p_a(C')-2 + Z(\cF',C').
\]
We refer the reader to \cite[\S 2]{Bru02} for the definition of $Z(\cF',C')$. Since $\cF'$ is canonical, we have $Z(\cF',C') \geq 0$. Therefore $C'$ is a rational curve and so is $C$. Moreover, $K_{\cF'}\cdot C'\geq -2 $, and $(K_\cF + B + \bM_S) \cdot C \geq K_\cF \cdot C \geq K_{\cF'} \cdot C' \geq -2$.
%see Liu19 Lemma 4.2
\end{proof}



