In the end of this section we give the cone theorem for the surface num-gfq, which generalizes \cite[Theorem 6.3]{Spi20}.

\begin{proposition}\label{prop:conethmnumgfq}
    Let $S$ be a normal projective surface and $(S,\cF,B,\bM)$ be a rank $1$ surface num-gfq. Let $f:X \to S$ be the minimal resolution of $S$. Let $Z_{-\infty}$ be the subcone spanned by those prime divisors $D\subset \Supp B$ such that $\mu_D B >\epsilon(D)$. Let $\{R_j\}_{j\in \Lambda}$ be the set of all \( (K_\cF + B + \bM_S) \)-negative extremal rays of $\NE^M(S)$ not contained in $Z_{-\infty}$. Then the following hold:
    \begin{enumerate}
    \item We may write 
    \[
        \NE^M (S) = \NE^M(S)_{K_\cF + B + \bM_S\geq 0} + Z_{-\infty} + \sum_{j \in \Lambda} R_j.
    \]
    \item For each $j \in \Lambda$, $R_j$ is generated by a rational curve $C_j$ which is tangent to $\cF$, and 
    \[
    0 < -(K_\cF + B + \bM_S) \cdot C_j \leq 2.
    \]
    \item For each ample $\R$-divisor $A'$ on $X$, let $A = f_* A'$. Then the set 
    \[
    \Lambda_A :=\{\, j \in \Lambda \mid R_j \subset \NE^M(S)_{K_\cF + B + \bM_S +A < 0} \, \}
    \]
    is finite.
    \item Every $(K_\cF + B + \bM_S)$-negative extremal ray is generated by an irreducible curve.
    \end{enumerate}
\end{proposition}

\begin{proof} Let $R$ be an $(K_\cF+ B + \bM_S)$-negative exposed ray of $\NE^M(S)$.

    \medskip

    \textit{Step 1}.
    In this step we show that $R$ is generated by an irreducible curve $C$. 

    Let $H_R$ be a supporting function to $R$. Then $H_R$,  as an $\R$-Weil divisor, is nef and not numerically trivial. We may write $H_R = K_\cF + B + \bM_S + D$ for some numerically ample $\R$-divisor $D$ on $S$, then $f^*H_R$ is nef, so $H_R^2 = (f^*H_R)^2 \geq 0$.

    First we consider the case when $H_R^2 = 0$. There exists a unique integer $\nu\in\{0,1\}$ satisfying $H_R^\nu \cdot D^{2-\nu} >H_R^{\nu + 1} \cdot D^{1-\nu} = 0$. If $\nu = 0$, set $D_1 = H_R$ and $D_2 = D$. Otherwise set $D_1 = D_2 = H_R$. Then $D_1\cdot D_2 = 0$, $-(K_\cF + B + \bM_S) \cdot D_2 >0$. Since $B \geq 0 $, $\bM_S $ is pseudo-effective and $D_2$ is nef, we have $(B +\bM_S)\cdot D_2 \geq 0$, then $-K_\cF \cdot D_2 > 0$. Set $M = H_R + D = 2H_R-(K_\cF + B + \bM_S)$, then $M$ is nef on $S$.

    Let $D_1'$, $D_2'$, $M'$ be the pullback of $D_1$, $D_2$, $M$ to $X$ respectively. Then $D_1'$, $D_2'$, $M'$ is nef on $X$. Let $\cG = f^{-1}\cF$, then $- K_\cG \cdot D_2' = - K_\cF \cdot D_2 >0$. By Theorem~\ref{thm:B&B} ({\cite[Corollary 2.28]{Spi20}}), there exists a rational curve $C'$ through a general point of $X$, such that $C'$ is tangent to $\cG$, and $D_1' \cdot C' = 0$. Since $C'$ passes through a general point of $X$, let $C = f(C')$, then $C$ is a rational curve on $S$ which tangent to $\cF$. Note that $(K_\cF + B + \bM_S + D) \cdot C = H_R \cdot C = D_1' \cdot C' = 0$, then $R$ is generated by $C$. Also we have $(K_\cF + B + \bM_S) \cdot C < 0$. By Proposition~\ref{prop:surfnum} (2), $0<-(K_\cF + B + \bM_X)\cdot C \leq 2$.


    Now we assume that $H_R^2 > 0$, then $f^*H_R$ is nef and big. We may write $f^*H_R \sim_\R \Gamma' + E'$, where $\Gamma'$ is ample and $E' \geq 0$. Note that $f$ induces a surjective map $f_*: \NE(X)\to \NE^M(S)$. By Lemma~\ref{lemma:ExtRayPullback}, there exists an extremal ray $R'$ with $f_*(R') = R$. We have $(\Gamma' + E') \cdot R' = f^*H_R\cdot R' = H_R \cdot R = 0$, then $E' \cdot R' <0$. Therefore there exists an irreducible curve $C'$ on $X$, which is contained in $\Supp E'$ and generates $R'$. Since $f_*R' = R \neq 0$ in $\NE^M(S)$, $C'$ is not $f$-exceptional. Thus $R$ is generated by $C = f_*C'$. Let $\Gamma = f_*\Gamma'$ and $E = f_* E'$. Since $\Gamma'$ is ample, then we may write $\Gamma' + \Xi = f^*\Gamma$ for some exceptional $\Xi \geq 0$. Since $C'$ is not $f$-exceptional, $\Xi \cdot C'\geq 0$. Then $\Gamma \cdot C = f^* \Gamma \cdot C' = \Gamma' \cdot C' + \Xi \cdot C' >0 $, and since $(\Gamma + E) \cdot C = H_R\cdot C = 0$, we have $E \cdot C<0$, $C^2 <0$. 

    \medskip 

    \textit{Step 2}.
    Now we assume that $R$ is not contained in $Z_{-\infty}$. Let $C$ be an irreducible curve which generates $R$. We prove that $0<-(K_\cF + B + \bM_S) \cdot C \leq 2$. By Step 1, we may assume $H_R^2 >0$ and $C^2 <0$. Then $(S,\cF,B,\bM)$ is lc at the generic point of $C$. If $C$ is not $\cF$-invariant, then since $\mu_C B \leq 1$, we may write $B + tC = \Delta + C$, where $t \geq 0$, $\Delta$ is effective and $C$ is not contained in $\Supp \Delta$. Then by Proposition~\ref{prop:surfnum} (1), $$(K_\cF + B + \bM_S + tC)\cdot C = (K_\cF + \Delta + C + \bM_S)\cdot C \geq 0,$$
    which contradicts with the fact that $C^2 <0$ and that $R$ is $(K_\cF + B + \bM_S)$-negative. Then $C$ is $\cF$-invariant and $C$ is not contained in $\Supp B$. By Proposition~\ref{prop:surfnum} (2), $0<-(K_\cF + B + \bM_S) \cdot C \leq 2$.

    \medskip 

    \textit{Step 3}. In this step we prove (3). Assume $\Lambda_A$ is not a finite set. Let $K = f^*(K_\cF + B + \bM_S)$, and let $A_1',\dots ,A_{\rho}'$ be ample Cartier divisors on $X$ such that $A_1',\dots ,A_{\rho}'$ form a basis for $N^1(X)_\R = N_1(X)_\R$. Here $\rho = \rho(X)$. Let $H' =  \sum_{k=1}^{\rho}A_k'$ and $H = f_*H'$. There exists a sufficiently small $\epsilon >  0 $ such that $A'-\epsilon H' $ is ample. By Lemma~\ref{lemma:bnefonsurface}, we have $\Lambda_A \subset \Lambda_{\epsilon H}$. Thus we may assume that $A' = \epsilon H' = \epsilon \sum_{k=1}^{\rho}A_k'$.

    By \cite[Theorem 18.6]{Roc70}, we may replace $\Lambda_A$ by a countable infinite subset and assume that for each $j\in \Lambda_A$, $R_j$ is a $(K_\cF + B + \bM_S + A)$-negative exposed ray. By Step 1 and 2 above, $R_j$ is generated by $C_j$ with $(K_\cF + B + \bM)\cdot C_j \in [-2,0)$. Let $C_j' = f^{-1}_*C_j $. Then $K \cdot C_j' = (K_\cF + B + \bM_S)\cdot C_j \in [-2,0)$.  For each $j\in \Lambda_A$, there exists a numerically ample $L_j$ on $S$, such that $H_j = (K_\cF + B +\bM_S + A)+ L_j$ is a supporting function of $R_j$. Then $H_j \cdot C_j = 0$, and we have
    \begin{align*}
        0 &= H_j \cdot C_j = ((K_\cF + B +\bM_S + A)+ L_j)\cdot C_j \\
        &=f^*(K_\cF + B + \bM_S + A)\cdot C_j' + L_j \cdot C_j \\
        &=(K + f^*A)\cdot C_j' + L_j \cdot C_j \geq (K + f^*A)\cdot C_j' \\
        &= K \cdot C_j' + (A' + \Theta)\cdot C_j'\geq K \cdot C_j' + A' \cdot C_j' \\
        &\geq  -2 + \epsilon\sum_{k=1}^{\rho}(A_k' \cdot C_j').
    \end{align*}
    where $f^*A = A' + \Theta$, $\Theta\geq 0$ is exceptional over $S$. Therefore, $(A_k '\cdot C_j')\in(0, \frac{2}{\epsilon}]$ for each $k$. Since for each $k$, $A_k'$ are ample Cartier divisors, $(A_k '\cdot C_j')\in \Z$. After replacing $\Lambda_A$ with a countable infinite subset, we may assume that the values of $(A_k '\cdot C_j')$ are independent of $j$. Thus for every $j, j'\in\Lambda_A$, $C_{j}'\equiv C_{j'}'$, then $C_j \equiv C_{j'}$, which leads to a contradiction. Thus (3) follows.

    \medskip

    \textit{Step 4.} In this step we finish the proof. It suffices to show that for every $j \in \Lambda$, $R_j$ is exposed. If $R_j$ is extremal but not exposed, we may assume $R_j$ is $(K_\cF + B + \bM_S + A)$-negative, where $A$ is the pushforward of some sufficiently small ample $\R$-divisor on $X$. By \cite[Theorem 18.6]{Roc70}, there exist exposed rays $\{R_{j,i}\}_{i=1}^\infty$ such that $R_j = \lim_i R_{j,i}$. By (3), $\Lambda_A$ is finite, then we may assume that $R_{j,i}\in Z_{-\infty}$ for all $i$. Since $Z_{-\infty}$ is closed, we have $R_j\subset Z_{-\infty}$, which is a contradiction. Thus by Step 1 and 2, (1) and (2) follow. (4) follows from Step 1 and the fact that $Z_{-\infty}$ is spanned by finitely many irreducible curves. 
\end{proof}

\section{Cone theorem}



\subsection{Invariant curves} 
First we state a lemma concerning blow-ups along invariant curves.
%First we give a lemma which generalizes \cite[Lemma 1.1.3]{BM16}.

\begin{lemma}\label{lemma:inv.blowup}
    Let $\cF$ be a foliation of rank $1$ on a normal variety $X$ such that $K_\cF$ is $\Q$-Cartier. 
    Let $f: \Tilde{X}\to X$ be a blow-up along an $\cF$-invariant center $C$ of $X$ and let $\Tilde{\cF} = f^{-1}\cF $. 
    Then if we write 
    \(
    K_{\Tilde{\cF}} + E =f^*K_\cF,
    \) 
    where $E$ is an $f$-exceptional $\Q$-divisor, then $E \geq 0$.
\end{lemma}

\begin{proof}
    It is a local statement for each point $x\in X$.  After possibly replacing $X$ by a neighborhood of $x$, we may assume that there exists a quasi-étale Galois cover $\sigma: Y \to X$ with the Galois group $G$ such that if $\cG = \sigma^{-1}\cF$, we have $K_\cG$ is Cartier. Let $\Tilde{C} = \sigma^{-1}(C)$, then $\Tilde{C}$ is $\cG$-invariant by \cite[Lemma 4.2]{CS24}.
    %Let $\Tilde{Z} = \sigma^{-1}(Z)$, then $\Tilde{C}$ is $\cG$-invariant by \cite[Lemma 2.3]{CS20}.
    %We may assume that $\sigma$ is étale in a neighborhood of the generic point of $C$, then $\Tilde{C}$ is $\cG$-invariant by \cite[Lemma 2.3]{CS20}.
    %\sigma is quasi-etale. This is Lemma 2.3 in the new (personal commu.) version of CS20.
    Let $ p:\Tilde{Y} \to Y $ be the blow-up along $\Tilde{C}$, then it induces a morphism $\alpha: \Tilde{Y} \to \Tilde{X}$. Let $\Tilde{\cG} = p^{-1}\cG$. By \cite[Lemma 1.1.3]{BM16}, $K_{\Tilde{\cG}}+ \Tilde{E} = p^*K_{\cG}$ for some $\Tilde{E}\geq 0$. Since $p$ is $G$-equivariant, Let $X' =\Tilde{Y}/G$, we have the quotient map $\pi: \Tilde{Y} \to  X'$ and there exists a birational morphism $q: X' \to X$. By \cite[Lemma 3.4]{Dru21} (see also \cite[Proposition 2.2]{CS20}), then $K_{\cF'} + E' = q^*K_\cF$ where $\cF' = q^{-1}\cF$ and $E' \geq 0$. Let $U = X\setminus Z$, then $p$ is isomorphic along $\sigma^{-1}(U)$. For any $g \in G$, let $\phi_g$ be the automorphism of $\Tilde{Y}$ induced by the action of $g$. Note that $\alpha\circ \phi_g$ coincides with $\alpha$ along $p^{-1}(\sigma^{-1}(U))$, hence also along $\Tilde{Y}$. Then there exists a birational morphism $h: X' \to \Tilde{X}$ with $h\circ \pi = \alpha$ and $q$ factors through $h$. Thus $E = h_*E' \geq 0$.
\end{proof} 

Now we give a proposition that shows the b-divisor has non-negative degree along invariant curves, provided that the generalized foliated quadruple is log canonical. This is a key step in the proof of the following cone theorem and in the construction of the MMP for generalized foliated quadruples on threefolds of rank $1$.

\begin{proposition}\label{proposition:bdivoncurve}

    Let $X$ be a normal projective $\Q$-factorial variety and $(X, \cF, B, \bM)$ be a rank 1 gfq. Let $C $ be an $\cF$-invariant curve. Assume that $(X, \cF, B, \bM)$ is lc at the generic point of $C$. Then $\bM_X \cdot C \geq 0$.
\end{proposition}

\begin{proof}
    %Since $(X,\cF,B,\bM)$ is lc at the generic point of $C$, then $(X,\cF,B)$ is also lc at the generic point of $C$. By \cite[Lemma 4.7]{CS24}, $(K_\cF + B )\cdot C \geq 0$ and $C$ is not contained in $\Supp B$. We claim that $\bM_{X} \cdot C \geq 0$.

    %2nd version

    %Let $b: X' \to X$ be the blow-up of $X$ along $C$. Since $C$ is $\cF$-invariant, there exists a $b$-exceptional $\Q$-divisor $E_1\geq 0$ with $K_{\cF'} +E_1 = b^*K_\cF$ by Lemma \ref{lemma:inv.blowup}, where $\cF' = b^{-1}\cF$. Let $B' = b^{-1}_*B$, then $B' +E_2 = b^*B$ for some $b$-exceptional $\R$-divisor $E_2 \geq 0$. Furthermore, by the negativity lemma, there exists a $b$-exceptional  $\R$-divisor $E_3\geq 0$ with $\bM_{X'} + E_3 = b^*\bM_X$. Therefore if we let $\Gamma = E_1 + E_2 + E_3$, then $\Gamma \geq 0$ and $K_{\cF'} + B' + \bM_{X'} + \Gamma = b^*(K_\cF + B + \bM_X)$. 

    %Let $E$ be a irreducible component of $\Exc (b)$ which dominates $C$. We claim that $E$ is not contained in $\Supp E_3$. If $\cF$ is canonical at the generic point of $C$, then $E$ is $\cF'$-invariant by \cite[Corollary III.1.4]{MP13}. The lc condition implies $\mu_E\Gamma \leq \epsilon(E) = 0$, $E$ is not contained in $\Supp \Gamma$, and the claim follows. Otherwise if $\cF$ is not canonical at the generic point of $C$, then by \cite[Fact III.1.3]{MP13} $a(E,\cF,0,\overline{0}) = -1$, which means $\mu_E E_1 = 1$. The lc condition gives $\mu_E \Gamma \leq \epsilon(E) = 1$, which implies that $ E $ is not contained in $\Supp E_3$.

    \textit{Step 1.} We claim that there exists a birational morphism $f: {X'} \to X$ such that the following hold:
    \begin{enumerate}
        \item $\bM_{X'} + F = f^*\bM_X$, where $F\geq 0$ is an $f$-exceptional $\R$-divisor on $X'$, and 
        \item there exists a prime divisor $E$ on $X'$ such that the center of $E$ on $X$ is $C$, and $E$ is not contained in $\Supp F$.
    \end{enumerate}
    First we show that it suffices to prove the claim above. Let $g: X'' \to X'$ be a birational morphism such that $X''$ is smooth and $\bM $ descends to $X''$. Let $\bM_{X''} + \Theta = g^*f^*\bM_X$. By the negativity lemma, we have $\Theta \geq 0$. Note that $F = g_*\Theta$. Let $E'$ be the strict transform of $E$ on $X''$, then $E'$ is not contained in $\Supp \Theta$. Take a general curve $C' \subset E'$ which dominates $C$. Then $\Theta \cdot C' \geq 0$ as $C'$ is not contained in $\Supp \Theta$. Let $d$ be the degree of the map $C' \to C$. Thus
    \begin{align*}
        \bM_{X} \cdot C = \frac{1}{d} (g^*f^*\bM_X \cdot C') = \frac{1}{d} (\bM_{X''}\cdot C' + \Theta\cdot C' )  \geq 0.
    \end{align*}

    \medskip

    \textit{Step 2.} In this step we prove the claim in Step 1 when $\cF$ is canonical at the generic point of $C$. Let $b: Y \to X$ be the blow-up of $X$ along $C$. Since $C$ is $\cF$-invariant, there exists a $b$-exceptional $\Q$-divisor $E_1\geq 0$ with $K_{\cF_Y} +E_1 = b^*K_\cF$ by Lemma~\ref{lemma:inv.blowup}, where $\cF_Y = b^{-1}\cF$. Let $B_Y = b^{-1}_*B$, then $B_Y +E_2 = b^*B$ for some $b$-exceptional $\R$-divisor $E_2 \geq 0$. Furthermore, by the negativity lemma, there exists a $b$-exceptional $\R$-divisor $E_3 \geq 0$ with $\bM_{Y} + E_3 = b^*\bM_X$. Therefore if we let $\Gamma = E_1 + E_2 + E_3$, then $\Gamma \geq 0$ and $K_{\cF_Y} + B_Y + \bM_{Y} + \Gamma = b^*(K_\cF + B + \bM_X)$. Let $D$ be a irreducible component of $\Exc (b)$ which dominates $C$. Since $\cF$ is canonical at the generic point of $C$, we have $D$ is $\cF'$-invariant by \cite[Corollary III.i.4]{MP13}. The lc condition implies $\mu_D\Gamma \leq \epsilon(D) = 0$, then $D$ is not contained in $\Supp \Gamma$ therefore also not contained in $\Supp E_3$. Thus the claim in Step 1 holds for $b: Y \to X $ and $D$. Note that $a(D,\cF) = -\mu_D E_1 = 0$.

    \medskip

    \textit{Step 3.} Now we may assume that $\cF$ is not canonical at the generic point of $C$. We may take a finite cover $\pi: \overline{X}\to X$ such that near the generic point of $C$, $\pi$ is quasi-\'etale and $\pi^*K_\cF$ is Cartier. In particular, let $\overline{\cF} = \pi^{-1}\cF$ and $\overline{C} = \pi^{-1}(C)$, then $K_{\overline{\cF}}$ is Cartier near the generic point of $\overline{C}$. By Lemma~\ref{lemma:GFQfinite}, $K_{\overline{\cF}}$ is lc at the generic point of $\overline{C}$. We show that $\overline{\cF}$ is not canonical at the generic point of $\overline{C}$. Otherwise, by \cite[Corollary III.i.4]{MP13}, every exceptional prime divisor centered on $\overline{C}$ would be invariant. However, since $\cF$ is lc but not canonical at the generic point of $C$, there exists an exceptional prime divisor $E$ over $X$ centered on $C$ such that $\epsilon(E) = 1$ and $a(E,\cF) <0$. Let $\alpha: W \to X$ be a birational morphism such that $E$ is a prime divisor on $W$. Let $\overline{W}$ be the normalization of the main component of $\overline{X}\times_X W$. Let $\overline{E}$ be a prime divisor on $\overline{W}$ which dominates $E$ and has center $\overline{C}$ on $\overline{X}$. Then $\overline{E}$ is a non-invariant prime divisor centered on $\overline{C}$, which leads to a contradiction.

    Since $\overline{\cF}$ is lc but not canonical at the generic point of $\overline{C}$, there exists a birational morphism $\overline{\beta}: \overline{V}\to \overline{X}$ and a prime divisor $\overline{D}$ on $\overline{V}$ centered on $\overline{C}$ such that $\epsilon(\overline{D}) = 1$ and $a(\overline{D},\overline{\cF}) <0$. Since $K_{\overline{\cF}}$ is Cartier near the generic point of $C$, $a(\overline{D}, \overline{\cF})$ would be an integer, so it must equal to $-1$ (see also \cite[Fact III.i.3]{MP13}). By \cite[Lemma 2.22]{Kol13}, there exist a birational morphism $\beta : V \to X$ and a finite morphism $p: \overline{V} \to V$ such that $D = p(\overline{D})$ is a $\beta$-exceptional prime divisor on $V$ and is centered on $C$. Recall the computation in Lemma~\ref{lemma:GFQfinite}, we have 
    $$a(\overline{D},\overline{\cF}) + \epsilon(\overline{D}) = r_D(a(D,\cF) + \epsilon(D)),
    $$
    where $r_D$ is the ramification index of $p$ along $D$. Since $ a(\overline{D},\overline{\cF}) = -1$ and $\epsilon(\overline{D}) = \epsilon(D) = 1$, we have $a(D,\cF) = -1$. 

    Let $\cF_V = \beta^{-1}\cF$. Similarly to Step 2, we may write $K_{\cF_V} + F_1 = \beta^*K_\cF$, $B_V + F_2 = \beta^*B$, where $B_V= \beta^{-1}_*B$, and $\bM_V + F_3 = \beta^*\bM_X$. We have $F_2, F_3\geq 0$ and $\mu_D(F_1) = -a(D,\cF) = 1$. Since $(X,\cF,B,\bM)$ is lc at the generic point of $C$, we have 
    \[
    1 = \mu_D(F_1)\leq \mu_D(F_1 + F_2 + F_3) = -a(D,\cF,B,\bM) \leq \epsilon(D) = 1.
    \]
    Thus $D$ is not contained in $\Supp F_3$, and the claim in Step 1 holds for $\beta: V\to X$ and $D$.
    \begin{comment}
