\end{proof}





\subsection{Non-invariant curves}

Let $X$ be a $\Q$-factorial normal variety and $(X, \cF, B, \bM)$ be a gfq of rank 1.  
As in \cite{CS24}, for a non-invariant curve $C$, after replacing $X$ by a suitable birational model $X'$, we aim to find an $\cF$-invariant surface containing $C$.  The following lemma is a variant of \cite[Lemma 4.6]{CS24} with the $\Q$-factoriality condition.


\begin{lemma}\label{lemma:findsurface,Q-fac}
    Let $X$ be a normal $\Q$-factorial variety, let $\cF$ be a foliation of rank $1$ on $X$ such that $K_\cF$ is $\Q$-Cartier. Let $C$ be a curve on $X$ which is not $\cF$-invariant and which is not contained in $\Sing^+ \cF$. Then there exists a birational morphism $p: X' \to X$ such that the following hold:
    \begin{enumerate}
        \item Let $\cF' = p^{-1} \cF$, then $K_{\cF'} + E = p^*K_\cF$, where $E \geq 0$ is a $p$-exceptional divisor;
        \item $p^{-1}$ is an isomorphism at the generic point of $C$, and let $C'$ be the strict transform of $C$ to $X'$, then $\cF'$ is terminal at all points of $C'$; 
        \item after possibly replacing $X$ by an analytic neighborhood of $C$, there exists a $\cF'$-invariant surface $\Gamma$ containing $C'$; and
        \item $X'$ is $\Q$-factorial. 
    \end{enumerate}
\end{lemma}

\begin{proof}
    We mostly follow the proof of \cite[Lemma 4.6]{CS24} and present the full argument for the reader’s convenience. 
    %The only thing we need to specify additionally is the $\Q$-factoriality of $X'$. 
    By \cite[Lemma 2.9]{CS20}, $\cF$ is terminal at general points on $C$.
    Let $P_1,\dots, P_k\in C$ be all the closed points where $\cF$ is not terminal. Let $H$ be a sufficiently general ample divisor on $X$ such that $P_i \notin \Supp H$ for $1 \leq i \leq k$. Let $M$ be the Cartier index of $K_\cF$ and we may assume that $\cO_X(m K_\cF) |_{X\setminus H} \cong \cO_{X\setminus H}$. Then we may find a finite Galois morphism $\sigma:Y \to X$ with Galois group $G$, such that $\sigma $ is quasi-\'etale outside $H$ and $\sigma^*K_\cF$ is Cartier on $Y$. Let $\cG = \sigma^{-1}\cF$, $\Tilde{C} = \sigma^{-1}(C)$, and $Z = \sigma^{-1}(\{P_1,\dots ,P_k\})$. Then $K_\cG$ is Cartier on $Y$ near each closed point $Q \in Z$. By Lemma~\ref{lemma:GFQfinite}, $\cG$ is terminal at every closed points $ Q' \in \Tilde{C} \setminus Z$.

    By the desingularization algorithm in \cite{BM97} 
    %(see also \cite[Theorem 1.2.2]{abramovich_logarithmic_2025})
    , after possibly replacing $X$ by an analytic neighborhood of $C$, there exists a birational morphism $\alpha: \overline{Y}\to Y$, obtained as a sequence of $G$-equivariant blow-ups along $\cG$-invariant centers, such that $\alpha^{-1}$ is an isomorphism near each point of $\tilde{C} \setminus Z$, and if we let $\overline{C}$ to be the birational transform of $\Tilde{C}$ on $\overline{Y}$, $\overline{Y}$ is smooth at each closed point contained in $\overline{C} \cap \alpha^{-1}(Z)$. By \cite[Proposition 1.2.4]{BM16}, there exists a birational morphism $\beta: Y' \to \overline Y$, obtained as a sequence of $G$-equivariant blow-ups along the $\cG$-invariant closed points, such that $\beta^{-1}$ is an isomorphism near each point of $\overline{C}\setminus \alpha^{-1}(Z)$, and the strict transform $\Tilde{C}'$ of $\tilde{C}$ on $Y'$ is disjoint from $\Sing^+\beta^{-1}\alpha^{-1}\cG$. Let $q = \alpha \circ \beta:Y' \to Y$. Note that each step in the sequence of blow-ups that constructs $\beta$ is a blow-up along a closed point over $\overline{C} \cap \alpha^{-1}(Z)$, so $Y'$ is smooth at each point in $\tilde{C}' \cap q^{-1}(Z)$. Let $\cG' = q^{-1}\cG$, then by \cite[Lemma 1.1.3]{BM16}, $K_{\cG'} + E' = q^*K_\cG$ for some $q$-exceptional $E'\geq 0$.

    In the construction above, we see that $q$ is $G$-equivariant. Therefore if $X' = Y'/G$, then there exists a birational morphism $p:X' \to X$ induced by quotient of $q$ by $G$. Let $r: Y' \to X'$ be the quotient map. It follows that $K_{\cF'}+ E = p^*K_\cF$ where $\cF' = p^{-1}\cF$ and $E\geq 0$ is $p$-exceptional by \cite[Lemma 3.4]{Dru21} (see also \cite[Proposition 2.2]{CS20}). Thus (1) follows. 

    Note that $p^{-1}$ is an isomorphism near each point $P\in  C \setminus \{P_1, \dots, P_k\}$. Then $X'$ is $\Q$-factorial near $p^{-1}P$. Let $C'$ be the birational transform of $C$ on $X'$. For any $Q\in C'$ such that $p(Q)\in \{P_1, \dots, P_k\}$, since $Y'$ is smooth at each point of $r^{-1}(Q)$, $X'$ is $\Q$-factorial near $Q$ (see e.g. \cite[Theorem 3.8.1]{Ben93}). Then by \cite[Théorème 6.1]{BGS11}, after possibly shrinking $X$ near $C$, we have $X'$ is $\Q$-factorial, (4) follows. 

    Since $\Tilde{C}'$ is disjoint from $\Sing^+\cG'$, by \cite[Lemma 2.9]{CS20}, $\cG'$ is terminal at all closed points on $\Tilde{C}'$. By \cite[Corollary III.i.4]{MP13}, each exceptional divisor over $Y'$ centered on some closed point on $\Tilde{C}'$ is $\cG'$-invariant. Thus each exceptional divisor over $X'$ centered on some closed point on $C'$ is $\cF'$-invariant. By the computation in Lemma~\ref{lemma:GFQfinite}, $\cF'$ is terminal at all closed points of $C'$, and (2) follows.

    By \cite[Proposition 1.2.4]{BM16}, there exists a $\cG'$-invariant surface $S$ containing $\Tilde{C}'$. We may take $\Gamma = r(S)$ then (3) follows. 
\end{proof}



\begin{lemma}\label{lemma:noninv}
    Let $X$ be a normal $\Q$-factorial threefold and $(X, \cF, B, \bM)$ be a rank 1 gfq on $X$. Let $C$ be a non-$\cF$-invariant curve and $T$ be an effective divisor. Assume that $(X,\cF,B,\bM)$ is lc at the generic point of $C$, and $T \cdot C<0$. Then $(K_\cF + B +\bM_X) \cdot C\geq 0$. 
\end{lemma}

\begin{proof}
    Assume that $(K_\cF + B + \bM_X) \cdot C< 0$. By Lemma~\ref{lemma:findsurface,Q-fac}, after possibly replacing $X$ by an analytic neighborhood of $C$, there exists a birational morphism $p: X' \to X$ which satisfies the properties stated in the lemma.
    We may write 
    \[
    K_{\cF'} + B' + \bM_{X'} = p^*(K_{\cF} + B + \bM_X),
    \]
    where $\cF' = p^{-1}\cF$, $C'$ is the birational transform of $C$ on $X'$. By Lemma~\ref{lemma:findsurface,Q-fac} (1) and the negativity lemma, we have $B' \geq 0$. Let $T'= p^*T$. Note that $X'$ is $\Q$-factorial. After possibly replacing $X,\cF,B,C$, and $T$ by $X',\cF',B',C'$ and $T'$, respectively, we may assume $\cF$ is terminal at all points of $C$ and $C$ is contained in an $\cF$-invariant surface $S$. 

    Since $(X,\cF,B,\bM)$ is lc at the generic point of $C$, we have $S$ is not contained in $\Supp B$. Let $S^\nu \to S$ be the normalization of $S$. By Proposition~\ref{prop:subadj,primediv}, there exists $B_S\geq 0$ on $S^\nu$ with
    \[
    K_{\cF_S}+B_S + \bM^S_{S^\nu} := (K_{\cF} + B + \bM_X)|_{S^\nu},
    \]
    where $\cF_S$ is the restricted foliation given in \cite{CS24} and $\bM^S = \bM|_{S^\nu}$ is the restricted b-divisor. 

    We claim that $(S^\nu,\cF_S,B_S,\bM_S)$ is lc at the generic point of $C$. In particular, $\mu_C B_S\leq 1 $. It is a local statement at a general point $x$ of $C$, so by Lemma~\ref{lemma:GFQfinite} we may replace $X$ by an index one cover and assume $K_\cF$ is Cartier. By Lemma~\ref{lemma:GFQfinite} and \cite[Lemma 2.9]{CS20}, $C$ is disjoint with $\Sing^+\cF$. Then by \cite[Lemma 1.2.1]{BM16}, there exists an analytic neighborhood $V$ of $x$ and a smooth morphism $q:U \to V$ such that $\cF|_U$ is induced by $q$. After replacing $X$ by $U$, we may assume $\cF$ is algebraically integrable. By \cite[Theorem 6.6.1]{CHLX23}, $(S^\nu,\cF_S,B_S,\bM_S)$ is lc at the generic point of $C$. 

    Then there exists $t \geq 0$ such that $B_S + tC = \Delta + C$, where $\Delta \geq 0$ and $C $ is not contained in $\Supp \Delta$. Note that on $S^\nu$ we have $C^2 \leq T|_{S^\nu} \cdot C <0$. Thus
    \begin{align*}
        (&K_{\cF_S} + \Delta + C+ \bM_{S^\nu}^S)\cdot C  \\ =  (&K_{\cF_S} + B_S +tC+ \bM_{S^\nu}^S)\cdot C \\ =(&K_\cF + B + \bM_X) \cdot C+ tC^2 <0,
    \end{align*}
    which contradicts to (1) of Proposition~\ref{prop:surfnum}.
\end{proof}

\subsection{Cone theorem} We give a lemma that provides an estimate for the length of extremal rays in the cone theorem. Using foliation adjunction, we may obtain a more precise bound compared to the classical case.

\begin{lemma}\label{lemma:step1}
Let $X$ be a normal projective $\Q$-factorial threefold and $(X,\cF,B,\bM)$ be a rank 1 gfq on $X$. Let $C$ be a $(K_\cF + B + \bM_X) $-negative curve which is $\cF$-invariant. If $(X,\cF,B,\bM)$ is lc at the generic point of $C$, then $C$ is a rational curve with
\[
    0 < -(K_\cF + B + \bM_X) \cdot C \leq 2.
\]
\end{lemma}

\begin{proof}
    By Corollary~\ref{coro:singinvcurve}, $C$ is not contained in $\Sing^+\cF$. By Remark~\ref{rmk:Clccenter}, $C$ is a log canonical center of $(X,\cF)$, then  $C$ is not contained in the support of $B$ as $(X,\cF,B)$ is lc at the generic point of $C$. In particular, $B \cdot C \geq 0$. By Lemma~\ref{proposition:bdivoncurve}, $\bM_X \cdot C \geq 0 $. Then by \cite[Proposition-Definition 3.12]{CS24}, if $C^\nu \to C$ be the normalization of $C$, then $K_\cF|_{C^\nu} = K_{C^\nu} +\Delta$ for some $\Delta \geq 0$. Therefore
    \begin{align*}
        0 < -(K_\cF + B + \bM_X) \cdot C \leq -K_\cF \cdot C \leq -\deg_{C^\nu} K_{C^\nu} \leq 2.
    \end{align*}
    In particular, $C$ is a rational curve.
\end{proof}

In the end of this section we give the proof of the cone theorem for generalized foliated quadruples on threefolds of rank 1 assuming the ambient variety is $\Q$-factorial.

\begin{theorem}\label{theorem:conethmgfq,Q-fac}

    Let $X$ be a normal projective $\Q$-factorial threefold and $(X,\cF,B,\bM)$ be a rank 1 gfq on $X$. Let $Z_{-\infty}$ be the subcone spanned by the images of $\NE(W) \to \NE(X)$ where $W$ is a non-lc centre of $(X,\cF,B,\bM)$. Let $\{R_j\}_{j \in \Lambda}$ be the set of all $(K_\cF + B + \bM_X)$-negative extremal rays not contained in \( Z_{-\infty}\) in $\NE(X)$. Then the following hold:
    \begin{enumerate}
        \item We may write 
        \[
            \NE (X) = \NE(X)_{K_\cF + B + \bM_X\geq 0} + Z_{-\infty} + \sum_{j \in \Lambda} R_j,
        \]
        \item For each $j \in \Lambda$, $R_j$ is spanned by a rational curve $C_j$ which is tangent to $\cF$, and 
        \[
            0 < -(K_\cF + B + \bM_X) \cdot C_j \leq 2.
        \]
        \item For any ample $\R$-divisor $A$ on $X$, the set 
        \[
        \Lambda_A := \{\,j \in \Lambda \mid R_j \subset \NE(X)_{K_\cF + B +\bM_X + A<0} \,\}
        \]
        is finite. In particular, the $(K_\cF + B + \bM_X)$-negative extremal rays that are not contained in $Z_{-\infty}$ are locally discrete.
    \end{enumerate}
\end{theorem}

\begin{proof}
    %We first provide a brief summary of the proof. In Steps 1 to 2, we show that any $ (K_\cF + B + \bM_X) $-negative exposed ray $ R $ not contained in \( Z_{-\infty} \) is generated by a rational curve as in (2). Let $H_R $ be the supporting function of $ R $.  Step 1 deals with the case where $ H_R $ is not big, using the bend-and-break lemma. Step 2 deal with the case when $ H_R $ is big. In Step 3, we prove (3) which is similarly to the classical case. In particular, (3) shows that every \( (K_\cF + B + \bM_X) \)-negative extremal ray which is not contained in \(Z_{-\infty} \) is exposed. Then (1) and (2) follow.  
    \textit{Step 1.} Let $R$ be a $(K_\cF + B + \bM_X)$-negative exposed ray, not contained in \( Z_{-\infty} \). In the first two steps we prove that $R$ is generated by an $\cF$-invariant rational curve $C$ with $0<-(K_\cF + B + \bM_X)\cdot C \leq 2$. Let $H_R$ be a supporting function to $R$. In particular, $H_R$ is nef and not numerically trivial. By \cite[Lemma 8.4.1]{CHLX23}, there exists an ample $\R$-divisor $A$ such that $H_R = K_\cF + B + \bM_X + A$ is the supporting function of $R$. 

    In this step we deal with the case when $H_R$ is not big. Then there exists an integer $\nu \in \{0,1,2\} $ such that 
\[
H_R^\nu \cdot A^{3-\nu} > H_R^{\nu + 1} \cdot A^{2-\nu} = 0.
\]
Let $D_i = H_R$ for $1 \leq i \leq \nu + 1$, $D_i = A$ for $\nu + 1 < i \leq 3$. Then $D_1 \cdot D_2 \cdot D_3 = H_R^{\nu + 1} \cdot A^{2-\nu } = 0$, and 
\begin{align*}
    -(K_\cF + B + \bM_X) \cdot D_2 \cdot D_3 &= (A - H_R)\cdot H_R^\nu \cdot A^{2-\nu } \\&= H_R^\nu \cdot A^{3-\nu} - H_R^{\nu + 1} \cdot A^{2-\nu} > 0.
\end{align*}

Since $\bM_X$ is pseudo-effective, $\bM_X \cdot D_2 \cdot \cdots \cdot D_n \geq 0$. Thus $-(K_\cF + B) \cdot D_2 \cdot \cdots D_n >0 $. Let $N = H_R + A = 2H_R - (K_\cF + B + \bM_X)$, $N$ is an ample $\R$-divisor on $X$.

By Theorem~\ref{thm:B&B} (\cite[Corollary 2.28]{Spi20}), there exists a rational curve $C$ through a general point of $X$, such that $C$ is tangent to $\cF$, and $H_R \cdot C = 0$. In particular, $R$ is generated by $[C]$. 
\begin{comment}
Thus 
\begin{align*}
    0 &< - (K_\cF + B + \bM_X) \cdot C = (2H_R - (K_\cF + B + \bM_X))\cdot C \\&=M \cdot C \leq 6 \cdot \frac{M \cdot H_R^\nu \cdot A^{2-\nu}}{-K_\cF \cdot H_R^\nu \cdot A^{2-\nu}} \\&= 6\cdot \frac{-(K_\cF + B + \bM_X) \cdot H_R^\nu \cdot A^{2-\nu}}{-K_\cF \cdot H_R^\nu \cdot A^{2-\nu}} \leq 6.
\end{align*}
Here we use the fact that $(B + \bM_X) \cdot H_R^\nu \cdot A^{2-\nu} \geq 0$ since $B+ \bM_X$ is pseudo-effective, and $-K_\cF\cdot H_R^\nu \cdot A^{2-\nu} = (B + \bM_X + A) \cdot H_R^\nu \cdot A^{2-\nu} > 0$. 
\end{comment}
We may assume $(X,\cF,B,\bM)$ is lc at the generic point of $C$, then by Lemma~\ref{lemma:step1}, $0< -(K_\cF + B + \bM_X) \cdot C \leq 2$.

\medskip

\textit{Step 2.} In this step we deal with the case when $ H_R $ is big. We may write $H_R \sim_\R H + D + tT$ where $H$ is an ample $\R$-divisor, $D \geq 0$ is an $\R$-divisor, $t>0$ and $T$ is a prime divisor not contained in $\Supp D$ such that $T$ is negative along $R$. Let $\nu: S = T^\nu \to T$ be the normalization of $T$.

Assume $T$ is not $\cF$-invariant. Since $T$ is negative along $R$, $R$ is contained in the image of $ \NE(T) \to \NE(X) $. Thus we have that $\mu_T B \leq 1$, since otherwise $T$ would be an non-lc center of $(X,\cF,B,\bM)$ and $R$ would be contained in $Z_{-\infty}$. Let $\alpha = 1-\mu_T B\geq 0$. Then $R$ is also $(K_\cF + B + \alpha T +\bM_X)$-negative. By Proposition~\ref{prop:subadj,primediv}, the restricted foliation $\cF_S$ on $S$ is the foliation by points, and we may write
\[
(K_\cF + B + \alpha T + \bM_X)|_{S}\sim_\R B_S + \bM^S_{S},
\]
where $B_S \geq 0 $ and $\bM^S = \bM|_{T^\nu}$ is the restricted b-divisor of $\bM$ on $ S = T^\nu$. Note that $R$ is contained in the image $\iota: \NE^M(S) \to \NE (X)$. Then by Lemma~\ref{lemma:ExtRayPullback}, there exists a $(B_S + \bM^S_{S})$-negative extremal ray $ R_S \subset \NE^M(S) $ such that $ \iota(R_S) = R$. By Lemma~\ref{lemma:bnefonsurface}, $\bM^S_S$ is nef on $S$, then $B_S$ is negative along $R_S$. Then there exists an irreducible curve $C_S$ contained in $\Supp B_S$ such that $R_S$ is negative on $C_S$. Since $R$ is extremal, $R_S$ is generated by $C_S$, and $R$ is generated by $C = \nu(C_S)$. We may assume $(X,\cF,B,\bM)$ is lc at the generic point of $C$. Note that $T \cdot C <0$, then by Lemma~\ref{lemma:noninv}, $C$ is $\cF$-invariant. By Lemma~\ref{lemma:step1}, $C$ is rational with $0< -(K_\cF + B + \bM_X) \cdot C \leq 2$.

Now we assume $T$ is $\cF$-invariant. Note that $T$ is not contained in $\Supp B$, since otherwise $T$ would be an non-lc center of $(X,\cF,B,\bM)$ and $R$ would be contained in $Z_{-\infty}$. Thus by Proposition~\ref{prop:subadj,primediv}, we may write
\[
(K_\cF + B + \bM_X )|_{S} \sim_\R K_{\cF_S} + B_S + \bM^{S}_{S},
\]
where $\cF_S$ is the restricted foliation and $B_S \geq 0$. In particular, $(S,\cF_S,B_S,\bM^S)$ is a surface num-gfq. By Lemma~\ref{lemma:ExtRayPullback}, there exists a $(K_{\cF_S} + B_S + \bM_{S}^S)$-negative extremal ray $R_S$ whose image along $\NE^M(S) \to \NE(X)$ is $R$. Apply Proposition~\ref{prop:conethmnumgfq} we conclude that $R_S$ is generated by an irreducible curve $C_S$. Then $R$ is also generated by an irreducible curve $C = \nu(C_S)$. Similarly by Lemma~\ref{lemma:noninv} and Lemma~\ref{lemma:step1}, $C$ is an $\cF$-invariant rational curve with $0< -(K_\cF + B + \bM_X) \cdot C \leq 2$.

\medskip

\textit{Step 3.} In this step we prove (3). The proof is similar to the proof of Proposition~\ref{prop:conethmnumgfq}. Assume that for some ample divisor $A$ on $X$, $\Lambda_A$ is an infinite set. Let $A_1,\dots,A_{\rho}$ be ample Cartier divisors on $X$ such that $A_1 ,\dots,A_{\rho}$ form a basis for $N^1(X)_\R$. We may assume $A =\epsilon \sum_{k=1}^{\rho} A_k$ for a sufficiently small $\epsilon>0$.

By \cite[Theorem 18.6]{Roc70}, we may shrink $\Lambda_A$ to a countable infinite subset and assume that for each $j \in \Lambda_A$, $R_j $ is exposed. Let $K = K_\cF + B + \bM_X$. By the previous steps, each $R_j$ is generated by a curve $C_j$ with $K\cdot C_j \in [-2,0)$. Since for each $j\in \Lambda_A$, $R_j$ is also $(K + A)$-negative exposed ray, there exists an ample $\R$-divisor $L_j$ such that $H_j = K + A+L_j$ is a supporting function of $R_j$. Then 
\[
0 = H_j \cdot C_j = (K + A+L_j)\cdot C_j \geq K \cdot C_j + A \cdot C_j \geq -2 + \epsilon \sum_{k=1}^{\rho} A_k \cdot C_j,
\]
then $A_k \cdot C_j \leq \frac{2}{\epsilon}$. Since $A_k$ is Cartier, $A_k\cdot C_j\in \Z$. By shrinking $\Lambda_A$ we may assume that $A_k \cdot C_j$ is independent of $j$ for each $k$. Thus for every $j ,j' \in \Lambda_A$, $C_j \equiv C_j'$, which leads to a contradiction. (3) follows. Moreover, following the same proof of Proposition~\ref{prop:conethmnumgfq}, we may see that for every $j \in \Lambda$, $R_j$ is an exposed ray. Then by Step 1 and 2, (1) (2) follows.
\end{proof}

\begin{remark}\label{rmk:WhyCS24notwork}
    It is worth noting that \cite[Theorem 4.8]{CS24} establishes a version of foliated cone theorem for a normal projective $\Q$-factorial variety $X$ and a foliated triple $(X,\cF,B)$ of rank $1$ in arbitrary dimension. One may expect an analogue statement to hold for gfqs of rank 1, but our techniques fails for arbitrary dimension case. The proof of \cite[Theorem 4.8]{CS24} relies on adjunction to higher-codimensional invariant centers, which fails in our setting of generalized foliated quadruples, since there is no clear definition of the analogue of "restricted b-divisors" (as in Definition~\ref{def:Restrictedbdiv}) along general higher-codimensional centers. In the threefold case, it suffices to consider divisorial adjunctions, for which the restricted b-divisors are well-defined. This allows us to reduce the problem to the surface case.
\end{remark}

\begin{corollary}\label{coro: afterconethm,extray}
    Let $X$ be a normal projective $\Q$-factorial threefold and let $(X,\cF,B,\bM)$ be an lc gfq on $X$. Assume that $K_\cF + B + \bM_X$ is not nef and there exists an ample $\R$-divisor $A$ such that $K_\cF + B + \bM_X + A$ is nef. Let 
    \[
    \lambda := \inf \{\, t > 0 \mid K_\cF + B + \bM_X + tA \text{ is nef}\ \},
    \]
    then there are only finitely many $(K_\cF + B + \bM_X)$-negative extremal rays $R_1,\dots ,R_k$ such that for every $1 \leq i \leq k$, $R_i$ is generated by a curve $C_i$ and $(K_\cF + B + \bM_X + \lambda A) \cdot C_i = 0$.
\end{corollary}

\begin{proof}
    By the assumption, we have $\lambda >0$ and $K_\cF + B + \bM_X + \frac{\lambda}{2} A$ is not nef. By Theorem~\ref{theorem:conethmgfq,Q-fac}, there are only finitely many $(K_\cF + B + \bM_X + \frac{\lambda}{2}A) $-negative extremal rays $R_1, \dots, R_n$. Moreover, for any $ i = 1,2 \dots, n$, there exists a curve $C_i$ such that $R_i = \R_{\geq 0} [C_i]$. By the definition of $\lambda$, we have
    \[
    \lambda = \max_{1\leq i \leq n} \frac{-(K_\cF + B + \bM_X)\cdot C_i}{A\cdot C_i}.
    \]
    In particular, there exist only finitely many $C_j$ such that $(K_\cF + B + \bM_X + \lambda A)\cdot C_j = 0$.
\end{proof}



\section{Minimal Model Program}

In this section we establish the generalized foliated MMP on $\Q$-factorial threefolds and derive the following results as straightforward consequences of \cite{CS20}, Theorem~\ref{theorem:conethmgfq,Q-fac} and Proposition~\ref{proposition:bdivoncurve}. Most of the consequences about MMP for foliated triples of rank 1 on threefolds in \cite{CS20} can be generalized to the case of generalized foliated quadruples.

\begin{proposition}[cf. {\cite[Proposition 8.1]{CS20}}]\label{prop:simpleMMP}
    Let $X$ be a normal threefold, $U$ a normal projective variety, and $\pi: X \to U$ a projective morphism. Let $(X,\cF,B,\bM)$ be a lc gfq of rank $1$ on $X$. Assume that $\cF$ has simple singularities and $K_\cF + B + \bM_X$ is pseudo-effective$/U$. Then we may run a $(K_\cF + B +\bM_X)$-MMP$/U$ to get a minimal model $\phi: X \bir X'$ of $(X,\cF,B,\bM)$ over $U$. If $\cF' = \phi_* \cF$ and $B' = \phi_* B$, then the following holds:
    \begin{enumerate}
        \item $\cF'$ has simple singularities.
        \item $(X',\cF',B',\bM_{X'})$ is lc. 
        \item If $\Theta\geq 0$  is a $\Q$-divisor on $X$ with $\cF$-invariant support such that $(X,\Theta)$ is lc, then $(X',\phi_*\Theta)$ is lc.
    \end{enumerate}
\end{proposition}

\begin{proof}
    First we assmue that $U$ is a point. Since $\cF$ has simple singularities, by Theorem~\ref{thm:simpleprop}, $X$ is $\Q$-factorial klt. We may assume that $K_\cF + B +\bM_X$ is not nef. Then let $R$ be an $(K_\cF + B + \bM_X)$-negative extremal ray. By Theorem~\ref{theorem:conethmgfq,Q-fac}, $R$ is spanned by an $\cF$-invariant rational curve $C$. By Proposition~\ref{proposition:bdivoncurve}, $\bM_X \cdot C \geq 0$. By Remark~\ref{rmk:Clccenter}, $C$ is an lc center of $(X,\cF)$. Since $(X,\cF,B)$ is also lc, $C$ is not contained in $\Supp B$. In particular, $B \cdot C \geq 0 $. Thus $K_\cF \cdot C<0$.

    By \cite[Theorem 6.2]{CS20} and \cite[Theorem 6.5]{CS20}, the contraction or the flip associated to $R$ exists. Denote this step of MMP by $\psi: X\bir X_1$ and let $\cF_1 = \psi_*\cF$. Moreover, $\cF_1$ has simple singularities, and $(X_1, \psi_*\Theta)$ is lc. By the negativity lemma, $(X_1,\cF_1,B_1 = \phi_*B, \bM_{X_1})$ is lc. Note that $\bM_{X_1} = \psi_*\bM_X$, $K_{\cF_1} + B_1 + \bM_{X_1} $ is pseudo-effective. Replace $X,\cF,B$ by $X_1,\cF_1,B_1$, we may continue this process. 

    Since $K_\cF + B + \bM_X$ is pseudo-effective, the MMP constructed above will not terminate on a Mori fiber space. Since each step of the MMP is also a $K_\cF$-MMP, then by \cite[Theorem 7.1]{CS20}, the MMP constructed above terminates.

    In the general case, take a sufficiently ample divisor $H$ on $U$. Note that $(X,\cF,B,\bM+\overline{\pi^*H})$ is lc and that $K_\cF + B + \bM_X + \pi^*H$ is pseudo-effective. Thus, we may run a $(K_\cF + B + \bM_X + \pi^*H)$-MMP, which is automatically a $(K_\cF + B + \bM_X)$-MMP$/U$ by Theorem~\ref{theorem:conethmgfq,Q-fac}.
\end{proof}

\begin{lemma}[cf. {\cite[Lemma 8.3]{CS20}}]\label{lemma:non-can,discrep}
    Let $X$ be a normal projective threefold, and let $(X,\cF,B,\bM)$ be a lc gfq of rank $1$ on $X$. Let $E$ be a prime divisor exceptional over $X$ such that $a(E,\cF,B,\bM)<0$. Then $a(E,\cF,B,\bM) = -1$. 
\end{lemma}

\begin{proof}
    Let $f: Y \to X$ be a birational morphism such that $E$ is a divisor on $Y$ and $\bM$ descends to $Y$. Let $\cF_Y = f^{-1}\cF$. By Theorem~\ref{thm:simpleprop}, after replacing by a higher resolution, we may assume that $\cF_Y$ has simple singularities. Let $B_Y = f^{-1}_*B$, then we may write 
    \[
    K_{\cF_Y} + B_Y + \bM_Y + F_1 = f^*(K_\cF + B + \bM_X) + F_2,
    \] 
    where $F_1, F_2 \geq 0$ are $f$-exceptional $\R$-divisors with no common components. After replacing with a higher resolution, we may assume that $(Y,\cF_Y ,B_Y+F) $ is lc (cf. \cite[Corollary, p. 282]{MP13}), where $F$ is the sum of all $f$-exceptional non-$\cF_Y$-invariant prime divisors.

    Now we assume that $a(E,\cF,B,\bM) \in (-1,0)$. Then $\mu_E F_1 \in (0,1)$. Since $(X,\cF,B,\bM)$ is lc, $E$ is not $\cF_Y$-invariant. Since $E$ is exceptional over $X$, $E$ is contained in $\Supp F$, then there exists an $\epsilon>0$ such that $(Y,\cF_Y,B_Y + F_1 +\epsilon E)$ is lc, and so is $(Y,\cF_Y,B_Y + F_1 + \epsilon E,\bM)$ since $\bM$ descends to $Y$. Then by Proposition~\ref{prop:simpleMMP}, we may run a $(K_{\cF_Y}+ B_Y + F_1 + \epsilon E + \bM_Y)$-MMP/$X$ to obtain a minimal model $\phi: Y \bir X'$/$X$. By the negativity lemma, $\phi$ contracts $E$, which contradicts with \cite[Lemma 6.1]{CS20}.%Here should be Lemma 6.1 of the new version of CS20. The proof is somehow contained in the proof of the cone theorem in CS24, using BDPP.
\end{proof}

\begin{proposition}\label{prop:pltblowup}
    Let $X$ be a normal projective threefold, and let $(X, \cF, B, \bM)$ be an lc gfq of rank $1$ on $X$. Then there exists a birational morphism $\pi: X' \to X$, such that if $\cF' = \pi^{-1} \cF$ and $B' = \pi^{-1}_* B$, then:  
\begin{enumerate}
    \item $\cF'$ has simple singularities.  
    \item Let $E'$ be the sum of all $\pi$-exceptional prime divisors which are not $\cF'$-invariant, then we may write
    \[
    K_{\cF'} + B' + E' + \bM_{X'} = \pi^*(K_{\cF} + B + \bM_X).
    \]  
    In particular, $(X', \cF',B'+E',\bM)$ is lc.
    \item $(X', \Theta)$ is lc, where $\Theta$ is the sum of all $\cF'$-invariant $\pi$-exceptional prime divisors.  
    \item Moreover, if $(X, \cF, B, \bM)$ has a non-canonical center $P$, we may choose $\pi$ such that there exists a $\pi$-exceptional prime divisor $D$ on $X'$ which is not $\cF'$-invariant and is centered on P. In particular, $\mu_D E' = 1$.
    \item If $(X, \cF, B, \bM)$ has an lc center $Q$, we may choose $\pi$ such that there exists a $\pi$-exceptional prime divisor $T$ on $X'$ centered on $Q$. In particular, $\mu_\Gamma E' = \epsilon(\Gamma)$.
\end{enumerate}  

\end{proposition}

\begin{proof}
    Let $f: Y \to X$ be a birational morphism such that $\bM$ descends to $Y$. Let $\cF_Y = f^{-1}\cF$. By Theorem~\ref{thm:simpleprop}, after replacing by a higher resolution, we may assume that $\cF_Y$ has simple singularities. Let $f^{-1}_*B = B_Y$, and let $E_1  = \sum_D \epsilon(D)D$, where the sum runs over all $f$-exceptional prime divisors on $Y$. We may write
    \[
    K_{\cF_Y} + B_Y + \bM_Y + E_1 = f^*(K_\cF + B + \bM_X)+E_2,
    \]
    where $ E_2\geq 0 $ is an $f$-exceptional $\R$-divisor. After passing to a higher resolution, we may assume that $(Y,\cF_Y, B_Y + E_1)$ is lc, and $(Y, F)$ is lc where $F$ is the sum of all $\cF_Y$-invariant $f$-exceptional prime divisors (cf. \cite[Corollary, p. 282]{MP13}). 
    Thus $(Y,\cF_Y,B_Y + E_1 ,\bM)$ is lc as $\bM$ descends to $Y$. By Proposition~\ref{prop:simpleMMP}, we may run a $(K_{\cF_Y} + B_Y + E_1 + \bM_{Y})$-MMP$/X$, which terminates at a minimal model $\phi: Y \bir X'/X$. Let $\pi: X' \to X$ be the induced morphism, and define $\cF' = \pi^{-1}\cF$, $B' = \pi^{-1}_* B$, and $E' = \phi_*E_1$. Note that $\phi$ contracts exactly the prime divisors that contained in $\Supp E_2$. Moreover, we have $\Theta = \phi_* F$, we conclude that (1)–(3) hold for $\pi$ by Proposition~\ref{prop:simpleMMP}.

    If $(X,\cF,B,\bM)$ has a non-canonical center $P$, then in the construction above, we may assume that there exists a prime divisor $D'$ on $Y$, centered on $P$, such that $a(D',\cF,B,\bM)<0$. Then $D'$ is not $\cF'$-invariant. By Lemma~\ref{lemma:non-can,discrep}, $a(D',\cF,B,\bM) = -1$. It follows that $\mu_{D'}E_1 = 1$, and $\mu_{D'}(E_1 -E_2) = 1$, which implies that $D'$ is not contained in $\Supp E_2$. 
    %Note that $\phi$ is an MMP/$X$ that contracts exactly the prime divisors that contained in $\Supp E_2$. 
    In particular, $D$ is not contracted by $\phi$, then let $D = \phi_*D'$ and (4) follows.

    If $(X,\cF,B,\bM)$ has an lc center $Q$, we may assume that there exists a prime divisor $T'$ on $Y$, centered on $Q$, such that $a(T',\cF,B,\bM)=-\epsilon(T')$. By (4), we may only consider the case when $\epsilon(T') = 0$. In this case we have $\mu_{T'}E_1 = 0 $ and $\mu_{T'}(E_1 - E_2) =-a(T',\cF,B,\bM) = 0$, then $T'$ is not contained in $\Supp E_2$. It follows that $T' $ is not contracted by $\phi$, and let $T = \phi_* T'$ and (5) follows.
\end{proof}

We give another corollary of Proposition~\ref{prop:simpleMMP} to construct a crepant pullback of any rank 1 gfq on threefolds.


\begin{lemma}\label{lemma:crepantmodel}
Let $X$ be a normal projective threefold, and $(X,\cF,B,\bM)$ be a gfq of rank 1 on $X$. Then there exists a birational morphism $ p : X' \to X$ such that $\cF' = p^{-1}\cF$ has simple singularities, and we may write 
\[
K_{\cF'} + B' + E' + \bM_Y = p^*(K_\cF + B +\bM_X),
\]
where $B' = p^{-1}_*B$, $E'\geq 0$ is an $p$-exceptional $\R$-divisor. % Moreover, If $\cF$ is not algebraically integrable, then we can choose $p$ such that $\cF'$ has simple singularities.
\end{lemma}

\begin{proof}
    %If $\cF$ is algebraically integrable, then by \cite[Proposition 8.3.2]{CHLX23} there exists a $\Q$-factorial ACSS model for $(X,\cF,B,\bM)$ (see \cite[II.7]{CHLX23} for more details on ACSS models for algebraically integrable foliations). In particular, there exists a birational morphism $p:X' \to X$ which satisfies the lemma.

    %From now we assume that $\cF$ is not algebraically integrable. 
    By Theorem~\ref{thm:simpleprop}, let $f: Y \to X$ be a birational morphism such that $\bM$ descends to $Y$ and $\cF_Y = f^{-1}\cF$ has simple singularities. Let $B_Y = f^{-1}_*B$, and we may write 
    \[
    K_{\cF_Y} + B_Y + E + \bM_Y = f^*(K_\cF + B+ \bM_X) + F,
    \]
    where $E,F \geq 0$ are both $f$-exceptional $\R$-divisors and has no common component. Since $\cF_Y$ has simple singularities, then by Theorem~\ref{thm:simpleprop}, $Y$ is $\Q$-factorial klt and $(Y,\cF_Y)$ has canonical singularities. Then $(Y,\cF_Y,0,\bM)$ is also canonical. 
    %If $K_{\cF_Y}+\bM_Y$ is not pseudo-effective, then $K_{\cF_Y}$ is not pseudo-effective. By \cite[Lemma 2.21]{CS21}, $\cF_Y$ is algebraically integrable, and so is $\cF$, which is a contradiction. Therefore $K_{\cF_Y}+\bM_Y$ is pseudo-effective, and 
    By Proposition~\ref{prop:simpleMMP}, we may run a $(K_{\cF_Y}+ \bM_Y)$-MMP/$X$ to obtain a minimal model $\phi: Y \bir X'$/$X$. Let $p: X' \to X$ be the induced morphism, then $p$ is a required morphism. Indeed, let $\cF' = p^{-1}\cF$, $B' = p^{-1}_*B = \phi_* B_Y$, $E' = \phi_* E$, and $F' = \phi_* F$. Note that 
    \[
    K_{\cF'} + \bM_{X'} = p^*(K_\cF + B + \bM_X) + F' - B' -E' \sim_{\R} F' - B' -E' /X
    \]
    is nef/$X$, and $F'$ is exceptional over $X$, $p_*(F'-B' - E') = -B - p_* E' \leq 0$. By the negativity lemma, $F' - B' -E' \leq 0$, then $F' = 0$ as $ F'$, $B'$ and $E'$ have no common components pairwise. By Proposition~\ref{prop:simpleMMP}, $\cF'$ has simple singularities.
\end{proof}


\begin{proof}[Proof of Theorem~\ref{MainThm:conethmgfq}]

    By Lemma~\ref{lemma:crepantmodel}, there exists a birational morphism $p:X'\to X$ such that we may write
    \[
    K_{\cF'} + B' + \bM_{X'} = p^*(K_\cF + B + \bM_X),
    \]
    where $\cF' = p^{-1}\cF$, $B'\geq 0$ is an $\R$-divisor, and $X'$ is $\Q$-factorial. By Lemma~\ref{lemma:ExtRayPullback}, for each $(K_\cF + B + \bM_X)$-negative extremal ray $R$ which is not contained in $\NE(X)_{\Nlc(X,\cF,B,\bM)}$, there exists a $(K_{\cF'}+B' + \bM_{X'})$-negative extremal ray $R'$ such that $p_*R' = R$ and $R'$ is not contained in $\NE(X')_{\Nlc(X',\cF',B',\bM)}$. Apply Theorem~\ref{theorem:conethmgfq,Q-fac} for $(X',\cF',B',\bM)$, $R'$ is generated by a rational curve $C'$, tangent to $\cF'$, with $0<-(K_{\cF'}+ B' + \bM_{X'} )\cdot C' \leq 2$. Let $C = h(C')$, then $C$ is a rational curve tangent to $\cF$, $R$ is generated by $C$, and 
    \[
    0 < -(K_\cF + B + \bM_X)\cdot C = -(K_{\cF'} + B' + \bM_{X'})\cdot C' \leq 2. \qedhere
    \]
    %Therefore Theorem~\ref{MainThm:conethmgfq} follows.
\end{proof}

We also have the divisorial subadjunction for foliated threefolds of rank 1 without $\Q$-factoriality.

\begin{corollary}
    Let $X$ be a normal projective threefold and let $(X, \cF, B ,\bM)$ be a gfq of rank $1$ on $X$. Let $S$ be a prime divisor on $X$ and let $\nu: S^\nu \to S$ be the normalization of $S$. Assume that $S$ is not contained in $\Supp B$. Then there exists a restricted foliation $\cF_S$ with $\rank \cF_S = 1-\epsilon(S)$ and an $\R$-divisor $B_S\geq 0$ such that 
    \[
    (K_\cF + B + \epsilon(S)S + \bM_X)|_{S^\nu} = K_{\cF_S} + B_S + \bM_{S^\nu}^S,
    \]
    where $\bM^S = \bM_{S^\nu}$ is the restricted b-divisor.
\end{corollary}

\begin{proof}
    By Lemma~\ref{lemma:crepantmodel}, there exists a birational model $p:X' \to X$ such that 
    \[
    K_{\cF'} + B' + \epsilon(T)T + \bM_{X'} = p^*(K_\cF + B +\epsilon(S)S + \bM_X),
    \]
    where $B'\geq 0$ and $T = p^{-1}_* S$ is not contained in $\Supp B'$. Moreover, $\cF' = p^{-1}\cF$ has simple singularities, and $X'$ is $\Q$-factorial. By Proposition~\ref{prop:subadj,primediv}, there exists a restricted foliation $\cF_T$ of rank $1-\epsilon(S)$ on $T^\nu$ and an $\R$-divisor $B_T \geq 0$ on $T^\nu$ such that
    \[
    \left(K_{\cF'} + B' + \epsilon(T)T + \bM_{X'}\right)|_{T^\nu} = K_{\cF_{T}} + B_{T} + \bM^{T}_{T_\nu},
    \]
    where $\bM^T = \bM|_{T^\nu}$ is the restricted b-divisor. Let $q:T^\nu \to S^\nu $ be the induced morphism. It is clear that $\bM^T_{S^\nu} = \bM^S_{S^\nu}$, where $\bM^S = \bM|_{S^\nu}$. Let $\cF_S = q_*\cF_T$ and $B_S =q_* B_T $, then $B_S \geq 0$ and we may conclude.
\end{proof}


The following proof of Theorem~\ref{MainThm:FoliatedMMP} is a direct corollary of \cite[Theorem 8.10]{CS20}, similarly to the proof of Proposition~\ref{prop:simpleMMP}.

\begin{proof}[Proof of Theorem~\ref{MainThm:FoliatedMMP}]
    If $K_\cF + B + \bM_X$ is pseudo-effective, we may assume that $K_\cF + B +\bM_X$ is not nef. Then let $R$ be an $(K_\cF + B + \bM_X)$-negative extremal ray. By Theorem~\ref{theorem:conethmgfq,Q-fac}, $R$ is spanned by an $\cF$-invariant rational curve $C$. Similarly to the proof of Proposition~\ref{prop:simpleMMP}, $K_\cF \cdot C<0$, and $R$ is also an $K_\cF$-negative extremal ray. We only need to show that the contraction or the flip associated to $R$ exists, which has been established in \cite[Theorem 8.10]{CS20}.

    If $K_\cF + B + \bM_X$ is not pseudo-effective, then $K_\cF$ is not pseudo-effective. By \cite[Theorem 1.1]{CP19} or \cite[Lemma 2.21]{CS21}, $\cF$ is algebraically integrable. Then we may conclude by \cite[Theorem A.6]{liu_minimal_2024}.
\end{proof}


\section{Base-point-free theorem}

\subsection{Canonical bundle formula} We recall some necessary definitions for canonical bundle formula for generalized pairs, following \cite{Fil20} or \cite{CHLX23}.

\begin{definition}[Discrimiant and moduli parts, cf. {\cite[\S 4]{Fil20}}]


Let $(X,B,\bM)$ be a generalized sub-pair and $f: X \to Z$ be a contraction such that $(X,B,\bM)$ is sub-lc over the generic point of $Z$. For any prime divisor $P$ on $Y$, $f^*P$ is defined over a neighborhood of the generic point of $P$. Then let \[
t_P = \sup \left\{\,t \mid (X,B + tf^*P,\bM) \text{ is sub-lc over the generic point of } P\,\right\},
\]
and we define the \textit{discriminant part} $B_Z$ of $f:(X,B,\bM)\to Z$ to be 
\[
B_Z = \sum_P (1-t_P) P,
\]
where the sum runs through all the prime divisors $P$ of $Z$. Let $X'$ and $Z'$ be birational models of $X$ and $Z$ respectively, and we assume that there exists a commutative diagram:
\begin{center}
    \begin{tikzcd}
        X' \arrow[r, "\phi"] \arrow[d, "f'"'] & X \arrow[d, "f"] \\
        Z' \arrow[r, "\phi_Z"]               & Z               
        \end{tikzcd}
\end{center}
We fix a choice of $K_X$ and $K_Z$, etc., such that $\phi_* K_{X'} = K_X$ and $(\phi_Z)_* K_{Z'} = K_Z$. We may define an $\R$-divisor $B'$ on $X'$ such that
\[
K_{X'} + B' + \bM_{X'} = \phi^*(K_X + B + \bM_X),
\]
and let $B_{Z'}$ be the discriminant part of $f':(X',B',\bM) \to Z'$. Since $\phi_Z$ is isomorphic over codimension $1$ points, we have $B_Z = (\phi_Z)_* (B_{Z'})$. This defines a b-divisor $\mathbf{B}^Z$ on $Z$, called the \textit{discriminant $b$-divisor} of $f:(X,B,\bM) \to Z$.

Moreover, if there exists an $\R$-Cartier divisor $L$ on $Z$ such that $K_X + B + \bM_X \sim_\R f^*L$, define \[
M_Z = L - (K_Z + B_Z)
\]
to be the \textit{moduli part} of $f: (X,B,\bM)\to Z$. 
For a fixed $L$, $M_Z $ is uniquely defined. In particular, $\bM_Z$ is defined up to $\R$-linear equivalence.
Given the diagram as above, we have $K_{X'} + B' + \bM_{X'}\sim_\R f'^*L'$ where $L' = \phi_Z^*L$. Let $M_{Z'}$ be the moduli part of $f':(X',B',\bM)\to Z'$. Then $M_{Z'} = (\phi_Z)_*M_Z$, which defines a b-divisor $\bM^Z$ on $Z$, called the \textit{moduli b-divisor} of $f: (X,B,\bM)\to Z$. We may write 
\[
K_{X} + B + \bM_X \sim_\R f^*(K_Z + B_Z + \bM^Z_Z).
\]

\end{definition}

\begin{lemma}\label{lemma:b-semiA}
    Let $X$ be a normal threefold and let $(X,B,\bM)$ be a $\Q$-generalized pair, $f:X\to Z$ is a contraction such that $\dim Z = 2$ and $K_{X} + B + \bM\sim_{\Q,Z} 0$. Assume that $\bM$ is b-semi-ample and $(X,B,\bM)$ is lc over the generic point of $Z$. Then the moduli b-divisor $\bM^Z$ of $(X,B,\bM) \to Z$ is b-semi-ample. 
\end{lemma}

\begin{proof}
    If $\bM = \overline{0}$, the proposition follows from \cite[Theorem 8.1]{PS09} and \cite[Remark 4.1]{FG14}. The general case follows from the proof of  \cite[Theorem 7.3]{Fil20} and $\bM = \overline{0}$ case.
\end{proof}

\begin{lemma}[{cf. \cite[Proposition 2.2]{CS25bpf}}]\label{lemma:BPFsemiamp}
    Let $X$ be a normal projective threefold, and let $(X,\cF ,B,\bM)$ be an lc algebraically integrable $\Q$-gfq of rank $1$ on $X$. Let $A$ be an ample $\Q$-divisor on $X$. Assume that $H = K_\cF + B + A+ \bM_X$ is nef and $\bM$ is b-semi-ample. Suppose that there exists an $\cF$-invariant curve $\xi$ passing through a general point of $X$ such that $H \cdot \xi = 0$. Then $H$ is semi-ample.
\end{lemma}

\begin{proof}
    Let $\bN = \bM + \overline{A}$, then $\bN$ is b-semi-ample. By Theorem~\ref{Thm:Exist*models}, there exists a $\Q$-factorial $(\ast)$-model \[
    \pi:(X',\cF,B',\bN;G)/Z \to (X,\cF,B,\bN) \] 
    of $(X,\cF,B,\bN)$. We may write 
    \[
    K_{\cF'} + B' + \bN_{X'} = \pi^*(K_\cF + B + \bN_X),
    \]
    where $\cF'$ is induced by an equidimensional morphism $f: X' \to Z$ and $B'\geq 0$. Let $\overline{\xi}$ be the strict transform of $\xi$ on $X'$, then $\overline{\xi}$ is a general fiber of $f$. Note that $\pi^*H \cdot \overline{\xi} = 0$ and $H$ is nef, we have $K_{\cF'} + B' +\pi^*A + \bM_{X'} = \pi^*H $ is numerically trivial over $Z$. Since $B'$, $\pi^*A$ and $\bM_{X'}$ is pseudo-effective, and $\pi^*A$ is not numerically trivial over $Z$, then $K_{\cF'}$ is not pseudo-effective over $Z$. Since $f$ is equidimensional, by \cite[2.9]{Dru17} we have
    \[
    K_{\cF'} = K_{X'/Z} - R,
    \]
    where $K_{X'/Z} = K_{X'}-f^*K_Z$ and 
    \[
    R = \sum_D (f^*P - f^{-1}(P)),
    \]
    where the sum runs through all the prime divisors $P$ of $Z$. In particular, $K_X'$ is not pseudo-effective over $Z$. Since $X'$ is $\Q$-factorial klt, we may run a $K_{X'}$-MMP which terminates on a Mori fiber space $h: X'' \to Z'$/$Z$. Note that $\dim Z' = \dim Z =2$. Let $\phi: X'\bir X''$ be the above MMP, $\cF'' := \phi_*\cF'$ and let $B''$ be the strict transform of $B$ on $X''$. Then $K_{\cF''} + B'' + \bN_{X''}$ is numerically trivial over $Z$, and also over $Z'$. Since $h$ is a Mori fiber space, there exists a $\Q$-Cartier divisor $\Theta'$ such that $K_{\cF''}+ B'' + \bN_{X''} = h^*\Theta'$. Let $\alpha: Z' \to Z$ denote the induced morphism. Note that $\Theta'\equiv 0 /Z$ and $Z$ is smooth, it follows that if $\Theta = \alpha_*\Theta'$, we have $\Theta' = \alpha^*\Theta$. It follows that $K_{\cF'} + B' + \bN_{X'} = f^*\Theta$.

    Let $B_Z$ be the discriminant part of $(X',B'+G,\bN) \to Z$. By \cite[Proposition 7.3.6]{CHLX23}, $R + G = f^*B_Z$. Then 
    \[
    K_{X'} + B' + G + \bN_{X'} = f^*(K_{Z'} + B_Z + \Theta).
    \]
    Let $\bN^Z$ be the moduli b-divisor of $(X',B' + G,\bN)\to Z$, then $\Theta \sim_\Q \bN^Z_Z$. In particular, $\bN^Z_Z$ is $\Q$-Cartier. Since $(X',B' + G,\bN)$ is lc and $\bN$ is b-semiample, it follows from Lemma~\ref{lemma:b-semiA} that $\bN^Z$ is b-semi-ample. Since $Z$ is a surface, the stable base locus of $\bN^Z_Z$ are just closed points. By \cite[Theorem 1.10]{Fuj83}, $\bN^Z_Z$ is semi-ample, and so is $H$.
\end{proof}

