\begin{theorem}\label{Thm:BPFgfq}
    Let $X$ be a normal projective threefold, and let $(X,\cF ,B,\bM)$ be an lc $\Q$-gfq of rank $1$ on $X$ such that $\bM$ is b-semi-ample. Assume that $X$ is $\Q$-factorial klt. Let $A$ be an ample $\Q$-divisor on $X$. Suppose that $H = K_\cF + B + \bM_X + A$ is nef. Then $H$ is semi-ample.
\end{theorem}

\begin{proof}
    If $H$ is not big, then $K_\cF$ is not pseudo-effective. By \cite[Theorem 1.1]{CP19} or \cite[Lemma 2.21]{CS21}, $\cF$ is algebraically integrable. By Theorem~\ref{thm:B&B} (\cite[Corollary 2.28]{Spi20}), there exists an $\cF$-invariant curve $\xi$ passing through a general point of $X$ such that $H \cdot \xi = 0$. By Lemma~\ref{lemma:BPFsemiamp}, $H$ is semi-ample.

    From now we assume that $H$ is big. If $K_\cF + B + \bM_X + \alpha A$ is nef for some $\alpha \in (0,1)$, then $H = (K_\cF+ B+ \bM_X +\alpha A) + (1-\alpha) A$ ample and we may conclude. Thus we may assume that
    \[
    \lambda = \inf \{\, t > 0 \mid K_\cF + B + \bM_X + tA \text{ is nef}\, \} = 1.
    \]
    By Corollary~\ref{coro: afterconethm,extray}, there exist only finitely many $(K_\cF + B + \bM_X)$-negative extremal rays $R_1, \dots, R_k$ such that $H$ vanishes along $R_i$ for each $1 \leq i\leq k$. By Theorem~\ref{theorem:conethmgfq,Q-fac}, $R_i$ is generated by an $\cF$-invariant curve $C_i$. Since $H$ is big, $\loc R_i\neq X$ for each $1 \leq i \leq k$. By the proof of Lemma~\ref{lemma:step1}, for each $i$ we have $K_\cF \cdot C_i <0$.

    By \cite[Corollary 8.5]{CS20}, we may assume that $\cF$ is canonical along $C_i$ for each $i$. If $\loc R_i$ has dimension $2$ for some $i$, then by \cite[Theorem 6.2]{CS20}, the divisorial contraction $\phi: X\to Y$ associated to $R_i$ of $X$ exists. Take a sufficiently small ample $\Q$-divisor $D$ on $Y$ such that $A - \phi^* D$ is ample. Let $\Theta\geq 0$ be a $\Q$-divisor such that $A - \phi^* D \sim_\Q \Theta$. Since $(X,\cF,B,\bM)$ is lc, then so is $(X,\cF,B,\bM + \overline{\Theta + \phi^*D})$. Note that as b-divisors, $\overline{\phi^*D} = \overline{D}$, and since $\phi$ is $H$--trivial, $\phi$ is also $(K_\cF + B + \bM_X + \Theta + \phi^*D)$--trivial. Then we have
    \[
    K_\cF + B + \bM_X + \Theta + \phi^*D = \phi^*(K_{\cF_Y} + B_Y +\bM_Y +  \Theta_Y + D),
    \]
    where $\cF_Y = \phi_*\cF$, $B_Y = \phi_* B$ and $\Theta_Y = \phi_*\Theta$. In particular, $(Y,\cF_Y,B_Y,\bM + \overline{\Theta} + \overline{D})$ is lc. Let $\bM^Y = \bM + \overline{\Theta}$, then $\bM^Y$ is b-semiample and $(Y,\cF_Y,B_Y,\bM^Y)$ is lc. Then we may repalce $(X,\cF,B,\bM),A$ with $(Y,\cF_Y,B_Y,\bM^Y),D$ and apply induction on the Picard number of $X$.

    Now we assume that when $Z_i := \loc R_i$ has dimension $1$ for every $1 \leq i \leq k$. By \cite[Lemma 3.2]{CS25bpf}, we may assume that each connected component of $Z_i$ is irreducible and $Z_i, Z_j$ are disjoint for each $i \neq j$. By \cite[Theorem 8.8]{CS20}, the flip contraction $f_i: X \to X_i$ associated to $R_i$ exists for each $i$. In particular, $\Exc f_i = Z_i$. Since $R_i$ is $H$-trivial, let $H_i = (f_i)_* H$ then $H_i$ is $\Q$-Cartier and $H = f^*H_i$. Let 
    \[
        U_0 = X \setminus \left(\bigcup_{i= 1}^k Z_j \right), \quad U_i = X \setminus \bigcup_{j \neq i} Z_j,\ \ \text{and }V_i = f_i(U_i).
    \]
    Note that $f_i|_{U_0}:U_0 \to f_i(U_0) \subset V_i$ is an isomorphism for each $i$. Then we may glue $V_i$ along the isomorphisms $V_i \supset f_i(U_0) \to f_j(U_0)\subset V_j$ to construct a scheme $Y$, and glue $f_i|_{U_i}$ to $f$ to construct a morphism $f: X \to Y$. By the construction, $Y$ is a normal proper variety. Note that $f$ is isomorphic in codimension $1$. Let $H_Y = f_* H$. Then $H_Y|_{V_i}$ is $\Q$-Cartier on $V_i$, then $H_Y$ is $\Q$-Cartier on $Y$. and we have $H = f^*H_Y$. In particular, $H_Y$ is nef on $Y$. If $H_Y$ is ample on $Y$, then $H$ is semi-ample and we may conclude. Then we may assume that $H_Y$ is nef but not ample, then there exists an extremal ray $R_{0,Y}$ of $\NE(Y)$ such that $H_Y$ vanishes along $R_{0,Y}$. Then by Lemma~\ref{lemma:ExtRayPullback}, there exists an extremal ray $R_0$ on $X$ such that the $\iota(R_0) = R_{0,Y} $ where $\iota: \NE(X) \to \NE(Y)$, and $H$ vanishes along $R_0$. Note that $R_0$ is also a $(K_\cF + B + \bM_X)$-negative extremal ray. Since $\iota(R_i) = 0$ for every $1 \leq i \leq k$, $R_0$ is not any of $R_i$, which contradicts to the choice of those $R_i$.
\end{proof}



\begin{proof}[Proof of Theorem~\ref{MainThm:BPF}]
    It follows from Theorem~\ref{Thm:BPFgfq} for $\bM = \overline{0}$.
\end{proof}

\section{ACC for log canonical thresholds}\label{section:ACCforLCT}

\subsection{Precise Adjunction Formula} We give a precise subadjunction formula to an invariant surface for generalized foliated quadruples of rank 1 on threefolds, provided that the foliation has simple singularities.

\begin{proposition}[cf. {\cite[Theorem 3.3]{LMX24}}]\label{prop:Pre.AdjF.Simple}
    Let $X$ be a normal threefold and $(X,\cF,B,\bM) $ be a gfq of rank $1$ on $X$ such that $\cF$ has simple singularities. Let $T,B_1,\dots,B_m$ be distinct prime divisors on $X$, and let $\bM^1 ,\dots,\bM^n$ be b-nef b-Cartier b-divisors on $X$. Suppose that $\epsilon (T) = 0$ and 
    \[
    B = \sum_{i=1}^m b_iB_i, \quad \bM = \sum_{j=1}^n r_j\bM^j,
    \]
    where $b_1,\dots,b_m,r_1,\dots r_n$ are nonnegative real numbers. Let $S\to T$ be the normalization of $T$ and let $\bM^{j,S} = \bM^j |_{S}$ be the restricted b-divisors. Then there exist a foliation $\cF_S$ of rank $1$ on $S$, prime divisors $C_1,\dots, C_q$ on $S$, and nonnegative integers $\{w_{i,j}\}_{1\leq i \leq q,0\leq j\leq m}$ and $\{v_{i,j}\}_{1\leq i \leq q, 1\leq j \leq n}$ such that for any real numbers $b_1',\dots, b_m'$, $r_1',\dots r_n'$, we have the following holds: Let 
    \[
    B' = \sum_{i=1}^m b_i'B_i, \quad \bM' = \sum_{j=1}^n r_j'\bM^j,
    \]
    we may write 
    \[
    (K_{\cF} + B' + \bM'_X)|_{S} = K_{\cF_S} + B'_S + \bM'^S_{S},
    \]
    where 
    \[
    B'_S = \sum_{i=1}^q \frac{w_{i,0} + \sum_{j=1}^m w_{i,j}b_j' + \sum_{j=1}^n v_{i,j}r_j'}{2} C_i, \quad \bM'^S = \sum_{j=1}^n r_j' \bM^{j,S}.
    \]
    In particular, if there exists an $I\subset [0,+\infty)$ such that $1, b_1',\dots, b_m'$, $r_1',\dots r_n' \in I$, then the coefficients of $B_S$ are contained in $\frac{1}{2}I_+$. 
\end{proposition}

\begin{proof}
    Since $\cF$ has simple singularities, $X$ is $\Q$-factorial. For any prime divisor $D$ on $S^\nu$, let $\eta_D$ be the generic point of the image of $D$ in $X$.  By \cite[Theorem 3.3]{LMX24}, we only need to show that for any prime divisor $D$ on $S$, we have non-negative integers $v_1,\dots v_n$ such that near $\eta_D$ we have
    \[
    \left(\sum_{j=1}^n r_j'\bM^j_{X} \right) \Bigg|_{S} =  \frac{\sum_{j=1}^n v_jr_j'}{2}  D + \sum_{j=1}^n r_j' \bM^{j,S}_{S}.
    \]
    Here we point out that the proof of \cite[Theorem 3.3]{LMX24} does not require the lc assumption. By \cite[Claim 3.4]{LMX24}, for any prime divisor $L$ on $X$, $2L$ is Cartier near the generic point of the image of $D$ in $X$. Let $f:Y \to X$ be a log resolution of $(X,T)$ such that $\bM^j$ descends to $Y$ for each $1\leq j\leq n$. 
    Let $S' = f^{-1}_*T$, let $g: S' \to S$ be the induced morphism, and let $D' = g^{-1}_*D$.
    By the negativity lemma, we may write 
    $$f^*(2\bM^{j}_X) = 2\bM^{j}_Y + F_j, $$
    where $F_j\geq 0$. Then $F_j$ is Cartier near the generic point of the image of $D'$ on $Y$, since $f^*(2\bM^j_X)$ is Cartier near the generic point of the image of $D'$ on $Y$ and $\bM^j_Y$ is Cartier on $Y$. In particular, $v_j = \mu_{D'}(F_j|_{S'}) $ is a non-negative integer. Then we have
    \[
    (\bM^{j}_X)|_{S} =  \frac{v_j}{2}D + \bM^{j,S}_{S}
    \]
    near $\eta_D$. Therefore, the non-negative integers $v_1,\dots,v_n$ are as required.
\end{proof}

