\subsection{Proof of Theorem~\ref{MainThm:ACCforLCT}}





\begin{lemma}\label{lemma:ACC1}
    Let $X$ be a normal projective threefold and let $(X, \cF,B,\bM)$ be an lc gfq of rank $1$ on $X$. Let $D$ be an effective $\R$-divisor on $X$ and $\bN$ be a b-nef b-divisor on $X$ such that $D + \bN_X$ is $\R$-Cartier. Assume that 
    \begin{itemize}
        \item $(X,\cF,B+D,\bM+\bN)$ is lc,
        \item $ (X,\cF,B + tD, \bM + t\bN)$ is not lc for any $t >1$, and
        \item $\lfloor B\rfloor = \lfloor B+ D\rfloor$.
    \end{itemize}
    Then there are birational morphisms $g: Y\to X'$ and $\pi:X' \to X$ such that 
    \begin{enumerate}
        \item Let $\cF' = \pi^{-1}\cF$, let $B'$ and $ D'$ be the strict transforms of $B$ and $D$ respectively, and let $E' $ be the sum of all $\pi$-exceptional divisors which are not $\cF'$-invariant. Then we may write
        \[
        K_{\cF'} + B' + D' + E' + \bM_{X'} + \bN_{X'} = \pi^*(K_\cF + B + D + \bM_X  + \bN_X),
        \]
        and 
        \[
            K_{\cF'} + B'+ E' + \bM_{X'}= \pi^*(K_\cF + B + \bM_X ).
        \]
        \item The birational morphism $g:Y \to X'$ is a divisorial contraction of a prime divisor $T$. Let $\cF_Y= g^{-1}\cF'$, then $T$ is $\cF_Y$-invariant. Moreover, $a(T,\cF,B+D,\bM+\bN)=0$ and $a(T,\cF,B,\bM)>0$. In particular, $-T$ is ample over $X'$.
        \item Both $\cF'$ and $\cF_Y$ has simple singularities. In particular, $X'$ and $Y$ are $\Q$-factorial.
    \end{enumerate}
\end{lemma}

\begin{proof}
    Since $(X,\cF,B+D ,\bM + \bN)$ is lc, both $B$ and $D$ have no $\cF$-invariant component. Then by the assumptions, there exists an lc center $Q$ of $(X,\cF,B+D,\bM + \bN)$ of codimension $\geq 2$ which is not an lc center for $(X,\cF,B,\bM)$. 

    By Proposition~\ref{prop:pltblowup}, there exists a birational morphism $\pi':X'' \to X$ such that we may write
    \[
    K_{\cF''} + B'' + D'' + E'' + \bM_{X''} + \bN_{X''} = \pi'^*(K_\cF + B + D + \bM_X + \bN_X),
    \]
    where $\cF'' = \pi'^{-1}\cF$, $B''$, $D''$ are the birational transforms of $B$, $D$ respectively on $X''$, and $E''$ is the sum of all $\pi'$-exceptional prime divisors which are not $\cF''$-invariant. We have that $\cF''$ has simple singularities and $X''$ is $\Q$-factorial. 

    For any $\Gamma \subset \Supp E''$,  we have 
    \[
    a(\Gamma,\cF,B + D, \bM + \bN) = -1.
    \]
    Assume that $a(\Gamma,\cF,B,\bM)>-1$. Since $(X,\cF,B,\bM)$ is lc, by Lemma~\ref{lemma:non-can,discrep}, we have 
    \[
    a(\Gamma):= a(\Gamma,\cF,B,\bM) \geq 0.
    \]
    Then for $0 < \delta < \frac{1}{a(\Gamma) + 1}$, we have
    \begin{align*}
        & a(\Gamma, \cF, B + (1-\delta)D,\bM +(1-\delta)\bN)\\ = \,& \delta a(\Gamma, \cF, B,\bM) + (1-\delta) a(\Gamma, \cF, B + D,\bM +\bN) \\ = \,& \delta (a(\Gamma)+1) - 1 \in (-1,0),
    \end{align*}  
    which contradicts with Lemma~\ref{lemma:non-can,discrep} and the fact that $(X,\cF, B + (1-\delta)D,\bM +(1-\delta)\bN)$ is lc. Thus $a(\Gamma,\cF,B,\bM) = -1$.

    By the negativity lemma, we may write 
    \[
    D'' + P'' +  \bN_{X''}  = \pi'^*(D + \bN_{X}),
    \]
    where $P''\geq 0$ is a $\pi'$-exceptional $\R$-divisor on $X''$. Then we have 
    \[
    K_{\cF''} + B''+ E'' -P''+\bM_{X''} = \pi'^*(K_\cF + B + \bM_X).
    \]
    Note that $P''$ and $E''$ have no common component as $a(\Gamma,\cF,B ,\bM) = -1$ for each prime divisor $\Gamma \subset \Supp E''$. In particular, each component of $P''$ is $\cF''$-invariant and exceptional over $X$. Moreover, by Proposition~\ref{prop:pltblowup} (5), we may assume that there exists a prime divisor $T''$ on $X''$, centered on $Q$, such that $\mu_{T''}E'' = \epsilon(T'')$. Then $T''$ must be $\cF''$-invariant and contained in $\Supp P''$, as $Q$ is not an lc center for $(X, \cF, B, \bM)$. In particular, $P'' \neq 0$. 

    Since $(X'',\cF'',B''+D'' +E'',\bM +  \bN)$ is lc and $X''$ is $\Q$-factorial, we have $(X'',\cF'',B'' +E'',\bM )$ is lc. By Proposition~\ref{prop:simpleMMP}, we may run a $(K_{\cF''}+ B'' + E'' + \bM_{X''})$-MMP/$X$ which terminates at a minimal model $\phi:X'' \bir X'$/$X$. Let $\pi:X' \to X$ be the induced morphism. Note that $\phi$ contracts exactly prime divisors contained in $\Supp P''$. Let $\cF' = \pi^{-1}\cF$, and let $B'$, $D'$, $E'$ be the strict transform of $B''$, $D''$, $E''$ on $X'$, respectively. We have
    \[
    K_{\cF'} + B' + E' + \bM_{X'}  = \pi^*(K_\cF + B + \bM_X).
    \]
    Note that 
    \[
    K_{\cF''} + B'' + D'' + E'' + \bM_{X''} + \bN_{X''}\sim_{\R,X} 0,
    \]
    hence (1) holds. Moreover, note that $P''\neq 0$, then the sequence of MMP consists a step of divisorial contraction. Since $K_{\cF'} + B' + E' + \bM_{X'} \sim_{\R,X} 0$, the last step of this sequence of MMP is a divisorial contraction. Let $g: Y \to X'$ be the divisorial contraction which is the last step of the sequence of MMP associated with the $g$-exceptional prime divisor $T$. Note that the strict transform of $T$ on $X''$ is contained in $\Supp P''$, hence $\epsilon(T) = 0$, $a(T,\cF,B+D,\bM+\bN)=0$, and $a(T,\cF,B,\bM)>0$. In particular, $-T$ is ample over $X'$ and (2) follows. (3) follows by Proposition~\ref{prop:simpleMMP}. 
\end{proof}




\begin{proof}[Proof of Theorem~\ref{MainThm:ACCforLCT}]
    \textit{Step 1}. Assume the theorem does not hold, then there exists a sequence of rank $1$ gfqs $(X_i,\cF_i,B_i,\bM^i)$ and $D_i$, $\bN^i$ satisfying the assumptions of the theorem such that if 
    \[
    t_i = \lct (X_i,\cF_i,B_i,\bM^i;D_i,\bN^i),
    \]
    then $\{t_i\}_{i=1}^\infty$ form a strictly increasing sequence of numbers. We may assume $0<t_i<+\infty$ for each $i$. Then $(X_i,\cF_i,B_i+ t_i D_i,\bM^i + t_i \bN^i)$ is lc, and $(X_i,\cF_i,B_i+ t D_i,\bM^i + t \bN^i)$ is not lc for $t >t_i$. In particular, both $B_i$ and $D_i$ have no $\cF_i$-invariant components. If $\lfloor B_i + t_iD_i \rfloor \neq \lfloor B_i \rfloor $ for infinitely many $i$, then we may conclude that $t_i$ belongs to a fixed ACC set which leads to a contradiction. Thus we may assume that $\lfloor B_i + t_iD_i \rfloor = \lfloor B_i \rfloor $ for each $i$. In particular, there exists an lc center $Q_i$ of $(X_i,\cF_i, B_i + t_iD_i,\bM^i + t_i\bN^i)$ of codimension $\geq 2$ which is not an lc center for $(X_i,\cF_i,B_i,\bM^i) $. 

    \medskip

    \textit{Step 2.} 
    In this step we replace $X_i$ with a suitable birational model. By Lemma~\ref{lemma:ACC1}, for each $i$, there exists birational morphisms $\pi_i: X_i' \to X_i$ and $g_i:Y_i \to X_i'$ such that the following hold:
    \begin{itemize}
        \item Let $\cF_i' = \pi_i^{-1}\cF_i$, let $B_i'$ and $ D_i'$ be the strict transforms of $B_i$ and $D_i$,  respectively, and let $E_i' $ be the sum of all $\pi_i$-exceptional divisors which are not $\cF_i'$-invariant. Then $\cF_i'$ has simple singularities, and we may write
        \[
            K_{\cF_i'} + B_i' + E_i' + t_iD_i' + \bM^i_{X_i'} + t_i\bN^i_{X_i'} = \pi^*(K_{\cF_i} + B_i + t_iD_i + \bM^i_{X_i}  + t_i\bN^i_{X_i}),
        \]
        and
        \[
            K_{\cF_i'} + B_i' + E_i' + \bM^i_{X_i'} = \pi^*(K_{\cF_i} + B_i + \bM^i_{X_i}).
        \]
        \item The birational morphism $g:Y_i \to X_i'$ is a divisorial contraction of a prime divisor $T_i$,  $\cF_{Y_i}= g_i^{-1} \cF_i'$ has simple singularities, and $T_i$ is $\cF_{Y_i}$-invariant. Moreover, $a(T_i,\cF_i,B_i+t_iD_i,\bM^i+t_i\bN^i)=0$ and $e_i:=a(T_i,\cF_i,B_i,\bM^i)>0$. In particular, $-T_i$ is ample over $X_i'$.
    \end{itemize}
    In particular, $t_i = \lct(X_i',\cF_i', B_i' + E_i', \bM^i; D_i', \bN^i)$. We may assume that $1 \in I$. After replacing $(X_i,\cF_i,B_i,\bM^i;D_i,\bN^i)$ with $(X_i',\cF_i', B_i' + E_i', \bM^i; D_i', \bN^i)$, we may assume that $\cF_i$ has simple singularities and there exists a birational morphism $g_i: Y_i \to X_i$ which is a divisorial contraction of the prime divisor $T_i$ with $\epsilon(T_i) = 0$. Let $\cF_{Y_i} = g^{-1}\cF_i$, and let $B_{Y_i}$, $D_{Y_i}$ be the birational transform of $B_i$ and $D_i$ on $Y_i$ respectively, we may write
    \[ 
    K_{\cF_{Y_i}} + B_{Y_i} + t_i D_{Y_i} + \bM^i_{Y_i} + t_i \bN^i_{Y_i} = g_i^* ( K_{\cF_i} + B_i +t_iD_i + \bM^i_{X_i} + t_i \bN^{i}_{X_i}),    
    \]
    and 
    \[
        K_{\cF_{Y_i}} + B_{Y_i} -e_i T_i + \bM^i_{Y_i}  = g_i^* ( K_{\cF_i} + B_i  + \bM^i_{X_i} ).
    \]
    In particular, $-T_i$ is ample over $X_i$. Moreover, by the two equalities above, we have
    \[
    D_{Y_i} + \bN^i_{Y_i} +\frac{e_i}{t_i}T_i = g_i^*(D_i + \bN^i_{X_i}).
    \]



    \medskip

    \textit{Step 3.} In this step we apply the divisorial adjunction to $T_i$ and introduce some necessary notations. Let $S_i \to T_i$ be the normalization of $T_i$. Apply Proposition~\ref{prop:Pre.AdjF.Simple} for $(Y_i,\cF_{Y_i},B_{Y_i} + t_iD_{Y_i},\bM^i + t_i \bN^i)$ and $T_i$, we may write

    \[
    K_{\cF_{S_i}} + \Delta_i + \mathbf{\Psi}^i_{S_i} := (K_{\cF_{Y_i}}+ B_{Y_i}+t_iD_{Y_i}+ \bM^i_{Y_i} + t_i \bN^i_{Y_i})|_{S_i},
    \] 
    where $\cF_{S_i}$ is the restricted foliation of $\cF_i'$ on $S_i$, $\Delta_i \geq 0$, and $\mathbf{\Psi}^i = \bM^{S_i} + t_i \bN^{S_i}$. Here $\bM^{S_i} = \bM^i|_{S_i}$, $\bN^{S_i} = \bN^i|_{S_i}$. In particular, $\bM^{S_i}, \bN^{S_i}$ are both $I$-linear combination of b-nef b-Cartier b-divisors on $S_i$. %(see \ref{sec:b-div}).

    Now we give some notations used in next steps. We define
    \[
    K_i := \{\,a + t_ib \mid a,b\in I\cup \{0\}\, \},
    \]
    then $K_i$ is a DCC set. The coefficients of $B_{Y_i}+ t_iD_{Y_i}$ belong to $K_i$, and $\bM^i + t_i\bN^i$ is a $K_i$-linear combination of b-nef b-Cartier b-divisors. Then by Proposition~\ref{prop:Pre.AdjF.Simple}, the coefficients of $\Delta_i$ belong to $\frac{1}{2}(K_i)_+$. Let $K = \bigcup_{i=1}^\infty K_i$, then $K$ is a DCC set as $\{\,t_i\mid i \geq 1\,\}$ is DCC. In particular, $\Delta_i \in \frac{1}{2}K_+$.

    By Proposition~\ref{prop:Pre.AdjF.Simple}, there exists a $\Q$-divisor $G_i\geq 0$ on $S_i$ such that $K_{\cF_{S_i}} + G_i = K_{\cF_{Y_i}}|_{S_i}$. Let $D_{S_i} = D_{Y_i}|_{S_i}$. By the negativity lemma, we may write $\bM^i_{Y_i}|_{S_i} = \bM^{S_i}_{S_i} + \Theta_i$ and $\bN_{Y_i}^i |_{S_i} = \bN_{S_i}^{S_i} + \Xi_i $ where $\Theta_i, \Xi_i\geq 0 $. Let $B_{S_i} = G_i + B_{Y_i}|_{S_i} + \Theta_i \geq 0 $, then we have \[
        K_{\cF_{S_i}} + B_{S_i} + \bM_{S_i}^{S_i} := (K_{\cF_{Y_i}} + B_{Y_i}  + \bM_{Y_i}^i)|_{S_i},
        \]
    and \[
    \Delta_i = B_{S_i} + t_i(D_{S_i} + \Xi_i).
    \]
    \medskip

    \textit{Step 4.} In this step we assume that $\dim Q_i = 1$ for each $i$. Let $Q_i^\nu \to Q_i$ be the normalization of $Q_i$, and let $F_i$ be a general fiber of $S_i \to Q_i^\nu$. By the construction,
    \[
    K_{\cF_{S_i}} + \Delta_i + \mathbf{\Psi}^i_{S_i} = (K_{\cF_{Y_i}}+ B_{Y_i}+t_iD_{Y_i}+ \bM^i_{Y_i} + t_i \bN^i_{Y_i})|_{S_i} \equiv 0/Q_i^\nu.
    \]
    Since $F_i$ is general, we have that $(B_{Y_i}|_{S_i} )\cdot F_i \geq 0$ and $\Theta_i \cdot F_i\geq 0$. By Lemma~\ref{lemma:bnefonsurface}, $\bM_{S_i}^{S_i} \cdot F_i \geq 0$. Then $\bM^i_{X_i'}|_{S_i}\cdot F_i \geq 0$. Since $-T_i$ is ample over $X_i$, $T_i|_{S_i}\cdot F_i <0$, then 
    \[
    (D_{Y_i} + \bN_{Y_i}^i)|_{S_i}\cdot F_i  = - \frac{e_i}{t_i}(T_i|_{S_i})\cdot F_i >0.
    \] 
    It follows that $K_{\cF_{Y_i}}|_{S_i} \cdot F_i <0$. Since $F_i$ is general, $G_i\cdot F_i \geq 0$, which implies that $K_{\cF_{S_i}} \cdot F_i <0$. We may assume that $F_i$ is disjoint with $\Sing X \cup \Sing\cF$. Then by  
    \cite[Lemma 1.14]{Che22}, $F_i$ is $\cF_{S_i}$-invariant and $K_{\cF_{S_i}}\cdot F_i = -2$. It follows that 
    \[
        (\Delta_i+\mathbf{\Psi}_{S_i}^i)\cdot F_i = 2.
    \]

    Assume that $\bN_{S_i}^{S_i}\cdot F_i\neq 0$ for all $i$. Then we have $(\Delta_i + \bM^{S_i}_{S_i} + t_i \bN^{S_i}_{S_i})\cdot F_i = 2$. Since $F_i$ is general, we have $H_i \cdot F_i$, $ \mathbf{R}_{S_i}\cdot F_i \in \Z_{\geq 0}$ for every prime divisor $H_i$ contained in $\Supp \Delta_i$ and every b-Cartier b-nef b-divisor $\mathbf{R}$ appears in $\bM^{S_i}$ and $\bN^{S_i}$. Since $\Delta_i\in \frac{1}{2} K_+$ and $\bM^{S_i},\bN^{S_i}\in I$, by Lemma~\ref{lemma:finiteset}, there exists $\nu_i\in I\setminus \{0\}$, occurs as a coefficient of $\bN^{S_i}$, such that $t_i\nu_i$ belongs to a finite set that is independent of $i$, which contradicts with the fact that $\{t_i\}_{i=1}^\infty$ is strictly increasing.

    Now we may assume that $\bN^{S_i}_{S_i} \cdot F_i = 0$ for all $i$. 
    Let $\Delta_i(t) =  B_{S_i} + t(D_{S_i} + \Xi_i)$, then  $\Delta_i = \Delta_i(t_i)$. Note that
    \[
    (D_{S_i}+ \Xi_i)\cdot F_i = (D_{S_i} +  \bN_{S_i}^{S_i} + \Xi_i)\cdot F_i = (D_{Y_i} + \bN^i_{Y_i})|_{S_i} \cdot F_i >0,
    \]
    and 
    \begin{align*}
        (B_{S_i} + t_i(D_{S_i}+ \Xi_i) + \bM_{S_i}^{S_i})\cdot F_i = (\Delta_i(t_i) + \bM_{S_i}^{S_i})\cdot F_i = (\Delta_i + \mathbf{\Psi}_{S_i}^i)\cdot F_i = 2
    \end{align*}
    as $\bN^{S_i}_{S_i} \cdot F_i = 0$.
    Since $F_i$ is general, $H_i \cdot F_i$, $ \mathbf{R}_{S_i}\cdot F_i \in \Z_{\geq 0}$ for every prime divisor $H_i$ contained in $\Supp \Delta_i$ and every b-Cartier b-nef b-divisor $\mathbf{R}$ appears in $\bM^{S_i}$. Note that $\Delta_i \in \frac{1}{2}K_+$ and $\bM^{S_i}\in I$, hence by Lemma~\ref{lemma:finiteset}, there exists a linear function $f_i(t)$ of $t$, which occurs as a coefficient of $\Delta_i(t)$ and is not a constant function of $t$, such that $f_i(t_i)$ belongs to a finite set independent of $i$. Moreover, $f_i(t_i)\in \frac{1}{2}(K_i)_+ \setminus \{0\}$. We may write $2f_i(t_i) = \sum_{j=1}^n (a^i_j + t_ib^i_j)$, where $a^i_j,b^i_j\in I\cup \{0\}$ such that $\sum_j b^i_j \neq 0$. We may assume that $b_1^i \neq 0$ for each $i$. By Lemma~\ref{lemma:finiteset}, $a^i_1 + t_ib^i_1$ belongs to a finite set independent of $i$, which again contradicts with the fact that $\{t_i\}_{i=1}^\infty$ is strictly increasing.

    \medskip

    \textit{Step 5.} Now we may assume that $\dim Q_i = 0$ for all $i$. Then we have
    \[
        K_{\cF_{S_i}} + \Delta_i + \mathbf{\Psi}^i_{S_i}  \equiv 0.
    \]
    Let $L_i$ be a general leaf of $\cF_{S_i}$. Similarly to Step 4, we have
    \[
    \left(B_{Y_i}|_{S_i}+ \bM^i_{Y_i}|_{S_i} + G_i \right)\cdot L_i \geq 0.
    \]
    Since $-T_i$ is ample over $X_i$, $T_i|_{S_i}\cdot L_i<0$.
    Then $K_{\cF_{S_i}}\cdot L_i <0$ as $ (D_{Y_i} + \bN_{Y_i}^i)|_{S_i}\cdot L_i = -\frac{e_i}{t_i} T_i|_{S_i}\cdot L_i >0$. In particular, $K_{\cF_{S_i}}$ is not numerically trivial. By Lemma~\ref{lemma:surfacemodel}, there exists $\alpha_i: \Tilde{S_i} \to S_i$ such that $K_{\cG_i} + R_i = \alpha_i^* K_{\cF_{S_i}}$, where $\tilde{S_i}$ is $\Q$-factorial, $\cG_i = \alpha_i^{-1}\cF_{S_i}$ and $R_i\geq 0$ is exceptional over $S_i$. Note that $K_{\cF_{S_i}}$ may not be $\Q$-Cartier but we may define the pullback in the sense of Mumford. Let $\tilde{L_i}$ be the strict transform of $L_i$ on $\tilde{S_i}$. Then $R_i \cdot \tilde{L_i}\geq 0 $, and 
    \[
    K_{\cG_i} \cdot \tilde{L_i} = \alpha_i^*K_{\cF_{S_i}}\cdot \tilde{L_i} - R_i \cdot \tilde{L_i} = K_{\cF_{S_i}}\cdot L_i - R_i \cdot \tilde{L_i}<0.
    \]
    Since $K_{\cG_i} + R_i + \alpha_i^*(\Delta_i+ \mathbf{\Psi}^i_{S_i}) \equiv 0$, $R_i + \alpha_i^*(\Delta_i + \mathbf{\Psi}^i_{S_i}) $ is pseudo-effective, and $K_{\cG_i}$ is $\Q$-Cartier and not numerically trivial, we have $K_{\cG_i}$ is not pseudo-effective and then by \cite[Theorem 1.1]{CP19} or \cite[Lemma 2.21]{CS21}, $\cG_i$ is algebraically integrable and general leaves of $\cG_i$ are rational curves. Thus $\cF_{S_i}$ is also algebraically integrable, and general leaves of $\cF_{S_i}$ are rational curves.

    Let $L_{Y_i}$ be the image of $L_i$ on $Y_i$. We have
    \[
    (K_{\cF_{Y_i}} + B_{Y_i} + t_iD_{Y_i} + \bM^i_{Y_i} + t_i \bN^i_{Y_i}) \cdot L_{Y_i} = 0.
    \]
    Assume that \[
    B_{Y_i} + t_iD_{Y_i} = \sum_
    {j=1}^{m_i} \alpha_{i,j}C_{i,j},\qquad \bM^i + t_i\bN^i = \sum_{l=1}^{n_i}\beta_{i,l} \mathbf{L}^{i,l},
    \]
    where $m_i,n_i \geq 0$, $C_{i,j}$ are prime divisors on $Y_i$ distinct from $T_i$, $\mathbf{L}^{i,l}$ are b-Cartier b-divisors on $Y_i$, $\alpha_{i,j}, \beta_{i,l} \in K_i \subset K$.
    By Lemma~\ref{lemma:forACC.adj.curves}, there exists a non-negative integer $\lambda_i, q_i$ and positive integers $p_{i,k}$ for $1 \leq k \leq q_i$ such that the above equality can be written as 
    \[
    \frac{\lambda_i}{2} + \sum_{k=1}^{q_i} \frac{p_{i,k}-1}{p_{i,k}} + \sum_{j=1}^{m_i} \frac{\alpha_{i,j} }{2}(2C_{i,j}\cdot L_{Y_i}) + \sum_{l=1}^{n_i} \frac{\beta_{i,l}}{2} (2\bL^{i,l}_{Y_i} \cdot L_{Y_i}) = 2,
    \]
    and $(2C_{i,j}\cdot L_{Y_i})$ and $(2\bL^{i,l}_{Y_i} \cdot L_{Y_i})$ are non-negative integers. Let $\alpha_{i,j}' := \alpha_{i,j}$ if $(2C_{i,j}\cdot L_{Y_i})>0$ and $\alpha_{i,j}' := 0$ otherwise. Let $\beta_{i,l}' := \beta_{i,l}$ if $(2\bL^{i,l}_{Y_i} \cdot L_{Y_i}) > 0$ and $\beta_{i,l}' := 0$ otherwise.

    Note that \(
        \frac{1}{2}K \cup \left\{\,\frac{m-1}{m}\,|\, m \in \Z_{>0}\,\right\}
    \) is a DCC set. By Lemma~\ref{lemma:finiteset}, $\alpha_{i,j}', \beta_{i,l}'$ belong to a finite set $J$ independent of $i$. Note that $(D_{Y_i} + \bN^i_{Y_i}) \cdot L_{Y_i} = -\frac{e_i}{t_i} T_i \cdot L_{Y_i} >0$, there exists $a_i\in I\cup  \{0\}$, $b_i \in I \setminus \{0\}$, such that $a_i+ t_ib_i$, which equals to one of the $\alpha_{i,j}'$ and $\beta_{i,l}'$, belongs to the finite set $J$. It follows that $\{t_i\}$ belongs to an ACC set independent of $i$ which leads to a contradiction.
\end{proof}





    \begin{comment}



    Since $\cF_{S_i}$ is algebraically integrable, we may apply \cite[Theorem 6.0.1]{CHLX23} on $K_{\cF_{S_i}}+ \Delta_i + \mathbf{\Psi}_{S_i}^i $ and $L_i$ then write
    \[
    K_{L_i^\nu} + \Lambda_i + \mathbf{\Psi}^{L_i}_{L_i^\nu} := (K_{\cF_{S_i}}+ \Delta_i + \mathbf{\Psi}_{S_i}^i)|_{L_i^\nu},
    \]
    where $L_i^\nu \to L_i$ is the normalization, $\mathbf{\Psi}^{L_i} =  \bM^{L_i} + t_i \bN^{L_i}$ (here $\bM^{L_i} = \bM^{S_i}|_{L_i^\nu}$ and $\bN^{L_i} = \bN^{S_i}|_{L_i^\nu}$ are restricted b-divisors), and the coefficients of $\Lambda_i$ belongs to $D\left(\frac{1}{2}(K_i)_+\right)$. In particular, $\mathbf{\Psi}^{L_i} \in K_i$. Note that $\deg K_{L_i^\nu} = -2$, then
    \begin{align*}
