        &= A_i + \Delta_i|_{L_i^\nu} + (\bM^{S_i}_{S_i}|_{L_i^\nu}-\bM^{L_i}_{L_i^\nu}) + t_i (\bN^{S_i}_{S_i}|_{L_i^\nu}-\bN^{L_i}_{L_i^\nu}) \\
        &= A_i + B_{S_i}|_{L_i^\nu} + \Theta^L_i + t_i\left((D_{S_i} + \Xi_i)|_{L_i^\nu} +\Xi^L_i\right).
    \end{align*}
    Moreover, we have
    \begin{align*}
        \deg & \left((  D_{S_i} + \Xi_i)|_{L_i^\nu} +\Xi^L_i\right) =
        (D_{S_i} + \Xi_i) \cdot L_i + \deg \left(\bN^{S_i}_{S_i}|_{L_i^\nu} - \bN^{L_i}_{L_i^\nu}\right) \\
        &= (D_{S_i} + \Xi_i) \cdot L_i + \bN^{S_i}_{S_i} \cdot L_i
        = (D_{Y_i}|_{S_i} + \bN_{Y_i}^i|_{S_i}) \cdot L_i \\
        &= (D_{Y_i} + \bN_{Y_i}^i)\cdot L_{Y_i}  = -e_i T_i \cdot L_{Y_i} > 0,
    \end{align*}
    where $L_{Y_i}$ is the image of $L_i$ on $Y_i$. Define
    \[
    \Lambda_i(t) := A_i + B_{S_i}|_{L_i^\nu} + \Theta^L_i + t\left((D_{S_i} + \Xi_i)|_{L_i^\nu} +\Xi^L_i\right),
    \]
    then $\Lambda_i = \Lambda_i(t_i)$ and $\deg \Lambda_i(t)$ is not a constant function of $t$. Note that $\Lambda_i \in D\left(\frac{1}{2}K_+\right)$ and $\bM^{L_i}\in I$. Therefore by Lemma \ref{lemma:finiteset}, there exists a linear function $h_i(t)$ of $t$, which is a coefficient of $\Lambda_i(t)$ and is not a constant function of $t$, such that $h_i(t_i)$ belongs to a finite set independent of $i$. Moreover, $h_i(t_i)\in D(\frac{1}{2}(K_i)_+)$.
