   \label{fig:MC2}
   \begin{subfigure}{\textwidth}
   \caption{Weak loadings $(\alpha=0.7)$.\vspace{-0.2cm}}
   \includegraphics[width=\textwidth]{Figures/MSEk_TN_PCAk_rho1ia2}
