\subsection{Proof of Detectability Guarantees}

In this appendix section we provide the full proof and a brief discussion of the main assumptions behind Theorem \ref{thm:bound}. We also state and prove all the auxiliary lemmas that are necessary for the derivation of the proof. 

We start by arguing that the set of assumptions made for Theorem \ref{thm:bound} is not excessively restrictive. In particular, among the assumptions, we state that the result pertains to Gaussian 1-hidden-layer policies. However, this assumption can be relaxed in two ways. First of all, the result is easily extendable to $L$-layers MLPs quite straightforwardly (see Lemma \ref{lemma:maskMLP}). This will impact coefficient $B_j$ uniquely. Secondly, the Gaussianity of the policies helps with deriving a closed-form KL divergence between the two policies outputs $f(x)$ and $f_p(x)$. This can be relaxed in favor of a general non-parametric assumption on the distribution form, but at the cost of losing a direct dependency between the difference in performance and the coefficient $B_j$ (although one can derive closed-form KL divergence also for other classes of distributions, such as Binomial for instance). Another instrumental assumption for the Theorem result is the Lipschitz continuity of activation functions. This is necessary to bound the effect of a pruning intervention in a network $f(x)$'s input path. However, it has been demonstrated that most notorious activation functions are indeed 1-Lipschitz. This include ReLU, TanH and Softmax. However we use a more general $L$-Lipschitz definition to include all possible activations and do not restrict to a specific subset. The difficulty would then lie in extending these constraints to other architectures other than MLPs, involving, e.g., convolutions. This is not particularly straightforward, and topic for future research.

\begin{proof}[Proof of Theorem \ref{thm:bound}]
    Suppose we have two Gaussian, 1-hidden layer, policy networks $\pi_1$ and $\pi_2$, and two time-dependent state-action transition densities $p^t_1(s,a)$ and $p^t_2(s,a)$. Then we have:
    \begin{gather*}
        |J(\pi_1)- J(\pi_2)| = | \sum^T_{t=0} \gamma^t \Big[  \mathbb{E}_{a \sim \pi_1, s \sim p_1} [r(s_t, a_t)] - \mathbb{E}_{a \sim \pi_2, s \sim p_2} [r(s_t, a_t)] \Big] | = \\
        = | \sum^T_{t=0} \gamma^t \Big[  \int_a \int_s \big[ p^t_1(s, a) - p^t_2(s, a) \big] r(s, a) \, ds \, da \Big] | \leq \\
        \leq \sum^T_{t=0} \gamma^t \Big[  \int_a \int_s | p^t_1(s, a) - p^t_2(s, a) | r(s, a) \, ds \, da \Big]
    \end{gather*}
    Using the fact that rewards are bounded $r: \mathcal{S} \times\mathcal{A} \rightarrow [r_{min}, r_{max}] \subset \mathbb{R}$, then:
    \begin{gather*}
    |J(\pi_1)- J(\pi_2)| \leq \sum^T_{t=0} \gamma^t \Big[  \int_a \int_s | p^t_1(s, a) - p^t_2(s, a) | r(s, a) \, ds \, da \Big] \leq \\
    \leq r_{max} \sum^T_{t=0} \gamma^t \Big[  \int_a \int_s | p^t_1(s, a) - p^t_2(s, a) | \, ds \, da \Big] = \\
    = 2r_{max} \sum^T_{t=0} \gamma^t \Big[  D_{TV} ( p^t_1(s,a) \| p^t_2(s,a) ) \Big]
    \end{gather*}
    Then, by Lemma \ref{lemma:jointTVD} (see below) we have:
    \begin{gather*}
    |J(\pi_1)- J(\pi_2)| \leq 2r_{max} \sum^T_{t=0} \gamma^t \Big[  D_{TV} ( p^t_1(s,a) \| p^t_2(s,a) ) \Big] \leq \\
    \leq 2r_{max} \sum^T_{t=0} \gamma^t \Big[  D_{TV} ( p^t_1(s) \| p^t_2(s) ) + \mathbb{E}_{s \sim p} \big[ D_{TV} ( \pi_1(a|s) \| \pi_2(s,a) \big] \Big] 
    \end{gather*}
    Additionally, via Lemma \ref{lemma:TVDtime} (see below) we obtain:
    \begin{gather*}
    |J(\pi_1)- J(\pi_2)| \leq 2r_{max} \sum^T_{t=0} \gamma^t \Big[  D_{TV} ( p^t_1(s) \| p^t_2(s) ) + \mathbb{E}_{s \sim p} \big[ D_{TV} ( \pi_1(a|s) \| \pi_2(s,a) \big] \Big]  \leq \\
    \leq 2r_{max} \sum^T_{t=0} \gamma^t \Big[  t \delta + \mathbb{E}_{s \sim p} \big[ D_{TV} ( \pi_1(a|s) \| \pi_2(a|s) \big] \Big]  
    \end{gather*}
    From here, using Pinsker's inequality we derive:
    \begin{gather*}
    |J(\pi_1)- J(\pi_2)| \leq 2r_{max} \sum^T_{t=0} \gamma^t \Big[  t \delta + \mathbb{E}_{s \sim p} \big[ D_{TV} ( \pi_1(a|s) \| \pi_2(a|s) \big] \Big] \leq \\
    \leq 2r_{max} \sum^T_{t=0} \gamma^t \Big[  t \delta + \mathbb{E}_{s \sim p} \big[ \sqrt{2 D_{KL} ( \pi_1(a|s) \| \pi_2(a|s) )} \big] \Big]
    \end{gather*}
    Considering that we have two policies $\pi_1$ and $\pi_2$ that are 1-hidden layer MLPs, outputting a Gaussian distribution, by Lemma \ref{lemma:maskMLP} below we obtain:
    \begin{gather*}
    |J(\pi_1)- J(\pi_2)| \leq 2r_{max} \sum^T_{t=0} \gamma^t \Big[  t \delta + \mathbb{E}_{s \sim p} \big[ \sqrt{2 D_{KL} ( \pi_1(a|s) \| \pi_2(a|s) )} \big] \Big] \leq \\
    \leq 2r_{max} \sum^T_{t=0} \gamma^t \Big[  t \delta + \mathbb{E}_{s \sim p} \big[ \sqrt{2 \frac{(B_j s_j)^2}{2\sigma^2_f} )} \big] \Big] = \\
    = 2r_{max} \sum^T_{t=0} \gamma^t \Big[  t \delta +  \frac{B_j \mathbb{E}_{s \sim p} [|s_j|]}{\sigma_f}  \Big]
    \end{gather*}
    Finally, using the normalized inputs assumption by which $s_j \in [0,1]$ then we have:
    \begin{gather*}
    |J(\pi_1)- J(\pi_2)| \leq 2r_{max} \sum^T_{t=0} \gamma^t \Big[  t \delta +  \frac{B_j \mathbb{E}_{s \sim p} [|s_j|]}{\sigma_f}  \Big] \leq \\
    \leq 2r_{max} \sum^T_{t=0} \gamma^t \Big[  t \delta +  \frac{B_j}{\sigma_f}  \Big] \leq \\
    \leq 2r_{max} \sum^{\infty}_{t=0} \gamma^t \Big[  t \delta +  \frac{B_j}{\sigma_f}  \Big] \leq \\
    \leq 2r_{max}  \Big[  \frac{\gamma\delta}{(1 - \gamma)^2} +  \frac{B_j}{\sigma_f (1- \gamma)}  \Big] ~ ,
    \end{gather*}
    where $\frac{1}{2} \mathbb{E}_{s' \sim p} \big[ D_{TV} \big( p_1(s|s') \| p_2(s|s')  \big) \big] \leq \delta$ according to assumptions.
\end{proof}
\noindent After stating the full proof of Theorem \ref{thm:bound}, we proceed here below by providing statements of all the auxiliary lemmas instrumental to the theorem's proof, together with their own standalone proofs. For almost all the lemmas and proofs, we will be using the Total-Variation Distance on continuous probability spaces, which is defined for a continuous random variable $s \in \mathcal{S}$ and two density functions $p,q$ defined on the same probability space as:
\begin{gather*}
    D_{TV} \big( p(s) \| q(s) \big) = \frac{1}{2} \int_{s \in \mathcal{S}} | p(s) - q(s)| \, ds ~ .
\end{gather*}
\begin{lemma}[Joint Probability $D_{TV}$ Decomposition] \label{lemma:jointTVD}
    Consider two, time-dependent, joint state-action visitation probabilities $p^t_1 (s,a)$ and $p^t_2 (s,a)$, and their Total Variation Distance:
    \begin{gather*}
        D_{TV} \big( p^t_1 (s,a) \| p^t_2 (s,a) \big) = \frac{1}{2} \int_s \int_a | p^t_1 (s,a) - p^t_2 (s,a) | \, ds \, da ~ .
    \end{gather*}
    We can decompose this quantity into:
    \begin{gather*}
        D_{TV} \big( p^t_1 (s,a) \| p^t_2 (s,a) \big) \leq D_{TV} \big( p^t_1 (s) \| p^t_2 (s) \big) + \mathbb{E}_{s \sim p} \big[ D_{TV} \big( \pi_1 (a|s) \| \pi_2 (a |s) \big) \big] ~ .
    \end{gather*}
\end{lemma}
\begin{proof}[Proof of Lemma \ref{lemma:jointTVD}]
    Let us first define the recursive one-step decomposition of the joint probability $p^t_i (s,a)$:
    \begin{gather*}
        p^i_t (s,a) = \int_s p_i(s' |,s,a) \pi_i(a|s) p^{t-1}_i (s) \, ds ~ .
    \end{gather*}
    Then, we have that the difference:
    \begin{gather*}
        p^{t+1}_1 (s,a) - p^{t+1}_t (s,a) = \int_s \big[ p_1 (s' |s,a) \pi_1 (a|s) p^t_1(s) - p_2 (s' |s,a) \pi_2 (a|s) p^t_2(s) \big] \, ds = \\
        = \int_s \Big\{ p_1 (s' |s,a) \big[ \pi_1 - \pi_2 \big] p^t_1(s) + p_2(s'|s,a) \pi_2 \big[ p^t_1 (s) - p^t_2 (s) \big]  \Big\} \, ds
    \end{gather*}
    The Total Variation Distance between the two densities is then defined as:
    \begin{gather*}
        D_{TV} \big( p^{t+1}_1 (s,a) \| p^{t+1}_2 (s,a) \big) = \frac{1}{2} \int_s\int_a \left| p^{t+1}_1 (s,a) - p^{t+1}_t (s,a) \right| \, da \, ds \leq \\
        \leq \frac{1}{2} \int_s\int_a \left| p_1 (s' |s,a) \big[ \pi_1 - \pi_2 \big] p^t_1(s) \right| \, ds\,da \, + \frac{1}{2} \int_s\int_a \left| p_2(s'|s,a) \pi_2 \big[ p^t_1 (s) - p^t_2 (s) \right| \, ds\,da \,
    \end{gather*}
    For the first term of the sum above, we can derive:
    \begin{gather*}
        \frac{1}{2} \int_s\int_a \left| p_1 (s' |s,a) \big[ \pi_1 - \pi_2 \big] p^t_1(s) \right| \, ds\,da \leq \\
        \leq \frac{1}{2} \int_s\int_a \left|  \pi_1 - \pi_2 \right| p^t_1(s) \, ds\,da \leq \frac{1}{2} \int_s\int_a \left|  \pi_1 - \pi_2 \right| \, ds\,da \leq \\
        \int_s D_{TV} \big( \pi_1 \| \pi_2 \big) \, ds = \mathbb{E}_{s \sim p} \big[ D_{TV} \big( \pi_1 \| \pi_2 \big) \big]
    \end{gather*}
    For the second term instead we have:
    \begin{gather*}
        \frac{1}{2} \int_s\int_a \left| p_2(s'|s,a) \pi_2 \big[ p^t_1 (s) - p^t_2 (s) \right| \, ds\,da \leq \frac{1}{2} \int_s\int_a \left| p^t_1 (s) - p^t_2 (s) \right| \, ds\,da \leq \\
        \frac{1}{2} \int_s \left| p^t_1 (s) - p^t_2 (s) \right| \, ds  =  D_{TV} \big( p^t_1 (s) \| p^t_2 (s) \big)
    \end{gather*}
    Putting the two together, we eventually obtain:
    \begin{gather*}
        D_{TV} \big( p^{t+1}_1 (s,a) \| p^{t+1}_2 (s,a) \big) \leq D_{TV} \big( p^t_1 (s) \| p^t_2 (s) \big) + \mathbb{E}_{s \sim p} \big[ D_{TV} \big( \pi_1 (a|s) \| \pi_2 (a|s) \big) \big] ~ .
    \end{gather*}
\end{proof}

\begin{lemma}[Time-Dependent $D_{TV}$ Bound] \label{lemma:TVDtime}
    Suppose we assume same initial state distributions $p^0_1 (s) = p^0_2(s)$ and we define the following supremum quantity $\sup_t \mathbb{E}_{{\tilde{s}} \sim p} \big[ D_{TV} \big( p_1(s |{\tilde{s}}) \| p_2(s|{\tilde{s}}) \big) \big] \leq \delta$. Then we can obtain the following bound:
    $$ D_{TV} \big( p^t_1 (s) \| p^t_2 (s) \big) \leq t\delta ~ . $$
\end{lemma}

\begin{proof}[Proof of Lemma \ref{lemma:TVDtime}]
    Let us start by defining the one-step recursive decomposition:
    $$ p^t_1(s) = \int_{\tilde{s}} p_1(s|\tilde{s}) p^{t-1}_1 (\tilde{s}) \, d\tilde{s} ~ . $$
    Then we have:
    \begin{gather*}
        D_{TV} \big( p^t_1 (s) \| p^t_2 (s) \big) = \frac{1}{2} \int_s | p^t_1 (s) - p^t_2 (s) | \, ds = \\
        = \frac{1}{2} \int_{\tilde{s}} \int_{\tilde{s}} \left| p_1(s|\tilde{s}) p^{t-1}_1 (\tilde{s}) - p_2(s|\tilde{s}) p^{t-1}_2 (\tilde{s}) \right| \, ds \, d\tilde{s} \leq \\
        \leq \frac{1}{2} \int_{s} \left[ \int_{\tilde{s}} p^{t-1}_1 (\tilde{s}) \left| p_1(s|\tilde{s}) - p_2(s|\tilde{s}) \right| \,d\tilde{s} + \int_{\tilde{s}} p^{t-1}_2 (s|\tilde{s}) \left| p^{t-1}_1(s) - p^{t-1}_2(s) \right| \,d\tilde{s} \right] ds = \\
        = \frac{1}{2} \int_{\tilde{s}} p^{t-1}_1 (\tilde{s}) \left[ \int_s | p_1(s|\tilde{s}) - p_2(s|\tilde{s}) | \, ds \right] d\tilde{s} + \frac{1}{2} \int_{\tilde{s}} | p^{t-1}_1 (\tilde{s}) - p^{t-1}_2 (\tilde{s}) | \, d\tilde{s} = \\
        = \mathbb{E}_{\tilde{s} \sim p^{t-1}} \left[ \frac{1}{2} \int_s | p_1(s|\tilde{s}) - p_2(s|\tilde{s}) | \, ds \right] + D_{TV} \big( p^{t-1}_1 (s) \| p^{t-1}_2 (s) \big) \leq \\
        \leq \delta + D_{TV} \big( p^{t-1}_1 (s) \| p^{t-1}_2 (s) \big) ~ ,
    \end{gather*}
    By recursion over time $t$, we can compactly rewrite:
    $$ D_{TV} \big( p^{t}_1 (s) \| p^{t}_2 (s) \big) \leq t \delta + D_{TV} \big( p^{0}_1 (s) \| p^{0}_2 (s) \big) ~ , $$
    where by assumption $D_{TV} \big( p^{0}_1 (s) \| p^{0}_2 (s) \big) = 0$, leaving:
    $$ D_{TV} \big( p^{t}_1 (s) \| p^{t}_2 (s) \big) \leq t \delta ~ . $$
\end{proof}

\noindent Finally here below we prove the lemma regarding the masking of Multi-Layer Perceptron networks.

\begin{lemma}[Path Masking Intervention on MLPs] \label{lemma:maskMLP}
    Suppose we have a 1-hidden layer MLP that outputs $y \sim \mathcal{N} \big( f(x), \sigma^2_f \big)$ from inputs $(x_1, ..., x_d)$, where $\sigma^2_f \in \mathbb{R}^+$ and:
    $$ f(x) = \sum^H_{i=1} W_{2,i} \phi(z_i) + b_2 ~, ~~\text{ where } ~ z_i = \sum^d_{k=1} W_{1, ik} x_k + b_{1,i} ~ , $$
    and $\phi: \mathbb{R} \rightarrow (a,b) \subseteq \mathbb{R}$ is a $L_{\phi}$-Lipschitz continuous activation function. Then defining as $f_p(x)$ the “pruned” version of $f(x)$, where input $x_j$ is masked out via the intervention $W_{1,j} = 0$, we have that:
    $$ D_{KL} \big( \mathcal{N} \big( f(x), \sigma^2_f \big) \| \mathcal{N} \big( f_p(x), \sigma^2_f \big) \big) \leq \frac{(B_j |x_j|)^2}{2 \sigma^2_f} ~ , $$
    where $B_j = L_{\phi} \sum^H_{i=1} | W_{1, ij} W_{2,i} |$.
\end{lemma}

\begin{proof}[Proof of Proposition \ref{lemma:maskMLP}]
    The “pruned” version $f_p(x)$ of $f(x)$ can be written in the following form:
    $$ f_p(x) = \sum^H_{i=1} W_{2,i} \phi(z'_i) + b_2 ~, ~~~ \text{ where } ~ z'_i = \sum^d_{k=1, k\neq j} W_{1, ik} x_k + b_{1,i} ~ . $$
    Then, it is easy to obtain that $z'_i = z_i - W_{1, ij} x_j$, so that the difference becomes:
    $$ f(x) - f_p(x) = \sum^H_{i=1} W_{2,i} \left[ \phi(z_i) - \phi(z_i - W_{1, ij} x_j)   \right] ~ . $$
    Using the $L_{\phi}$-Lipschitz property of $\phi(\cdot)$ we obtain:
    \begin{gather*}
        |f(x) - f_p(x)| = | \sum^H_{i=1} W_{2,i} \left[ \phi(z_i) - \phi(z_i - W_{1, ij} x_j)   \right] | \leq \sum^H_{i=1} |W_{2,i}| \, | \phi(z_i) - \phi(z_i - W_{1, ij} x_j) | \leq \\
        \leq \sum^H_{i=1} |W_{2,i}| L_{\phi} |W_{1,ij} x_j| = |x_j| L_{\phi} \sum^H_{i=1} |W_{2,i} W_{1,ij}| = B_j |x_j| ~ .
    \end{gather*}
    Finally this implies that:
    $$ D_{KL} \big( \mathcal{N} \big( f(x), \sigma^2_f \big) \| \mathcal{N} \big( f_p(x), \sigma^2_f \big) \big) = \frac{\big( f(x) - f_p(x) \big)^2}{2 \sigma^2_f} \leq \frac{(B_j |x_j|)^2}{2 \sigma^2_f} ~ , $$
    where $D_{KL}$ is the KL divergence, defined as $D_{KL}(p\|q) = \int_{x \in \mathcal{X}} p(x) \log \frac{p(x)}{q(x)} \, dx$.
\end{proof}
