	\title{Function-Correcting Codes with Homogeneous Distance \let\thefootnote\relax\footnotetext{E-Mail addresses: huiyingliu@mails.ccnu.edu.cn (H.Y. Liu),  hwliu@ccnu.edu.cn (H. Liu).}}
