\title[Newcomb-Benford Law in Neuromuscular Transmission]{Newcomb-Benford Law in Neuromuscular Transmission: Validation at Hyperkalemic Conditions}

\author{Adriano Silva$^{1}$, Sergio Floquet$^{2}$ and Ricardo Lima$^{3}$}
